def run(self, dag):
    for run in dag.collect_1q_runs():
        block = QuantumCircuit(1)
        for node in run:
            block.append(node.op, [0], [])
        box = BoxOp(block, annotations=[PerformsUnitary(Operator(block).data)])
        dag.replace_block_with_op(run, box, {run[0].qargs[0]: 0})
    return dag

def definition(self) -> QuantumCircuit:
    """Return definition in terms of other basic gates. If the gate has
    open controls, as determined from :attr:`ctrl_state`, the returned
    definition is conjugated with X without changing the internal
    ``_definition``.
    """
    if self._open_ctrl:
        closed_gate = self.to_mutable()
        closed_gate.ctrl_state = None
        bit_ctrl_state = bin(self.ctrl_state)[2:].zfill(self.num_ctrl_qubits)
        qreg = QuantumRegister(self.num_qubits, "q")
        qc_open_ctrl = QuantumCircuit(qreg)
        for qind, val in enumerate(bit_ctrl_state[::-1]):
            if val == "0":
                qc_open_ctrl.x(qind)
        qc_open_ctrl.append(closed_gate, qargs=qreg[:])
        for qind, val in enumerate(bit_ctrl_state[::-1]):
            if val == "0":
                qc_open_ctrl.x(qind)
        return qc_open_ctrl
    else:
        return super().definition

def _define(self):
    num_state_qubits = self.num_qubits - 1
    qr_state = QuantumRegister(num_state_qubits, "state")
    qr_flag = QuantumRegister(1, "flag")
    circuit = QuantumCircuit(qr_state, qr_flag)

    angles = [0.0]
    nl = 2 ** (num_state_qubits - 1) if self.neg_vals else 2**num_state_qubits

    # Angles to rotate by scaling / x, where x = i / nl
    for i in range(1, nl):
        if isclose(self.scaling * nl / i, 1, abs_tol=1e-5):
            angles.append(np.pi)
        elif self.scaling * nl / i < 1:
            angles.append(2 * np.arcsin(self.scaling * nl / i))
        else:
            angles.append(0.0)

    circuit.append(UCRYGate(angles), [qr_flag[0]] + qr_state[: len(qr_state) - self.neg_vals])

    if self.neg_vals:
        circuit.append(
            UCRYGate([-theta for theta in angles]).control(annotated=False),
            [qr_state[-1]] + [qr_flag[0]] + qr_state[:-1],
        )
        angles_neg = [0.0]
        for i in range(1, nl):
            if isclose(self.scaling * (-1) / (1 - i / nl), -1, abs_tol=1e-5):
                angles_neg.append(-np.pi)
            elif np.abs(self.scaling * (-1) / (1 - i / nl)) < 1:
                angles_neg.append(2 * np.arcsin(self.scaling * (-1) / (1 - i / nl)))
            else:
                angles_neg.append(0.0)
        circuit.append(
            UCRYGate(angles_neg).control(annotated=False),
            [qr_state[-1]] + [qr_flag[0]] + qr_state[:-1],
        )

    self.definition = circuit

def _define(self):
    circuit = QuantumCircuit(self.num_qubits)

    # build the circuit
    qr_state = circuit.qubits[: self.num_qubits - 1]
    qr_target = circuit.qubits[-1]

    if self.basis == "x":
        circuit.rx(self.offset, qr_target)
    elif self.basis == "y":
        circuit.ry(self.offset, qr_target)
    else:  # 'Z':
        circuit.rz(self.offset, qr_target)

    for i, q_i in enumerate(qr_state):
        if self.basis == "x":
            circuit.crx(self.slope * pow(2, i), q_i, qr_target)
        elif self.basis == "y":
            circuit.cry(self.slope * pow(2, i), q_i, qr_target)
        else:  # 'Z'
            circuit.crz(self.slope * pow(2, i), q_i, qr_target)

    self.definition = circuit

def _define(self):
    poly_r = PiecewisePolynomialPauliRotationsGate(
        self.num_state_qubits, self.breakpoints, self.polynomials
    )

    self.definition = QuantumCircuit(poly_r.num_qubits)
    self.definition.append(poly_r, self.definition.qubits)

def _define(self):
    circuit = QuantumCircuit(self.num_qubits)
    qr_state = circuit.qubits[: self.num_qubits - 1]
    qr_target = circuit.qubits[-1]

    rotation_coeffs = self._get_rotation_coefficients()

    if self.basis == "x":
        circuit.rx(self.coeffs[0], qr_target)
    elif self.basis == "y":
        circuit.ry(self.coeffs[0], qr_target)
    else:
        circuit.rz(self.coeffs[0], qr_target)

    for c in rotation_coeffs:
        qr_control = []
        for i, _ in enumerate(c):
            if c[i] > 0:
                qr_control.append(qr_state[i])

        # apply controlled rotations
        if len(qr_control) > 1:
            if self.basis == "x":
                circuit.mcrx(rotation_coeffs[c], qr_control, qr_target)
            elif self.basis == "y":
                circuit.mcry(rotation_coeffs[c], qr_control, qr_target)
            else:
                circuit.mcrz(rotation_coeffs[c], qr_control, qr_target)

        elif len(qr_control) == 1:
            if self.basis == "x":
                circuit.crx(rotation_coeffs[c], qr_control[0], qr_target)
            elif self.basis == "y":
                circuit.cry(rotation_coeffs[c], qr_control[0], qr_target)
            else:
                circuit.crz(rotation_coeffs[c], qr_control[0], qr_target)

    self.definition = circuit

def _define(self):
    quadratic, linear, offset = self.quadratic, self.linear, self.offset

    qr_input = QuantumRegister(self.num_input_qubits)
    qr_result = QuantumRegister(self.num_result_qubits)
    circuit = QuantumCircuit(qr_input, qr_result)

    # set quadratic and linear again to None if they were None
    if len(quadratic) == 0:
        quadratic = None

    if len(linear) == 0:
        linear = None

    scaling = np.pi * 2 ** (1 - self.num_result_qubits)

    # initial QFT
    qft = QFTGate(self.num_result_qubits)
    circuit.append(qft, qr_result)

    # constant coefficient
    if offset != 0:
        for i, q_i in enumerate(qr_result):
            circuit.p(scaling * 2**i * offset, q_i)

    # the linear part consists of the vector and the diagonal of the
    # matrix, since x_i * x_i = x_i, as x_i is a binary variable
    for j in range(self.num_input_qubits):
        value = linear[j] if linear is not None else 0
        value += quadratic[j][j] if quadratic is not None else 0
        if value != 0:
            for i, q_i in enumerate(qr_result):
                circuit.cp(scaling * 2**i * value, qr_input[j], q_i)

    # the quadratic part adds A_ij and A_ji as x_i x_j == x_j x_i
    if quadratic is not None:
        for j in range(self.num_input_qubits):
            for k in range(j + 1, self.num_input_qubits):
                value = quadratic[j][k] + quadratic[k][j]
                if value != 0:
                    for i, q_i in enumerate(qr_result):
                        circuit.mcp(scaling * 2**i * value, [qr_input[j], qr_input[k]], q_i)

    # add the inverse QFT
    iqft = qft.inverse()
    circuit.append(iqft, qr_result)

    self.definition = circuit

def _define(self):
    circuit = QuantumCircuit(self.num_qubits, name="xor")
    amount = self.amount
    for i in range(self.num_qubits):
        bit = amount & 1
        amount = amount >> 1
        if bit == 1:
            circuit.x(i)

    self.definition = circuit

def pauli_evolution(self, pauli_string, time):
    """Get the evolution block for the given pauli string."""
    # for some reason this is in reversed order
    pauli_string = pauli_string[::-1]

    # trim the pauli string if identities are included
    trimmed = []
    indices = []
    for i, pauli in enumerate(pauli_string):
        if pauli != "I":
            trimmed += [pauli]
            indices += [i]

    evo = QuantumCircuit(len(pauli_string))

    if len(trimmed) == 0:
        return evo

    def basis_change(circuit, inverse=False):
        for i, pauli in enumerate(pauli_string):
            if pauli == "X":
                circuit.h(i)
            elif pauli == "Y":
                if inverse:
                    circuit.sxdg(i)
                else:
                    circuit.sx(i)

    def cx_chain(circuit, inverse=False):
        num_cx = len(indices) - 1
        for i in reversed(range(num_cx)) if inverse else range(num_cx):
            circuit.cx(indices[i], indices[i + 1])

    basis_change(evo)
    cx_chain(evo)
    evo.p(self.alpha * time, indices[-1])
    cx_chain(evo, inverse=True)
    basis_change(evo, inverse=True)
    return evo

def _define_from_label(self):
    q = QuantumRegister(self.num_qubits, "q")
    initialize_circuit = QuantumCircuit(q, name="init_def")

    for qubit, param in enumerate(reversed(self.params)):
        if param == "1":
            initialize_circuit.append(XGate(), [q[qubit]])
        elif param == "+":
            initialize_circuit.append(HGate(), [q[qubit]])
        elif param == "-":
            initialize_circuit.append(XGate(), [q[qubit]])
            initialize_circuit.append(HGate(), [q[qubit]])
        elif param == "r":  # |+i>
            initialize_circuit.append(HGate(), [q[qubit]])
            initialize_circuit.append(SGate(), [q[qubit]])
        elif param == "l":  # |-i>
            initialize_circuit.append(HGate(), [q[qubit]])
            initialize_circuit.append(SdgGate(), [q[qubit]])

    if self._inverse:
        initialize_circuit = initialize_circuit.inverse()

    return initialize_circuit

def _define(self):
    thetas = self.params[0]
    q = QuantumRegister(self.num_qubits, name="q")
    qc = QuantumCircuit(q)
    for i in range(self.num_qubits):
        for j in range(i + 1, self.num_qubits):
            # if theta is just a single angle, use that, otherwise use the correct index
            theta = thetas if not isinstance(thetas, Sequence) else thetas[i][j]
            qc._append(RXXGate(theta), [q[i], q[j]], [])

    self.definition = qc

def inverse(self, annotated: bool = False) -> Gate:
    """Return the inverse.

    Note that the resulting Gate object has an empty ``params`` property.
    """
    if not annotated:
        inverse_gate = Gate(
            name=self.name + "_dg", num_qubits=self.num_qubits, params=[]
        )  # removing the params because arrays are deprecated

        definition = QuantumCircuit(*self.definition.qregs)
        for inst in reversed(self._definition):
            definition._append(
                inst.replace(operation=inst.operation.inverse(annotated=annotated))
            )
        inverse_gate.definition = definition
    else:
        inverse_gate = super().inverse(annotated=annotated)
    return inverse_gate

def _define(self):
    """
    gate pauli (p1 a1,...,pn an) { p1 a1; ... ; pn an; }
    """

    from qiskit.circuit import QuantumCircuit, QuantumRegister

    gates = {"X": XGate, "Y": YGate, "Z": ZGate}
    q = QuantumRegister(len(self.params[0]), "q")
    qc = QuantumCircuit(q, name=f"{self.name}({self.params[0]})")

    paulis = self.params[0]
    for i, p in enumerate(reversed(paulis)):
        if p == "I":
            continue
        qc._append(CircuitInstruction(gates[p](), (q[i],), ()))
    self.definition = qc

def inverse(self, annotated: bool = False) -> Gate:
    """Return the inverse.

    This does not re-compute the decomposition for the multiplexer with the inverse of the
    gates but simply inverts the existing decomposition.
    """
    if not annotated:
        inverse_gate = Gate(
            name=self.name + "_dg", num_qubits=self.num_qubits, params=[]
        )  # removing the params because arrays are deprecated

        definition = QuantumCircuit(*self.definition.qregs)
        for inst in reversed(self._definition):
            definition._append(
                inst.replace(operation=inst.operation.inverse(annotated=annotated))
            )

        definition.global_phase = -self.definition.global_phase

        inverse_gate.definition = definition
    else:
        inverse_gate = super().inverse(annotated=annotated)
    return inverse_gate

def _dec_ucrot(self):
    """
    Finds a decomposition of a UC rotation gate into elementary gates
    (C-NOTs and single-qubit rotations).
    """
    q = QuantumRegister(self.num_qubits, "q")
    circuit = QuantumCircuit(q)
    q_target = q[0]
    q_controls = q[1:]
    if not q_controls:  # equivalent to: if len(q_controls) == 0
        if self.rot_axes == "X":
            if np.abs(self.params[0]) > _EPS:
                circuit.rx(self.params[0], q_target)
        if self.rot_axes == "Y":
            if np.abs(self.params[0]) > _EPS:
                circuit.ry(self.params[0], q_target)
        if self.rot_axes == "Z":
            if np.abs(self.params[0]) > _EPS:
                circuit.rz(self.params[0], q_target)
    else:
        # First, we find the rotation angles of the single-qubit rotations acting
        #  on the target qubit
        angles = self.params.copy()
        UCPauliRotGate._dec_uc_rotations(angles, 0, len(angles), False)
        # Now, it is easy to place the C-NOT gates to get back the full decomposition.
        for i, angle in enumerate(angles):
            if self.rot_axes == "X":
                if np.abs(angle) > _EPS:
                    circuit.rx(angle, q_target)
            if self.rot_axes == "Y":
                if np.abs(angle) > _EPS:
                    circuit.ry(angle, q_target)
            if self.rot_axes == "Z":
                if np.abs(angle) > _EPS:
                    circuit.rz(angle, q_target)
            # Determine the index of the qubit we want to control the C-NOT gate.
            # Note that it corresponds
            # to the number of trailing zeros in the binary representation of i+1
            if not i == len(angles) - 1:
                binary_rep = np.binary_repr(i + 1)
                q_contr_index = len(binary_rep) - len(binary_rep.rstrip("0"))
            else:
                # Handle special case:
                q_contr_index = len(q_controls) - 1
            # For X rotations, we have to additionally place some Ry gates around the
            # C-NOT gates. They change the basis of the NOT operation, such that the
            # decomposition of for uniformly controlled X rotations works correctly by symmetry
            # with the decomposition of uniformly controlled Z or Y rotations
            if self.rot_axes == "X":
                circuit.ry(np.pi / 2, q_target)
            circuit.cx(q_controls[q_contr_index], q_target)
            if self.rot_axes == "X":
                circuit.ry(-np.pi / 2, q_target)
    return circuit

def _define(self):
    """Calculate a subcircuit that implements this unitary."""
    if self.num_qubits == 1:
        from qiskit.synthesis.one_qubit.one_qubit_decompose import OneQubitEulerDecomposer

        q = QuantumRegister(1, "q")
        qc = QuantumCircuit(q)
        theta, phi, lam, global_phase = OneQubitEulerDecomposer("U").angles_and_phase(
            self.to_matrix()
        )
        qc._append(UGate(theta, phi, lam), [q[0]], [])
        qc.global_phase = global_phase
        self.definition = qc
    elif self.num_qubits == 2:
        from qiskit.synthesis.two_qubit.two_qubit_decompose import (
            two_qubit_cnot_decompose,
        )

        self.definition = two_qubit_cnot_decompose(self.to_matrix())
    else:

        mat = self.to_matrix()

        from qiskit.synthesis.unitary.qsd import qs_decomposition

        try:
            # The Rust code for Quantum Shannon Decomposition may return QiskitError
            # when linear algebra methods (e.g. Schur decomposition) fail.
            mat_def = qs_decomposition(mat)
        except QiskitError:
            mat_def = None

        # If QSD fails or provides numerically imprecise matrices, fallback on the
        # Isometry decomposition (which produces more gates but is more numerically
        # stable)
        from qiskit.quantum_info.operators import Operator

        if (mat_def is None) or not (
            matrix_equal(Operator(mat_def).to_matrix(), mat, atol=1e-7)
        ):
            mat_def = Isometry(self.to_matrix(), 0, 0).definition

        self.definition = mat_def

def _define(self):
    adjacency_matrix = self.adjacency_matrix
    circuit = QuantumCircuit(self.num_qubits)
    circuit.h(range(self.num_qubits))
    for i in range(self.num_qubits):
        for j in range(i + 1, self.num_qubits):
            if adjacency_matrix[i][j] == 1:
                circuit.cz(i, j)
    self.definition = circuit

def _build(self):
    num_state_qubits = self.oracle.num_qubits - self.oracle.num_ancillas
    circuit = QuantumCircuit(QuantumRegister(num_state_qubits, name="state"), name="Q")
    num_ancillas = numpy.max(
        [
            self.oracle.num_ancillas,
            self.zero_reflection.num_ancillas,
            self.state_preparation.num_ancillas,
        ]
    )
    if num_ancillas > 0:
        circuit.add_register(AncillaRegister(num_ancillas, name="ancilla"))

    circuit.compose(self.oracle, list(range(self.oracle.num_qubits)), inplace=True)
    if self._insert_barriers:
        circuit.barrier()
    circuit.compose(
        self.state_preparation.inverse(),
        list(range(self.state_preparation.num_qubits)),
        inplace=True,
    )
    if self._insert_barriers:
        circuit.barrier()
    circuit.compose(
        self.zero_reflection, list(range(self.zero_reflection.num_qubits)), inplace=True
    )
    if self._insert_barriers:
        circuit.barrier()
    circuit.compose(
        self.state_preparation, list(range(self.state_preparation.num_qubits)), inplace=True
    )

    # minus sign
    circuit.global_phase = numpy.pi

    self.add_register(*circuit.qregs)
    try:
        circuit_wrapped = circuit.to_gate()
    except QiskitError:
        circuit_wrapped = circuit.to_instruction()

    self.compose(circuit_wrapped, qubits=self.qubits, inplace=True)

def _evolve_operator(self, operator, time):

    from qiskit.circuit.library.hamiltonian_gate import HamiltonianGate

    # if the operator is specified as matrix use exact matrix exponentiation
    if isinstance(operator, Operator):
        gate = HamiltonianGate(operator, time)
    # otherwise, use the PauliEvolutionGate
    else:
        from qiskit.synthesis.evolution import LieTrotter

        evolution = LieTrotter() if self._evolution is None else self._evolution
        gate = PauliEvolutionGate(operator, time, synthesis=evolution)

    evolved = QuantumCircuit(operator.num_qubits)
    if not self.flatten:
        evolved.append(gate, evolved.qubits)
    else:
        evolved.compose(gate.definition, evolved.qubits, inplace=True)
    return evolved

def _build(self) -> None:
    """If not already built, build the circuit."""
    if self._is_built:
        return

    super()._build()

    if self.num_qubits == 0:
        return

    if not self._flatten:
        circuit = QuantumCircuit(*self.qregs, name=self.name)
    else:
        circuit = self

    # use the initial state as starting circuit, if it is set
    if self.initial_state:
        circuit.compose(self.initial_state.copy(), inplace=True, copy=False)

    param_iter = iter(self.ordered_parameters)

    # build the prepended layers
    self._build_additional_layers(circuit, "prepended")

    # main loop to build the entanglement and rotation layers
    for i in range(self.reps):
        # insert barrier if specified and there is a preceding layer
        if self._insert_barriers and (i > 0 or len(self._prepended_blocks) > 0):
            circuit.barrier()

        # build the rotation layer
        self._build_rotation_layer(circuit, param_iter, i)

        # barrier in between rotation and entanglement layer
        if self._insert_barriers and len(self._rotation_blocks) > 0:
            circuit.barrier()

        # build the entanglement layer
        self._build_entanglement_layer(circuit, param_iter, i)

    # add the final rotation layer
    if not self._skip_final_rotation_layer:
        if self.insert_barriers and self.reps > 0:
            circuit.barrier()
        self._build_rotation_layer(circuit, param_iter, self.reps)

    # add the appended layers
    self._build_additional_layers(circuit, "appended")

    # cast global phase to float if it has no free parameters
    if isinstance(circuit.global_phase, ParameterExpression):
        try:
            circuit.global_phase = float(circuit.global_phase)
        except TypeError:
            # expression contains free parameters
            pass

    if not self._flatten:
        try:
            block = circuit.to_gate()
        except QiskitError:
            block = circuit.to_instruction()

        self.append(block, self.qubits, copy=False)

def _measurement_circuit(num_qubits: int, pauli: Pauli):
    # Note: if pauli is I for all qubits, this function generates a circuit to measure only
    # the first qubit.
    # Although such an operator can be optimized out by interpreting it as a constant (1),
    # this optimization requires changes in various methods. So it is left as future work.
    qubit_indices = np.arange(pauli.num_qubits)[pauli.z | pauli.x]
    if not np.any(qubit_indices):
        qubit_indices = [0]
    meas_circuit = QuantumCircuit(
        QuantumRegister(num_qubits, "q"), ClassicalRegister(len(qubit_indices), f"__c_{pauli}")
    )
    for clbit, i in enumerate(qubit_indices):
        if pauli.x[i]:
            if pauli.z[i]:
                meas_circuit.sdg(i)
            meas_circuit.h(i)
        meas_circuit.measure(i, clbit)
    return meas_circuit, qubit_indices

def _define(self):
    self._definition = QuantumCircuit(1)
    for _ in [None] * self.params[0]:
        self._definition.id(0)

def _define(self):
    # This is a stripped-down version of the bytecode interpreter; there's very few opcodes that
    # we actually need to handle within gate bodies.

    qubits = [Qubit() for _ in [None] * self.num_qubits]
    qc = QuantumCircuit(qubits)
    for op in self._bytecode:
        if op.opcode == OpCode.Gate:
            gate_id, args, op_qubits = op.operands
            qc._append(
                CircuitInstruction(
                    self._gates[gate_id](*(_evaluate_argument(a, self.params) for a in args)),
                    [qubits[q] for q in op_qubits],
                )
            )
        elif op.opcode == OpCode.Barrier:
            op_qubits = op.operands[0]
            qc._append(
                CircuitInstruction(Barrier(len(op_qubits)), [qubits[q] for q in op_qubits])
            )
        else:
            raise ValueError(f"received invalid bytecode to build gate: {op}")
    self._definition = qc

def conjugate(self):
    circ = self.to_instruction()
    new_circ = QuantumCircuit(self.num_qubits)
    bit_indices = {bit: index for index, bit in enumerate(circ.definition.qubits)}
    for instruction in circ.definition:
        new_qubits = [bit_indices[tup] for tup in instruction.qubits]
        if instruction.operation.name == "p":
            params = 2 * np.pi - instruction.operation.params[0]
            new_circ.p(params, new_qubits)
        elif instruction.operation.name == "t":
            instruction.operation.name = "tdg"
            new_circ.append(instruction.operation, new_qubits)
        elif instruction.operation.name == "tdg":
            instruction.operation.name = "t"
            new_circ.append(instruction.operation, new_qubits)
        elif instruction.operation.name == "s":
            instruction.operation.name = "sdg"
            new_circ.append(instruction.operation, new_qubits)
        elif instruction.operation.name == "sdg":
            instruction.operation.name = "s"
            new_circ.append(instruction.operation, new_qubits)
        else:
            new_circ.append(instruction.operation, new_qubits)
    result = self._from_circuit(new_circ)
    return result

def to_instruction(self):
    """Convert to Pauli circuit instruction."""
    from math import pi

    pauli, phase = self._to_label(
        self.z, self.x, self._phase[0], full_group=False, return_phase=True
    )
    if len(pauli) == 1:
        gate = {"I": IGate(), "X": XGate(), "Y": YGate(), "Z": ZGate()}[pauli]
    else:
        gate = PauliGate(pauli)
    if not phase:
        return gate
    # Add global phase
    circuit = QuantumCircuit(self.num_qubits, name=str(self))
    circuit.global_phase = -phase * pi / 2
    circuit.append(gate, range(self.num_qubits))
    return circuit.to_instruction()

def _default_cz_synth_func(symmetric_mat):
    """
    Construct the layer of CZ gates from a symmetric matrix.
    """
    nq = symmetric_mat.shape[0]
    qc = QuantumCircuit(nq, name="CZ")

    for j in range(nq):
        for i in range(j):
            if symmetric_mat[i][j]:
                qc.cz(i, j)
    return qc

def synth_cnotdihedral_two_qubits(elem: CNOTDihedral) -> QuantumCircuit:
    """Decompose a :class:`.CNOTDihedral` element on a single qubit and two
    qubits into a :class:`.QuantumCircuit`.
    This decomposition has an optimal number of :class:`.CXGate`\\ s.

    Args:
        elem: A :class:`.CNOTDihedral` element.

    Returns:
        A circuit implementation of the :class:`.CNOTDihedral` element.

    Raises:
        QiskitError: if the element is not 1-qubit or 2-qubit :class:`.CNOTDihedral`.

    References:
        1. Shelly Garion and Andrew W. Cross, *On the structure of the CNOT-Dihedral group*,
           `arXiv:2006.12042 [quant-ph] <https://arxiv.org/abs/2006.12042>`_
    """

    circuit = QuantumCircuit(elem.num_qubits)

    if elem.num_qubits > 2:
        raise QiskitError(
            "Cannot decompose a CNOT-Dihedral element with more than 2 qubits. "
            "use synth_cnotdihedral_full function instead."
        )

    if elem.num_qubits == 1:
        if elem.poly.weight_0 != 0 or elem.linear != [[1]]:
            raise QiskitError("1-qubit element is not CNOT-Dihedral.")
        tpow0 = elem.poly.weight_1[0]
        xpow0 = elem.shift[0]
        if tpow0 > 0:
            circuit.p((tpow0 * np.pi / 4), [0])
        if xpow0 == 1:
            circuit.x(0)
        if tpow0 == 0 and xpow0 == 0:
            circuit.id(0)
        return circuit

    # case elem.num_qubits == 2:
    if elem.poly.weight_0 != 0:
        raise QiskitError("2-qubit element is not CNOT-Dihedral.")
    weight_1 = elem.poly.weight_1
    weight_2 = elem.poly.weight_2
    linear = elem.linear
    shift = elem.shift

    # CS subgroup
    if (linear == [[1, 0], [0, 1]]).all():
        [xpow0, xpow1] = shift

        # Dihedral class
        if weight_2 == [0]:
            [tpow0, tpow1] = weight_1
            if tpow0 > 0:
                circuit.p((tpow0 * np.pi / 4), [0])
            if xpow0 == 1:
                circuit.x(0)
            if tpow1 > 0:
                circuit.p((tpow1 * np.pi / 4), [1])
            if xpow1 == 1:
                circuit.x(1)
            if tpow0 == 0 and tpow1 == 0 and xpow0 == 0 and xpow1 == 0:
                circuit.id(0)
                circuit.id(1)

        # CS-like class
        if (weight_2 == [2] and xpow0 == xpow1) or (weight_2 == [6] and xpow0 != xpow1):
            tpow0 = (weight_1[0] - 2 * xpow1 - 4 * xpow0 * xpow1) % 8
            tpow1 = (weight_1[1] - 2 * xpow0 - 4 * xpow0 * xpow1) % 8
            if tpow0 > 0:
                circuit.p((tpow0 * np.pi / 4), [0])
            if xpow0 == 1:
                circuit.x(0)
            if tpow1 > 0:
                circuit.p((tpow1 * np.pi / 4), [1])
            if xpow1 == 1:
                circuit.x(1)
            # CS gate is implemented using 2 CX gates
            circuit.p((np.pi / 4), [0])
            circuit.p((np.pi / 4), [1])
            circuit.cx(0, 1)
            circuit.p((7 * np.pi / 4), [1])
            circuit.cx(0, 1)

        # CSdg-like class
        if (weight_2 == [6] and xpow0 == xpow1) or (weight_2 == [2] and xpow0 != xpow1):
            tpow0 = (weight_1[0] - 6 * xpow1 - 4 * xpow0 * xpow1) % 8
            tpow1 = (weight_1[1] - 6 * xpow0 - 4 * xpow0 * xpow1) % 8
            if tpow0 > 0:
                circuit.p((tpow0 * np.pi / 4), [0])
            if xpow0 == 1:
                circuit.x(0)
            if tpow1 > 0:
                circuit.p((tpow1 * np.pi / 4), [1])
            if xpow1 == 1:
                circuit.x(1)
            # CSdg gate is implemented using 2 CX gates
            circuit.p((7 * np.pi / 4), [0])
            circuit.p((7 * np.pi / 4), [1])
            circuit.cx(0, 1)
            circuit.p((np.pi / 4), [1])
            circuit.cx(0, 1)

        # CZ-like class
        if weight_2 == [4]:
            tpow0 = (weight_1[0] - 4 * xpow1) % 8
            tpow1 = (weight_1[1] - 4 * xpow0) % 8
            if tpow0 > 0:
                circuit.p((tpow0 * np.pi / 4), [0])
            if xpow0 == 1:
                circuit.x(0)
            if tpow1 > 0:
                circuit.p((tpow1 * np.pi / 4), [1])
            if xpow1 == 1:
                circuit.x(1)
            # CZ gate is implemented using 2 CX gates
            circuit.cz(1, 0)

    # CX01-like class
    if (linear == [[1, 0], [1, 1]]).all():
        xpow0 = shift[0]
        xpow1 = (shift[1] + xpow0) % 2
        if xpow0 == xpow1:
            m = ((8 - weight_2[0]) / 2) % 4
            tpow0 = (weight_1[0] - m) % 8
            tpow1 = (weight_1[1] - m) % 8
        else:
            m = (weight_2[0] / 2) % 4
            tpow0 = (weight_1[0] + m) % 8
            tpow1 = (weight_1[1] + m) % 8
        if tpow0 > 0:
            circuit.p((tpow0 * np.pi / 4), [0])
        if xpow0 == 1:
            circuit.x(0)
        if tpow1 > 0:
            circuit.p((tpow1 * np.pi / 4), [1])
        if xpow1 == 1:
            circuit.x(1)
        circuit.cx(0, 1)
        if m > 0:
            circuit.p((m * np.pi / 4), [1])

    # CX10-like class
    if (linear == [[1, 1], [0, 1]]).all():
        xpow1 = shift[1]
        xpow0 = (shift[0] + xpow1) % 2
        if xpow0 == xpow1:
            m = ((8 - weight_2[0]) / 2) % 4
            tpow0 = (weight_1[0] - m) % 8
            tpow1 = (weight_1[1] - m) % 8
        else:
            m = (weight_2[0] / 2) % 4
            tpow0 = (weight_1[0] + m) % 8
            tpow1 = (weight_1[1] + m) % 8
        if tpow0 > 0:
            circuit.p((tpow0 * np.pi / 4), [0])
        if xpow0 == 1:
            circuit.x(0)
        if tpow1 > 0:
            circuit.p((tpow1 * np.pi / 4), [1])
        if xpow1 == 1:
            circuit.x(1)
        circuit.cx(1, 0)
        if m > 0:
            circuit.p((m * np.pi / 4), [0])

    # CX01*CX10-like class
    if (linear == [[0, 1], [1, 1]]).all():
        xpow1 = shift[0]
        xpow0 = (shift[1] + xpow1) % 2
        if xpow0 == xpow1:
            m = ((8 - weight_2[0]) / 2) % 4
            tpow0 = (weight_1[0] - m) % 8
            tpow1 = (weight_1[1] - m) % 8
        else:
            m = (weight_2[0] / 2) % 4
            tpow0 = (weight_1[0] + m) % 8
            tpow1 = (weight_1[1] + m) % 8
        if tpow0 > 0:
            circuit.p((tpow0 * np.pi / 4), [0])
        if xpow0 == 1:
            circuit.x(0)
        if tpow1 > 0:
            circuit.p((tpow1 * np.pi / 4), [1])
        if xpow1 == 1:
            circuit.x(1)
        circuit.cx(0, 1)
        circuit.cx(1, 0)
        if m > 0:
            circuit.p((m * np.pi / 4), [1])

    # CX10*CX01-like class
    if (linear == [[1, 1], [1, 0]]).all():
        xpow0 = shift[1]
        xpow1 = (shift[0] + xpow0) % 2
        if xpow0 == xpow1:
            m = ((8 - weight_2[0]) / 2) % 4
            tpow0 = (weight_1[0] - m) % 8
            tpow1 = (weight_1[1] - m) % 8
        else:
            m = (weight_2[0] / 2) % 4
            tpow0 = (weight_1[0] + m) % 8
            tpow1 = (weight_1[1] + m) % 8
        if tpow0 > 0:
            circuit.p((tpow0 * np.pi / 4), [0])
        if xpow0 == 1:
            circuit.x(0)
        if tpow1 > 0:
            circuit.p((tpow1 * np.pi / 4), [1])
        if xpow1 == 1:
            circuit.x(1)
        circuit.cx(1, 0)
        circuit.cx(0, 1)
        if m > 0:
            circuit.p((m * np.pi / 4), [0])

    # CX01*CX10*CX01-like class
    if (linear == [[0, 1], [1, 0]]).all():
        xpow0 = shift[1]
        xpow1 = shift[0]
        if xpow0 == xpow1:
            m = ((8 - weight_2[0]) / 2) % 4
            tpow0 = (weight_1[0] - m) % 8
            tpow1 = (weight_1[1] - m) % 8
        else:
            m = (weight_2[0] / 2) % 4
            tpow0 = (weight_1[0] + m) % 8
            tpow1 = (weight_1[1] + m) % 8
        if tpow0 > 0:
            circuit.p((tpow0 * np.pi / 4), [0])
        if xpow0 == 1:
            circuit.x(0)
        if tpow1 > 0:
            circuit.p((tpow1 * np.pi / 4), [1])
        if xpow1 == 1:
            circuit.x(1)
        circuit.cx(0, 1)
        circuit.cx(1, 0)
        if m > 0:
            circuit.p((m * np.pi / 4), [1])
        circuit.cx(0, 1)

    return circuit

def _synth_mcx_special_cases(num_ctrl_qubits: int) -> QuantumCircuit:
    """Internal function that produces default MCX circuits when num_ctrl_qubits is 0, 1, or 2."""
    if num_ctrl_qubits == 0:
        qc = QuantumCircuit(1)
        qc.x(0)
        return qc

    elif num_ctrl_qubits == 1:
        qc = QuantumCircuit(2)
        qc.cx(0, 1)
        return qc

    elif num_ctrl_qubits == 2:
        qc = QuantumCircuit(3)
        qc.ccx(0, 1, 2)
        return qc

    else:
        raise QiskitError(
            "_synth_mcx_special_cases should be called with only 0, 1, or 2 controls."
        )

def _contract_control_flow(inst):
    """Contract a `CircuitInstruction` containing a control-flow operation.

    Returns the input object by the same reference if there's no contraction to be done at the call
    site, though nested control-flow ops may have been contracted in place."""
    op = inst.operation
    idle = set(inst.qubits)
    for block in op.blocks:
        qubit_map = dict(zip(block.qubits, inst.qubits))
        for i, inner in enumerate(block.data):
            if inner.is_control_flow():
                # In `QuantumCircuit` it's easy to replace an instruction with a narrower one, so it
                # doesn't matter much if this is replacing it with itself.
                block.data[i] = inner = _contract_control_flow(inner)
            for qubit in inner.qubits:
                idle.discard(qubit_map[qubit])
    # If a box, we still want the prior side-effect of contracting any internal control-flow
    # operations (optimisations are still valid _within_ a box), but we don't want to contract the
    # box itself.  If there's no idle qubits, we're also done here.
    if not idle or inst.name == "box":
        return inst

    def contract(block):
        out = QuantumCircuit(
            name=block.name,
            global_phase=block.global_phase,
            metadata=block.metadata,
            captures=block.iter_captures(),
        )
        out.add_bits(
            [
                block_qubit
                for (block_qubit, inst_qubit) in zip(block.qubits, inst.qubits)
                if inst_qubit not in idle
            ]
        )
        out.add_bits(block.clbits)
        for creg in block.cregs:
            out.add_register(creg)
        # Control-flow ops can only have captures and locals, and we already added the captures.
        for var in block.iter_declared_vars():
            out.add_uninitialized_var(var)
        for stretch in block.iter_declared_stretches():
            out.add_stretch(stretch)
        for inner in block:
            out._append(inner)
        return out

    return inst.replace(
        operation=op.replace_blocks(contract(block) for block in op.blocks),
        qubits=[qubit for qubit in inst.qubits if qubit not in idle],
    )

def run(self, high_level_object, coupling_map=None, target=None, qubits=None, **options):
    if not isinstance(high_level_object, MCMTGate):
        return None

    base_gate = high_level_object.base_gate
    ctrl_state = options.get("ctrl_state", None)

    if high_level_object.num_target_qubits == 1:
        # no broadcasting needed (makes for better circuit diagrams)
        circuit = QuantumCircuit(high_level_object.num_qubits)
        circuit.append(
            base_gate.control(
                high_level_object.num_ctrl_qubits, ctrl_state=ctrl_state, annotated=False
            ),
            circuit.qubits,
        )

    else:
        base = QuantumCircuit(high_level_object.num_target_qubits, name=high_level_object.label)
        for i in range(high_level_object.num_target_qubits):
            base.append(base_gate, [i], [])

        circuit = base.control(
            high_level_object.num_ctrl_qubits, ctrl_state=ctrl_state, annotated=False
        )

    return circuit.decompose()

def _apply_annotations(circuit: QuantumCircuit, modifiers: list[Modifier]) -> QuantumCircuit:
    """
    Applies modifiers to a quantum circuit.
    """
    for modifier in modifiers:
        if isinstance(modifier, InverseModifier):
            circuit = circuit.inverse()

        elif isinstance(modifier, ControlModifier):
            if circuit.num_clbits > 0:
                raise TranspilerError(
                    "AnnotatedSynthesisDefault: cannot control a circuit with classical bits."
                )

            # Apply the control modifier to each gate in the circuit.
            controlled_circuit = QuantumCircuit(modifier.num_ctrl_qubits + circuit.num_qubits)
            if circuit.global_phase != 0:
                controlled_op = GlobalPhaseGate(circuit.global_phase).control(
                    num_ctrl_qubits=modifier.num_ctrl_qubits,
                    label=None,
                    ctrl_state=modifier.ctrl_state,
                    annotated=False,
                )
                controlled_qubits = list(range(modifier.num_ctrl_qubits))
                controlled_circuit.append(controlled_op, controlled_qubits)
            for inst in circuit:
                inst_op = inst.operation
                inst_qubits = inst.qubits
                controlled_op = inst_op.control(
                    num_ctrl_qubits=modifier.num_ctrl_qubits,
                    label=None,
                    ctrl_state=modifier.ctrl_state,
                    annotated=False,
                )
                controlled_qubits = list(range(modifier.num_ctrl_qubits)) + [
                    modifier.num_ctrl_qubits + circuit.find_bit(q).index for q in inst_qubits
                ]
                controlled_circuit.append(controlled_op, controlled_qubits)

            circuit = controlled_circuit

            if isinstance(circuit, AnnotatedOperation):
                raise TranspilerError(
                    "AnnotatedSynthesisDefault: failed to synthesize the control modifier."
                )

        elif isinstance(modifier, PowerModifier):
            circuit = circuit.power(modifier.power)

        else:
            raise TranspilerError(f"AnnotatedSynthesisDefault: Unknown modifier {modifier}.")

    return circuit

def _define(self):
    circuit = QuantumCircuit(1, name=self.name)
    self.definition = circuit

def _preprocess_for_gradient(objective, settings: Union[QiskitAerSimulationSettings, AerSimulator]):
    if objective._ansatz is not None:
        ansatz_num_qubits = objective._ansatz.num_qubits
        target_num_qubits = len(objective._target_tensornetwork.gamma)
        if ansatz_num_qubits != target_num_qubits:
            raise ValueError(
                "Ansatz and target have different numbers of qubits "
                f"({ansatz_num_qubits} vs. {target_num_qubits})."
            )
    gate_actions = preprocess_circuit_for_backtracking(objective._ansatz, settings)
    lhs_tensornetwork = tensornetwork_from_circuit(
        QuantumCircuit(objective._ansatz.num_qubits), settings
    )  # |0>
    return gate_actions, lhs_tensornetwork

def __init__(self, objective, settings):
    self.gate_actions = preprocess_circuit_for_backtracking(objective._ansatz, settings)
    self.lhs_tensornetwork = tensornetwork_from_circuit(
        QuantumCircuit(objective._ansatz.num_qubits), settings
    )  # |0>

def default(self, obj: Any) -> Any:
    if isinstance(obj, CouplingMap):
        return list(obj)
    if isinstance(obj, date):
        return {"__type__": "datetime", "__value__": obj.isoformat()}
    if isinstance(obj, complex):
        return {"__type__": "complex", "__value__": [obj.real, obj.imag]}
    if isinstance(obj, np.ndarray):
        if obj.dtype == object:
            return {"__type__": "ndarray", "__value__": obj.tolist()}
        value = _serialize_and_encode(obj, np.save, allow_pickle=False)
        return {"__type__": "ndarray", "__value__": value}
    if isinstance(obj, np.int64):
        return obj.item()
    if isinstance(obj, set):
        return {"__type__": "set", "__value__": list(obj)}
    if isinstance(obj, Result):
        return {"__type__": "Result", "__value__": obj.to_dict()}
    if hasattr(obj, "to_json"):
        return {"__type__": "to_json", "__value__": obj.to_json()}
    if isinstance(obj, QuantumCircuit):
        kwargs: dict[str, object] = {
            "version": min(SERVICE_MAX_SUPPORTED_QPY_VERSION, QISKIT_QPY_VERSION)
        }
        value = _serialize_and_encode(
            data=obj,
            serializer=lambda buff, data: dump(data, buff, RuntimeEncoder, **kwargs),
        )
        return {"__type__": "QuantumCircuit", "__value__": value}
    if isinstance(obj, Parameter):
        value = _serialize_and_encode(
            data=obj,
            serializer=_write_parameter,
            compress=False,
        )
        return {"__type__": "Parameter", "__value__": value}
    if isinstance(obj, ParameterView):
        return obj.data
    if isinstance(obj, Instruction):
        kwargs = {"version": min(SERVICE_MAX_SUPPORTED_QPY_VERSION, QISKIT_QPY_VERSION)}
        # Append instruction to empty circuit
        quantum_register = QuantumRegister(obj.num_qubits)
        quantum_circuit = QuantumCircuit(quantum_register)
        quantum_circuit.append(obj, quantum_register)
        value = _serialize_and_encode(
            data=quantum_circuit,
            serializer=lambda buff, data: dump(data, buff, **kwargs),
        )
        return {"__type__": "Instruction", "__value__": value}
    if isinstance(obj, ObservablesArray):
        return {"__type__": "ObservablesArray", "__value__": obj.tolist()}
    if isinstance(obj, BindingsArray):
        out_val = {"shape": obj.shape}
        encoded_data = {}
        for key, val in obj.data.items():
            encoded_data[json.dumps(key, cls=RuntimeEncoder)] = val
        out_val["data"] = encoded_data
        return {"__type__": "BindingsArray", "__value__": out_val}
    if isinstance(obj, BitArray):
        out_val = {"array": obj.array, "num_bits": obj.num_bits}
        return {"__type__": "BitArray", "__value__": out_val}
    if isinstance(obj, DataBin):
        out_val = {
            "field_names": list(obj),
            "shape": obj.shape,
            "fields": dict(obj.items()),
        }
        return {"__type__": "DataBin", "__value__": out_val}
    if isinstance(obj, EstimatorPub):
        return (
            obj.circuit,
            obj.observables.tolist(),
            obj.parameter_values.as_array(obj.circuit.parameters),
            obj.precision,
        )
    if isinstance(obj, SamplerPub):
        return (
            obj.circuit,
            obj.parameter_values.as_array(obj.circuit.parameters),
            obj.shots,
        )
    if isinstance(obj, EstimatorPubResult):
        out_val = {"data": obj.data, "metadata": obj.metadata}
        return {"__type__": "EstimatorPubResult", "__value__": out_val}
    if isinstance(obj, SamplerPubResult):
        out_val = {"data": obj.data, "metadata": obj.metadata}
        return {"__type__": "SamplerPubResult", "__value__": out_val}
    if isinstance(obj, PubResult):
        out_val = {"data": obj.data, "metadata": obj.metadata}
        return {"__type__": "PubResult", "__value__": out_val}
    if isinstance(obj, PrimitiveResult):
        out_val = {"pub_results": obj._pub_results, "metadata": obj.metadata}
        return {"__type__": "PrimitiveResult", "__value__": out_val}
    if isinstance(obj, NoiseLearnerResult):
        out_val = {"data": obj.data, "metadata": obj.metadata}
        return {"__type__": "NoiseLearnerResult", "__value__": out_val}
    if isinstance(obj, DoubleSliceSpan):
        out_val = {
            "start": obj.start,
            "stop": obj.stop,
            "data_slices": {
                idx: (shape, arg_sl.start, arg_sl.stop, shot_sl.start, shot_sl.stop)
                for idx, (shape, arg_sl, shot_sl) in obj._data_slices.items()
            },
        }
        return {"__type__": "DoubleSliceSpan", "__value__": out_val}
    if isinstance(obj, TwirledSliceSpanV2):
        out_val = {
            "start": obj.start,
            "stop": obj.stop,
            "data_slices": {
                idx: (x[0], x[1], x[2].start, x[2].stop, x[3].start, x[3].stop, y)
                for idx, x, y in zip(
                    obj._data_slices.keys(), obj._data_slices.values(), obj._pub_shots.values()
                )
            },
        }

        return {"__type__": "TwirledSliceSpanV2", "__value__": out_val}
    if isinstance(obj, TwirledSliceSpan):
        out_val = {
            "start": obj.start,
            "stop": obj.stop,
            "data_slices": {
                idx: (x[0], x[1], x[2].start, x[2].stop, x[3].start, x[3].stop)
                for idx, x in obj._data_slices.items()
            },
        }

        return {"__type__": "TwirledSliceSpan", "__value__": out_val}

    if isinstance(obj, SliceSpan):
        out_val = {
            "start": obj.start,
            "stop": obj.stop,
            "data_slices": {
                idx: (shape, data_slice.start, data_slice.stop)
                for idx, (shape, data_slice) in obj._data_slices.items()
            },
        }
        return {"__type__": "ExecutionSpan", "__value__": out_val}
    if isinstance(obj, ExecutionSpans):
        obj_type = "ExecutionSpans"
        out_val = {"spans": list(obj)}
        return {"__type__": obj_type, "__value__": out_val}
    if HAS_PAULI_LINDBLAD_MAP and isinstance(obj, PauliLindbladMap):
        out_val = {"paulis": obj.to_sparse_list(), "num_qubits": obj.num_qubits}
        return {"__type__": "PauliLindbladMap", "__value__": out_val}
    if "qiskit_aer" in sys.modules:
        # Guard import so qiskit_aer is not imported unnecessarily. If a
        # NoiseModel instance has been created, qiskit_aer must already have
        # been imported.
        from qiskit_aer.noise import NoiseModel

        if isinstance(obj, NoiseModel):
            return {"__type__": "NoiseModel", "__value__": obj.to_dict()}
    if hasattr(obj, "settings"):
        return {
            "__type__": "settings",
            "__module__": obj.__class__.__module__,
            "__class__": obj.__class__.__name__,
            "__value__": _set_int_keys_flag(copy.deepcopy(obj.settings)),
        }
    if hasattr(obj, "_json"):
        return {
            "__type__": "_json",
            "__module__": obj.__class__.__module__,
            "__class__": obj.__class__.__name__,
            "__value__": _set_int_keys_flag(copy.deepcopy(obj._json())),
        }
    if callable(obj):
        warnings.warn(f"Callable {obj} is not JSON serializable and will be set to None.")
        return None
    if "scipy" in sys.modules:
        # Guard import so scipy is not imported unnecessarily. If an
        # spmatrix instance has been created, scipy must already have
        # been imported.
        from scipy.sparse import save_npz, spmatrix

        if isinstance(obj, spmatrix):
            value = _serialize_and_encode(obj, save_npz, compress=False)
            return {"__type__": "spmatrix", "__value__": value}
    return super().default(obj)

def _construct(self, node_index):
    entry = self._target.qargs_graph[node_index]
    base_circuit = QuantumCircuit(entry.num_qubits)

    def extract_sub_qargs(node_indices, cur_node, outer_from_current):
        for parent, _, parent_from_child in self._target.qargs_graph.in_edges(cur_node):
            sub_outer_from_current, sub_current_from_outer = (
                {
                    parent: outer_from_current[child]
                    for child, parent in parent_from_child.items()
                },
                {
                    outer_from_current[child]: parent
                    for child, parent in parent_from_child.items()
                },
            )
            node_indices[frozenset(sub_current_from_outer)] = (
                parent,
                sub_current_from_outer,
            )
            extract_sub_qargs(node_indices, parent, sub_outer_from_current)
        return node_indices

    node_index_from_homogenized_qargs = extract_sub_qargs(
        {}, node_index, {i: i for i in range(entry.num_qubits)}
    )

    def rule_satisfied(name, homogenized_qargs):
        if len(homogenized_qargs) == entry.num_qubits:
            return False
        if (
            lookup := node_index_from_homogenized_qargs.get(frozenset(homogenized_qargs))
        ) is None:
            return False
        parent, qarg_lookup = lookup
        local_qargs = tuple(qarg_lookup[q] for q in homogenized_qargs)
        return (name, local_qargs) in self._constructed.get(parent, {})

    def score_equivalence(equivalence, current_constructed):
        total_score = [0] * len(self._score)
        for instruction in equivalence.decomposition.data:
            num_qubits = len(instruction.qubits)
            qargs = tuple(
                equivalence.decomposition.find_bit(q).index for q in instruction.qubits
            )
            if num_qubits == entry.num_qubits:
                constructed = current_constructed
                local_qargs = qargs
            else:
                parent, qarg_lookup = node_index_from_homogenized_qargs[frozenset(qargs)]
                constructed = self._constructed[parent]
                local_qargs = tuple(qarg_lookup[q] for q in qargs)
            total_score = [
                a + b
                for a, b in zip(total_score, constructed[instruction.name, local_qargs].score)
            ]
        return _CandidateRule(
            tuple(total_score),
            equivalence.name,
            equivalence.qargs,
            equivalence.decomposition,
        )

    candidates = []
    for instruction in entry.instructions:
        qc = QuantumCircuit(instruction.example.num_qubits, instruction.example.num_clbits)
        qc.append(instruction.example, qc.qubits, qc.clbits)
        qc.assign_parameters(
            dict(
                zip(
                    instruction.example.params,
                    _get_parameter_vector(len(instruction.example.params)),
                )
            ),
            inplace=True,
            flat_input=True,
            strict=False,
        )
        heapq.heappush(
            candidates,
            _CandidateRule(
                score=tuple(component.score_target(instruction) for component in self._score),
                name=instruction.name,
                qargs=instruction.qargs,
                abstract_decomposition=qc,
                # Rules that come from the `Target` are automatically concrete with themselves.
                # Setting this forms the base case of the recursion in reconstruction passes.
                concrete_decomposition=qc,
            ),
        )
    for instruction in self._target.instructions_global.get(entry.num_qubits, []):
        qc = QuantumCircuit(instruction.example.num_qubits, instruction.example.num_clbits)
        qc.append(instruction.example, qc.qubits, qc.clbits)
        qc.assign_parameters(
            dict(
                zip(
                    instruction.example.params,
                    _get_parameter_vector(len(instruction.example.params)),
                )
            ),
            inplace=True,
            flat_input=True,
            strict=False,
        )
        for permutation in itertools.permutations(range(entry.num_qubits)):
            heapq.heappush(
                candidates,
                _CandidateRule(
                    score=tuple(
                        component.score_target(instruction) for component in self._score
                    ),
                    name=instruction.name,
                    qargs=permutation,
                    abstract_decomposition=qc,
                    # Rules that come from the `Target` are automatically concrete with
                    # themselves.  Setting this forms the base case of the recursion in
                    # reconstruction passes.
                    concrete_decomposition=qc,
                ),
            )

    constructed = {}
    used_by = collections.defaultdict(list)
    available_rules = []
    for equivalences in self._equivalences_by_arity[entry.num_qubits].values():
        for equivalence in equivalences:
            for permutation in itertools.permutations(range(entry.num_qubits)):
                this_id = len(available_rules)
                permuted_equivalence = dataclasses.replace(
                    dataclasses.replace(equivalence, qargs=permutation),
                    decomposition=base_circuit.compose(equivalence.decomposition, permutation),
                )
                rules_needed = 0
                for (name, _), sub_qargs in permuted_equivalence.needs():
                    if rule_satisfied(name, sub_qargs):
                        continue
                    rules_needed += 1
                    used_by[name, sub_qargs].append(this_id)
                if rules_needed == 0:
                    heapq.heappush(
                        candidates,
                        score_equivalence(permuted_equivalence, constructed),
                    )
                else:
                    available_rules.append(_AvailableRule(permuted_equivalence, rules_needed))

    while candidates:
        best_rule = heapq.heappop(candidates)
        key = best_rule.key()
        if (previous := constructed.get(key)) is not None:
            _LOGGER.debug(
                "skipping previously constructed %r as %s>=%s",
                key,
                best_rule.score,
                previous.score,
            )
            continue
        _LOGGER.debug("constructing %r with score %s", key, best_rule.score)
        constructed[key] = best_rule
        for dependent in used_by[key]:
            rule = available_rules[dependent]
            rule.remaining -= 1
            if rule.remaining == 0 and rule.equivalence.key() not in constructed:
                heapq.heappush(candidates, score_equivalence(rule.equivalence, constructed))
    return constructed

def _to_circuit(cls, op):
    if isinstance(op, QuantumCircuit):
        return op
    if isinstance(op, tuple):
        inst, qubits = op
        circ = QuantumCircuit(max(qubits) + 1)
        circ.append(inst, qargs=qubits)
        return circ
    if isinstance(op, Instruction):
        if op.num_clbits > 0:
            raise NoiseError(
                f"Unable to convert instruction with clbits: {op.__class__.__name__}"
            )
        circ = QuantumCircuit(op.num_qubits)
        circ.append(op, qargs=list(range(op.num_qubits)))
        return circ
    if isinstance(op, QuantumChannel):
        if not op.is_cptp(atol=cls.atol):
            raise NoiseError("Input quantum channel is not CPTP.")
        try:
            return cls._to_circuit(Kraus(op).to_instruction())
        except QiskitError as err:
            raise NoiseError(
                f"Fail to convert {op.__class__.__name__} to Instruction."
            ) from err
    if isinstance(op, BaseOperator):
        if hasattr(op, "to_instruction"):
            try:
                return cls._to_circuit(op.to_instruction())
            except QiskitError as err:
                raise NoiseError(
                    f"Fail to convert {op.__class__.__name__} to Instruction."
                ) from err
        else:
            raise NoiseError(
                f"Unacceptable Operator, not implementing to_instruction: "
                f"{op.__class__.__name__}"
            )
    if isinstance(op, list):
        if all(isinstance(aop, tuple) for aop in op):
            num_qubits = max(max(qubits) for _, qubits in op) + 1
            circ = QuantumCircuit(num_qubits)
            for inst, qubits in op:
                try:
                    circ.append(inst, qargs=qubits)
                except CircuitError as err:
                    raise NoiseError(
                        f"Invalid operation type: {inst.__class__.__name__},"
                        f" not appendable to circuit."
                    ) from err
            return circ
        else:
            raise NoiseError(f"Invalid type of op list: {op}")

    raise NoiseError(f"Invalid noise op type {op.__class__.__name__}: {op}")

def _enlarge_qreg(qc: QuantumCircuit, num_qubits: int):
    if qc.num_qubits < num_qubits:
        enlarged = QuantumCircuit(num_qubits)
        return enlarged.compose(qc)
    return qc

def _thermal_relaxation_error(self, op: Instruction, qubits: Sequence[int]):
    """Return thermal relaxation error on each operand qubit"""

    duration = None

    if self._target is not None:
        if op.name == "delay":
            duration = op.duration
            if duration is not None:
                # Convert op duration to seconds
                if op.unit == "dt":
                    if self._dt is None:
                        raise NoiseError(
                            "RelaxationNoisePass cannot apply noise to a 'dt' unit duration"
                            " without a dt time set."
                        )
                    duration = op.duration * self._dt
                else:
                    duration = apply_prefix(op.duration, op.unit)
        else:
            op_props = self._target.get(op.name)
            if op_props is not None:
                inst_props = op_props.get(tuple(qubits))
                if inst_props is not None:
                    # get duration in seconds
                    duration = getattr(inst_props, "duration")
    else:
        try:
            duration = op.duration
            if duration is not None:
                # Convert op duration to seconds
                if op.unit == "dt":
                    if self._dt is None:
                        raise NoiseError(
                            "RelaxationNoisePass cannot apply noise to a 'dt' unit duration"
                            " without a dt time set."
                        )
                    duration = op.duration * self._dt
                else:
                    duration = apply_prefix(op.duration, op.unit)

        except AttributeError:
            duration = None

    if duration is None:
        warnings.warn(
            f"Instruction duration not found for {op.name}. RelaxationNoisePass ignores "
            "instructions without duration. "
            "To avoid this warning, provide the corresponding duration information via `target`.",
            UserWarning,
        )
        return None

    t1s = self._t1s[qubits]
    t2s = self._t2s[qubits]
    p1s = self._p1s[qubits]

    # pylint: disable=invalid-name
    if op.num_qubits == 1:
        t1, t2, p1 = t1s[0], t2s[0], p1s[0]
        if t1 == np.inf and t2 == np.inf:
            return None
        return thermal_relaxation_error(t1, t2, duration, p1)

    # General multi-qubit case
    noise = QuantumCircuit(op.num_qubits)
    for qubit, (t1, t2, p1) in enumerate(zip(t1s, t2s, p1s)):
        if t1 == np.inf and t2 == np.inf:
            # No relaxation on this qubit
            continue
        error = thermal_relaxation_error(t1, t2, duration, p1)
        noise.append(error.to_instruction(), [qubit])

    return noise

def _create_meas_circuit(self, basis: Pauli, circuit_index: int):
    qargs = np.arange(basis.num_qubits)[basis.z | basis.x]
    meas_circuit = QuantumCircuit(basis.num_qubits, len(qargs))
    for clbit, qarg in enumerate(qargs):
        if basis.x[qarg]:
            if basis.z[qarg]:
                meas_circuit.sdg(qarg)
            meas_circuit.h(qarg)
        meas_circuit.measure(qarg, clbit)
    meas_circuit.metadata = {"basis": basis}

    if self._skip_transpilation:
        return meas_circuit

    layout = self._layouts[circuit_index]
    passmanager = PassManager([SetLayout(layout)])
    opt1q = Optimize1qGatesDecomposition(target=self._backend.target)
    passmanager.append(opt1q)
    if isinstance(self._backend.coupling_map, CouplingMap):
        coupling_map = self._backend.coupling_map
        passmanager.append(FullAncillaAllocation(coupling_map))
        passmanager.append(EnlargeWithAncilla())
    passmanager.append(ApplyLayout())
    return passmanager.run(meas_circuit)

def visit_QuantumPhase(self, node: ast.QuantumPhase, context: State) -> State:
    gate = QuantumCircuit(global_phase=self._resolve_angle(node.argument, context)).to_gate()
    for modifier in reversed(node.modifiers):
        gate = self._apply_gate_modifier(modifier, gate, context)
    if not node.qubits:
        context.circuit.global_phase += gate.definition.global_phase
        return context
    for i, qubits in enumerate(
        self._broadcast_gate([self._resolve_qarg(qarg, context) for qarg in node.qubits], node)
    ):
        if i > 0:
            gate = gate.copy()
        context.circuit.append(gate, qubits, [])
    return context

