def encode(bits, bases):
    """This function encodes each bit into the given basis."""

    encoded_qubits = []

    for bit, basis in zip(bits, bases):
        qc = QuantumCircuit(1, 1) # Create a quantum circuit for each qubit

        # Possible Cases
        if bit=="0" and basis == "Z":
            encoded_qubits.append(qc) # Do not apply any gates

        elif bit=="1" and basis == "Z":
            qc.x(0) # Apply X Gate
            encoded_qubits.append(qc)

        elif bit=="0" and basis == "X":
            qc.h(0) # Apply H Gate
            encoded_qubits.append(qc)

        elif bit=="1" and basis == "X":
            qc.x(0) # Apply X Gate
            qc.h(0) # Apply H Gate
            encoded_qubits.append(qc)

    return (encoded_qubits)

def circuit_i():
    i_q = QuantumRegister(2, name='i_q')
    i_c = ClassicalRegister(2, name='i_c')
    initial_states = ['00','01','10','11']
    initial_circuits = {state: QuantumCircuit(i_q, i_c, name='%s'%(state)) \
                       for state in initial_states}
    final_circuits = {}
    for state in initial_states:
        if state[0] is '1':
            initial_circuits[state].x(i_q[0])
        if state[1] is '1':
            initial_circuits[state].x(i_q[1])

        initial_circuits[state].cx(i_q[0], i_q[1]) 

        initial_circuits[state].measure(i_q[0], i_c[0])
        initial_circuits[state].measure(i_q[1], i_c[1])
        final_circuits[state] = initial_circuits[state]
    return initial_circuits

