        else:
            qc.barrier()
            qc += oracle
            qc.barrier()

    def update_output():
        statevec = execute(qc, backend).result().get_statevector()
        msg.vec = vec_in_braket(statevec, nqubits)
        html_math.value = "$$ %s = %s $$" % (msg.ops, msg.vec)
        image.value = qc.draw('mpl')

    def on_hads_click(b):
        hadamards(qc, nqubits)
        if display_ancilla:
            msg.ops = "|{-}\\rangle\\otimes H^{\\otimes n}" + msg.ops[18:]
        else:
            msg.ops = "H^{\\otimes n}" + msg.ops            
        update_output()
    def on_oracle_click(b):
        apply_oracle(qc, nqubits)
        if display_ancilla:
            msg.ops = "|{-}\\rangle\\otimes U_f" + msg.ops[18:]
        else:
            msg.ops = "U_f" + msg.ops
        update_output()

    def on_clear_click(b):
        for i in range(len(qc.data)-2):
            qc.data.pop()
        msg.__init__()
        update_output()

    hads_btn = widgets.Button(description="H⊗ⁿ")
    hads_btn.on_click(on_hads_click)
    oracle_btn = widgets.Button(description="Oracle")
    oracle_btn.on_click(on_oracle_click)
    clear_btn = widgets.Button(description="Clear")
    clear_btn.on_click(on_clear_click)

    hbox = widgets.HBox([hads_btn, oracle_btn, clear_btn])
    html_math = widgets.HTMLMath()
    html_math.value = "$$ %s = %s $$" % (msg.ops, msg.vec)
    image = _img()
    image.value = qc.draw('mpl')
    display(hbox, html_math, image.widget)

def _gate_gradient(gate: Gate) -> Instruction:
    """Returns the derivative of the gate"""
    # pylint: disable=too-many-return-statements
    if isinstance(gate, RXGate):
        return CXGate()
    if isinstance(gate, RYGate):
        return CYGate()
    if isinstance(gate, RZGate):
        return CZGate()
    if isinstance(gate, RXXGate):
        cxx_circ = QuantumCircuit(3)
        cxx_circ.cx(0, 1)
        cxx_circ.cx(0, 2)
        cxx = cxx_circ.to_instruction()
        return cxx
    if isinstance(gate, RYYGate):
        cyy_circ = QuantumCircuit(3)
        cyy_circ.cy(0, 1)
        cyy_circ.cy(0, 2)
        cyy = cyy_circ.to_instruction()
        return cyy
    if isinstance(gate, RZZGate):
        czz_circ = QuantumCircuit(3)
        czz_circ.cz(0, 1)
        czz_circ.cz(0, 2)
        czz = czz_circ.to_instruction()
        return czz
    if isinstance(gate, RZXGate):
        czx_circ = QuantumCircuit(3)
        czx_circ.cx(0, 2)
        czx_circ.cz(0, 1)
        czx = czx_circ.to_instruction()
        return czx
    raise TypeError(f"Unrecognized parameterized gate, {gate}")

def _phi_add_gate(size: int, angles: Union[np.ndarray, ParameterVector]) -> Gate:
    """Gate that performs addition by a in Fourier Space."""
    circuit = QuantumCircuit(size, name="phi_add")
    for i, angle in enumerate(angles):
        circuit.p(angle, i)
    return circuit.to_gate()

def construct_circuit(self, mode='circuit', register=None):
    # pylint: disable=import-outside-toplevel
    from qiskit import BasicAer

    if mode == 'vector':
        if self._state_vector is None:
            if self._circuit is not None:
                self._state_vector = np.asarray(q_execute(self._circuit, BasicAer.get_backend(
                    'statevector_simulator')).result().get_statevector(self._circuit))
        return self._state_vector
    elif mode == 'circuit':
        if self._circuit is None:
            # create empty quantum circuit
            circuit = QuantumCircuit()

            if register is None:
                register = QuantumRegister(self._num_qubits, name='q')

            if isinstance(register, QuantumRegister):
                circuit.add_register(register)
            elif isinstance(register, list):
                for q in register:
                    if isinstance(q, Qubit):
                        if not circuit.has_register(q.register):
                            circuit.add_register(q.register)
                    else:
                        raise AquaError('Unexpected qubit type {}.'.format(type(q)))
            else:
                raise AquaError('Unexpected register type {}.'.format(type(register)))

            if self._state is None or self._state == 'random':
                svc = StateVectorCircuit(self._state_vector)
                svc.construct_circuit(circuit=circuit, register=register)
            elif self._state == 'uniform':
                for i in range(self._num_qubits):
                    circuit.h(register[i])
            elif self._state == 'zero':
                pass
            else:
                AquaError('Unexpected state mode {}.'.format(self._state))
            self._circuit = circuit
        return self._circuit.copy()
    else:
        raise AquaError('Mode should be either "vector" or "circuit"')

def construct_circuit(self, mode='circuit', register=None):
    if mode == 'vector':
        return np.array([1.0] + [0.0] * (np.power(2, self._num_qubits) - 1))
    elif mode == 'circuit':
        if register is None:
            register = QuantumRegister(self._num_qubits, name='q')
        quantum_circuit = QuantumCircuit(register)
        return quantum_circuit
    else:
        raise AquaError('Mode should be either "vector" or "circuit"')

def construct_circuit(self):
    """ construct circuit """
    if self._circuit is not None:
        return self._circuit
    self._output_register = QuantumRegister(self._num_outputs, name='o')
    self._variable_register = QuantumRegister(self._nbits, name='v')
    self._circuit = QuantumCircuit(self._variable_register, self._output_register)

    if self._esops:
        num_ancillae, self._ancillary_register = 0, None
        for i, e in enumerate(self._esops):
            num_ancillae = max(num_ancillae, e.compute_num_ancillae(self._mct_mode))
        if num_ancillae > 0:
            self._ancillary_register = QuantumRegister(num_ancillae, name='a')
            self._circuit.add_register(self._ancillary_register)

        for i, e in enumerate(self._esops):
            if e is not None:
                e.construct_circuit(
                    circuit=self._circuit,
                    variable_register=self._variable_register,
                    output_register=self._output_register,
                    output_idx=i,
                    ancillary_register=self._ancillary_register,
                    mct_mode=self._mct_mode
                )

    else:
        self._ancillary_register = None
    return self._circuit

def evolution_instruction(pauli_list, evo_time, num_time_slices,
                          controlled=False, power=1,
                          use_basis_gates=True, shallow_slicing=False,
                          barrier=False):
    """
    Construct the evolution circuit according to the supplied specification.

    Args:
        pauli_list (list([[complex, Pauli]])): The list of pauli terms corresponding
                                               to a single time slice to be evolved
        evo_time (Union(complex, float, Parameter, ParameterExpression)): The evolution time
        num_time_slices (int): The number of time slices for the expansion
        controlled (bool, optional): Controlled circuit or not
        power (int, optional): The power to which the unitary operator is to be raised
        use_basis_gates (bool, optional): boolean flag for indicating only using basis
                                          gates when building circuit.
        shallow_slicing (bool, optional): boolean flag for indicating using shallow
                                          qc.data reference repetition for slicing
        barrier (bool, optional): whether or not add barrier for every slice

    Returns:
        Instruction: The Instruction corresponding to specified evolution.

    Raises:
        AquaError: power must be an integer and greater or equal to 1
        ValueError: Unrecognized pauli
    """

    if not isinstance(power, int) or power < 1:
        raise AquaError("power must be an integer and greater or equal to 1.")

    state_registers = QuantumRegister(pauli_list[0][1].num_qubits)
    if controlled:
        inst_name = 'Controlled-Evolution^{}'.format(power)
        ancillary_registers = QuantumRegister(1)
        qc_slice = QuantumCircuit(state_registers, ancillary_registers, name=inst_name)
    else:
        inst_name = 'Evolution^{}'.format(power)
        qc_slice = QuantumCircuit(state_registers, name=inst_name)

    # for each pauli [IXYZ]+, record the list of qubit pairs needing CX's
    cnot_qubit_pairs = [None] * len(pauli_list)
    # for each pauli [IXYZ]+, record the highest index of the nontrivial pauli gate (X,Y, or Z)
    top_xyz_pauli_indices = [-1] * len(pauli_list)

    for pauli_idx, pauli in enumerate(reversed(pauli_list)):
        n_qubits = pauli[1].num_qubits
        # changes bases if necessary
        nontrivial_pauli_indices = []
        for qubit_idx in range(n_qubits):
            # pauli I
            if not pauli[1].z[qubit_idx] and not pauli[1].x[qubit_idx]:
                continue

            if cnot_qubit_pairs[pauli_idx] is None:
                nontrivial_pauli_indices.append(qubit_idx)

            if pauli[1].x[qubit_idx]:
                # pauli X
                if not pauli[1].z[qubit_idx]:
                    if use_basis_gates:
                        qc_slice.h(state_registers[qubit_idx])
                    else:
                        qc_slice.h(state_registers[qubit_idx])
                # pauli Y
                elif pauli[1].z[qubit_idx]:
                    if use_basis_gates:
                        qc_slice.u(pi / 2, -pi / 2, pi / 2, state_registers[qubit_idx])
                    else:
                        qc_slice.rx(pi / 2, state_registers[qubit_idx])
            # pauli Z
            elif pauli[1].z[qubit_idx] and not pauli[1].x[qubit_idx]:
                pass
            else:
                raise ValueError('Unrecognized pauli: {}'.format(pauli[1]))

        if nontrivial_pauli_indices:
            top_xyz_pauli_indices[pauli_idx] = nontrivial_pauli_indices[-1]

        # insert lhs cnot gates
        if cnot_qubit_pairs[pauli_idx] is None:
            cnot_qubit_pairs[pauli_idx] = list(zip(
                sorted(nontrivial_pauli_indices)[:-1],
                sorted(nontrivial_pauli_indices)[1:]
            ))

        for pair in cnot_qubit_pairs[pauli_idx]:
            qc_slice.cx(state_registers[pair[0]], state_registers[pair[1]])

        # insert Rz gate
        if top_xyz_pauli_indices[pauli_idx] >= 0:

            # Because Parameter does not support complexity number operation; thus, we do
            # the following tricks to generate parameterized instruction.
            # We assume the coefficient in the pauli is always real. and can not do imaginary time
            # evolution
            if isinstance(evo_time, (Parameter, ParameterExpression)):
                lam = 2.0 * pauli[0] / num_time_slices
                lam = lam.real if lam.imag == 0 else lam
                lam = lam * evo_time
            else:
                lam = (2.0 * pauli[0] * evo_time / num_time_slices).real

            if not controlled:
                if use_basis_gates:
                    qc_slice.p(lam, state_registers[top_xyz_pauli_indices[pauli_idx]])
                else:
                    qc_slice.rz(lam, state_registers[top_xyz_pauli_indices[pauli_idx]])
            else:
                if use_basis_gates:
                    qc_slice.p(lam / 2, state_registers[top_xyz_pauli_indices[pauli_idx]])
                    qc_slice.cx(ancillary_registers[0],
                                state_registers[top_xyz_pauli_indices[pauli_idx]])
                    qc_slice.p(-lam / 2, state_registers[top_xyz_pauli_indices[pauli_idx]])
                    qc_slice.cx(ancillary_registers[0],
                                state_registers[top_xyz_pauli_indices[pauli_idx]])
                else:
                    qc_slice.crz(lam, ancillary_registers[0],
                                 state_registers[top_xyz_pauli_indices[pauli_idx]])

        # insert rhs cnot gates
        for pair in reversed(cnot_qubit_pairs[pauli_idx]):
            qc_slice.cx(state_registers[pair[0]], state_registers[pair[1]])

        # revert bases if necessary
        for qubit_idx in range(n_qubits):
            if pauli[1].x[qubit_idx]:
                # pauli X
                if not pauli[1].z[qubit_idx]:
                    if use_basis_gates:
                        qc_slice.h(state_registers[qubit_idx])
                    else:
                        qc_slice.h(state_registers[qubit_idx])
                # pauli Y
                elif pauli[1].z[qubit_idx]:
                    if use_basis_gates:
                        qc_slice.u(-pi / 2, -pi / 2, pi / 2, state_registers[qubit_idx])
                    else:
                        qc_slice.rx(-pi / 2, state_registers[qubit_idx])
    # repeat the slice
    if shallow_slicing:
        logger.info('Under shallow slicing mode, the qc.data reference is repeated shallowly. '
                    'Thus, changing gates of one slice of the output circuit might affect '
                    'other slices.')
        if barrier:
            qc_slice.barrier(state_registers)
        qc_slice.data *= (num_time_slices * power)
        qc = qc_slice
    else:
        qc = QuantumCircuit(*qc_slice.qregs, name=inst_name)
        for _ in range(num_time_slices * power):
            qc.append(qc_slice, qc.qubits)
            if barrier:
                qc.barrier(state_registers)
    return qc.to_instruction()

def tensor(self, other: OperatorBase) -> OperatorBase:
    # pylint: disable=cyclic-import,import-outside-toplevel
    from .pauli_op import PauliOp
    from .matrix_op import MatrixOp
    if isinstance(other, (PauliOp, CircuitOp, MatrixOp)):
        other = other.to_circuit_op()

    if isinstance(other, CircuitOp):
        new_qc = QuantumCircuit(self.num_qubits + other.num_qubits)
        # NOTE!!! REVERSING QISKIT ENDIANNESS HERE
        new_qc.append(other.to_instruction(),
                      qargs=new_qc.qubits[0:other.primitive.num_qubits])  # type: ignore
        new_qc.append(self.to_instruction(),
                      qargs=new_qc.qubits[other.primitive.num_qubits:])  # type: ignore
        new_qc = new_qc.decompose()
        return CircuitOp(new_qc, coeff=self.coeff * other.coeff)

    return TensoredOp([self, other])

def to_circuit(self) -> QuantumCircuit:
    """ Returns a ``QuantumCircuit`` equivalent to this Operator. """
    qc = QuantumCircuit(self.num_qubits)
    qc.append(self.to_instruction(), qargs=range(self.primitive.num_qubits))  # type: ignore
    return qc.decompose()

def from_dict(density_dict: dict) -> 'CircuitStateFn':
    """ Construct the CircuitStateFn from a dict mapping strings to probability densities.

    Args:
        density_dict: The dict representing the desired state.

    Returns:
        The CircuitStateFn created from the dict.
    """
    # If the dict is sparse (elements <= qubits), don't go
    # building a statevector to pass to Qiskit's
    # initializer, just create a sum.
    if len(density_dict) <= len(list(density_dict.keys())[0]):
        statefn_circuits = []
        for bstr, prob in density_dict.items():
            qc = QuantumCircuit(len(bstr))
            # NOTE: Reversing endianness!!
            for (index, bit) in enumerate(reversed(bstr)):
                if bit == '1':
                    qc.x(index)
            sf_circuit = CircuitStateFn(qc, coeff=prob)
            statefn_circuits += [sf_circuit]
        if len(statefn_circuits) == 1:
            return statefn_circuits[0]
        else:
            return cast(CircuitStateFn, SummedOp(cast(List[OperatorBase], statefn_circuits)))
    else:
        sf_dict = StateFn(density_dict)
        return CircuitStateFn.from_vector(sf_dict.to_matrix())

def get_controlled_circuit(circuit, ctl_qubit, tgt_circuit=None, use_basis_gates=True):
    """
    Construct the controlled version of a given circuit.

    Args:
        circuit (QuantumCircuit) : the base circuit
        ctl_qubit (Qubit) : the control qubit to use
        tgt_circuit (QuantumCircuit) : the target controlled circuit to be modified in-place
        use_basis_gates (bool) : boolean flag to indicate whether or not
                                only basis gates should be used

    Return:
        QuantumCircuit: a QuantumCircuit object with the base circuit being controlled by ctl_qubit
    Raises:
        RuntimeError: unexpected operation
    """
    if tgt_circuit is not None:
        qc = tgt_circuit
    else:
        qc = QuantumCircuit()

    # get all the qubits and clbits
    qregs = circuit.qregs
    qubits = []
    for qreg in qregs:
        if not qc.has_register(qreg):
            qc.add_register(qreg)
        qubits.extend(qreg)
    cregs = circuit.cregs
    clbits = []
    for creg in cregs:
        if not qc.has_register(creg):
            qc.add_register(creg)
        clbits.extend(creg)

    # get all operations
    unroller = Unroller(basis=['u', 'p', 'cx'])
    ops = dag_to_circuit(unroller.run(circuit_to_dag(circuit))).data

    # process all basis gates to add control
    if not qc.has_register(ctl_qubit._register):
        qc.add_register(ctl_qubit._register)
    for op in ops:
        if op[0].name == 'id':
            apply_cu(qc, 0, 0, 0, ctl_qubit, op[1][0], use_basis_gates=use_basis_gates)
        elif op[0].name == 'p':
            apply_cp(qc, *op[0].params, ctl_qubit, op[1][0], use_basis_gates=use_basis_gates)
        elif op[0].name == 'u':
            apply_cu(qc, *op[0].params, ctl_qubit, op[1][0], use_basis_gates=use_basis_gates)
        elif op[0].name == 'cx':
            apply_ccx(qc, ctl_qubit, op[1][0], op[1][1], use_basis_gates=use_basis_gates)
        elif op[0].name == 'measure':
            qc.measure(op[1], op[2])
        elif op[0].name == 'barrier':
            qc.barrier(op[1])
        else:
            raise RuntimeError('Unexpected operation {}.'.format(op[0].name))

    return qc

def construct_circuit(self, parameters, q=None):
    """
    Construct the variational form, given its parameters.

    Args:
        parameters (Union(numpy.ndarray, list[Parameter], ParameterVector)): circuit parameters
        q (QuantumRegister, optional): Quantum Register for the circuit.

    Returns:
        QuantumCircuit: a quantum circuit with given `parameters`

    Raises:
        ValueError: the number of parameters is incorrect.
    """
    if len(parameters) != self._num_parameters:
        raise ValueError('The number of parameters has to be {}'.format(self._num_parameters))

    if q is None:
        q = QuantumRegister(self._num_qubits, name='q')
    if isinstance(self._initial_state, QuantumCircuit):
        circuit = QuantumCircuit(q)
        circuit.compose(self._initial_state, inplace=True)
    elif isinstance(self._initial_state, InitialState):
        circuit = self._initial_state.construct_circuit('circuit', q)
    else:
        circuit = QuantumCircuit(q)

    if logger.isEnabledFor(logging.DEBUG) and self._logging_construct_circuit:
        logger.debug("Evolving hopping operators:")
        TextProgressBar(sys.stderr)
        self._logging_construct_circuit = False

    num_excitations = len(self._hopping_ops)

    if not self.uccd_singlet:
        list_excitation_operators = [
            (self._hopping_ops[index % num_excitations], parameters[index])
            for index in range(self._reps * num_excitations)]
    else:
        list_excitation_operators = []
        counter = 0
        for i in range(int(self._reps * self.num_groups)):
            for _ in range(len(self._double_excitations_grouped[i % self.num_groups])):
                list_excitation_operators.append((self._hopping_ops[counter],
                                                  parameters[i]))
                counter += 1

    # TODO to uncomment to update for Operator flow:
    # from functools import reduce
    # ops = [(qubit_op.to_opflow().to_matrix_op() * param).exp_i()
    #        for (qubit_op, param) in list_excitation_operators]
    # circuit += reduce(lambda x, y: x @ y, reversed(ops)).to_circuit()
    # return circuit

    results = parallel_map(UCCSD._construct_circuit_for_one_excited_operator,
                           list_excitation_operators,
                           task_args=(q, self._num_time_slices),
                           num_processes=aqua_globals.num_processes)

    if self._shallow_circuit_concat:
        for qc in results:
            for _, qbits, _ in qc._data:
                for i, _ in enumerate(qbits):
                    qbits[i] = circuit.qubits[qbits[i].index]
        for qc in results:
            circuit._data += qc._data
    else:
        for qc in results:
            circuit += qc

    return circuit

def make_bell_circs(layered_coupling_map, conf, cxnum):
    """
    run simultaneous bell test. simultaneous pairs are obtained from get_layered_coupling_map
    We assume each cr ran only one time
    (e.g. [[1_2, 3_4], [5_6, 7_8]] is okay, but [[1_2, 3_4], [1_2, 5_6, 7_8]] is not okay)
    """

    n_reset = 2
    cxnum = 5
    insert_barrier = False

    hadamard_idle = False
    y_basis = False
    measure_idle = False
    circs = []

    for coupling_map in layered_coupling_map:
        bits = flatten_bits(coupling_map)
        nbits = len(bits)

        qc = QuantumCircuit(conf.n_qubits, nbits)
        # prepare qubits in superposition and then reset (conditionally) if requested
        if n_reset > 0:
            for bit in bits:
                qc.h(bit)
            for rnum in range(n_reset):
                qc.barrier()
                for bit in bits:
                    qc.reset(bit)
            qc.barrier()
        elif insert_barrier:
            qc.barrier(bits)
        # now do the Bell state
        if hadamard_idle:  # Hadamard all qubits except CNOT targets
            for i in range(conf.n_qubits):
                if i not in [edge[1] for edge in coupling_map]:
                    qc.h(i)
        else:  # Hadamard only CNOT control qubits
            for edge in coupling_map:
                qc.h(edge[0])
        for i in range(cxnum):
            if insert_barrier:
                qc.barrier(bits)
            for edge in coupling_map:
                qc.cx(edge[0], edge[1])
                qc.barrier(edge[0], edge[1])
        if y_basis:
            if insert_barrier:
                qc.barrier(bits)
            for edge in coupling_map:
                qc.s(edge[0])
                qc.sdg(edge[1])
                qc.h(edge[0])
                qc.h(edge[1])
        if measure_idle:
            full_list = list(range(conf.n_qubits))
            qc.measure(full_list, full_list)
        else:
            qc.measure(bits, list(range(nbits)))

        qc.metadata["coupling_map"] = coupling_map
        qc.metadata["cxnum"] = cxnum
        circs.append(qc)
    return circs

def circuits(self) -> List[QuantumCircuit]:
    """Return a list of RB circuits.

    Returns:
        A list of :class:`QuantumCircuit`.
    """
    rng = default_rng(seed=self.seed)

    n_qubits = self.num_qubits

    # Construct interleaved parts
    ff_circs = []
    for ff_type in self.ff_operations:
        ff_circs.append(self.ff_circ(ff_type))

    circuits = []

    for i in range(self.num_samples):
        for length in self.n_blocks:
            generators = (
                self._generate_sequences(length * self.cliff_per_meas, rng)
                for _ in range(n_qubits - 1)
            )

            # Generate MCM RB circuit
            circs = []
            for ff_type in self.ff_operations:
                circ = QuantumCircuit(n_qubits, n_qubits)
                circ.metadata = {
                    "xval": length,
                    "physical_qubits": self.physical_qubits,
                    "num_sample": i,
                    "ff_type": ff_type,
                }
                circs.append(circ)

            n_elms = 0
            for elms in zip(*generators):
                n_elms += 1
                for q, elm in enumerate(elms):
                    # Add a single random clifford
                    for inst in self._sequence_to_instructions(elm):
                        for circ in circs:
                            circ._append(inst, [circ.qubits[q]], [])
                # Sync time
                for circ in circs:
                    circ.barrier()
                if n_elms <= (length * self.cliff_per_meas) and (
                    np.mod(n_elms, self.cliff_per_meas) == 0
                ):
                    # Interleave MCM
                    for circ, ff_circ in zip(circs, ff_circs):
                        circ.compose(ff_circ, inplace=True, qubits=circ.qubits)
                        circ.barrier()
            for circ in circs:
                circ.barrier()
                circ.measure(circ.qubits, circ.clbits)

            circuits.extend(circs)

    return circuits

def run(self, dag: DAGCircuit) -> DAGCircuit:
    nodes_to_remove = []

    for node in dag.topological_op_nodes():
        if node.op.name == "gpi2" and node not in nodes_to_remove:
            successors = [
                succ
                for succ in dag.quantum_successors(node)
                if isinstance(succ, DAGOpNode)
            ]
            for next_node in successors:
                if next_node.op.name == "gpi2" and node.qargs == next_node.qargs:
                    phi1 = node.op.params[0]
                    phi2 = next_node.op.params[0]
                    if np.isclose(phi1, phi2):
                        qc = QuantumCircuit(dag.num_qubits())
                        qubit_index = dag.qubits.index(node.qargs[0])
                        qc.append(GPIGate(phi1), [qubit_index])
                        qc_dag = circuit_to_dag(qc)

                        wire_mapping = {qarg: qarg for qarg in next_node.qargs}

                        dag.substitute_node_with_dag(
                            next_node, qc_dag, wires=wire_mapping
                        )
                        nodes_to_remove.append(node)

    for node in nodes_to_remove:
        dag.remove_op_node(node)

    return dag

def default(self, obj: Any) -> Any:  # pylint: disable=arguments-renamed
    if istype(obj):
        return _serialize_type(obj)
    if hasattr(obj, "__json_encode__"):
        return _serialize_object(obj)
    if isinstance(obj, complex):
        return _serialize_safe_float(obj)
    if isinstance(obj, set):
        return {"__type__": "set", "__value__": list(obj)}
    if isinstance(obj, np.ndarray):
        value = _serialize_and_encode(obj, np.save, allow_pickle=False)
        return {"__type__": "ndarray", "__value__": value}
    if isinstance(obj, sps.spmatrix):
        value = _serialize_and_encode(obj, sps.save_npz, compress=False)
        return {"__type__": "spmatrix", "__value__": value}
    if isinstance(obj, bytes):
        return _serialize_bytes(obj)
    if isinstance(obj, datetime):
        return {"__type__": "datetime", "__value__": obj.isoformat()}
    if isinstance(obj, np.number):
        return obj.item()
    if dataclasses.is_dataclass(obj):
        # Note that dataclass.asdict recursively convert nested dataclass into dictionary.
        # Thus inter dataclass is unintentionally decoded as dictionary.
        # obj.__dict__ doesn't convert inter dataclass thus serialization
        # is offloaded to usual json serialization mechanism.
        return _serialize_object(obj, settings=obj.__dict__)
    if isinstance(obj, uncertainties.UFloat):
        # This could be UFloat (AffineScalarFunc) or Variable.
        # UFloat is a base class of Variable that contains parameter correlation.
        # i.e. Variable is special subclass for single number.
        # Since this object is not serializable, we will drop correlation information
        # during serialization. Then both can be serialized as Variable.
        # Note that UFloat doesn't have a tag.
        settings = {
            "value": _serialize_safe_float(obj.nominal_value),
            "std_dev": _serialize_safe_float(obj.std_dev),
            "tag": getattr(obj, "tag", None),
        }
        cls = uncertainties.core.Variable
        return {
            "__type__": "object",
            "__value__": {
                "class": _serialize_type(cls),
                "settings": settings,
                "version": get_object_version(cls),
            },
        }
    if isinstance(obj, lmfit.Model):
        # LMFIT Model object. Delegate serialization to LMFIT.
        return {
            "__type__": "LMFIT.Model",
            "__value__": obj.dumps(),
        }
    if isinstance(obj, Instruction):
        # Serialize gate by storing it in a circuit.
        circuit = QuantumCircuit(obj.num_qubits, obj.num_clbits)
        circuit.append(obj, range(obj.num_qubits), range(obj.num_clbits))
        value = _serialize_and_encode(
            data=circuit, serializer=lambda buff, data: qpy.dump(data, buff)
        )
        return {"__type__": "Instruction", "__value__": value}
    if isinstance(obj, QuantumCircuit):
        value = _serialize_and_encode(
            data=obj, serializer=lambda buff, data: qpy.dump(data, buff)
        )
        return {"__type__": "QuantumCircuit", "__value__": value}
    if isinstance(obj, ParameterExpression):
        value = _serialize_and_encode(
            data=obj,
            serializer=qpy._write_parameter_expression,
            compress=False,
        )
        return {"__type__": "ParameterExpression", "__value__": value}
    if istype(obj):
        return _serialize_type(obj)
    try:
        return super().default(obj)
    except TypeError:
        return _serialize_object(obj)

def calibration_circuit(num_qubits: int, state_label: str) -> QuantumCircuit:
    """Return a calibration circuit.

    This is an N-qubit circuit where N is the length of the label.
    The circuit consists of X-gates on qubits with label bits equal to 1,
    and measurements of all qubits.
    """
    circ = QuantumCircuit(num_qubits, name="meas_mit_cal_" + state_label)
    for i, val in enumerate(reversed(state_label)):
        if val == "1":
            circ.x(i)
    circ.measure_all()
    circ.metadata = {"state_label": state_label}
    return circ

