def _apply_qubit_layout(circuit: QuantumCircuit, physical_qubits: Sequence[int]) -> QuantumCircuit:
    # Mapping qubits in circuit to physical qubits (layout)
    res = QuantumCircuit(1 + max(physical_qubits), name=circuit.name, metadata=circuit.metadata)
    res.add_bits(circuit.clbits)
    for reg in circuit.cregs:
        res.add_register(reg)
    _circuit_compose(res, circuit, qubits=physical_qubits)
    if hasattr(circuit, "_parameter_table"):
        res._parameter_table = circuit._parameter_table
    return res

def _create_cliff_2q_layer_2():
    """Layer 2 consists of a Pauli gate on each qubit {Id, X, Y, Z}.
    Number of Cliffords == 16."""
    circuits = []
    pauli = ("i", XGate(), YGate(), ZGate())
    for p0, p1 in itertools.product(pauli, pauli):
        qc = QuantumCircuit(2)
        if p0 != "i":
            qc.append(p0, [0])
        if p1 != "i":
            qc.append(p1, [1])
        circuits.append(qc)
    return circuits

def __set_up_interleaved_op(self) -> None:
    # Convert interleaved element to transpiled circuit operation and store it for speed
    self._interleaved_op = self._interleaved_element
    # Convert interleaved element to circuit
    if isinstance(self._interleaved_op, Clifford):
        opts = self._get_synthesis_options()
        self._interleaved_op = _synthesize_clifford(self._interleaved_op, **opts)

    if isinstance(self._interleaved_op, QuantumCircuit):
        interleaved_circ = self._interleaved_op
    elif isinstance(self._interleaved_op, Gate):
        interleaved_circ = QuantumCircuit(self.num_qubits, name=self._interleaved_op.name)
        interleaved_circ.append(self._interleaved_op, list(range(self.num_qubits)))
    else:  # Delay
        interleaved_circ = []

    # Validate if all instructions in the interleaved circuit are supported in the backend
    if self.backend and hasattr(self.backend, "target"):
        for inst in interleaved_circ:
            qargs = tuple(
                self.physical_qubits[interleaved_circ.find_bit(q).index] for q in inst.qubits
            )
            if not self.backend.target.instruction_supported(inst.operation.name, qargs):
                raise QiskitError(
                    f"{inst.operation.name} in interleaved element is not supported"
                    f" on qubits {qargs} in the backend."
                )

    # Store interleaved operation as Instruction
    if isinstance(self._interleaved_op, QuantumCircuit):
        if not self._interleaved_op.name.startswith("Clifford"):
            self._interleaved_op.name = f"Clifford-{self._interleaved_op.name}"
        self._interleaved_op = self._interleaved_op.to_instruction()

def _define(self):
    """Gate decomposition."""
    qubits = QuantumRegister(self.num_qubits)
    circuit = QuantumCircuit(qubits, name=self.name)
    for instruction in _num_num_ansatz_spin_balanced_jw(
        qubits, self.num_num_ansatz_op
    ):
        circuit.append(instruction)
    self.definition = circuit

def _define(self):
    """Gate decomposition."""
    qubits = QuantumRegister(self.num_qubits)
    circuit = QuantumCircuit(qubits, name=self.name)
    alpha_qubits = qubits[: self.norb]
    beta_qubits = qubits[self.norb :]
    occ_a, occ_b = self.occupied_orbitals

    if np.array_equal(self.orbital_rotation_a, np.eye(self.norb)):
        for instruction in _prepare_configuration_jw(alpha_qubits, occ_a):
            circuit.append(instruction)
    else:
        for instruction in _prepare_slater_determinant_jw(
            alpha_qubits, self.orbital_rotation_a.T[list(occ_a)]
        ):
            circuit.append(instruction)

    if np.array_equal(self.orbital_rotation_b, np.eye(self.norb)):
        for instruction in _prepare_configuration_jw(beta_qubits, occ_b):
            circuit.append(instruction)
    else:
        for instruction in _prepare_slater_determinant_jw(
            beta_qubits, self.orbital_rotation_b.T[list(occ_b)]
        ):
            circuit.append(instruction)

    sign = _permutation_sign(np.argsort(occ_a)) * _permutation_sign(
        np.argsort(occ_b)
    )
    phase = 0 if sign == 1 else math.pi
    circuit.append(GlobalPhaseGate(phase))

    self.definition = circuit

def _define(self):
    """Gate decomposition."""
    qubits = QuantumRegister(self.num_qubits)
    circuit = QuantumCircuit(qubits, name=self.name)

    if np.array_equal(self.orbital_rotation, np.eye(self.norb)):
        for instruction in _prepare_configuration_jw(
            qubits, self.occupied_orbitals
        ):
            circuit.append(instruction)
    else:
        for instruction in _prepare_slater_determinant_jw(
            qubits, self.orbital_rotation.T[list(self.occupied_orbitals)]
        ):
            circuit.append(instruction)

    sign = _permutation_sign(np.argsort(self.occupied_orbitals))
    phase = 0 if sign == 1 else math.pi
    circuit.append(GlobalPhaseGate(phase))

    self.definition = circuit

def aqt_to_qiskit_circuit(circuit: Circuit, number_of_qubits: int) -> QuantumCircuit:
    """Convert an AQT API quantum circuit payload to an equivalent Qiskit representation.

    Args:
        circuit: payload to convert
        number_of_qubits: size of the quantum register to use for the converted circuit.

    Returns:
        A :class:`QuantumCircuit <qiskit.circuit.quantumcircuit.QuantumCircuit>` equivalent
        to the passed circuit payload.
    """
    qiskit_circuit = QuantumCircuit(number_of_qubits)

    for operation in circuit.root:
        if isinstance(operation.root, GateRZ):
            qiskit_circuit.rz(operation.root.phi * pi, operation.root.qubit)
        elif isinstance(operation.root, GateR):
            qiskit_circuit.r(
                operation.root.theta * pi,
                operation.root.phi * pi,
                operation.root.qubit,
            )
        elif isinstance(operation.root, GateRXX):
            qiskit_circuit.rxx(operation.root.theta * pi, *operation.root.qubits)
        elif isinstance(operation.root, Measure):
            qiskit_circuit.measure_all()
        else:
            assert_never(operation.root)  # pragma: no cover

    return qiskit_circuit

def _emit_rxx_instruction(theta: float, instructions: list[CircuitInstruction]) -> Instruction:
    """Collect the passed instructions into a single one labeled 'Rxx(θ)'."""
    qc = QuantumCircuit(2, name=f"{WrapRxxAngles.SUBSTITUTE_GATE_NAME}({pi_check(theta)})")
    for instruction in instructions:
        qc.append(instruction.gate, instruction.qubits)

    return qc.to_instruction()

def _faulty_circuit(self, comb, error: Tuple[str]):
    """Construct faulty QuantumCircuit with the given faults.

    comb = tuple of DAG nodes
    error = tuple of Pauli strings
    Return QuantumCircuit
    """
    error_to_gate = {"i": IGate(), "x": XGate(), "y": YGate(), "z": ZGate()}
    circ = QuantumCircuit(
        *self.dag.qregs.values(),
        *self.dag.cregs.values(),
        name=self.dag.name,
        global_phase=self.dag.global_phase,
    )
    circ.calibrations = self.dag.calibrations
    for orig_node in self.dag.topological_op_nodes():
        if orig_node in comb:
            index = comb.index(orig_node)
            errs = [error_to_gate[x] for x in error[index]]
            if orig_node.name == "measure":
                for i, err in enumerate(errs):
                    circ._append(err, [orig_node.qargs[i]], orig_node.cargs)
        inst = orig_node.op.copy()
        circ._append(inst, orig_node.qargs, orig_node.cargs)
        if orig_node in comb:
            if orig_node.name != "measure":
                for i, err in enumerate(errs):
                    circ._append(err, [orig_node.qargs[i]], orig_node.cargs)
    circ.duration = self.dag.duration
    circ.unit = self.dag.unit
    return circ

