def make_syndrome_graph_from_aer(code, shots=1):
    """
    Generates a graph and list of hyperedges for a given code by inserting Pauli errors
    around the gates of the base circuit for that code. Also supplied information regarding which
    edges where generated by which Pauli insertions.

    Args:
        code (CodeCircuit): Code for which the graph is to be made
        shots (int): Number of shots used in simulations.
    Returns:
        graph (PyGraph): Graph of the form used in `DecodingGraph`.
        hyperedges (list): List of hyperedges of the form used in `DecodingGraph`.
        hyperedge_errors (list): A list of the Pauli insertions that causes each hyperedge.
        These are specified by a tuple that specifies the type of Pauli and where it was
        inserted: (circuit depth, qreg index, qubit index, Pauli type).
        error_circuit (dict): Keys are the above tuples, and values are the corresponding
        circuits.
    """

    graph = rx.PyGraph(multigraph=False)
    hyperedges = []
    hyperedge_errors = []

    qc = code.circuit[code.base]
    blank_qc = QuantumCircuit()
    for qreg in qc.qregs:
        blank_qc.add_register(qreg)
    for creg in qc.cregs:
        blank_qc.add_register(creg)

    error_circuit = {}
    depth = len(qc)
    for j in range(depth):
        gate = qc.data[j][0].name
        qubits = qc.data[j][1]
        if gate not in ["measure", "reset", "barrier"] and len(qubits) != 2:
            for error in ["x", "y", "z"]:
                for qubit in qubits:
                    temp_qc = copy.deepcopy(blank_qc)
                    for qreg in qc.qregs:
                        if qubit in qreg:
                            break
                    temp_qc_name = (j, qc.qregs.index(qreg), qreg.index(qubit), error)
                    temp_qc.data = qc.data[0:j]
                    getattr(temp_qc, error)(qubit)
                    temp_qc.data += qc.data[j : depth + 1]
                    error_circuit[temp_qc_name] = temp_qc
        elif len(qubits) == 2:
            qregs = []
            for qubit in qubits:
                for qreg in qc.qregs:
                    if qubit in qreg:
                        qregs.append(qreg)
                        break
            for pauli_0 in ["id", "x", "y", "z"]:
                for pauli_1 in ["id", "x", "y", "z"]:
                    if not pauli_0 == pauli_1 == "id":
                        temp_qc = copy.deepcopy(blank_qc)
                        temp_qc_name = (
                            j,
                            (qc.qregs.index(qregs[0]), qc.qregs.index(qregs[1])),
                            (qregs[0].index(qubits[0]), qregs[1].index(qubits[1])),
                            pauli_0 + "," + pauli_1,
                        )
                        temp_qc.data = qc.data[0:j]
                        getattr(temp_qc, pauli_0)(qubits[0])
                        getattr(temp_qc, pauli_1)(qubits[1])
                        temp_qc.data += qc.data[j : depth + 1]
                        error_circuit[temp_qc_name] = temp_qc
        elif gate == "measure":
            pre_error = "x"
            for post_error in ["id", "x"]:
                for qubit in qubits:
                    temp_qc = copy.deepcopy(blank_qc)
                    for qreg in qc.qregs:
                        if qubit in qreg:
                            break
                    temp_qc_name = (
                        j,
                        qc.qregs.index(qreg),
                        qreg.index(qubit),
                        pre_error + "_" + post_error,
                    )
                    temp_qc.data = qc.data[0:j]
                    getattr(temp_qc, pre_error)(qubit)
                    temp_qc.data.append(qc.data[j])
                    getattr(temp_qc, post_error)(qubit)
                    temp_qc.data += qc.data[j + 1 : depth + 1]
                    error_circuit[temp_qc_name] = temp_qc

    errors = []
    circuits = []
    for error, circuit in error_circuit.items():
        errors.append(error)
        circuits.append(circuit)

    result = AerSimulator().run(circuits, shots=shots).result()
    no_nodes = []
    for j, circuit in enumerate(circuits):
        for string in result.get_counts(j):
            nodes = code.string2nodes(string)
            for node in nodes:
                if node not in graph.nodes():
                    graph.add_node(node)
            hyperedge = {}
            for source in nodes:
                for target in nodes:
                    if target != source or (len(nodes) == 1):
                        n0 = graph.nodes().index(source)
                        n1 = graph.nodes().index(target)
                        if not (source.is_logical and target.is_logical):
                            qubits = list(set(source.qubits).intersection(target.qubits))
                        if source.time != target.time and len(qubits) > 1:
                            qubits = []
                        edge = DecodingGraphEdge(qubits, 1)
                        graph.add_edge(n0, n1, edge)
                        if (n1, n0) not in hyperedge:
                            hyperedge[n0, n1] = edge
            if hyperedge:
                if hyperedge not in hyperedges:
                    hyperedges.append(hyperedge)
                    hyperedge_errors.append([])
                k = hyperedges.index(hyperedge)
                if errors[j] not in hyperedge_errors[k]:
                    hyperedge_errors[k].append(errors[j])
            else:
                if errors[j] not in no_nodes:
                    no_nodes.append(errors[j])
    hyperedges.append({})
    hyperedge_errors.append(no_nodes)

    return graph, hyperedges, hyperedge_errors, error_circuit

def TFIMCircuit(num_qubits, trotter_steps):

    circuit = QuantumCircuit(num_qubits)

    beta = Parameter("β")
    gamma = Parameter("γ")

    for step in range(trotter_steps):

        for qubit in range(num_qubits):
            circuit.rx(beta, qubit)
        for qubit in range(0, num_qubits - 1, 2):
            circuit.rzz(gamma, qubit, qubit + 1)
        for qubit in range(1, num_qubits - 1, 2):
            circuit.rzz(gamma, qubit, qubit + 1)

    return circuit

def __init__(self, num_layers, num_qubits, init_state = None, mixer_layer = None):

    super().__init__()
    self.num_layers = num_layers
    self.num_qubits = num_qubits

    if init_state is None:
        # Add default initial state -> equal superposition
        self.init_state = QuantumCircuit(num_qubits)
        self.init_state.h(range(num_qubits))
    else: 
        self.init_state = init_state

    if mixer_layer is None:
        # Define default mixer layer
        self.mixer_layer = QuantumCircuit(num_qubits)
        self.mixer_layer.rx(-2*betas[0], range(num_qubits))
    else:
        self.mixer_layer = mixer_layer

def run(self, cost_layer_dag):

    cost_layer = dag_to_circuit(cost_layer_dag)
    qaoa_circuit = QuantumCircuit(self.num_qubits, self.num_qubits)
    # Re-parametrize the circuit
    gammas = ParameterVector("γ", self.num_layers)
    betas = ParameterVector("β", self.num_layers)

    # Add initial state
    qaoa_circuit.compose(self.init_state, inplace = True)

    # iterate over number of qaoa layers
    # and alternate cost/reversed cost and mixer
    for layer in range(self.num_layers): 

        bind_dict = {cost_layer.parameters[0]: gammas[layer]}
        bound_cost_layer = cost_layer.assign_parameters(bind_dict)

        bind_dict = {self.mixer_layer.parameters[0]: betas[layer]}
        bound_mixer_layer = self.mixer_layer.assign_parameters(bind_dict)

        if layer % 2 == 0:
            # even layer -> append cost
            qaoa_circuit.compose(bound_cost_layer, range(self.num_qubits), inplace=True)
        else:
            # odd layer -> append reversed cost
            qaoa_circuit.compose(bound_cost_layer.reverse_ops(), range(self.num_qubits), inplace=True)

        # the mixer layer is not reversed
        qaoa_circuit.compose(bound_mixer_layer, range(self.num_qubits), inplace=True)


    if self.num_layers % 2 == 1:
        # iterate over layout permutations to recover measurements
        if self.property_set["virtual_permutation_layout"]:
            for cidx, qidx in self.property_set["virtual_permutation_layout"].get_physical_bits().items():
                qaoa_circuit.measure(qidx, cidx)
        else:
            print("layout not found, assigining trivial layout")
            for idx in range(self.num_qubits):
                qaoa_circuit.measure(idx, idx)
    else:
        for idx in range(self.num_qubits):
            qaoa_circuit.measure(idx, idx)

    return circuit_to_dag(qaoa_circuit)

def circuit_ex3(params):
    qc = QuantumCircuit(8)
    qc.h(range(8))
    for j in range(2):
        qc.cz(range(0,4,2),range(1,5,2))
        qc.cz(range(1,4,2),range(2,5,2))
        qc.cz(range(4,8-1),range(5,8))
        for i in range(8):
            qc.rx(params[i,j],i)
    return qc

def run(self, cost_layer_dag: DAGCircuit):
    num_qubits = cost_layer_dag.num_qubits()

    # Make the initial state and the mixer.
    if self.init_state is None:
        init_state = QuantumCircuit(num_qubits)
        init_state.h(range(num_qubits))
    else:
        init_state = self.init_state

    if self.mixer_layer is None:
        mixer_layer = QuantumCircuit(num_qubits)
        beta = Parameter("β")
        mixer_layer.rx(2 * beta, range(num_qubits))
    else:
        mixer_layer = self.mixer_layer

    # Do some sanity checks on qubit numbers.
    if init_state.num_qubits != num_qubits:
        raise TranspilerError(
            "Number of qubits in the initial state does not match the number in the DAG. "
            f"{init_state.num_qubits} != {num_qubits}"
        )

    if mixer_layer.num_qubits != num_qubits:
        raise TranspilerError(
            "Number of qubits in the mixer does not match the number in the DAG. "
            f"{init_state.num_qubits} != {num_qubits}"
        )

    # Note: converting to circuit is inefficent. Update to DAG only.
    cost_layer = dag_to_circuit(cost_layer_dag)
    qaoa_circuit = QuantumCircuit(num_qubits, num_qubits)

    # Re-parametrize the circuit
    gammas = ParameterVector("γ", self.num_layers)
    betas = ParameterVector("β", self.num_layers)

    # Add initial state
    qaoa_circuit.compose(init_state, inplace=True)

    # iterate over number of qaoa layers
    # and alternate cost/reversed cost and mixer
    for layer in range(self.num_layers):
        bind_dict = {cost_layer.parameters[0]: gammas[layer]}
        bound_cost_layer = cost_layer.assign_parameters(bind_dict)

        bind_dict = {mixer_layer.parameters[0]: betas[layer]}
        bound_mixer_layer = mixer_layer.assign_parameters(bind_dict)

        if layer % 2 == 0:
            # even layer -> append cost
            qaoa_circuit.compose(bound_cost_layer, range(num_qubits), inplace=True)
        else:
            # odd layer -> append reversed cost
            qaoa_circuit.compose(
                bound_cost_layer.reverse_ops(), range(num_qubits), inplace=True
            )

        # the mixer layer is not reversed and not permuted.
        qaoa_circuit.compose(bound_mixer_layer, range(num_qubits), inplace=True)

    if self.num_layers % 2 == 1:
        # iterate over layout permutations to recover measurements
        if self.property_set["virtual_permutation_layout"]:
            for cidx, qidx in (
                self.property_set["virtual_permutation_layout"].get_physical_bits().items()
            ):
                qaoa_circuit.measure(qidx, cidx)
        else:
            warnings.warn("Layout not found, assigining trivial layout")
            for idx in range(num_qubits):
                qaoa_circuit.measure(idx, idx)
    else:
        for idx in range(num_qubits):
            qaoa_circuit.measure(idx, idx)

    return circuit_to_dag(qaoa_circuit)

def _get_test_set_iterator(name, *, offset=0, seed=None):
    if name == "nannicini-qv8":
        with gzip.open("../stats/nannicini-qv8/qv256_batch1_original.qpy.gz", "rb") as f:
            circuits_orig1 = qpy_serialization.load(f)
        return circuits_orig1[offset:]
