        n = int(name[2:])
        return QVIterator(n, seed=seed, offset=offset)
    if name.startswith("mcx"):
        n = int(name[3:])
        qc = QuantumCircuit(n)
        qc.mcx(list(range(qc.num_qubits - 1)), qc.num_qubits - 1)
