def build_circuit(nq):
    pars = ParameterVector(name="$\\theta$", length=nq)
    pqc = QuantumCircuit(nq)
    for i in range(nq):
        pqc.ry(pars[i], i)
    for i in range(nq-1):
        pqc.cx(i, i+1)
    return pqc, pars

