    """Build a normalized and transpiled copy of the input circuit."""
    from ..circuit import build_target

    num_qubits = circuit.num_qubits
    normalized = QuantumCircuit(num_qubits).compose(circuit)
    return transpile(normalized, target=build_target(), optimization_level=1)

def ansatz(params, cparams=None):
    layers, num_qubits, depth = params.shape
    ansatz = qiskit.QuantumCircuit(num_qubits)
    for idx in range(layers):
        if idx:
            ansatz.barrier()
        for ind in range(num_qubits):
            ansatz.rx(params[idx][ind][0], ind)
            ansatz.rz(params[idx][ind][1], ind)
            ansatz.rx(params[idx][ind][2], ind)
        for ind in range(num_qubits-1):
            ansatz.cx(ind, ind+1)
    return ansatz

