        for i_conn in range(1,conn+1):
            for i_q in range(0,n-i_conn): 
                circ.cx(qr[i_q],qr[i_q+i_conn])
                circ.rx(gamma[0],qr[i_q])
                circ.cx(qr[i_q],qr[i_q+i_conn])                                                       #circ.rxx(gamma[0], qr[i_q], qr[i_q+i_conn])

