def modular_exponentiation_helper(a, x):
    circuit = QuantumCircuit(4)
    # if 3 or 5, then we would have a gcd of 15, and have our solution. Therefore our possible inputs to this function are
    if a not in modular_expansion_primes:
        raise ValueError(
            "Bad a value, must be 2, 7, 8, 11, or 13"
        )  #  -1 # We got here when we should not have

    for iteration in range(x):
        if a in [2, 13]:
            circuit.swap(0, 1)
            circuit.swap(1, 2)
            circuit.swap(2, 3)
        if a in [7, 8]:
            circuit.swap(2, 3)
            circuit.swap(1, 2)
            circuit.swap(0, 1)
        if a == 11:
            circuit.swap(1, 3)
            circuit.swap(0, 2)
        if a in [7, 11, 13]:
            # circuit.x(range(4))
            for q in range(4):
                circuit.x(q)

    circuit = circuit.to_gate()
    circuit.name = "%i^%i mod 15" % (a, x)  # Hard coded 15
    control_circuit = circuit.control()
    return control_circuit

def __init__(self, fsm: FSM):
    print("  Setting FSM instance up...")
    self._ready = False
    self._measured = False
    self._fsm = fsm
    _regs: List[QuantumRegister] = []
    for reg in self._fsm.regs.values():
        if isinstance(reg, list):
            _regs.extend(reg)
        else:
            _regs.append(reg)

    print("  Creating circuit...")
    self._qc = QuantumCircuit(*_regs, *list(self._fsm.cregs.values()))

    print("  Initializing input registers...")
    for i, bit in enumerate(bin(self.d)[2:]):
        if bit == "1":
            self._qc.x(self.di[i])

    _inx, _iny = (self._fsm.input["x"], self._fsm.input["y"])
    _regx, _regy = self.xy
    for i, bit in enumerate(_inx):
        if bit == "1":
            self._qc.x(_regx[i])
    for i, bit in enumerate(_iny):
        if bit == "1":
            self._qc.x(_regy[i])

    if self.mode == FSMMode.FPM.value:
        _ddinit = "".join(["1", "0" * self.n])
    elif self.mode == FSMMode.FFP.value:
        _ddinit = "".join(
            ["0" * self.from_pos, "1", "0" * (self.n - self.from_pos)]
        )
    else:
        _ddinit = "1" * (self.n + 1)
    for i, bit in enumerate(_ddinit):
        if bit == "1":
            self._qc.x(self.ddinit[i])
    print("FSM instance initialization successful.")

def revert(self):
    """Resets circuit removing all the gates."""
    self._qc = QuantumCircuit(list(self._fsm.regs.values()))

def generate_circuit(fuzzy_partitions, encoding='logaritmic'):
    """Function generating a quantum circuit with width required by QFS"""
    qc = QuantumCircuit()
    for partition in fuzzy_partitions:
        if encoding=='logaritmic':
            qc.add_register(
                QuantumRegister(
                    math.ceil(math.log(partition.len_partition() + 1, 2)),
                    name=partition.name,
                )
            )
            Qregisters.append(
                QuantumRegister(
                    math.ceil(math.log(partition.len_partition() + 1, 2)),
                    name=partition.name,
                )
            )
        if encoding == 'linear':
            qc.add_register(
                QuantumRegister(
                    partition.len_partition(),
                    name=partition.name,
                )
            )
            Qregisters.append(
                QuantumRegister(
                    partition.len_partition(),
                    name=partition.name,
                )
            )

    return qc

def run(self, num_qubits, state, composite: cliffords.CompositeCliffordGate, phases=None):
    circuit = QuantumCircuit(len(state)) 
    #first flip all the bits for which state is 1

    for i, b in enumerate(state):
        if b:
            circuit.x(i)
    projectors = []
    t_count = 0
    for gate in composite.gates:
        d = gate.data()
        if d[0] == "H":
            circuit.h(d[1])
        elif d[0] == "S":
            circuit.s(d[1])
        elif d[0] == "CZ":
            circuit.cz(target_qubit=d[1], control_qubit=d[2])
        elif d[0] == "CX":
            circuit.cx(target_qubit=d[1], control_qubit=d[2])
        elif d[0] == "T":
            if isinstance(phases, type(None)):
                circuit.t(qubit=d[1])
            else:
                circuit.rz(phases[t_count],d[1])

            t_count += 1

        elif d[0] == "PZ":                
            projectors.append(d)
        else:
            raise TypeError("Only unitary Clifford gates and Z projectors supported! Recieved: {}".format(gate))

    job = qiskit.execute(circuit, backend=self.backend,backend_options={"method": "statevector", "max_parallel_threads":10})

    statevector = _rearange_state_vector(num_qubits, job.result().get_statevector(circuit))
    #statevector = job.result().get_statevector(circuit)
    for projector in projectors:
        #we need to zero everything that we aren't projecting onto
        #this will be half of the entries of the state-vector
        target_qubit = projector[1]
        bits_to_zero = None
        if projector[2] == 0:
            bit_to_zero = '1'
        elif projector[2] == 1:
            bit_to_zero = '0'
        indices_to_zero = [n for n in range(len(statevector)) if np.binary_repr(n,width=num_qubits)[target_qubit] == bit_to_zero]
        #print(target_qubit)
        #print([np.binary_repr(n,width=num_qubits) for n in range(len(statevector))])
        #print(indices_to_zero)
        statevector[indices_to_zero] = 0.

    #job = self.backend.run(circuit, backend_options=self.backend_options)
    return statevector

def merge_q_registers(circ, qubit_number):
    """
    Given a circuit that has been defined on individually-named quantum registers of decimal format q1...qN, converts to a monolithic register 

    circ - a circuit on many registers
    qubit_number - how many qubits total should be in the monolithic system

    returns a quantum circuit, merged
    """
    qreg_mono = QuantumRegister(qubit_number)
    classical_bits = circ.clbits
    cl_regs = frozenset(cb.register for cb in classical_bits)

    def parse_name(qreg_name):
        return int(qreg_name[1:])

    qc = QuantumCircuit(*([qreg_mono] + list(cl_regs)))
    #Now iterate the item, see which qubits each thing touches
    measured_qubits = []
    for item in circ:
        #print(item)
        item_qubits= item[1]
        item_cbits = item[2]

        #print(item_qubits)
        #print([qubit.register.name for qubit in item_qubits])
        qubit_indices = [parse_name(qubit.register.name) for qubit in item_qubits]
        qubits_new = [qreg_mono[index] for index in qubit_indices]
        #Keep the same classical bits & registers

        if isinstance(item[0], HGate):
            qc.h(*qubits_new)
        elif isinstance(item[0], XGate):
            qc.x(*qubits_new)
        elif isinstance(item[0], Barrier):
            qc.barrier(*qubits_new)
        elif isinstance(item[0], Delay):
            qc.delay(duration=item[0].duration, qarg=qubits_new, unit=item[0].unit)
        elif isinstance(item[0], SdgGate):
            qc.sdg(*qubits_new)
        elif isinstance(item[0], SGate):
            qc.s(*qubits_new)
        elif isinstance(item[0], CXGate):
            qc.cx(*qubits_new)
        elif isinstance(item[0], SwapGate):
            qc.swap(*qubits_new)
        elif isinstance(item[0], IGate):
            qc.id(*qubits_new)
        elif isinstance(item[0], Measure):
            qc.measure(qubits_new[0], item_cbits[0])
            measured_qubits.extend(qubit_indices)
        else:
            raise ValueError("Gate %s of unsupported type %s" % (str(item), item[0].__class__.__name__))

    return [qc, measured_qubits]

