def score(self, X, y, loss_type):
    y_pred = self.predict(X)[0]
    if loss_type=='fidelity':
        score=0
        for i,j in zip(y_pred,y):
            score =score+qi.state_fidelity(i,j,validate=True)
        return score/len(y)

    elif loss_type=='wasserstein': 
        num_data=len(X)

        dim=len(X[0])
        n_qubits_latent=int(2*math.log2(dim))
        swap_circuit = QuantumCircuit(n_qubits_latent,0)
        for i in range(int(n_qubits_latent*0.5)):
            swap_circuit.swap(i, int(n_qubits_latent*0.5)+i)
        backend = Aer.get_backend('unitary_simulator')
        job=execute(swap_circuit,backend,shots=100)
        result=job.result()
        swap=result.get_unitary(swap_circuit,3).data
        identity_matrix=np.identity(dim*dim)
        C=0.5*(identity_matrix-swap)

        cost=0
        pi_state=np.zeros((len(X[0])*len(X[0]),len(X[0])*len(X[0])))
        for v,m in zip(y,y_pred):
            input_densityMatrix=qi.DensityMatrix(v)
            in_out_state=qi.DensityMatrix(m).expand(input_densityMatrix)
            pi_state=(pi_state+in_out_state.data*1./num_data)
        cost=np.trace(np.matmul(pi_state,C))
        return -cost.real

    elif loss_type=='cross_entropy':
        score=0
        for v,m in zip(y,y_pred):
            input_state_entropy=qi.entropy(v)
            log_state=qi.DensityMatrix(scipy.linalg.logm(m/np.log(2.0)))
            relative_entropy=-qi.DensityMatrix(np.dot(v,log_state)).trace()-input_state_entropy
            score+=relative_entropy.real
        return -score/len(y)

    elif loss_type=='JSD':
        score=0
        for v,m in zip(y,y_pred):
            M_state=0.5*(v.data+m.data)
            log_M=qi.DensityMatrix(scipy.linalg.logm(M_state)/np.log(2.0)) # in base 2
            relative_entropy=(-qi.DensityMatrix(np.dot(v,log_M)).trace()-qi.entropy(v)-qi.DensityMatrix(np.dot(m,log_M)).trace()-qi.entropy(m))*0.5 ##check if correct!
            score+=relative_entropy.real
        return -score*1./len(y)
    else:
        raise ValueError('reconstruction loss type not recognized')

def reconstruction_loss(self,matrix,vector):
    if self._reconstruction_loss=='wasserstein':
        num_data=len(vector)

        dim=len(vector[0])
        n_qubits_latent=int(2*math.log2(dim))
        swap_circuit = QuantumCircuit(n_qubits_latent,0)
        for i in range(int(n_qubits_latent*0.5)):
            swap_circuit.swap(i, int(n_qubits_latent*0.5)+i)
        backend = Aer.get_backend('unitary_simulator')
        job=execute(swap_circuit,backend,shots=100)
        result=job.result()
        swap=result.get_unitary(swap_circuit,3).data
        identity_matrix=np.identity(dim*dim)
        C=0.5*(identity_matrix-swap)

        cost=0
        pi_state=np.zeros((len(vector[0])*len(vector[0]),len(vector[0])*len(vector[0])))
        for v,m in zip(vector,matrix):
            input_densityMatrix=qi.DensityMatrix(v)
            in_out_state=qi.DensityMatrix(m).expand(input_densityMatrix)
            pi_state=(pi_state+in_out_state.data*1./num_data)
        cost=np.trace(np.matmul(pi_state,C))
        return cost.real

    else:
        if self._reconstruction_loss=='cross_entropy':
            sum=0
            for v,m in zip(vector,matrix):
                input_state_entropy=qi.entropy(v)
                log_state=qi.DensityMatrix(scipy.linalg.logm(m)/np.log(2.0))
                relative_entropy=-qi.DensityMatrix(np.dot(v,log_state)).trace()-input_state_entropy
                sum+=relative_entropy.real
            return sum*1./len(vector)

        elif self._reconstruction_loss=='fidelity':
            sum=0
            for v,m in zip(vector,matrix):
                current_fidelity=qi.state_fidelity(m,v,validate=True)
                sum+=current_fidelity
            return -sum*1./len(vector)

        elif self._reconstruction_loss=='JSD':
            sum=0
            for v,m in zip(vector,matrix):
                M_state=0.5*(v.data+m.data)
                log_M=scipy.linalg.logm(M_state)/np.log(2.0) # in base 2
                relative_entropy=(-qi.DensityMatrix(np.dot(v,log_M)).trace()-qi.entropy(v)-qi.DensityMatrix(np.dot(m,log_M)).trace()-qi.entropy(m))*0.5 ##check if correct!
                sum+=relative_entropy.real
            return sum*1./len(vector)

        else:
            raise ValueError('reconstruction loss type not recognized')

def __init__(self,name,num):
    self.backend = Aer.get_backend('statevector_simulator');
    self.circ = QuantumCircuit(num);
    self.name = name;
    self.seed = 14256;
    self.num = num;
    np.random.seed(self.seed);
    self.params = ParameterVector('Θ',0);
    # self.circ.rz(self.params[0],1);
    # self.circ.rz(self.params[1],1);

def add(self,gate="rz",cc=0,c=0,o=0):
    pastlen = len(self.params.params);
    if gate == "rz" or gate == "rx":
        if o<0 or o>=self.num:
            print("Index Error");
            return;
        self.params.resize(pastlen+1);
        if gate == "rz":
            self.circ.rz(self.params[pastlen],o);
        if gate == "rx":
            self.circ.rx(self.params[pastlen],o);
    if gate == "crz" or gate == "crx":
        if o<0 or o>=self.num or c<0 or c>=self.num or o==c:
            print("Index Error");
            return;
        self.params.resize(pastlen+1);
        if gate == "crz":
            cir = QuantumCircuit(1, name="RZ");
            cir.rz(self.params[pastlen],0);
        if gate == "crx":
            cir = QuantumCircuit(1, name="RX");
            cir.rx(self.params[pastlen],0);
        temp = cir.to_gate().control(1);
        self.circ.append(temp,[c,o]);

def subroutine_add_const(data_qubits: int, const: int, to_gate=True):
    qc = QuantumCircuit(data_qubits)
    for i in range(data_qubits):
        angle = const*np.pi/(2**i)
        qc.p(angle,i)
    return qc.to_gate(label=" ["+str(const)+"] ") if to_gate else qc

def create_oracle(n_qubits, target):
    oracle = QuantumCircuit(n_qubits)
    target_bits = format(target, f'0{n_qubits}b')[::-1]
    for qubit in range(n_qubits):
        if target_bits[qubit] == '0':
            oracle.x(qubit)

    oracle.h(n_qubits - 1)
    oracle.mcx(list(range(n_qubits - 1)), n_qubits - 1)
    oracle.h(n_qubits - 1)
    for qubit in range(n_qubits):
        if target_bits[qubit] == '0':
            oracle.x(qubit)
    return oracle

def prepare_computational_basis(nqubits, number):
    """Encode number as binary and create the circuit"""
    # Create empty circuit of requested size
    qc = QuantumCircuit(nqubits)

    # encode number into a byte array 
    ba = int2ba(number, nqubits); 

    # Populate the circuit
    for q in range(nqubits):
        if ba[q]:
            qc.x(q)

    return qc

def create_entangled_qubits(num_qubits):
    circuit = QuantumCircuit(num_qubits, num_qubits)
    for i in range(1, num_qubits):
        circuit.cx(0, i)
    return circuit

def _get_mod_exp_gate(self, current_a):
    """Wraps the modular multiplication into a controlled quantum gate"""
    qc = QuantumCircuit(self.target_qubits)
    matrix = self._create_permutation_matrix(current_a)
    qc.unitary(matrix, range(self.target_qubits))
    return qc.to_gate(label=f" {current_a}x mod {self.n} ")

def prepare_work(self,ctrl_bits):
    reg_base = qk.QuantumRegister(self.msystem.n)
    reg_work = qk.QuantumRegister(max(1,self.msystem.n-1))
    circ = qk.QuantumCircuit(reg_base,reg_work)

    ctrl_bits_flip=ctrl_bits[::-1]
    # switch desired 0's to 1's
    for p in range(self.msystem.n):
        if ctrl_bits_flip[p]=='0':
            circ.append(clib.XGate(),[reg_base[p]])
    # set work bits
    if(self.msystem.n>1):
        circ.append(clib.CCXGate(),[reg_base[0]]+[reg_base[1]]+[reg_work[0]])
        for p in range(1,self.msystem.n-1):
            circ.append(clib.CCXGate(),[reg_base[p+1]]+[reg_work[p-1]]+[reg_work[p]])
    else:
        circ.append(clib.CXGate(),[reg_base[0]]+[reg_work[0]])

    return circ.to_gate()

def S(self):
    reg_r1=qk.QuantumRegister(self.msystem.n)
    reg_r1a=qk.QuantumRegister(1)
    reg_r2=qk.QuantumRegister(self.msystem.n)
    reg_r2a=qk.QuantumRegister(1)
    circ=qk.QuantumCircuit(reg_r1,reg_r1a,reg_r2,reg_r2a)
    for jk in range(self.msystem.n):
        circ.append(clib.SwapGate(), [reg_r1[jk],reg_r2[jk]])
    circ.append(clib.SwapGate(), reg_r1a[:]+reg_r2a[:])
    return circ.to_gate()

def schedule_quantum_circuit(coupling_graph, initial_mapping, num_qubits=20):
    #initialised the final circuit
    final_cir = QuantumCircuit(6)
    current_mapping = initial_mapping.copy()
    #fron_list : tracks gates waiting to be scheduled
    #act_list : tracks gates currently being scheduled
    #frozen : tracks logical qubits which have been processed 0 means unfrozen 1 means frozen
    fron_list = []
    act_list = []
    frozen = {q: False for q in range(num_qubits)}
    executed_gates = []  # Track executed gates order

    #  dependence lists
    dlist = defaultdict(DependenceList)
    gates = [(0, 2), (5, 2), (0, 5), (4, 0), (0, 3), (5, 0), (3, 1)]
    for c, t in gates:
        gate = Gate(c, t)
        dlist[c].push_back(gate)
        dlist[t].push_back(gate)

    # Computes distances between nodes in coupling graph 
    distances = [[float('inf')] * num_qubits for _ in range(num_qubits)]
    for node, neighbors in coupling_graph.items():
        i = int(node[1:])
        distances[i][i] = 0
        for neighbor in neighbors:
            j = int(neighbor[1:])
            distances[i][j] = distances[j][i] = 1

    # Stores operations for later conversion
    operations = []

    while True:

        for q in range(6):
            if not frozen[q]:
                gate = dlist[q].head()
                if gate:
                    if gate in fron_list:
                        fron_list.remove(gate)
                        if gate not in act_list:
                            act_list.append(gate)
                    else:
                        if gate not in fron_list:
                            fron_list.append(gate)
                    frozen[q] = True

        # Execute gates that are satisfying connectivity constraint
        gates_to_remove = []
        for gate in act_list:
            if check_connectivity(gate, current_mapping, coupling_graph):
                gates_to_remove.append(gate)
                dlist[gate.control].pop_front()
                dlist[gate.target].pop_front()
                # Store gate operation with logical qubits
                operations.append(('cx', gate.control, gate.target))
                executed_gates.append(gate)
                frozen[gate.control] = False
                frozen[gate.target] = False

        for gate in gates_to_remove:
            act_list.remove(gate)
        # repeat till fron_list is empty


        # SWAP selection
        # Now act_list containes gates which donot satisfy the connectivity constraint.
        if act_list:
            candi_list = []
        #candi_list contains SWAPs having positive effect on at least one active gate;    
            for node, neighbors in coupling_graph.items():
                i = int(node[1:])
                for neighbor in neighbors:
                    j = int(neighbor[1:])
                    if i < j:
                        candi_list.append((i, j))
            # mcpe_costs contains mcpe of all the swaps in candi_list
            mcpe_costs = {}
            for swap in candi_list:
                cost = calculate_mcpe_cost(swap, act_list, current_mapping, distances)
                if cost > 0:
                    mcpe_costs[swap] = cost

            if mcpe_costs:
                best_swap = max(mcpe_costs.items(), key=lambda x: x[1])[0]
                p1, p2 = best_swap

                # Store SWAP operation with logical qubits
                rev_mapping = get_reverse_mapping(current_mapping)
                if p1 in rev_mapping and p2 in rev_mapping:
                    operations.append(('swap', rev_mapping[p1], rev_mapping[p2]))

                # Update mapping implementing that swap
                for q in current_mapping:
                    if current_mapping[q] == p1:
                        current_mapping[q] = p2
                    elif current_mapping[q] == p2:
                        current_mapping[q] = p1
      if  not fron_list:
            break
    # Create final circuit with logical qubits
    final_logical_cir = QuantumCircuit(6)
    for op_type, q1, q2 in operations:
        if op_type == 'cx':
            final_logical_cir.cx(q1, q2)
        else:  # swap
            final_logical_cir.swap(q1, q2)

    return final_logical_cir

def construct_qcc_circuit(entanglers: List[str], params: List[float], truncation=None, barrier=False):
    '''This function defines the exponential building block for hamtilbonian simulation. 

    Args:
        entanglers: list storing Pauli words for construction of qcc_circuit.
        params: parameters for the rotations in blocks
    Returns:
        qcc_circuit
    '''
    if truncation != None:
        if len(entanglers) > truncation:
            num_blocks = truncation
        else:
            num_blocks = len(entanglers)
    else:
        num_blocks = len(entanglers)

    num_qubits = len(entanglers[0])
    qcc_circuit = QuantumCircuit(num_qubits)
    for i in range(num_blocks):
        circuit = QuantumCircuit(num_qubits)
        key = entanglers[i]
        if all(c == 'I' for c in key):
            continue
        coupler_map = []
        # We first construct coupler_map according to the key.
        for j in range(num_qubits):
            if key[num_qubits-1-j] != 'I':
                coupler_map.append(j)

        # Then we construct the circuit.
        if len(coupler_map) == 1:
            # there is no CNOT gate.
            c = coupler_map[0]
            if key[num_qubits-1-c] == 'X':
                circuit.h(c)
                circuit.rz(params[i], c)
                circuit.h(c)
            elif key[num_qubits-1-c] == 'Y': 
                circuit.sdg(c)
                circuit.h(c)
                circuit.rz(params[i], c)
                circuit.h(c)
                circuit.s(c)
            elif key[num_qubits-1-c] == 'Z':
                circuit.rz(params[i], c)

            qcc_circuit.compose(circuit, inplace=True)
        else:
            # Here we would need CNOT gate.
            for j in coupler_map:
                if key[num_qubits-1-j] == 'X':
                    circuit.h(j)
                elif key[num_qubits-1-j] == 'Y':
                    circuit.sdg(j)
                    circuit.h(j)

            for j in range(len(coupler_map) - 1):
                circuit.cx(coupler_map[j], coupler_map[j+1])

            param_gate = QuantumCircuit(num_qubits)
            param_gate.rz(params[i], coupler_map[-1])

            qcc_circuit.compose(circuit, inplace=True)
            qcc_circuit.compose(param_gate, inplace=True)
            qcc_circuit.compose(circuit.inverse(), inplace=True)
        if barrier is True:
            qcc_circuit.barrier()

    return qcc_circuit

def find_single_tree(base_entangler_inv: str, match_entangler_inv: str):

    '''This function generates the best CNOT tree circuit for the base_entangler, maximizing the minimization of match_entangler.

    Args:
        base_entangler: the base entangler that searchers for the CNOT tree structure
        match_entangler: the target entangler that we are matching and minimizing
    Returns:
        CNOT_tree: the CNOT tree circuit
    '''
    num_qubits  = len(base_entangler_inv)
    I_list = []
    X_list = []
    Y_list = []
    Z_list = []
    N_list = []
    match_entangler = match_entangler_inv[::-1]
    base_entangler = base_entangler_inv[::-1]
    #first iterate over the base_entangler and find the non I index:
    for i in range(num_qubits):
        if base_entangler[i] != 'I':
            if match_entangler[i] == 'I':
                I_list.append(i)
            elif match_entangler[i] == 'X':
                X_list.append(i)
            elif match_entangler[i] == 'Y':
                Y_list.append(i)
            elif match_entangler[i] == 'Z':
                Z_list.append(i)
            else:
                raise Exception("Incorrect letter in entangler spotted", match_entangler)
        else:
            N_list.append(i)
    #Based on the lists, construct the quantum circuit:
    root_list = []
    qc = QuantumCircuit(num_qubits)
    I_root = X_root = Y_root = Z_root = N_root = final_root = -1
    #iterate over the I list:
    if len(I_list) == 1:
        I_root = I_list[0]
    elif len(I_list) > 1:
        for i_idx in range(len(I_list) - 1):
            qc.cx(I_list[i_idx], I_list[i_idx + 1])
        I_root = I_list[-1]
    #iterate over the Z list:
    if len(Z_list) == 1:
        Z_root = Z_list[0]
    elif len(Z_list) > 1:
        for z_idx in range(len(Z_list) - 1):
            qc.cx(Z_list[z_idx], Z_list[z_idx + 1])
        Z_root = Z_list[-1]
    #iterate over the X list:
    if len(X_list) == 1:
        X_root = X_list[0]
    elif len(X_list) > 1:
        for x_idx in range(len(X_list) - 1):
            qc.cx(X_list[x_idx], X_list[x_idx + 1])
        X_root = X_list[-1]
    #iterate over the Y list:
    if len(Y_list) == 1:
        Y_root = Y_list[0]
    elif len(Y_list) > 1:
        for y_idx in range(len(Y_list) - 1):
            qc.cx(Y_list[y_idx], Y_list[y_idx + 1])
        Y_root = Y_list[-1]

    # Function to connect the roots based on priority and set the final root
    def connect_roots(qc, root_name, roots_dict, priorities):
        root_value = roots_dict[root_name]
        if root_value > -1:
            for other_root_name in priorities:
                if roots_dict[other_root_name] > -1:
                    qc.cx(root_value, roots_dict[other_root_name])
                    # roots_dict[other_root_name] = -1
                    roots_dict[root_name] = -1
                    return roots_dict[other_root_name]
        return -1

    # Initialize the root dictionary
    roots_dict = {
        "Z_root": Z_root,
        "I_root": I_root,
        "Y_root": Y_root,
        "X_root": X_root,
        "N_root": N_root
    }

    final_root = None

    # Connection priorities
    priority_connections = {
        "Z_root": ["Y_root", "X_root", "I_root"],
        "I_root": ["X_root", "Y_root"],
        "Y_root": ["X_root"],
        # "X_root": ["N_root"]
    }

    # Connect roots based on priority
    for root_name in ["Z_root", "I_root", "Y_root", "X_root"]:
        if root_name in priority_connections:
            last_connected = connect_roots(qc, root_name, roots_dict, priority_connections[root_name])
            if last_connected != -1:
                final_root = last_connected

    # If any roots are still unconnected, set final_root
    for root_name in ["Z_root", "I_root", "Y_root", "X_root"]:
        if roots_dict[root_name] > -1:
            final_root = roots_dict[root_name]
            # print("final, root, rootes_dict[root_name]", final_root, roots_dict[root_name])


    # Ensure final_root is set correctly if not already set
    if final_root is None:
        #final_root = X_root
        raise Exception("final root not set")


    return final_root, qc

def n_qubit_A_circuit(n,m, repeat = 1):
    qc = QuantumCircuit(n)
    index = 0
    theta  = ParameterVector('theta', repeat*(n-m)*m)
    ## primitive pattern
    for _ in range(repeat): 
        for i in range(m):
            qc.x(i)
            for j in range(m,n):
                A_gate(qc,i,j,theta[index])
                index += 1

    return qc, index*2

def apply_fixed_ansatz(qubits,layer,parameters):

    qc = QuantumCircuit(qubits)

    for i in range(qubits):
        qc.h(i)

    for l in range(layer) :
        for i in range(qubits):
            qc.ry(parameters[2*l*qubits+i],i)
        for i in range(int(qubits/2)):
            qc.cz(2*i,2*i+1)
        for i in range(qubits):
            qc.ry(parameters[(2*l+1)*qubits+i],i)
        for i in range(int(qubits/2-1/2)):
            qc.cz(2*i+1,2*i+2)
    return qc

def __init__(self,n_qubits,noise_models = [],noise_values = []):
    self.n_qubits = n_qubits
    self.ansatz = QuantumCircuit(n_qubits)

def create_quantum_circuit(circuit_type: str, num_qubits: int) -> QuantumCircuit:
    """Create quantum circuit based on type"""
    qc = QuantumCircuit(num_qubits)

    if circuit_type == "bell_state":
        qc.h(0)
        qc.cx(0, 1)

    elif circuit_type == "ghz":
        qc.h(0)
        for i in range(1, num_qubits):
            qc.cx(0, i)

    elif circuit_type == "vqe":
        # Simple VQE ansatz
        for i in range(num_qubits):
            qc.ry(np.pi / 4, i)
        for i in range(num_qubits - 1):
            qc.cx(i, i + 1)

    else:
        # Default: Hadamard on all qubits
        for i in range(num_qubits):
            qc.h(i)

    qc.measure_all()
    return qc

def generate_quantum_key(self, num_qubits):
    """Generate a quantum key represented as quantum states."""
    qc = QuantumCircuit(num_qubits)
    for qubit in range(num_qubits):
        qc.h(qubit)  # Apply Hadamard gate for superposition
    return qc

def generate_signature(self, message, private_key):
    """Generate a quantum signature using the private key."""
    num_qubits = len(message)
    qc = QuantumCircuit(num_qubits)
    for i, bit in enumerate(message):
        if bit == '1':
            qc.x(i)  # Apply X gate for '1'
    qc.compose(private_key, inplace=True)
    return qc

def create_variational_circuit(self, input_angles, theta_params):
    """Create parameterized quantum circuit for encoding"""
    qc = QuantumCircuit(self.n_qubits)

    # Amplitude encoding of input data
    for i in range(min(len(input_angles), self.n_qubits)):
        qc.ry(input_angles[i], i)

    # Variational layers with entanglement
    for layer in range(2):
        # Parameterized single-qubit gates
        for i in range(self.n_qubits):
            param_idx = layer * self.n_qubits + i
            if param_idx < len(theta_params):
                qc.rx(theta_params[param_idx], i)
                qc.ry(theta_params[param_idx], i)
                qc.rz(theta_params[param_idx], i)

        # Entangling gates (CNOT ladder)
        for i in range(self.n_qubits - 1):
            qc.cx(i, i + 1)
        if self.n_qubits > 2:
            qc.cx(self.n_qubits - 1, 0)  # Circular connectivity

    return qc

def create_decoder_circuit(self, latent_encoding, theta_params):
    """Create quantum circuit for decoding"""
    qc = QuantumCircuit(self.n_qubits)

    # Encode latent variables
    for i in range(min(len(latent_encoding), self.n_qubits)):
        qc.ry(latent_encoding[i], i)

    # Variational decoding layers
    for layer in range(2):
        # Parameterized gates
        for i in range(self.n_qubits):
            param_idx = layer * self.n_qubits + i
            if param_idx < len(theta_params):
                qc.rx(theta_params[param_idx], i)
                qc.ry(theta_params[param_idx], i)
                qc.rz(theta_params[param_idx], i)

        # Entangling gates
        for i in range(self.n_qubits - 1):
            qc.cx(i, i + 1)
        if self.n_qubits > 2:
            qc.cx(self.n_qubits - 1, 0)

    return qc

def generate_circuit_from_line(line, num_qubits):
    qc = QuantumCircuit(num_qubits)
    commands = line.strip().split(' ')[2:]  # Skip the 'Circuit X:' part
    for cmd in commands:
        gate, args = cmd.split('(')
        args = args.strip(')').split(',')

        if gate in ['x', 'y', 'z', 'h', 's', 'sdg', 't', 'tdg']:
            getattr(qc, gate)(int(args[0]))
        elif gate in ['rx', 'ry', 'rz']:
            if 'pi/2' in args[0]:
                angle = np.pi / 2
            else:
                angle = float(args[0])  # Assuming other angles are directly specified
            getattr(qc, gate)(angle, int(args[1]))
        elif gate == 'cx':
            getattr(qc, gate)(int(args[0]), int(args[1]))
    return qc

def quantum_circuit(num_qubits, gate_type, gate_qubits):
  qc = QuantumCircuit(num_qubits)
  if gate_type=="H":
    assert type(gate_qubits)==int
    qc.h(gate_qubits)
  elif gate_type=="S":
    assert type(gate_qubits)==int
    qc.s(gate_qubits)
  elif len(gate_qubits)==2:
    qc.cx(gate_qubits[0], gate_qubits[1])
  return qc

def init_circuit(action_map, d, num_qubits):
  qc = QuantumCircuit(num_qubits)
  target_sequence = random.choices(list(action_map.values()), k=d)
  for gate in target_sequence:
    gate_type = gate[0]
    gate_qubits = gate[1]
    if gate_type=="H":
      assert type(gate_qubits)==int
      qc.h(gate_qubits)
    elif gate_type=="S":
      assert type(gate_qubits)==int
      qc.s(gate_qubits)
    elif len(gate_qubits)==2:
      qc.cx(gate_qubits[0], gate_qubits[1])
  return Clifford(qc)

def preprocessing(qc, only_cx=False):
    prg = load_program(qc)
    prg.remove_idle_qubits()
    qc = prg.program
    new_circuit = QuantumCircuit(qc.num_qubits, qc.num_qubits)
    qubit_map = {}
    for i, q in enumerate(qc.qubits):
        qubit_map[q] = new_circuit.qubits[i]

    for gate in qc.data:
        if gate.operation.name == 'measure':
            continue
        if gate.operation.name == 'barrier':
            continue
        if len(gate.qubits) == 2 and gate.operation.name != 'cx':
            print("error")
        if only_cx and gate.operation.name != 'cx':
            continue
        new_qubits = []
        for q in gate.qubits:
            new_qubits.append(qubit_map[q])
        new_circuit.append(gate.operation, new_qubits)
    new_circuit.measure(list(range(new_circuit.num_qubits)), list(range(new_circuit.num_qubits)))
    return new_circuit

def recv_quantum(quantum_state: list):
    # Load state
    quantum = [qiskit.QuantumCircuit(1, 1) for _ in range(4)]
    # Recover quantum
    for i in range(4):
        real_part_a = quantum_state[i][0].real
        real_part_b = quantum_state[i][1].real
        if real_part_a == 1.0 and real_part_b == 0.0:
            continue
        elif real_part_a == 0.0 and real_part_b == 1.0:
            quantum[i].x(0)
        elif real_part_a > 0.7 and real_part_b > 0.7:
            quantum[i].h(0)
        else:
            quantum[i].x(0)
            quantum[i].h(0)
    return quantum

def make_ham(self, measure=True, modified_trotter=True):
    """Make the hamiltonian n times after initialization
    """
    if self.V is None:
        raiseExceptions("Please set V with ham.set_V()")
    self.circ = QuantumCircuit(self.q)
    self.initilize(self.start_mu, self.start_sigma, self.p0)
    for i in range(self.ntimes):
        if modified_trotter:
            self.add_H_once_modified_trotter()
        else:
            self.add_H_once()
    if measure:
        self.circ.measure_all()

def export(self, _selfqc, mode: Literal["circuit", "gate"]):  # noqa: C901
    from qiskit import QuantumCircuit
    from qiskit.circuit.library.standard_gates import ZGate

    qc = QuantumCircuit(_selfqc.num_qubits, 0)

    for g, w, p in _selfqc.gates:
        g_name = g.__class__.__name__.lower()

        if isinstance(g, gates.MCX) or (
            isinstance(g, gates.MCtrl) and isinstance(g.gate, gates.X)
        ):
            qc.mcx(w[0:-1], w[-1])
        elif isinstance(g, gates.MCtrl) and isinstance(g.gate, gates.Z):
            zg = ZGate().control(len(w[0:-1]))
            qc.append(zg, w)

        elif isinstance(g, gates.Barrier) and mode != "gate":
            qc.barrier(label=p)

        elif issubclass(g.__class__, gates.NopGate):
            pass

        elif hasattr(qc, g_name):
            if p:
                getattr(qc, g_name)(p, *w)
            else:
                getattr(qc, g_name)(*w)

        else:
            raise Exception(f"Gate not handled for qiskit exporter: {g_name}")

    if mode == "gate":
        qc.remove_final_measurements()
        gate = qc.to_gate()

        gate.name = _selfqc.name

        if hasattr(QuantumCircuit, _selfqc.name):
            gate.name += "_"

        return gate
    elif mode == "circuit":
        return qc
    else:
        raise Exception(f"Uknown export mode: {mode}")

def build_oracle(n: int, f) -> QuantumCircuit:
    # implement the oracle O_f^\pm
    # NOTE: use U1 gate (P gate) with \lambda = 180 ==> CZ gate
    # or multi_control_Z_gate (issue #127)

    controls = QuantumRegister(n, "ofc")
    target = QuantumRegister(1, "oft")
    oracle = QuantumCircuit(controls, target, name="Of")
    for i in range(2 ** n):
        rep = np.binary_repr(i, n)
        if f(rep) == "1":
            for j in range(n):
                if rep[j] == "0":
                    oracle.x(controls[j])
            oracle.mct(controls, target[0], None, mode='noancilla')
            for j in range(n):
                if rep[j] == "0":
                    oracle.x(controls[j])
            # oracle.barrier()
    # oracle.draw('mpl', filename='circuit/deutsch-oracle.png')
    return oracle

def build_oracle(n: int, f) -> QuantumCircuit:
    # implement the oracle O_f^\pm
    # NOTE: use U1 gate (P gate) with \lambda = 180 ==> CZ gate
    # or multi_control_Z_gate (issue #127)

    controls = QuantumRegister(n, "ofc")
    oracle = QuantumCircuit(controls, name="Zf")

    for i in range(2 ** n):
        rep = np.binary_repr(i, n)
        if f(rep) == "1":
            for j in range(n):
                if rep[j] == "0":
                    oracle.x(controls[j])

            # oracle.h(controls[n])
            if n >= 2:
                oracle.mcu1(pi, controls[1:], controls[0])

            for j in range(n):
                if rep[j] == "0":
                    oracle.x(controls[j])
            # oracle.barrier()

    return oracle

def Subtractor2(K, modular=False, circuit=True):
    '''
    Same as Subtractor, except the register organization is different.

    Register Organization:
        |anc> |a> |b> --> |anc> |a-b> |b>
    '''

    b= QuantumRegister(K)
    anc= QuantumRegister(1)

    if modular == False:
        a= QuantumRegister(K+1)
    else:
        a= QuantumRegister(K)

    qc= QuantumCircuit(anc, a, b)

    qc.x(a[:K])

    if modular == False:
        qc.compose(RippleAdder(K, modular=False, circuit=True), anc[:] + b[:] + a[:], inplace=True)
    else:
        qc.compose(RippleAdder(K, modular=True, circuit=True), anc[:] + b[:] + a[:], inplace=True)

    qc.x(a)

    if circuit:
        return qc
    else:
        return qc.to_gate(label='subtractor2')

def build_oracle(n: int, f) -> QuantumCircuit:
    # implement the oracle O_f
    # NOTE: use multi_control_toffoli_gate ('noancilla' mode)
    # https://qiskit.org/documentation/_modules/qiskit/aqua/circuits/gates/multi_control_toffoli_gate.html
    # https://quantumcomputing.stackexchange.com/questions/3943/how-do-you-implement-the-toffoli-gate-using-only-single-qubit-and-cnot-gates
    # https://quantumcomputing.stackexchange.com/questions/2177/how-can-i-implement-an-n-bit-toffoli-gate
    controls = QuantumRegister(n, "ofc")
    target = QuantumRegister(1, "oft")
    oracle = QuantumCircuit(controls, target, name="Of")
    for i in range(2 ** n):
        rep = np.binary_repr(i, n)
        if f(rep) == "1":
            for j in range(n):
                if rep[j] == "0":
                    oracle.x(controls[j])
            oracle.mct(controls, target[0], None, mode='noancilla')
            for j in range(n):
                if rep[j] == "0":
                    oracle.x(controls[j])
            # oracle.barrier()
    return oracle

