def haar_random_circuit(x, n_qubits=2, depth=2, seed=None):
    if seed is not None:
        np.random.seed(seed)

    qc = QuantumCircuit(n_qubits)

    # Angle encoding
    for i in range(n_qubits):
        qc.ry(x[i], i)

    # Haar-random layers
    for _ in range(depth):
        for i in range(n_qubits):
            theta, phi, lam = np.random.uniform(0, 2*np.pi, 3)
            qc.u(theta, phi, lam, i)

        for i in range(n_qubits - 1):
            qc.cx(i, i + 1)

    return qc

def haar_random_circuit(x, n_qubits=3, depth=2, seed=None):
    if seed is not None:
        np.random.seed(seed)

    qc = QuantumCircuit(n_qubits)

    # Angle encoding
    for i in range(n_qubits):
        qc.ry(x[i], i)

    # Haar-random layers
    for _ in range(depth):
        for i in range(n_qubits):
            theta, phi, lam = np.random.uniform(0, 2*np.pi, 3)
            qc.u(theta, phi, lam, i)

        # Linear entanglement
        for i in range(n_qubits - 1):
            qc.cx(i, i + 1)

    return qc

def construct_circuit(self, x, qr=None, inverse=False):
    """
    Construct the second order expansion based on given data.

    Args:
        x (numpy.ndarray): 1-D to-be-transformed data.
        qr (QauntumRegister): the QuantumRegister object for the circuit, if None,
                              generate new registers with name q.
        inverse (bool): whether or not inverse the circuit

    Returns:
        QuantumCircuit: a quantum circuit transform data x.
    """
    if not isinstance(x, np.ndarray):
        raise TypeError("x must be numpy array.")
    if x.ndim != 1:
        raise ValueError("x must be 1-D array.")
    if x.shape[0] != self._num_qubits:
        raise ValueError("number of qubits and data dimension must be the same.")

    if qr is None:
        qc = self._construct_circuit_with_template(x)
    else:
        qc = QuantumCircuit(qr)
        for _ in range(self._depth):
            for i in range(self._num_qubits):
                qc.u2(0, pi, qr[i])
            for pauli in self._pauli_strings:
                coeff = self._data_map_func(self._extract_data_for_rotation(pauli, x))
                p = Pauli.from_label(pauli)
                qc += Operator.construct_evolution_circuit([[coeff, p]], 1, 1, qr)

    if inverse:
        qc.data = [gate.inverse() for gate in reversed(qc.data)]

    return qc

def __init__(self, qubits, layer, thetaList) -> None:
    self.qubits = qubits
    self.layer = layer -1
    self.theta = thetaList

    nbgates_0_last = self.__countOdd(self.layer + 1)*2
    nbtheta = (nbgates_0_last*2) + (self.qubits-2)*((self.layer+1)*2)

    if (len(self.theta) > nbtheta):
        print('Given theta list is Greater than Required gates')
    elif (len(self.theta) == nbtheta):
        pass
    else:
        print("Number of Elements in theta list provided isn't equal to Gates required in Ansatz. Please check thetaList")
        raise

    if (self.qubits < 4) or (self.qubits%2 != 0):
        print('Qubit must be greater than 4 and qubit must be even')
        raise

    if ((self.layer + 1) <= 2) or ((self.layer+1)%2 != 1):
        print('Layer should always be greater than 2 and layer must be odd number')

    if type(self.qubits) != type(int):
        self.qubits = int(self.qubits)
    else:
        print("Please Check You're Entering Right DataType in place of 'Qubits' parameter")
        raise

    self.qc = QuantumCircuit(self.qubits)

    nbgates_0_last = self.__countOdd(self.layer + 1)*2
    nbgates_all = (self.layer+1)*2

    nbgates_at_each_layer = []
    for i in range(0, self.qubits):
        nbgates_at_each_layer.append(nbgates_all)

    for i in range(0, self.layer + 1):
        if i%2 == 0: # apply first layer with entanglement
            j = 0
            ent = 0
            while j < self.qubits:
                self.qc.ry(self.theta[self.__addAllAtIndex(nbgates_at_each_layer, j) + i*2], j)
                self.qc.rz(self.theta[self.__addAllAtIndex(nbgates_at_each_layer, j) + i *2+ 1], j)   
                j += 1
            if i != self.layer:
                while ent < self.qubits:
                    self.qc.swap(ent, ent+1)
                    ent += 2
        else: 
            j = 0
            ent = 1
            while j < self.qubits:
                self.qc.ry(self.theta[self.__addAllAtIndex(nbgates_at_each_layer, j) + i*2], j)
                self.qc.rz(self.theta[self.__addAllAtIndex(nbgates_at_each_layer, j) + i*2 + 1], j)
                j += 1
            self.qc.i(0)
            while ent < self.qubits -1:
                self.qc.swap(ent, ent+1)
                ent += 2
            self.qc.i(self.qubits-1)

def SuzukiTrotter(self, spinChain):
    '''
    Qiskit instruction for performing a ST step. See chain Hamiltonian
    and ST scheme.
    '''
    # Create quantum circuit
    qc_H = QuantumCircuit(spinChain)
    #  Append TwoSpinEvol with field evolution for odd particles
    for idx in range(0, len(spinChain), 2):
        try:
            qc_H.append(
                self.TwoSpinEvolUnit(), [spinChain[idx], spinChain[idx+1]])
        except:
            continue
    #  Append TwoSpinEvol with field evolution for even particles
    for idx in range(1, len(spinChain), 2):
        try:
            qc_H.append(
                self.TwoSpinEvolUnit(), [spinChain[idx], spinChain[idx+1]])
        except:
            continue
    # Perform time evolution of mag. field
    qc_H.append(self.MagFieldEvol(spinChain), spinChain)
    # Return instruction
    return qc_H.to_instruction()

def build_surface_code(distance: int = 3) -> QuantumCircuit:
    """Builds a d=3 surface code circuit measuring only Z-stabilizers."""
    if distance != 3:
        raise ValueError(f"Only distance=3 is supported, got distance={distance}")
    q    = QuantumRegister(9, 'q')
    anc  = QuantumRegister(4, 'anc')
    creg = ClassicalRegister(4, 'syndrome')
    qc   = QuantumCircuit(q, anc, creg)
    for i, qubits in enumerate(_Z_STABILIZERS):
        for dq in qubits:
            qc.cx(q[dq], anc[i])
        qc.measure(anc[i], creg[i])
    return qc

