def _build_qiskit_circuit_quantinuum(circuit_data: dict) -> QuantumCircuit:
    """Builds a Qiskit QuantumCircuit from the standardized circuit data."""
    num_qubits = circuit_data["qubits"]
    circuit = QuantumCircuit(num_qubits, num_qubits) # Classical bits for measurement

    for gate_info in circuit_data["gates"]:
        gate_type = gate_info["gate"].lower()

        if gate_type == "h":
            circuit.h(gate_info["target"])
        elif gate_type == "x":
            circuit.x(gate_info["target"])
        elif gate_type == "y":
            circuit.y(gate_info["target"])
        elif gate_type == "z":
            circuit.z(gate_info["target"])
        elif gate_type == "s":
            circuit.s(gate_info["target"])
        elif gate_type == "sdg":
            circuit.sdg(gate_info["target"])
        elif gate_type == "t":
            circuit.t(gate_info["target"])
        elif gate_type == "tdg":
            circuit.tdg(gate_info["target"])
        elif gate_type == "rx":
            circuit.rx(gate_info["params"]["theta"], gate_info["target"])
        elif gate_type == "ry":
            circuit.ry(gate_info["params"]["theta"], gate_info["target"])
        elif gate_type == "rz":
            circuit.rz(gate_info["params"]["theta"], gate_info["target"])
        elif gate_type == "cx":
            circuit.cx(gate_info["control"], gate_info["target"])
        elif gate_type == "ccx":
            controls = gate_info["controls"]
            if len(controls) == 2:
                circuit.ccx(controls[0], controls[1], gate_info["target"])
            else:
                raise ValueError(f"CCX gate requires exactly 2 control qubits, got {len(controls)}")
        elif gate_type == "swap":
            circuit.swap(gate_info["target"], gate_info["control"])
        elif gate_type == "measure":
            circuit.measure(gate_info["target"], gate_info["target"])
        else:
            raise ValueError(f"Unsupported gate type for Quantinuum (Azure Quantum): {gate_type}")
    return circuit

def get_ansatz(self, params):
    qc = QuantumCircuit(self.num_qubits)
    if torch.is_tensor(params):
        p_np = params.detach().numpy().reshape((self.num_layers, self.num_qubits, 3))
    else:
        p_np = params.reshape((self.num_layers, self.num_qubits, 3))

    for l in range(self.num_layers):
        for q in range(self.num_qubits):
            qc.u(float(p_np[l, q, 0]), float(p_np[l, q, 1]), float(p_np[l, q, 2]), q)
        for q in range(self.num_qubits):
            qc.cx(q, (q + 1) % self.num_qubits)
    return qc

def _build_circuit(inputs, weights, bias, shifts=None, asp_params=None, qda_std=0.0):
    qc = QuantumCircuit(num_qubits)
    if asp_params is not None:
        asp_qc = asp.get_ansatz(asp_params)
        qc.compose(asp_qc, inplace=True)

    # Quantum Data Augmentation (Micro-rotations) - ACTIVE Defense
    if qda_std > 0:
        for q in range(num_qubits):
            qc.rx(np.random.normal(0, qda_std), q)
            qc.ry(np.random.normal(0, qda_std), q)
            qc.rz(np.random.normal(0, qda_std), q)

    if shifts is None:
        shifts = np.zeros((num_layers, num_qubits, 3))

    for l in range(num_layers):
        for q in range(num_qubits):
            val = weights[l, q] * inputs[l, q] + bias[l, q] + shifts[l, q]
            qc.rz(val[0], q)
            qc.ry(val[1], q)
            qc.rz(val[2], q)
        r = (l % (num_qubits - 1)) + 1
        for q in range(num_qubits):
            qc.cx(q, (q + r) % num_qubits)
    qc.measure_all()
    return qc

