def _get_target_state(self):
    if self.mode == 'custom' and self.custom_target_state is not None:
        return self.custom_target_state

    qc = QuantumCircuit(self.num_qubits)
    if self.mode == 'ghz':
        qc.h(0)
        for i in range(self.num_qubits - 1):
            qc.cx(i, i + 1)
    elif self.mode == 'bell':
        qc.h(0); qc.cx(0, 1)
    elif self.mode == 'w':
        if self.num_qubits == 3:
            qc.ry(2 * np.arccos(1 / np.sqrt(3)), 0)
            qc.cx(0, 1)
            qc.ry(2 * np.arccos(1 / np.sqrt(2)), 1)
            qc.cx(1, 2)
        else:
            raise NotImplementedError("W state only implemented for 3 qubits.")
    return Statevector.from_label('0' * self.num_qubits).evolve(qc)

def create_kicked_ising_otoc(n, depth, J=0.9, h=0.7):
    qr = QuantumRegister(n, 'q')
    cr = ClassicalRegister(n, 'c')
    qc = QuantumCircuit(qr, cr)

    qc.h(qr[0])
    qc.x(qr[0])

    for _ in range(depth):
        for i in range(n):
            qc.rx(2 * h, qr[i])
        for i in range(n - 1):
            qc.rzz(2 * J, qr[i], qr[i + 1])
        qc.rzz(2 * J, qr[n-1], qr[0])

    qc.z(qr[n - 1])

    for _ in range(depth):
        qc.rzz(-2 * J, qr[n-1], qr[0])
        for i in range(n - 2, -1, -1):
            qc.rzz(-2 * J, qr[i], qr[i + 1])
        for i in range(n):
            qc.rx(-2 * h, qr[i])

    qc.x(qr[0])
    qc.measure(qr, cr)

    return qc

