def _build(self) -> None:
    """If not already built, build the circuit."""
    if self._is_built:
        return

    super()._build()

    qr_state = self.qubits[: self.num_state_qubits]
    q_compare = self.qubits[self.num_state_qubits]
    qr_ancilla = self.qubits[self.num_state_qubits + 1 :]

    circuit = QuantumCircuit(*self.qregs, name=self.name)

    if self.value <= 0:  # condition always satisfied for non-positive values
        if self._geq:  # otherwise the condition is never satisfied
            circuit.x(q_compare)
    # condition never satisfied for values larger than or equal to 2^n
    elif self.value < pow(2, self.num_state_qubits):

        if self.num_state_qubits > 1:
            twos = self._get_twos_complement()
            for i in range(self.num_state_qubits):
                if i == 0:
                    # if twos[i] == 1:                          #  Delete    
                    circuit.cx(qr_state[i], qr_ancilla[i])
                elif i < self.num_state_qubits - 1:
                    if twos[i] == 1:
                        circuit.compose(
                            OR(2), [qr_state[i], qr_ancilla[i - 1], qr_ancilla[i]], inplace=True
                        )
                    else:
                        circuit.ccx(qr_state[i], qr_ancilla[i - 1], qr_ancilla[i])
                else:
                    if twos[i] == 1:
                        # OR needs the result argument as qubit not register, thus
                        # access the index [0]
                        circuit.compose(
                            OR(2), [qr_state[i], qr_ancilla[i - 1], q_compare], inplace=True
                        )
                    else:
                        circuit.ccx(qr_state[i], qr_ancilla[i - 1], q_compare)

            # flip result bit if geq flag is false
            if not self._geq:
                circuit.x(q_compare)                            

            # uncompute ancillas state
            for i in reversed(range(self.num_state_qubits - 1)):
                if i == 0:
                    if twos[i] == 1:
                        circuit.cx(qr_state[i], qr_ancilla[i])
                else:
                    if twos[i] == 1:
                        circuit.compose(
                            OR(2), [qr_state[i], qr_ancilla[i - 1], qr_ancilla[i]], inplace=True
                        )
                    else:
                        circuit.ccx(qr_state[i], qr_ancilla[i - 1], qr_ancilla[i])
        else:

            # num_state_qubits == 1 and value == 1:
            circuit.cx(qr_state[0], q_compare)

            # flip result bit if geq flag is false
            if not self._geq:
                circuit.x(q_compare)

    else:
        if not self._geq:  # otherwise the condition is never satisfied
            circuit.x(q_compare)

    self.append(circuit.to_gate(), self.qubits)

def _build_circuit(self) -> QuantumCircuit:
    qc = QuantumCircuit(self.n_qubits)
    # Parameterised single‑qubit rotations
    for i, theta in enumerate(self.theta):
        qc.rx(theta, i)
    # Simple nearest‑neighbour entanglement
    for i in range(self.n_qubits - 1):
        qc.cx(i, i + 1)
    qc.barrier()
    return qc

def AnsatzCircuit(params, p):
    """
    Implements HVA ansatz using circuits from https://arxiv.org/pdf/1906.06343.pdf
    :param params: parameters to parameterize circuit
    :param p: depth of the ansatz
    """
    circ = QuantumCircuit(L)

    def get_angles(a):
        return (np.pi/2 - 2*a, 2*a - np.pi/2, np.pi/2 - 2*a)

    def N(cir, angles, qb0, qb1):
        cir.rz(-np.pi/2, qb1)
        cir.cnot(qb1, qb0)
        cir.rz(angles[0], qb0)
        cir.ry(angles[1], qb1)
        cir.cnot(qb0, qb1)
        cir.ry(angles[2], qb1)
        cir.cnot(qb1, qb0)
        cir.rz(np.pi/2, qb0)
        return cir

    for i in range(p):
        if (L % 2 == 0):
            for j in range(1, L-1, 2): # L for periodic bdy conditions
                circ = N(circ, get_angles(-params[((L-1)*i)+j]/4), j, (j+1)%L)
            for j in range(0, L-1, 2):
                circ = N(circ, get_angles(-params[((L-1)*i)+j]/4), j, (j+1)%L)
        else:
            for j in range(1, L, 2):
                circ = N(circ, get_angles(-params[((L-1)*i)+j]/4), j, (j+1)%L)
            for j in range(0, L-1, 2):
                circ = N(circ, get_angles(-params[((L-1)*i)+j]/4), j, (j+1)%L)
            # circ = N(circ, get_angles(-params[(L*i)+L-1]/4), L-1, 0) # boundary
    return circ

def apply_one_qubit(u):
  circ = QuantumCircuit(1)
  if isclose(u[0][0], -u[1][1]) and isclose(u[1][0], u[0][1]):
    circ.z(0)
  theta = atan2(u[1][0], u[0][0])
  circ.ry(2 * theta, 0)
  return circ.to_gate()

def random_circuit_with_bias(nqubits, depth, bias_strength=0.0):
    qc = QuantumCircuit(nqubits)
    for layer in range(depth):
        for q in range(nqubits):
            if np.random.rand() > (0.5 - bias_strength*0.3):
                qc.h(q)
        if nqubits > 1 and np.random.rand() > 0.6:
            for q in range(nqubits - 1):
                if np.random.rand() > 0.5:
                    qc.cx(q, q+1)
        for q in range(nqubits):
            angle = np.pi * bias_strength if bias_strength > 0 else np.random.uniform(0, 2*np.pi)
            qc.rz(angle, q)
    qc.measure_all()
    return qc

def Measure_A(self, init_circ, params, N, shots=2**10, noisy=False):
    A = [[0.0 for i in range(len(params))] for j in range(len(params))]
    for i in range(len(params)):
        for j in range(len(params)-i):
            if(i%(2*N-1) < N):
                if((i+j)%(2*N-1) < N):
                    qc = QuantumCircuit(N+1, 1)
                    ansatz = self.A_Circuit(params, i, i+j, N, True, True)
                    qc = qc.compose(init_circ, [k for k in range(N)])
                    qc = qc.compose(ansatz, [k for k in range(N+1)])

                    observable = SparsePauliOp.from_list([("Z"+"I"*N, 1.0)])
                    if noisy:
                        device_backend = FakeSherbrooke()
                        coupling_map = device_backend.coupling_map
                        noise_model = NoiseModel.from_backend(device_backend)
                        basis_gates = noise_model.basis_gates
                        estimator = Estimator(options={
                                            "backend_options":{"noise_model": noise_model},
                                            "run_options":{"shots": shots}}
                        )
                    else:
                        estimator = Estimator(options={"run_options":{"shots": shots}})
                    result = estimator.run([(qc.decompose(), observable)]).result()

                    A[i][i+j] += 1/4*result[0].data.evs
                    if(j != 0):
                        A[i+j][i] += 1/4*result[0].data.evs
                else:
                    for XX2 in [True, False]:
                        qc = QuantumCircuit(N+1, 1)
