def Measure_C(self, init_circ, params, H, N, shots=2**10, evolution_type="real", noisy=False):
    C = [0.0 for i in range(len(params))]
    for i in range(len(params)):
        for pauli_string in range(len(H.paulis)):
            if(i%(2*N-1) < N):
                qc = QuantumCircuit(N+1, 1)
                ansatz = self.C_Circuit(params, i, H.paulis[pauli_string], N, True, evolution_type=evolution_type)
                qc = qc.compose(init_circ, [k for k in range(N)])
                qc = qc.compose(ansatz, [k for k in range(N+1)])

                observable = SparsePauliOp.from_list([("Z"+"I"*N, 1.0)])
                if noisy:
                    device_backend = FakeSherbrooke()
                    coupling_map = device_backend.coupling_map
                    noise_model = NoiseModel.from_backend(device_backend)
                    basis_gates = noise_model.basis_gates
                    estimator = Estimator(options={
                                        "backend_options":{"noise_model": noise_model},
                                        "run_options":{"shots": shots}}
                    )
                else:
                    estimator = Estimator(options={"run_options":{"shots": shots}})
                result = estimator.run([(qc.decompose(), observable)]).result()

                C[i] -= 1/2*H.coeffs[pauli_string].real*result[0].data.evs
            else:
                for XX in [True, False]:
                    qc = QuantumCircuit(N+1, 1)
                    ansatz = self.C_Circuit(params, i, H.paulis[pauli_string], N, XX, evolution_type=evolution_type)
                    qc = qc.compose(init_circ, [k for k in range(N)])
                    qc = qc.compose(ansatz, [k for k in range(N+1)])

                    observable = SparsePauliOp.from_list([("Z"+"I"*N, 1.0)])
                    if noisy:
                        device_backend = FakeSherbrooke()
                        coupling_map = device_backend.coupling_map
                        noise_model = NoiseModel.from_backend(device_backend)
                        basis_gates = noise_model.basis_gates
                        estimator = Estimator(options={
                                            "backend_options":{"noise_model": noise_model},
                                            "run_options":{"shots": shots}}
                        )
                    else:
                        estimator = Estimator(options={"run_options":{"shots": shots}})
                    result = estimator.run([(qc.decompose(), observable)]).result()

                    C[i] -= 1/2*H.coeffs[pauli_string].real*result[0].data.evs#*1/2
    return C

def Construct_Ansatz(self, init_circ=None, params=None, N=None):
    if(params is None):
        num_params = self.num_qubits * (self.num_layers + 1) + (self.num_qubits-1) * self.num_layers
        params = np.zeros(num_params)
    if(N is None):
        N = self.num_qubits
    qc = QuantumCircuit(N)
    if(init_circ is None):
        init_circ = QuantumCircuit(N)
    qc.compose(init_circ, [k for k in range(N)], inplace=True)
    for parameter in range(len(params)):# Apply parameterized gates
        self.apply_param(params, parameter, qc, N)
    return qc

def add_register(self, *regs: Register | int | Sequence[Bit]) -> None:
    """Add registers."""
    if not regs:
        return

    if any(isinstance(reg, int) for reg in regs):
        # QuantumCircuit defined without registers
        if len(regs) == 1 and isinstance(regs[0], int):
            # QuantumCircuit with anonymous quantum wires e.g. QuantumCircuit(2)
            if regs[0] == 0:
                regs = ()
            else:
                regs = (QuantumRegister(regs[0], "q"),)
        elif len(regs) == 2 and all(isinstance(reg, int) for reg in regs):
            # QuantumCircuit with anonymous wires e.g. QuantumCircuit(2, 3)
            if regs[0] == 0:
                qregs: tuple[QuantumRegister, ...] = ()
            else:
                qregs = (QuantumRegister(regs[0], "q"),)
            if regs[1] == 0:
                cregs: tuple[ClassicalRegister, ...] = ()
            else:
                cregs = (ClassicalRegister(regs[1], "c"),)
            regs = qregs + cregs
        else:
            raise CircuitError(
                "QuantumCircuit parameters can be Registers or Integers."
                " If Integers, up to 2 arguments. QuantumCircuit was called"
                " with %s." % (regs,)
            )

    for register in regs:
        if isinstance(register, Register) and any(
            register.name == reg.name for reg in self.qregs + self.cregs
        ):
            raise CircuitError('register name "%s" already exists' % register.name)

        if isinstance(register, AncillaRegister):
            for bit in register:
                if bit not in self._qubit_indices:
                    self._ancillas.append(bit)

        if isinstance(register, QuantumRegister):
            self.qregs.append(register)

            for idx, bit in enumerate(register):
                if bit in self._qubit_indices:
                    self._qubit_indices[bit].registers.append((register, idx))
                else:
                    self._data.add_qubit(bit)
                    self._qubit_indices[bit] = BitLocations(
                        len(self._data.qubits) - 1, [(register, idx)]
                    )

        elif isinstance(register, ClassicalRegister):
            self.cregs.append(register)

            for idx, bit in enumerate(register):
                if bit in self._clbit_indices:
                    self._clbit_indices[bit].registers.append((register, idx))
                else:
                    self._data.add_clbit(bit)
                    self._clbit_indices[bit] = BitLocations(
                        len(self._data.clbits) - 1, [(register, idx)]
                    )

        elif isinstance(register, list):
            self.add_bits(register)
        else:
            raise CircuitError("expected a register")

def qft_dagger(n):
    qc = QuantumCircuit(n)
    for qubit in range(n//2):
        qc.swap(qubit, n-qubit-1)
    for j in range(n):
        for m in range(j):
            qc.cp(-np.pi/float(2**(j-m)), m, j)       # Controlled phase gate which induces a phase given a control=1
        qc.h(j)
    qc.name = "QFT†"
    return qc

def c_amod15(a, power):
    if a not in [2,7,8,11,13]:
        raise ValueError("'a' must be 2,7,8,11 or 13") # Or else it would share factors with N=15.
    U = QuantumCircuit(4)        
    for iteration in range(power):
        if a in [2,13]:
            U.swap(0,1)
            U.swap(1,2)
            U.swap(2,3)
        if a in [7,8]:
            U.swap(2,3)
            U.swap(1,2)
            U.swap(0,1)
        if a == 11:
            U.swap(1,3)
            U.swap(0,2)
        if a in [7,11,13]:
            for q in range(4):
                U.x(q)
    U = U.to_gate()
    U.name = "%i^%i mod 15" % (a, power)
    c_U = U.control()
    return c_U

def make_circuit_family(num_qubits: int, num_circuits: int, rng: random.Random):
    from qiskit import QuantumCircuit
    from qiskit.quantum_info import SparsePauliOp

    circuits: List[QuantumCircuit] = []
    observables: List[SparsePauliOp] = []
    for _ in range(num_circuits):
        qc = QuantumCircuit(num_qubits)
        for qubit in range(num_qubits):
            qc.h(qubit)
        for layer in range(4):
            for qubit in range(num_qubits):
                qc.rz(rng.uniform(-np.pi, np.pi), qubit)
            for qubit in range(num_qubits - 1):
                qc.cx(qubit, qubit + 1)
            target = rng.randrange(num_qubits)
            qc.rx(rng.uniform(-np.pi, np.pi), target)
        qc.measure_all(False)
        circuits.append(qc)
        observables.append(SparsePauliOp.from_list([("Z" + "I" * (num_qubits - 1), 1.0)]))
    return circuits, observables

