        if full_entangle:
            # Full entanglement: all-to-all connectivity
            for i in range(num_qubits):
                for j in range(i + 1, num_qubits):
                    qc.cx(i, j)
        else:
            # Linear entanglement: nearest-neighbor connectivity
            for i in range(num_qubits - 1):
                qc.cx(i, i + 1)

        # Rotation layer
        for i in range(num_qubits):
            qc.ry(data_params[i] + theta_params[param_idx], i)
            param_idx += 1
        for i in range(num_qubits):
            qc.rz(data_params[i] + theta_params[param_idx], i)
            param_idx += 1

    return qc

def createQCircuit(board):
    # Create a Quantum Register with the necessary number of qubits
    q = QuantumRegister(9)
    # Create a Classical Register with the necessary number of bits
    c = ClassicalRegister(9)
    # Create a Quantum Circuit
    qc = QuantumCircuit(q, c)

    index = 0
    for i in range(0, len(board)):
        for j in range(0, len(board[i])):
            if board[i][j] == 'X':
                qc.x(q[index])
            else:
                qc.h(q[index])
            index+=1

    index = 0
    for i in range(0, len(board)):
        for j in range(0, len(board[i])):
            if board[i][j] == 'X':
                # add T gate to every option
                # row checks
                if i + 1 < 3 :
                    qc.t(q[index+1])
                if i - 1 >= 0:
                    qc.t(q[index-1])
                # column checks
                if j + 1 < 3 and index+3 < 9:
                    qc.t(q[index+3])
                if j - 1 >= 0 and index-3 >= 0:
                    qc.t(q[index-3])
                # diagonal checks
                if i == j :
                    qc.t(q[0])
                    qc.t(q[4])
                    qc.t(q[8])
                if (i == 0 and j == 2) or (i == 2 and j == 0):
                    qc.t(q[2])
                    qc.t(q[4])
                    qc.t(q[6])

            index += 1

    # apply an H gate and measure
    qc.h(q)
    qc.measure(q, c)
    return qc

