    circuit = QuantumCircuit(self.qr, self.cr)
    for i in range(self.n_qubits):
        circuit.rx(rotation_params[3 * i], i)
        circuit.ry(rotation_params[3 * i + 1], i)
        circuit.rz(rotation_params[3 * i + 2], i)
    for i in range(self.n_qubits - 1):
        circuit.cx(i, i + 1)
    return circuit

def _patch_circuit(self, data: np.ndarray) -> QuantumCircuit:
    qc = QuantumCircuit(self.n_wires)
    for i, val in enumerate(data):
        qc.initialize([np.cos(val), np.sin(val)], i)
    for i in range(self.n_wires - 1):
        qc.cx(i, i + 1)
    return qc

def qft_inverse(num_qubits):
    """
    Implements the inverse Quantum Fourier Transform (QFT).
    This reverses the quantum states back into a classical readable form.
    """
    qft_circuit = QuantumCircuit(num_qubits)

    for j in range(num_qubits):
        for k in range(j):
            qft_circuit.cp(-np.pi / (2 ** (j - k)), k, j)  # Controlled Phase Shift
        qft_circuit.h(j)  # Hadamard gate
    for qubit in range(num_qubits // 2):
        qft_circuit.swap(qubit, num_qubits - qubit - 1)  # Swap qubits for proper ordering

    return qft_circuit.to_gate(label="QFT†")

def get_evolution_circuit(string, dt):
    num_qubits = len(string)
    qc = QuantumCircuit(num_qubits)
    unique_angles = []
    if string == 'I'*num_qubits:
        pass
    else:
        active_qubits = [i for i in range(len(string)) if string[i] != 'I']
        active_string = "".join([string[i] for i in active_qubits])
        num_active_qubits = len(active_string)
        active_qc = QuantumCircuit(num_active_qubits)

        for i, op in enumerate(active_string):
            if op == 'X':
                active_qc.h(i)
            elif op == 'Y':
                active_qc.sdg(i)
                active_qc.h(i)
        for i in range(num_active_qubits-1):
            active_qc.cx(i, i + 1)
        active_qc.rz(2 * dt, num_active_qubits-1)
        unique_angles.append(2 * dt)
        for i in range(num_active_qubits-1, 0, -1):
            active_qc.cx(i-1, i)
        for i, op in enumerate(active_string):
            if op == 'X':
                active_qc.h(i)
            elif op == 'Y':
                active_qc.h(i)
                active_qc.s(i)
        qc.compose(active_qc, qubits=active_qubits, inplace=True)
        # qc.barrier()
    return qc, list(set(unique_angles))

def one_step_circuit(self):
    qc = QuantumCircuit(self.num_qubits)
    unique_angles = []
    for string, coef in zip(self.H.strings, self.H.coeffs):
        dt_circ, angles = get_evolution_circuit(string, coef * self.dt)
        qc = qc.compose(dt_circ)
        unique_angles += angles
    return qc, list(set(unique_angles))

def full_circuit(self, plus_state=False):
    qc = QuantumCircuit(self.num_qubits)
    if plus_state:
        qc.h(range(self.num_qubits))
    for _ in np.arange(self.start_time, self.end_time, self.dt):
        circuit, unique_angles = self.one_step_circuit()
        qc = qc.compose(circuit)
    return qc, unique_angles

