def ir_to_native(c: Circuit) -> qiskit.QuantumCircuit:
    """
    Make a qiskit circuit from a qcware_transpile Circuit
    """
    # qiskit wants the number of qubits first.
    num_qubits = max(c.qubits) - min(c.qubits) + 1
    _clbits = c.metadata.get("clbits", []) if c.metadata is not None else {}
    # this is slightly different because we only list classical bits used and assume
    # they start from 0 without checking for unused edge bits.
    num_clbits = len(_clbits)
    result = (
        qiskit.QuantumCircuit(num_qubits)
        if num_clbits == 0
        else qiskit.QuantumCircuit(num_qubits, num_clbits)
    )
    for instruction in c.instructions:
        g = qiskit_gate_from_instruction(instruction)
        if "clbits" in instruction.metadata:
            result.append(g, instruction.bit_bindings, instruction.metadata["clbits"])
        else:
            result.append(g, instruction.bit_bindings)
    result = result.reverse_bits()
    return result

def quantum_fourier_transform(number_of_qubits: int = 3) -> qiskit.result.counts.Counts:
    if isinstance(number_of_qubits, str):
        raise TypeError("number of qubits must be a integer.")
    if number_of_qubits <= 0:
        raise ValueError("number of qubits must be > 0.")
    if math.floor(number_of_qubits) != number_of_qubits:
        raise ValueError("number of qubits must be exact integer.")
    if number_of_qubits > 10:
        raise ValueError("number of qubits too large to simulate(>10).")

    qr = QuantumRegister(number_of_qubits, "qr")
    cr = ClassicalRegister(number_of_qubits, "cr")

    quantum_circuit = QuantumCircuit(qr, cr)

    counter = number_of_qubits

    for i in range(counter):
        quantum_circuit.h(number_of_qubits - i - 1)
        counter -= 1
        for j in range(counter):
            quantum_circuit.cp(np.pi / 2 ** (counter - j), j, counter)

    for k in range(number_of_qubits // 2):
        quantum_circuit.swap(k, number_of_qubits - k - 1)


    quantum_circuit.measure(qr, cr)

    backend = Aer.get_backend("qasm_simulator")
    job = execute(quantum_circuit, backend, shots=10000)

    return job.result().get_counts(quantum_circuit)

def get_compiled_circuit(self):
    compiled_circuit = co.circuit_by_inverting_circuit(
        co.extract_inner_circuit(
            self.full_circuit, self.variational_circuit_range()
        )
    )
    if self.starting_circuit is not None:
        transpile_kwargs = (
            {"backend": self.backend}
            if (isinstance(self.backend, Backend))
            else None
        )
        co.add_to_circuit(
            compiled_circuit,
            self.starting_circuit,
            0,
            transpile_before_adding=True,
            transpile_kwargs=transpile_kwargs,
        )
    final_circuit = QuantumCircuit(
        *self.circuit_to_compile.qregs, *self.circuit_to_compile.cregs
    )
    qubit_map = {
        full_circ_index: subset_index
        for subset_index, full_circ_index in enumerate(self.qubit_subset_to_compile)
    }
    co.add_to_circuit(final_circuit, compiled_circuit, qubit_subset=qubit_map)

    # If self.target is a QuantumCircuit object, this ensures the quantum and classical registers of the compiled
    # circuit are the same as those of the target. If self.target is an MPS, there were no registers in the first
    # place, so this makes a QuantumCircuit with the default register names
    if isinstance(self.target, QuantumCircuit):
        final_circuit_original_regs = QuantumCircuit(
            *self.target.qregs, *self.target.cregs
        )
    else:
        final_circuit_original_regs = QuantumCircuit(
            self.circuit_to_compile.num_qubits
        )

    final_circuit_original_regs.append(
        final_circuit.to_instruction(), final_circuit_original_regs.qubits
    )
    circuit_no_classical_ops = co.unroll_to_basis_gates(final_circuit_original_regs)
    if self.original_circuit_classical_ops is not None:
        co.add_classical_operations(
            circuit_no_classical_ops, self.original_circuit_classical_ops
        )
    return circuit_no_classical_ops

def create_circuit(self) -> QuantumCircuit:
    qc = QuantumCircuit(self.num_qubits)
    for i in range(self.num_qubits):
        qc.h(i)
    for i, param in enumerate(self.parameters[:self.num_qubits]):
        qc.ry(param, i)
    for i in range(self.num_qubits - 1):
        qc.cx(i, i + 1)
    for i, param in enumerate(self.parameters[:self.num_qubits]):
        qc.rz(param, i)
    return qc

def create_circuit(self) -> QuantumCircuit:
    qc = QuantumCircuit(self.num_qubits)
    param_idx = 0
    for layer in range(self.num_layers):
        for qubit in range(self.num_qubits):
            qc.rx(self.parameters[param_idx], qubit)
            param_idx += 1
            qc.ry(self.parameters[param_idx], qubit)
            param_idx += 1
            qc.rz(self.parameters[param_idx], qubit)
            param_idx += 1
        for qubit in range(self.num_qubits - 1):
            qc.cx(qubit, qubit + 1)
        if self.num_qubits > 2:
            qc.cx(self.num_qubits - 1, 0)
    return qc

def create_error_correction_circuit(self, logical_qubits: int) -> QuantumCircuit:
    """Create error correction circuit for given number of logical qubits."""

    if self.correction_method == "repetition":
        return self._create_repetition_code_circuit(logical_qubits)
    elif self.correction_method == "surface":
        return self._create_surface_code_circuit(logical_qubits)
    elif self.correction_method == "steane":
        return self._create_steane_code_circuit(logical_qubits)
    else:
        # No error correction - just return identity circuit
        return QuantumCircuit(logical_qubits)

def _create_surface_code_circuit(self, logical_qubits: int) -> QuantumCircuit:
    """Create simplified surface code circuit."""
    if self.code_distance < 3:
        warnings.warn("Surface code requires distance >= 3, using repetition code instead")
        return self._create_repetition_code_circuit(logical_qubits)

    total_qubits = logical_qubits * self.physical_qubits_per_logical
    circuit = QuantumCircuit(total_qubits)

    # Simplified surface code implementation
    for logical_idx in range(logical_qubits):
        start_idx = logical_idx * self.physical_qubits_per_logical

        # Create basic stabilizer structure
        for i in range(self.code_distance - 1):
            for j in range(self.code_distance - 1):
                qubit_idx = start_idx + i * self.code_distance + j
                if qubit_idx + 1 < start_idx + self.physical_qubits_per_logical:
                    circuit.cx(qubit_idx, qubit_idx + 1)

    return circuit

def make_hartree_state(self, occ_basis):
    """
    Create the Hartree-Fock circuit state
    """
    circuit = qiskit.QuantumCircuit(self.n_qubits)
    for count, value in enumerate(occ_basis): 
        if value==1:
            circuit.x(count)
    self.ansatz = circuit

def amplitude_amplification(self,evidence):
    self.state_preparation = self.circ
    self.oracle = QuantumCircuit(self.ctrl, self.anc, self.tgt)
    for index, e in enumerate(evidence):
        if evidence[e]['state'] == '1':
            self.oracle.z([evidence[e]['n']])

    self.grover_op = Grover(self.oracle, state_preparation=self.state_preparation)
    self.grover_op.draw()

def simulate(tokens, num_qubits):
    """
    Build a Qiskit QuantumCircuit from token strings; compute probabilities_dict.
    Bucketed rotations: angle = (bucket/8)*2π.
    """
    n = num_qubits
    qc = QuantumCircuit(n)
    for tok in tokens:
        parts = tok.split()
        op = parts[0]
        if op in {'h','x','y','z'} and len(parts) == 2:
            q = int(parts[1][1:])
            if q < n:
                getattr(qc, op)(q)
        elif op == 'cx' and len(parts) == 3:
            q1 = int(parts[1][1:]); q2 = int(parts[2][1:])
            if q1 < n and q2 < n:
                qc.cx(q1, q2)
        elif op.startswith(('rx','ry','rz')) and len(parts) == 2:
            gate = op[:2]
            try:
                bucket = int(op[3:-1])
                angle = bucket * 2 * np.pi / 8
                q = int(parts[1][1:])
                if q < n:
                    getattr(qc, gate)(angle, q)
            except:
                continue
        elif op == 'e91_entangle' and len(parts) == 3:
            q1 = int(parts[1][1:]); q2 = int(parts[2][1:])
            if q1 < n and q2 < n:
                qc.h(q1); qc.cx(q1, q2)
        elif op == 'ghz_entangle' and len(parts) == 3:
            q1 = int(parts[1][1:]); q2 = int(parts[2][1:])
            if q1 == 0 and q2 < n:
                qc.cx(0, q2)
        elif op == 'ghz_step' and len(parts) == 2:
            q0 = int(parts[1][1:])
            if q0 == 0 and n > 0:
                qc.h(0)
        # skip bb84_step, unknown tokens
    sv = Statevector.from_instruction(qc)
    return sv.probabilities_dict()

def parity_feature_map_circuit(x):
    qc = QuantumCircuit(n_qubits)
    for i in range(n_qubits):
        if x[i]:
            qc.rx(np.pi, i)
    qc.h(range(n_qubits))
    return qc

def _define(self):
