    self.definition = qc

def _define(self):
    num_qubits = self.control_qubits + self.target_qubits
    qc = QuantumCircuit(num_qubits)

    # Apply X gates to control qubits if needed
    for i in range(len(self.contstr)):
        if self.contstr[i] == "0":
            qc.x([i])

    # Create and append the MCMT gate
    mcmt_gate = MCMT(
        XGate(),
        num_ctrl_qubits=self.control_qubits,
        num_target_qubits=self.target_qubits,
    )
    qc.append(mcmt_gate, list(range(num_qubits)))

    # Apply X gates to control qubits if needed
    for i in range(len(self.contstr)):
        if self.contstr[i] == "0":
            qc.x([i])

    self.definition = qc

def _define(self):
    """
    gate ch a,b {
        s b;
        h b;
        t b;
        cx a, b;
        tdg b;
        h b;
        sdg b;
    }
    """
    # pylint: disable=cyclic-import
    from qiskit.circuit.quantumcircuit import QuantumCircuit
    from .x import CXGate  # pylint: disable=cyclic-import
    from .t import TGate, TdgGate
    from .s import SGate, SdgGate

    q = QuantumRegister(2, "q")
    qc = QuantumCircuit(q, name=self.name)
    rules = [
        (SGate(), [q[1]], []),
        (HGate(), [q[1]], []),
        (TGate(), [q[1]], []),
        (CXGate(), [q[0], q[1]], []),
        (TdgGate(), [q[1]], []),
        (HGate(), [q[1]], []),
        (SdgGate(), [q[1]], []),
    ]
    for instr, qargs, cargs in rules:
        qc._append(instr, qargs, cargs)

    self.definition = qc

def _build(self, rotation_params: np.ndarray, entangle_params: np.ndarray) -> QuantumCircuit:
    circ = QuantumCircuit(self.n_qubits)
    for i in range(self.n_qubits):
        circ.rx(rotation_params[3 * i], i)
        circ.ry(rotation_params[3 * i + 1], i)
        circ.rz(rotation_params[3 * i + 2], i)
    for i in range(self.n_qubits - 1):
        circ.crx(entangle_params[i], i, i + 1)
    return circ

def qft(n: int) -> QuantumCircuit:
    """量子フーリエ変換 (QFT) 回路"""
    qc = QuantumCircuit(n, name="QFT")
    for j in range(n - 1, -1, -1):
        qc.h(j)
        for k in range(j - 1, -1, -1):
            qc.cp(math.pi / (2 ** (j - k)), k, j)
    for i in range(n // 2):
        qc.swap(i, n - 1 - i)
    return qc

def quantum_strategy(x, y, z):
  qc = QuantumCircuit(3, 3)
  qc.h(0)
  qc.cx(0, 1)
  qc.cx(0, 2)
  for (i, t) in enumerate([x, y, z]):  
    if (t == 0):
      # measure in |+>, |-> basis
      qc.h(i)
    elif (t == 1):
      # measure in |i>, |-i> basis
      qc.sdg(i)
      qc.h(i)
  qc.measure(range(3), range(3))
  backend = BasicAer.get_backend('qasm_simulator')
  job = execute(qc, backend=backend, shots=1, optimization_level=3)
  result = job.result()
  counts = result.get_counts(qc)
  for key in counts:
    if (counts[key] == 1):
      a, b, c = key
      return int(a), int(b), int(c)

def copy_operator(n: int):
    """
    builds a copy gate on `n` qubits
    """

    qin = QuantumRegister(n, "in")
    qout = QuantumRegister(n, "out")
    qc = QuantumCircuit(qin, qout)

    for i in range(n):
        qc.cx(qin[i], qout[i])

    return qc.to_gate(label="COPY")

def quantum_number_encode(num: int, code_len: int = 0):
    """
    encodes the given `num` into a gate. if specified, `code_len` lets
    you use more qubits than needed for the number specified by `num`
    """

    if num == 0:
        return QuantumCircuit(code_len).to_gate(label=" 0 ")

    if code_len < int(np.ceil(np.log2(num))):
        code_len = len(bin(num)[2:])

    bin_num = int_to_bin(num, code_len)
    qc = QuantumCircuit(code_len)

    for c, i in enumerate(bin_num):
        if i == "1":
            qc.x(code_len - 1 - c)

    return qc.to_gate(label=" " + str(num) + " ")

