def eval(self, X, y):
    sampler = Sampler()
    acc_and_score = np.zeros(2)
    for a in range(y.shape[0]  // self.world_size):
        qc = QuantumCircuit(self.n_qubits * self.world_size, self.world_size)
        feature_map = []
        for b in range(self.world_size):
            feature_map.append(FraxisFeatureMap(self.n_qubits, X[b + a * self.world_size]))  
        for b in range(self.layer_size):
            original_ansatz = FraxisAnsatz(self.n_qubits, self.params[b])
            for c in range(self.world_size):
                qc.compose(
                    feature_map[c], 
                    qubits=range(self.n_qubits * c, self.n_qubits * (c + 1), 1), 
                    inplace=True
                )
                qc.compose(
                    original_ansatz, 
                    qubits=range(self.n_qubits * c, self.n_qubits * (c + 1), 1), 
                    inplace=True
                )

        qc.measure(range(0, self.n_qubits * self.world_size, self.n_qubits),range(self.world_size))

        result = sampler.run(
            circuits=[qc],
        ).result().quasi_dists
        Zexp = np.zeros(self.world_size)
        for b in result[0]:
            for c in range(self.world_size):
                if (b >> c) % 2 == 1:
                    Zexp[c] -= result[0][b]
                else:
                    Zexp[c] += result[0][b]

        acc_and_score[0] += np.sum(np.where(y[a * self.world_size : (a + 1) * self.world_size : 1] * Zexp > 0, 1, 0))
        acc_and_score[1] += np.sum(y[a * self.world_size : (a + 1) * self.world_size : 1] * Zexp) * 2
    return acc_and_score

def new_qc_from_dsl(self, dsl, argvals):
    qc = QuantumCircuit(self.C["in"])

    for line in dsl.splitlines():
        line = line.strip()
        if line:
            tokens = line.split(",")
            method = tokens[0].strip()
            args = []
            for arg in tokens[1:]:
                arg = arg.strip()
                if arg.isnumeric():
                    if "." in arg:
                        args.append(float(arg))
                    else:
                        args.append(int(arg))
                else:
                    if arg in argvals:
                        args.append(argvals[arg])
                    else:
                        args.append(arg)

            if "_in" in args:
                args[args.index("_in")] = self.C["in"]
            if "_out" in args:
                args[args.index("_out")] = self.C["out"]

            if method == "random_circuit":
                qc = random_circuit(self.C["in"])  # measure=True)
            else:
                getattr(qc, method)(*args)

    return qc

