def _define(self) -> None:
    qc = QuantumCircuit(self.num_qubits, name=self.name)
    for op_type, src, tgt in self.operations:
        if op_type == "swap":
            qc.swap(src, tgt)
        elif op_type == "xor":
            qc.cx(src, tgt)
    self.definition = qc

def definition(self) -> List:
    """Return definition in terms of other basic gates. If the gate has
    open controls, as determined from `self.ctrl_state`, the returned
    definition is conjugated with X without changing the internal
    `_definition`.
    """
    if self._open_ctrl:
        closed_gate = self.copy()
        closed_gate.ctrl_state = None
        bit_ctrl_state = bin(self.ctrl_state)[2:].zfill(self.num_ctrl_qubits)
        qreg = QuantumRegister(self.num_qubits, 'q')
        qc_open_ctrl = QuantumCircuit(qreg)
        for qind, val in enumerate(bit_ctrl_state[::-1]):
            if val == '0':
                qc_open_ctrl.x(qind)
        qc_open_ctrl.append(closed_gate, qargs=qreg[:])
        for qind, val in enumerate(bit_ctrl_state[::-1]):
            if val == '0':
                qc_open_ctrl.x(qind)
        return qc_open_ctrl
    else:
        return super().definition

def _define(self):
    """
    gate cu3(theta,phi,lambda) c, t
    { u1(pi/2) t;
      cx c,t;
      u3(-theta/2,0,0) t;
      cx c,t;
      u3(theta/2,-pi/2,0) t;
    }
    """
    # pylint: disable=cyclic-import
    from qiskit.circuit.quantumcircuit import QuantumCircuit
    from .u1 import U1Gate
    from .u3 import U3Gate
    from .x import CXGate

    q = QuantumRegister(2, "q")
    qc = QuantumCircuit(q, name=self.name)
    rules = [
        (U1Gate(pi / 2), [q[1]], []),
        (CXGate(), [q[0], q[1]], []),
        (U3Gate(-self.params[0] / 2, 0, 0), [q[1]], []),
        (CXGate(), [q[0], q[1]], []),
        (U3Gate(self.params[0] / 2, -pi / 2, 0), [q[1]], []),
    ]
    for instr, qargs, cargs in rules:
        qc._append(instr, qargs, cargs)

    self.definition = qc

