def build_parametric_feature_map(feature_dimension, reps=1, entangler="chain"):
    params = ParameterVector("x", feature_dimension)
    qc = QuantumCircuit(feature_dimension)
    for _ in range(reps):
        for idx in range(feature_dimension):
            qc.ry(params[idx], idx)
        if entangler == "chain":
            for idx in range(feature_dimension - 1):
                qc.cz(idx, idx + 1)
        elif entangler == "full":
            for i in range(feature_dimension):
                for j in range(i + 1, feature_dimension):
                    qc.cz(i, j)
    return qc

