def momen_layer(it:int, n:int, momentum:list, radius:int=1, keep:int=2):
    lay=QuantumCircuit(n)
    params=[]
    inds=[]
    for i in range(keep):
        angle = Parameter("it-"+str(it)+", "+str(i))
        ind=momentum[i][1]
        params.append(1)
        inds.append(ind)
        lay.rx(angle, ind)
        for r in range(1,radius+1):
            if ind +r<n:
                lay.cx(ind,ind+r)
            if ind-r>=0:
                lay.cx(ind,ind-r)
    return lay, params, inds

def _build_circuit(self, candidate: CircuitCandidate) -> Any:
    """Build Qiskit circuit from candidate specification."""
    try:
        from qiskit import QuantumCircuit
        from qiskit.circuit import Parameter
    except ImportError:
        raise ImportError("qiskit required")

    qc = QuantumCircuit(candidate.num_qubits)

    # Add parameterized layers
    param_idx = 0
    for layer in range(candidate.depth):
        # Single-qubit gates
        for q in range(candidate.num_qubits):
            gate_idx = (layer * 2) % len(candidate.gate_sequence)
            gate = candidate.gate_sequence[gate_idx]

            if gate in ["rx", "ry", "rz"]:
                param = Parameter(f"θ_{param_idx}")
                param_idx += 1
                if gate == "rx":
                    qc.rx(param, q)
                elif gate == "ry":
                    qc.ry(param, q)
                else:
                    qc.rz(param, q)
            elif gate == "h":
                qc.h(q)

        # Entanglement
        if candidate.entanglement == "linear":
            for q in range(candidate.num_qubits - 1):
                qc.cx(q, q + 1)
        elif candidate.entanglement == "circular":
            for q in range(candidate.num_qubits):
                qc.cx(q, (q + 1) % candidate.num_qubits)
        elif candidate.entanglement == "full":
            for q1 in range(candidate.num_qubits):
                for q2 in range(q1 + 1, candidate.num_qubits):
                    qc.cx(q1, q2)

    qc.measure_all()
    return qc

def _create_shared_basis_circuit(pauli_string):
    """create the circuit needed to rotate the qubits in the shared eigenbasis"""

    num_qubits = len(pauli_string)
    circuit = QuantumCircuit(num_qubits)
    for iqbit in range(num_qubits):
        op = pauli_string[iqbit]
        if op == "X":
            circuit.ry(-np.pi / 2, iqbit)
        if op == "Y":
            circuit.rx(np.pi / 2, iqbit)

    return circuit

def hardware_efficient_ansatz(num_qubits, depth=2):
    qc = QuantumCircuit(num_qubits)
    params = []

    for d in range(depth):
        for q in range(num_qubits):
            theta = Parameter(f"θ_{d}_{q}")
            qc.ry(theta, q)
            params.append(theta)

        for q in range(num_qubits - 1):
            qc.cz(q, q + 1)

    return qc, params

def c_amod15(a, power):
    """Controlled multiplication by a mod 15"""
    if a not in [2,4,7,8,11,13]:
        raise ValueError("'a' must be 2,4,7,8,11 or 13")
    U = QuantumCircuit(4)
    for _iteration in range(power):
        if a in [2,13]:
            U.swap(0,1)
            U.swap(1,2)
            U.swap(2,3)
        if a in [7,8]:
            U.swap(0,1)
            U.swap(1,2)
            U.swap(2,3)
        if a in [4, 11]:
            U.swap(1,3)
            U.swap(0,2)
        if a in [7,11,13]:
            for q in range(4):
                U.x(q)
    U = U.to_gate()
    U.name = f"{a}^{power} mod 15"
    c_U = U.control()
    return c_U

def controlled_trotterized_time_evolution(qc_state, coeffs, hloc, dt, L, nsteps=1, hamil=None, control=True):
    if not control:
        qc = qiskit.QuantumCircuit(L)
        qc_state.x(L)
        for j in range(L-1, -1, -1):
            if j % 2 == 1:
                qc_state.cy(L, j)
            else:
                qc_state.cz(L, j)
        qc_state.x(L)


        for n in range(nsteps):
            Vlist = [scipy.linalg.expm(-1j*c*dt*hloc) for c in coeffs]
            Vlist_gates = []
            for V in Vlist:
                qc2 = qiskit.QuantumCircuit(2)
                qc2.unitary(V, [0, 1], label='str')
                Vlist_gates.append(qc2)
            perms = [None if i % 2 == 0 else np.roll(range(L), -1) for i in range(len(coeffs))]
            for layer, qc_gate in enumerate(Vlist_gates):
                for j in range(L//2):
                    if perms[layer] is not None:
                        qc.append(qc_gate.to_gate(), [L-(perms[layer][2*j]+1), L-(perms[layer][2*j+1]+1)])
                    else:
                        qc.append(qc_gate.to_gate(), [L-(2*j+1), L-(2*j+2)])

        qc_state.append(qc.to_gate(), [i for i in range(L)])

        if hamil is not None:
            backend = Aer.get_backend("unitary_simulator")
            qc_unit = execute(transpile(qc), backend).result().get_unitary(qc, L).data
            U = scipy.linalg.expm(-1j * dt * nsteps * hamil)
            print("U Error: ", np.linalg.norm(qc_unit-U, ord=2))    


        qc_state.x(L)
        for j in range(L-1, -1, -1):
            if j % 2 == 1:
                qc_state.cy(L, j)
            else:
                qc_state.cz(L, j)
        qc_state.x(L)
    else:
        qc = qiskit.QuantumCircuit(L+1)
        for n in range(nsteps):
            Vlist = [scipy.linalg.expm(-1j*c*dt*hloc) for c in coeffs]
            Vlist_gates = []
            for V in Vlist:
                qc2 = qiskit.QuantumCircuit(2)
                qc2.unitary(V, [0, 1], label='str')
                Vlist_gates.append(qc2)
            perms = [None if i % 2 == 0 else np.roll(range(L), -1) for i in range(len(coeffs))]
            for layer, qc_gate in enumerate(Vlist_gates):
                for j in range(L//2):
                    if perms[layer] is not None:
                        qc.append(qc_gate.to_gate().control(), [L, L-(perms[layer][2*j]+1), L-(perms[layer][2*j+1]+1)])
                    else:
                        qc.append(qc_gate.to_gate().control(), [L, L-(2*j+1), L-(2*j+2)])
        qc_state.append(qc.to_gate(), [i for i in range(L+1)])

def _define(self):
    """
    gate pauli (p1 a1,...,pn an) { p1 a1; ... ; pn an; }
    """
    # pylint: disable=cyclic-import
    from qiskit.circuit import QuantumCircuit, QuantumRegister

    gates = {"X": XGate, "Y": YGate, "Z": ZGate}
    q = QuantumRegister(len(self.params[0]), "q")
    qc = QuantumCircuit(q, name=f"{self.name}({self.params[0]})")

    paulis = self.params[0]
    for i, p in enumerate(reversed(paulis)):
        if p == "I":
            continue
        qc._append(CircuitInstruction(gates[p](), (q[i],), ()))
    self.definition = qc

def undress_right_dressed_box(box: BoxOp) -> BoxOp:
    """Return a box equivalent to ``box``, stripped of the single-qubit gates on the right side.

    This function removes all the single-qubit gates that can be pushed to the right-hand side of
    the given box without encountering any other operation.

    Args:
        box: The box to remove the single-qubit gates from.
    """
    # A map to temporarily store single-qubit gates before inserting them into a box
    cached_gates_1q: dict[Qubit, list[Instruction]] = defaultdict(list)

    dag = circuit_to_dag(box.body)
    new_content = QuantumCircuit(box.body.qubits + box.body.clbits)

    for node in dag.topological_op_nodes():
        if node.is_standard_gate() and node.num_qubits == 1:
            # If `node` contains a one-qubit gate, cache it
            cached_gates_1q[node.qargs[0]].append(node)
        else:
            # Otherwise, flush the cache, then append the node's operation
            for qarg in node.qargs:
                for node_gate_1q in cached_gates_1q.pop(qarg, []):
                    new_content.append(node_gate_1q.op, node_gate_1q.qargs)
            new_content.append(node.op, node.qargs, node.cargs)

    annotations = deepcopy(box.annotations)
    return BoxOp(body=new_content, annotations=annotations)

def _generate_qft_qiskit_code(self, n_qubits: int, use_swaps: bool, inverse: bool) -> str:
    """Generate QFT Qiskit code"""
    lines = []
    lines.append("from qiskit import QuantumCircuit")
    lines.append("import numpy as np")
    lines.append("")
    lines.append(f"qc = QuantumCircuit({n_qubits})")
    lines.append("")

    if inverse:
        lines.append("# Inverse QFT")
    else:
        lines.append("# Quantum Fourier Transform")

    lines.append("")

    if inverse:
        # Inverse QFT
        if use_swaps:
            lines.append("# Swap qubits")
            for i in range(n_qubits // 2):
                lines.append(f"qc.swap({i}, {n_qubits - i - 1})")
            lines.append("")

        for j in range(n_qubits - 1, -1, -1):
            lines.append(f"# Qubit {j}")
            for k in range(j - 1, -1, -1):
                power = j - k + 1
                lines.append(f"qc.cp(-np.pi/{2**power}, {k}, {j})")
            lines.append(f"qc.h({j})")
            lines.append("")
    else:
        # Forward QFT
        for j in range(n_qubits):
            lines.append(f"# Qubit {j}")
            lines.append(f"qc.h({j})")
            for k in range(j + 1, n_qubits):
                power = k - j + 1
                lines.append(f"qc.cp(np.pi/{2**power}, {j}, {k})")
            lines.append("")

        if use_swaps:
            lines.append("# Swap qubits")
            for i in range(n_qubits // 2):
                lines.append(f"qc.swap({i}, {n_qubits - i - 1})")

    lines.append("")
    lines.append("qc.measure_all()")

    return "\n".join(lines)

