def _to_qc(circuit):
    qiskit_qc = QuantumCircuit()
    # Qiskit is weird, it doesn't allow passing 0 as size for register.
    if circuit.num_cbits():
        qiskit_qc.add_register(circuit.num_qubits(), circuit.num_cbits())
    else:
        qiskit_qc.add_register(circuit.num_qubits())

    for instruction in circuit:
        gate = _convert_tweedledum_op(instruction)
        qubits = [qubit.uid() for qubit in instruction.qubits()]
        cbits = [cbit.uid() for cbit in instruction.cbits()]
        qiskit_qc.append(gate, qubits, cbits)
    return qiskit_qc

def add_register(self, *regs: Register | int | Sequence[Bit]) -> None:
    """Add registers."""
    if not regs:
        return

    if any(isinstance(reg, int) for reg in regs):
        # QuantumCircuit defined without registers
        if len(regs) == 1 and isinstance(regs[0], int):
            # QuantumCircuit with anonymous quantum wires e.g. QuantumCircuit(2)
            if regs[0] == 0:
                regs = ()
            else:
                regs = (QuantumRegister(regs[0], "q"),)
        elif len(regs) == 2 and all(isinstance(reg, int) for reg in regs):
            # QuantumCircuit with anonymous wires e.g. QuantumCircuit(2, 3)
            if regs[0] == 0:
                qregs: tuple[QuantumRegister, ...] = ()
            else:
                qregs = (QuantumRegister(regs[0], "q"),)
            if regs[1] == 0:
                cregs: tuple[ClassicalRegister, ...] = ()
            else:
                cregs = (ClassicalRegister(regs[1], "c"),)
            regs = qregs + cregs
        else:
            raise CircuitError(
                "QuantumCircuit parameters can be Registers or Integers."
                " If Integers, up to 2 arguments. QuantumCircuit was called"
                f" with {(regs,)}."
            )

    for register in regs:
        if isinstance(register, Register) and any(
            register.name == reg.name for reg in self.qregs + self.cregs
        ):
            raise CircuitError(f'register name "{register.name}" already exists')

        if isinstance(register, AncillaRegister):
            for bit in register:
                if bit not in self._qubit_indices:
                    self._ancillas.append(bit)

        if isinstance(register, QuantumRegister):
            self._add_qreg(register)

        elif isinstance(register, ClassicalRegister):
            self.cregs.append(register)

            for idx, bit in enumerate(register):
                if bit in self._clbit_indices:
                    self._clbit_indices[bit].registers.append((register, idx))
                else:
                    self._data.add_clbit(bit)
                    self._clbit_indices[bit] = BitLocations(
                        self._data.num_clbits - 1, [(register, idx)]
                    )

        elif isinstance(register, list):
            self.add_bits(register)
        else:
            raise CircuitError("expected a register")

def full_trotter_gates(order, trotter_steps=4, target_time=np.pi,
                       uniform_times=True, steps_times=None, draw_circ=False):
    '''
    this funtion returns a 3-qubit circuit with the gates implementing
    the specificed trotterization. This is used to inspect wheter or not
    the corresponding unitary differs from the identity, in the check_circuit_unitary() function
    '''

    qr = QuantumRegister(3)
    qc = QuantumCircuit(qr)

    if uniform_times:

        Trot_gate = trotter_step(order, Parameter('t'))

        for _ in range(trotter_steps):

            qc.append(Trot_gate, [qr[0], qr[1], qr[2]])

        qc = qc.bind_parameters({qc.parameters[0]: target_time/trotter_steps})

    else:

        # check
        if len(steps_times) != trotter_steps:
            raise ValueError(f"Incorrect quantity of times {len(steps_times)}! Must be equal to number of steps {trotter_steps}")

        for i in range(trotter_steps):

            Trot_gate = trotter_step(order, Parameter(f't{i}'))

            qc.append(Trot_gate, [qr[0], qr[1], qr[2]])

        params_dict = {param: time for param, time in zip(qc.parameters, steps_times)}

        qc = qc.bind_parameters(params_dict)

    if draw_circ:
        show_figure(qc.draw("mpl"))

    return qc

def build_kuramoto_circuits(n, dt, steps, backend, order=1):
    K = build_knm_paper27(L=n)
    omega = OMEGA_N_16[:n]
    H = knm_to_hamiltonian(K, omega)
    synth = LieTrotter(reps=1) if order == 1 else SuzukiTrotter(order=2, reps=1)

    circuits = []
    for s in range(1, steps + 1):
        for basis in ["Z", "X", "Y"]:
            qc = QuantumCircuit(n)
            for i in range(n):
                qc.ry(float(omega[i]) % (2 * np.pi), i)
            evo = PauliEvolutionGate(H, time=dt * s, synthesis=synth)
            qc.append(evo, range(n))
            if basis == "X":
                for i in range(n):
                    qc.h(i)
            elif basis == "Y":
                for i in range(n):
                    qc.sdg(i)
                    qc.h(i)
            qc.measure_all()
            circuits.append(transpile(qc, backend=backend, optimization_level=2))
    return circuits

