def _get_ucry_cz(nqubits, angles):
    """
    Get uniformly controlled Ry gate in in CZ-Ry as in UCPauliRotGate.
    """
    nangles = len(angles)
    qc = QuantumCircuit(nqubits)
    q_controls = qc.qubits[:-1]
    q_target = qc.qubits[-1]
    if not q_controls:
        if np.abs(angles[0]) > _EPS:
            qc.ry(angles[0], q_target)
    else:
        angles = angles.copy()
        UCPauliRotGate._dec_uc_rotations(angles, 0, len(angles), False)
        for (i, angle) in enumerate(angles):
            if np.abs(angle) > _EPS:
                qc.ry(angle, q_target)
            if not i == len(angles) - 1:
                binary_rep = np.binary_repr(i + 1)
                q_contr_index = len(binary_rep) - len(binary_rep.rstrip("0"))
            else:
                # Handle special case:
                q_contr_index = len(q_controls) - 1
            # leave off last CZ for merging with adjacent UCG
            if i < nangles - 1:
                qc.cz(q_controls[q_contr_index], q_target)
    return qc

def run(self, dag):
    """Run the ConsolidateBlocks pass on `dag`.

    Iterate over each block and replace it with an equivalent Unitary
    on the same wires.
    """
    if self.decomposer is None:
        return dag

    blocks = self.property_set["block_list"] or []
    basis_gate_name = self.decomposer.gate.name
    all_block_gates = set()
    for block in blocks:
        if len(block) == 1 and self._check_not_in_basis(dag, block[0].name, block[0].qargs):
            all_block_gates.add(block[0])
            dag.substitute_node(block[0], UnitaryGate(block[0].op.to_matrix()))
        else:
            basis_count = 0
            outside_basis = False
            block_qargs = set()
            block_cargs = set()
            for nd in block:
                block_qargs |= set(nd.qargs)
                if isinstance(nd, DAGOpNode) and getattr(nd, "condition", None):
                    block_cargs |= set(getattr(nd, "condition", None)[0])
                all_block_gates.add(nd)
            block_index_map = self._block_qargs_to_indices(dag, block_qargs)
            for nd in block:
                if nd.name == basis_gate_name:
                    basis_count += 1
                if self._check_not_in_basis(dag, nd.name, nd.qargs):
                    outside_basis = True
            if len(block_qargs) > 2:
                q = QuantumRegister(len(block_qargs))
                qc = QuantumCircuit(q)
                if block_cargs:
                    c = ClassicalRegister(len(block_cargs))
                    qc.add_register(c)
                for nd in block:
                    qc.append(nd.op, [q[block_index_map[i]] for i in nd.qargs])
                unitary = UnitaryGate(Operator(qc), check_input=False)
            else:
                try:
                    matrix = blocks_to_matrix(block, block_index_map)
                except QiskitError:
                    # If building a matrix for the block fails we should not consolidate it
                    # because there is nothing we can do with it.
                    continue
                unitary = UnitaryGate(matrix, check_input=False)

            max_2q_depth = 20  # If depth > 20, there will be 1q gates to consolidate.
            if (  # pylint: disable=too-many-boolean-expressions
                self.force_consolidate
                or unitary.num_qubits > 2
                or self.decomposer.num_basis_gates(matrix) < basis_count
                or len(block) > max_2q_depth
                or ((self.basis_gates is not None) and outside_basis)
                or ((self.target is not None) and outside_basis)
            ):
                identity = np.eye(2**unitary.num_qubits)
                if np.allclose(identity, unitary.to_matrix()):
                    for node in block:
                        dag.remove_op_node(node)
                else:
                    dag.replace_block_with_op(
                        block, unitary, block_index_map, cycle_check=False
                    )
    # If 1q runs are collected before consolidate those too
    runs = self.property_set["run_list"] or []
    identity_1q = np.eye(2)
    for run in runs:
        if any(gate in all_block_gates for gate in run):
            continue
        if len(run) == 1 and not self._check_not_in_basis(dag, run[0].name, run[0].qargs):
            dag.substitute_node(run[0], UnitaryGate(run[0].op.to_matrix(), check_input=False))
        else:
            qubit = run[0].qargs[0]
            operator = run[0].op.to_matrix()
            already_in_block = False
            for gate in run[1:]:
                if gate in all_block_gates:
                    already_in_block = True
                operator = gate.op.to_matrix().dot(operator)
            if already_in_block:
                continue
            unitary = UnitaryGate(operator, check_input=False)
            if np.allclose(identity_1q, unitary.to_matrix()):
                for node in run:
                    dag.remove_op_node(node)
            else:
                dag.replace_block_with_op(run, unitary, {qubit: 0}, cycle_check=False)

    dag = self._handle_control_flow_ops(dag)

    # Clear collected blocks and runs as they are no longer valid after consolidation
    if "run_list" in self.property_set:
        del self.property_set["run_list"]
    if "block_list" in self.property_set:
        del self.property_set["block_list"]

    return dag

def diffuser(nqubits):
    qc = QuantumCircuit(nqubits)
    for qubit in range(nqubits):
        qc.h(qubit)
    for qubit in range(nqubits):
        qc.x(qubit)
    qc.h(nqubits - 1)
    qc.mct(list(range(nqubits - 1)), nqubits - 1)
    qc.h(nqubits - 1)
    for qubit in range(nqubits):
        qc.x(qubit)
    for qubit in range(nqubits):
        qc.h(qubit)
    U_s = qc.to_gate()
    U_s.name = "Diffuser"
    return U_s

def get_circuit(self, barriers=True):
    qc = QuantumCircuit(self.num_qubits)
    params = []
    # initial Euler Rotation Layer
    for i in range(self.num_qubits):
        for _ in range(2):  # two new parameters
            params.append(Parameter(f'p{len(params):02}'))
        # rotation with the two new parameters. Don't need the first
        # z rotation
        qc.u(params[-2], params[-1], 0, i)
    if barriers:
        qc.barrier()
    for l in range(self.num_layers):
        # entangling layer
        for i in range(self.num_qubits - 1):
            qc.cnot(i, i + 1)
        if barriers:
            qc.barrier()
        for i in range(self.num_qubits):
            for _ in range(3):
                params.append(Parameter(f'p{len(params):02}'))
            qc.u(params[-3], params[-2], params[-1], i)
        if barriers:
            qc.barrier()
    return qc

def conjugate(self):
    circ = self.to_instruction()
    new_circ = QuantumCircuit(self.num_qubits)
    bit_indices = {bit: index for index, bit in enumerate(circ.definition.qubits)}
    for instr, qregs, _ in circ.definition:
        new_qubits = [bit_indices[tup] for tup in qregs]
        if instr.name == "p":
            params = 2 * np.pi - instr.params[0]
            instr.params[0] = params
            new_circ.append(instr, new_qubits)
        elif instr.name == "t":
            instr.name = "tdg"
            new_circ.append(instr, new_qubits)
        elif instr.name == "tdg":
            instr.name = "t"
            new_circ.append(instr, new_qubits)
        elif instr.name == "s":
            instr.name = "sdg"
            new_circ.append(instr, new_qubits)
        elif instr.name == "sdg":
            instr.name = "s"
            new_circ.append(instr, new_qubits)
        else:
            new_circ.append(instr, new_qubits)
    result = self._from_circuit(new_circ)
    return result

def inverse(self, annotated: bool = False):
    qc = QuantumCircuit(1)
    qc.ry(-np.pi / 2, 0)
    return qc.to_gate()

def inverse(self, annotated: bool = False):
    qc = QuantumCircuit(1)
    qc.ry(np.pi / 2, 0)
    return qc.to_gate()

def variational_circuit(num_qubits):
    # Define parameters
    params = [Parameter(f'theta_{i}') for i in range(num_qubits)]

    # Create a quantum circuit with parameterized gates
    qc = QuantumCircuit(num_qubits)
    for i, param in enumerate(params):
        qc.ry(param, i)
        if i < num_qubits - 1:
            qc.cz(i, i + 1)

    return qc, params

def constr_circuit_from_simp_steps(ham: Hamiltonian, steps: list[SimplificationStep]) -> QuantumCircuit:
    qc_pre = QuantumCircuit(ham.num_qubits)
    qc_post = QuantumCircuit(ham.num_qubits)

    for step in steps:
        qc_post.append(PauliEvolutionGate(step.local_hamiltonian), range(ham.num_qubits))
        qc_post.append(step.clifford, step.qubits)

        qc_pre.append(step.clifford, step.qubits)

    qc_post = qc_post.reverse_ops()
    qc_pre.append(PauliEvolutionGate(ham), range(ham.num_qubits)) # TODO: PauliEvolutionGate(ham) kernel to be optimized/rebased?

    return qc_pre.compose(qc_post).decompose('PauliEvolution')

def _define_initialize(self):

    circuit = QuantumCircuit(self.register)

    for level in range(self.levels):
        h_gate = HGate()
        if level > 0:
            h_gate = h_gate.control(level)

        circuit.compose(
            h_gate,
            self.register[:level+1],
            inplace=True
        )
        if level < self.num_qubits - 1:
            p_gate = self._permutation_gate(self.num_qubits - level)
            if level > 0:
                p_gate = p_gate.control(level)

            circuit.compose(
                p_gate,
                self.register,
                inplace=True
            )
    return circuit

def _permutation_gate(num_qubits):
    gate = QuantumCircuit(num_qubits)

    for qubit in range(num_qubits-1):
        gate.swap(qubit, qubit+1)

    return gate

def tensor(self, other: OperatorBase) -> Union["CircuitOp", TensoredOp]:
    # pylint: disable=cyclic-import
    from .pauli_op import PauliOp
    from .matrix_op import MatrixOp

    if isinstance(other, (PauliOp, CircuitOp, MatrixOp)):
        other = other.to_circuit_op()

    if isinstance(other, CircuitOp):
        new_qc = QuantumCircuit(self.num_qubits + other.num_qubits)
        # NOTE!!! REVERSING QISKIT ENDIANNESS HERE
        new_qc.append(
            other.to_instruction(), qargs=new_qc.qubits[0 : other.primitive.num_qubits]
        )
        new_qc.append(self.to_instruction(), qargs=new_qc.qubits[other.primitive.num_qubits :])
        new_qc = new_qc.decompose()
        return CircuitOp(new_qc, coeff=self.coeff * other.coeff)

    return TensoredOp([self, other])

def spin_interaction(time_rot):
    qc = QuantumCircuit(2)

    qc.rxx(time_rot, 0, 1)
    qc.ryy(time_rot, 0, 1)
    qc.rzz(time_rot, 0, 1)

    return qc.to_gate()

def spin_twist_interaction(time_rot, twist_angle):
    qc = QuantumCircuit(2)

    qc.rxx(time_rot * np.cos(twist_angle), 0, 1)
    qc.ryy(time_rot * np.cos(twist_angle), 0, 1)
    qc.rzz(time_rot, 0, 1)

    return qc.to_gate()

def non_commuting_twist(rotation):
    qc = QuantumCircuit(2)

    qc.append(XXPlusYYGate(rotation, -np.pi / 2), [0, 1])

    return qc.to_gate()

def bd_step(n_qubits, b_indexes, d_indexes, alpha, dt):
    qc = QuantumCircuit(n_qubits)

    for pair in b_indexes:
        time_rot = alpha * dt / 2
        qc.append(spin_interaction(time_rot), pair)

    for pair in d_indexes:
        time_rot = alpha * dt
        qc.append(spin_interaction(time_rot), pair)

    for pair in b_indexes:
        time_rot = alpha * dt / 2
        qc.append(spin_interaction(time_rot), pair)

    return qc.to_gate()

def a_split(n_qubits, a_indexes, twist_loc, twist, J, dt):
    qc = QuantumCircuit(n_qubits)

    twist_rot = -J * dt * np.sin(twist)
    qc.append(non_commuting_twist(twist_rot), twist_loc)

    for pair in a_indexes:
        time_rot = J * dt

        if pair == twist_loc:
            qc.append(spin_twist_interaction(time_rot, twist), pair)
            continue

        qc.append(spin_interaction(time_rot), pair)

    qc.append(non_commuting_twist(twist_rot), twist_loc)

    return qc.to_gate()

def c_split(n_qubits, c_indexes, twist_loc, twist, J, dt):
    qc = QuantumCircuit(n_qubits)

    twist_rot = -2 * J * dt * np.sin(twist)
    qc.append(non_commuting_twist(twist_rot), twist_loc)

    for pair in c_indexes:
        time_rot = 2 * J * dt

        if pair == twist_loc:
            qc.append(spin_twist_interaction(time_rot, twist), pair)
            continue

        qc.append(spin_interaction(time_rot), pair)

    qc.append(non_commuting_twist(twist_rot), twist_loc)

    return qc.to_gate()

def create_circuit(W_list: list, n: int):
    circ = QuantumCircuit(n)
    for i, unitary in enumerate(W_list):
        circ.append(UnitaryGate(unitary), range(i, int(np.log2(len(unitary))) + i))

    return circ

def qft(n: int) -> qiskit.circuit.Gate:
    """Returns a QFT gate for n qubits.

    :param n: Number of target qubits.
    :type n: int
    :return: QFT gate.
    :rtype: qiskit.circuit.Gate
    """
    def rotations(my_circuit: qiskit.circuit.Gate, m: int):
        if m == 0:
            return my_circuit
        else:
            my_circuit.h(m-1) #Add a Haddamard gate to the most significant qubit

            for i in range(m-1):
                my_circuit.crz(pi/(2**(m-1-i)), i, m-1)

            rotations(my_circuit, m-1) 

    my_circuit = qiskit.QuantumCircuit(n, name='QFT')

    rotations(my_circuit, n)

    for m in range(n//2):
        my_circuit.swap(m, n-m-1)

    return my_circuit.to_gate()

def MultiCRYGateV2(alpha_values: list, q_reg : QuantumRegister, starting_offset:float = 0) :
    circuit = QuantumCircuit(q_reg)
    q_target=q_reg[-1]
    if starting_offset != 0:
        circuit.append(RYGate(starting_offset, label="start_offset"), [q_target])
    # TODO: controllare che il numero degli angoli e dei qubit siano coerenti
    for i in range(0,len(q_reg)-1) :
        cy_gate = CRYGate(alpha_values[i], label="rot_"+str(i))
        circuit.append(cy_gate, [q_reg[i],q_target])
    return circuit

def MultiCRGateVar(alpha_values: list, q_reg : QuantumRegister, axis='Y', starting_offset:float = 0) :
    circuit = QuantumCircuit(q_reg)
    q_target=q_reg[-1]
    if axis=='Y':
        rgate = RYGate
        crgate = CRYGate
    else:
        rgate = RXGate
        crgate = CRXGate

    if starting_offset != 0:
        circuit.append(rgate(starting_offset, label="start_offset_"+axis), [q_target])
    # TODO: controllare che il numero degli angoli e dei qubit siano coerenti
    for i in range(0,len(q_reg)-1) :
        c_gate = crgate(alpha_values[i], label="rot_"+axis+"_"+str(i))
        circuit.append(c_gate, [q_reg[i],q_target])
    return circuit.to_gate()

def encode(self, data: np.ndarray) -> QuantumCircuit:
    """Create ZZ feature map circuit"""
    feature_map = ZZFeatureMap(feature_dimension=self.n_features, reps=self.reps)
    circuit = QuantumCircuit(self.n_qubits)

    # Bind parameters
    param_dict = {}
    for i, param in enumerate(feature_map.parameters):
        if i < len(data):
            param_dict[param] = data[i]

    circuit.compose(feature_map.assign_parameters(param_dict), inplace=True)
    return circuit

def circuit(self) -> QuantumCircuit:
    qc = QuantumCircuit(len(self.qubits.flatten()), name=type(self).__name__)

    qubits = qc.qubits
    for _ in range(self.num_layers):
        self._convolution(qc, qubits)
        qubits = self._pooling(qc, qubits)

    meas = {qc.find_bit(q)[0] for q in qubits}
    return qc, meas

def run(self, dag):
    for node in dag.op_nodes():
        if node.op.name == "swap":
            children = list(dag.successors(node))
            if len(children) == 1 and children[0].op.name == "swap":
                replacement = QuantumCircuit(2)
                dag.substitute_node_with_dag(node, circuit_to_dag(replacement))
                dag.substitute_node_with_dag(
                    children[0], circuit_to_dag(replacement)
                )
    return dag

def run(self, dag):
    for node in dag.op_nodes():
        if node.op.name == "swap":
            parents = dag.predecessors(node)
            children = dag.successors(node)
            init_swap = all(type(parent) == dagnode.DAGInNode for parent in parents)
            post_swap = all(type(child) == dagnode.DAGOutNode for child in children)
            if init_swap or post_swap:
                replacement = QuantumCircuit(2)
                dag.substitute_node_with_dag(node, circuit_to_dag(replacement))

    return dag

def line_graph_route(qc: QuantumCircuit) -> QuantumCircuit:
    """
    Reroute the gates of qiskit.Quantum circuit c by line-graph rerouting. Return the rerouted circtuit cp.
    """

    def heavy(g):
        # Return the heavy variant h of the networkx.Graph g, assuming g is of the form as returned by Roussopouloss algorithm (nx.inverse_line_graph). The newly added 'heavy' nodes have labels equal to the graph that was put in to Roussopoulos' algorithm. This is algorithm 1 in the paper.
        h = nx.Graph()
        for a, b in g.edges():
            cn = tuple(set(a) & set(b))  # common node
            assert len(cn) == 1
            if len(a) == 1 and len(b) != 1:
                b = str(b)
                h.add_edge(a[0], b)
            elif len(a) != 1 and len(b) == 1:
                a = str(a)
                h.add_edge(a, b[0])
            if len(a) != 1 and len(b) != 1:
                a = str(a)
                b = str(b)
                h.add_edge(a, cn[0])
                h.add_edge(cn[0], b)

        return h

    def lone_leaf(g, node):
        # Return true if `node` is a node of degree one in networkx.graph `g` and the neighbor of `node` is not connected to any other nodes of degree one. This function is needed for 'augmented line-graph routing' which reduces the number qubits.
        assert g.has_node(node)
        if g.degree[node] != 1:
            return False
        else:
            # The single neighbour of `node`.
            nbr = list(nx.neighbors(g, node))[0]
            # Siblings of `node`. Contains `node` itself.
            sibs = list(nx.neighbors(g, nbr))
            # list of siblings with degree one
            lone_sibs = [sib for sib in sibs if g.degree[sib] == 1]
            assert len(lone_sibs) >= 1
            if len(lone_sibs) == 1:
                return True
            else:
                return False

    def nodes_to_ints(h):
        # Return h with all non-int nodes mapped to ints. Int nodes remain unchanged.
        ints = [i for i in h.nodes if type(i) == int]
        maxint = max(ints)
        mapping = {}
        i = 1
        for node in h.nodes():
            if type(node) != int:
                mapping[node] = maxint + i
                i += 1
        h = nx.relabel_nodes(h, mapping)
        return h

    def resize_register_to(qc, h):
        # Resize the quantum register of QuantumCircuit qc to the size of the number of nodes of h. All nodes of h must be ints.
        qcp = QuantumCircuit(max(h.nodes) + 1)
        for qcinst in qc.data:
            qubits = (qc.find_bit(qubit).index for qubit in qcinst.qubits)
            qcp.append(qcinst.replace(qubits=qubits))
        return qcp

    def bare_reroute(qc, h):
        # Line-graph reroute without removal of lone leaf qubits. And without removal of superflous SWAPs. Map circuit on cg, the coupling graph of qc, to a circuit on heavy(g), with g=L^-1(cg).
        cp = QuantumCircuit(max(h.nodes) + 1)
        for inst in qc.data:
            qubits = inst.qubits
            assert (
                len(qubits) == 1 or len(qubits) == 2
            ), "line_graph_route() is currently only for circuits consisting out if one- and two-qubit gates."
            if len(inst.qubits) == 1:
                cp.append(inst)
            elif len(qubits) == 2:
                i = qc.find_bit(qubits[0]).index
                j = qc.find_bit(qubits[1]).index
                path = nx.shortest_path(h, source=i, target=j)
                assert (
                    len(path) == 3
                ), "The path through h=heavy(g) from node i to j of g must touch 3 nodes."
                m = path[1]
                if inst.operation.name != "pad":
                    # Always 'swap in' the qubit with the lowest degree.
                    if h.degree[i] >= h.degree[j]:
                        cp.swap(j, m)
                        cp.append(inst.replace(qubits=(i, m)))
                        cp.swap(m, j)
                    else:
                        cp.swap(i, m)
                        cp.append(inst.replace(qubits=(m, j)))
                        cp.swap(m, i)

        return cp

    def remove_lone_leaf(qc, h):
        # Return circuit with lone leaf qubits removed accoring to 'agumented line-graph routing'.
        cp = QuantumCircuit(qc.num_qubits)

        for inst in qc.data:
            qubits = inst.qubits
            if len(qubits) == 1:
                i = qc.find_bit(qubits[0]).index
                if lone_leaf(h, i):
                    nbr = list(nx.neighbors(h, i))[0]
                    cp.append(inst.replace(qubits=(nbr,)))
                else:
                    cp.append(inst)
            elif len(qubits) == 2:
                i = qc.find_bit(qubits[0]).index
                j = qc.find_bit(qubits[1]).index
                if lone_leaf(h, i) or lone_leaf(h, j):
                    assert (
                        inst.operation.name == "swap"
                        or inst.operation.name == "pad_swap"
                    ), "In the rerouted circuit (pre removal of degree 1 nodes) any two-qubit gate hitting a lone leaf node must be a SWAP gate."
                    # This SWAP is **not** included in cp, which removes the need for the dangling qubit.
                else:
                    cp.append(inst)
            else:
                raise ValueError(
                    "A non- one- or two-qubit gate was encountered during routing."
                )

        return cp

    def fix_labels(qc, h):
        # Fix labels of qubits that were before lone leaf so that the old labeling of nodes is retained in the output circuit. This is not essential, but is practical when gates need to be added to the circuit *after* routing.
        swap_dict = {}
        for node in h.nodes:
            if lone_leaf(h, node):
                nbr = list(nx.neighbors(h, node))
                assert len(nbr) == 1
                nbr = nbr[0]
                swap_dict[nbr] = node

        cp = QuantumCircuit(qc.num_qubits)
        for inst in qc.data:
            qubits = inst.qubits
            i = qc.find_bit(qubits[0]).index
            if len(qubits) == 2:
                j = qc.find_bit(qubits[1]).index
            if len(qubits) == 1 and i in swap_dict:
                node = swap_dict[i]
                cp.append(inst.replace(qubits=(node,)))
            elif len(qubits) == 2 and i in swap_dict and j not in swap_dict:
                node = swap_dict[i]
                cp.append(inst.replace(qubits=(node, j)))
            elif len(qubits) == 2 and j in swap_dict and i not in swap_dict:
                node = swap_dict[j]
                cp.append(inst.replace(qubits=(i, node)))
            elif len(qubits) == 2 and i in swap_dict and j in swap_dict:
                node0 = swap_dict[i]
                node1 = swap_dict[j]
                cp.append(inst.replace(qubits=(node0, node1)))
            else:
                cp.append(inst)

        return cp

    # Apply line-graph routing.
    cg = coupling_graph(qc)
    assert nx.is_connected(
        cg
    ), "Line-graph routing only implemented for connected connectivity graphs. Route the disconnected circuits seperately or add padding identity gates with pad_gate()"
    g = nx.inverse_line_graph(cg)
    h = heavy(g)
    assert nx.is_connected(h)
    h = nodes_to_ints(h)
    qc = resize_register_to(qc, h)
    start = time()
    qc = bare_reroute(qc, h)
    qc = remove_lone_leaf(qc, h)
    qc = fix_labels(qc, h)
    qc = DoubleSwapRemover()(qc)
    qc = OuterSwapRemover()(qc)
    end = time()
    qc = remove_idle_qwires(qc)

    return qc

def decomp_rz (self, thet, qidx):
  s = self.run_gridsynth (thet)
  circuit = QuantumCircuit(1)
  gate_mapping = {
    'S': circuit.s,
    'H': circuit.h,
    'T': circuit.t,
    'X': circuit.x
  }
  for gs in s:
    gate = gate_mapping[gs]
    gate (0)
  return circuit

def XX_Block_diag(input_str, q_no, my_str):

    qc = QuantumCircuit(q_no)
    if input_str[:-1] == 'I' * (len(input_str) - 1) and input_str[-1] == my_str:
        return qc

    b_val = CNOT_conc.op_cnot(input_str, q_no)[0]
    cnot_arr = CNOT_conc.output_cnot(input_str, q_no)


    if b_val % 2 == 0: 
        qc.cx(max(cnot_arr), 0)

        for posn in cnot_arr:
            qc.cx(0, posn)

        qc.cx(max(cnot_arr), 0)

    else:
        for posn in cnot_arr:
            qc.cx(0, posn)

    return qc

def start_cir(q_no,input_str):

    qc = QuantumCircuit(q_no)

    for ind in range(len(input_str)):

        if input_str[ind] == 'Z':
            qc.h(q_no-ind-1)

        if input_str[ind] == 'Y':
            qc.rz(np.pi/4,q_no-ind-1)

    return qc

def end_cir(q_no,input_str):

    qc = QuantumCircuit(q_no)

    for ind in range(len(input_str)):

        if input_str[ind] == 'Z':
            qc.h(q_no-ind-1)

        if input_str[ind] == 'Y':
            qc.rz(-np.pi/4,q_no-ind-1)

    return qc

def _define(self):
    """
    gate iswap a,b {
        s q[0];
        s q[1];
        h q[0];
        cx q[0],q[1];
        cx q[1],q[0];
        h q[1];
    }
    """
    # pylint: disable=cyclic-import
    from qiskit.circuit.quantumcircuit import QuantumCircuit
    from .h import HGate
    from .s import SGate
    from .x import CXGate

    q = QuantumRegister(2, "q")
    qc = QuantumCircuit(q, name=self.name)
    rules = [
        (SGate(), [q[0]], []),
        (SGate(), [q[1]], []),
        (HGate(), [q[0]], []),
        (CXGate(), [q[0], q[1]], []),
        (CXGate(), [q[1], q[0]], []),
        (HGate(), [q[1]], []),
    ]
    for instr, qargs, cargs in rules:
        qc._append(instr, qargs, cargs)

    self.definition = qc

def _process_solution_init_state(self, solution):
    qc = QuantumCircuit(self.nq)
    for i, var in enumerate(self.init_state_vars):
        if solution[var] == 1:
            qc.h(i)
    return qc

def create_unrestricted_circuit(state):
    """Simple function to create qc without any connectivity constraints"""
    first = None
    qc = QuantumCircuit(len(state))
    for i in range(len(state)):
        if state[i] == 0:
            continue
        if first is None:
            first = i
            qc.h(i)
            continue
        qc.cx(first, i)
    return qc

def construct_circuit(self, mode='circuit', register=None):
    from qiskit import BasicAer

    if mode == 'vector':
        if self._state_vector is None:
            if self._circuit is not None:
                self._state_vector = np.asarray(q_execute(self._circuit, BasicAer.get_backend(
                    'statevector_simulator')).result().get_statevector(self._circuit))
        return self._state_vector
    elif mode == 'circuit':
        if self._circuit is None:
            # create emtpy quantum circuit
            circuit = QuantumCircuit()

            if register is None:
                register = QuantumRegister(self._num_qubits, name='q')

            if isinstance(register, QuantumRegister):
                circuit.add_register(register)
            elif isinstance(register, list):
                for q in register:
                    if isinstance(q, Qubit):
                        if not circuit.has_register(q.register):
                            circuit.add_register(q.register)
                    else:
                        raise AquaError('Unexpected qubit type {}.'.format(type(q)))
            else:
                raise AquaError('Unexpected register type {}.'.format(type(register)))

            if self._state is None or self._state == 'random':
                svc = StateVectorCircuit(self._state_vector)
                svc.construct_circuit(circuit=circuit, register=register)
            elif self._state == 'uniform':
                for i in range(self._num_qubits):
                    circuit.u2(0.0, np.pi, register[i])
            elif self._state == 'zero':
                pass
            else:
                AquaError('Unexpected state mode {}.'.format(self._state))
            self._circuit = circuit
        return self._circuit.copy()
    else:
        raise AquaError('Mode should be either "vector" or "circuit"')

def _define(self):
    """Calculate a subcircuit that implements this unitary."""
    if self.num_qubits == 1:
        from qiskit.synthesis.one_qubit.one_qubit_decompose import OneQubitEulerDecomposer

        q = QuantumRegister(1, "q")
        qc = QuantumCircuit(q)
        theta, phi, lam, global_phase = OneQubitEulerDecomposer("U").angles_and_phase(
            self.to_matrix()
        )
        qc._append(UGate(theta, phi, lam), [q[0]], [])
        qc.global_phase = global_phase
        self.definition = qc
    elif self.num_qubits == 2:
        from qiskit.synthesis.two_qubit.two_qubit_decompose import (  # pylint: disable=cyclic-import
            two_qubit_cnot_decompose,
        )

        self.definition = two_qubit_cnot_decompose(self.to_matrix())
    else:
        from qiskit.synthesis.unitary.qsd import (  # pylint: disable=cyclic-import
            qs_decomposition,
        )

        self.definition = qs_decomposition(self.to_matrix())
        # Since iterative Quantum Shannon Decomposition may provide imprecise matrices,
        # we use the Isometry decomposition in this case
        # pylint: disable=cyclic-import
        from qiskit.quantum_info.operators import Operator

        if not (
            matrix_equal(Operator(self.definition).to_matrix(), self.to_matrix(), atol=1e-7)
        ):
            self.definition = Isometry(self.matrix, 0, 0).definition

def _define(self):
    # Create quantum registers for address, index (optional), and data
    addr = QuantumRegister(self.nq_addr, 'addr')
    index = QuantumRegister(self.nq_index, 'index') if self.has_index else None
    data = QuantumRegister(self.nq_data, 'data')

    # Build the quantum circuit definition
    if index is not None:
        oracle = QuantumCircuit(addr, index, data)
    else:
        oracle = QuantumCircuit(addr, data)

    # Helper function to apply data based on specific address/index values
    def apply_data_for_key(circuit, j_val, i_val, data_val):
        controls = []

        # Address controls
        for i, bit in enumerate(j_val):
            if bit == '0':
                circuit.x(addr[i])
            controls.append(addr[i])

        # Index controls (if any)
        if index is not None:
            for i, bit in enumerate(i_val):
                if bit == '0':
                    circuit.x(index[i])
                controls.append(index[i])

        # Apply multi-controlled X gates for each data qubit set to 1
        for k, data_bit in enumerate(data_val):
            if data_bit == '1':
                # Add the multi-controlled X gate
                circuit.mcx(controls, data[k])

        # Undo the X gates (clean up)
        if index is not None:
            for i, bit in enumerate(i_val):
                if bit == '0':
                    circuit.x(index[i])

        for i, bit in enumerate(j_val):
            if bit == '0':
                circuit.x(addr[i])

    # Apply the mappings reversing the order of the qubits to match qiskit's convention
    for key, data_val in self.output_mapping.items():
        if self.has_index:
            j_val, i_val = key
            apply_data_for_key(oracle, j_val[::-1], i_val[::-1], data_val[::-1])
        else:
            j_val = key
            apply_data_for_key(oracle, j_val[::-1], None, data_val[::-1])

    # Set the definition of this gate
    self.definition = oracle

def add(circuit, shifts, data_qubits, control_qubits=None):
    # If no control qubits, then do an uncontrolled U(shifts) operation (shifts should just be a single number)
    name = "add"
    if(control_qubits == None):
        sub_circ = QuantumCircuit(data_qubits, name=name)
        U(sub_circ, shifts, data_qubits)
        circuit.append(sub_circ, data_qubits)
    else:
        sub_circ = QuantumCircuit(control_qubits, data_qubits, name=name)
        for i in range(len(shifts)):
            U_controlled(sub_circ, shifts[len(shifts) -grayCode(i)-1], control_qubits, data_qubits, len(shifts) -grayCode(i)-1)
        circuit.append(sub_circ, combine_registers(control_qubits, data_qubits))

def _build_feature_map(self):
    """Build feature map based on encoding_method"""
    num_qubits = self.num_latent + self.num_trash

    if self.encoding_method == 'angle':
        # Angle encoding using RY rotations
        feature_map = QuantumCircuit(num_qubits)
        params = ParameterVector('x', num_qubits)
        for i in range(num_qubits):
            feature_map.ry(params[i], i)
        # Add entanglement
        self._add_entanglement(feature_map, num_qubits)
        return feature_map

    elif self.encoding_method == 'amplitude':
        # Amplitude encoding using controlled rotations
        feature_map = QuantumCircuit(num_qubits)
        params = ParameterVector('x', num_qubits)
        for i in range(num_qubits):
            feature_map.ry(2 * params[i], i)
        self._add_entanglement(feature_map, num_qubits)
        return feature_map

    elif self.encoding_method == 'basis':
        # Basis encoding (computational basis states)
        feature_map = QuantumCircuit(num_qubits)
        params = ParameterVector('x', num_qubits)
        for i in range(num_qubits):
            feature_map.rx(params[i] * np.pi, i)
        self._add_entanglement(feature_map, num_qubits)
        return feature_map

    elif self.encoding_method == 'pauli':
        # Pauli feature map (default ZZFeatureMap)
        return ZZFeatureMap(num_qubits)

    else:
        raise ValueError(f"Unknown encoding method: {self.encoding_method}")

def _build_ansatz(self):
    """Build variational ansatz based on entanglement pattern"""
    num_qubits = self.num_latent + self.num_trash

    if self.entanglement == 'linear':
        return RealAmplitudes(num_qubits, entanglement='linear', reps=self.circuit_depth)
    elif self.entanglement == 'circular':
        return RealAmplitudes(num_qubits, entanglement='circular', reps=self.circuit_depth)
    elif self.entanglement == 'full':
        return RealAmplitudes(num_qubits, entanglement='full', reps=self.circuit_depth)
    elif self.entanglement == 'none':
        # Create custom ansatz with no entanglement
        ansatz = QuantumCircuit(num_qubits)
        params = ParameterVector('theta', num_qubits * (self.circuit_depth + 1))
        param_idx = 0

        for rep in range(self.circuit_depth + 1):
            for qubit in range(num_qubits):
                ansatz.ry(params[param_idx], qubit)
                param_idx += 1
            if rep < self.circuit_depth:
                ansatz.barrier()

        return ansatz
    else:
        # Default to RealAmplitudes with full entanglement
        return RealAmplitudes(num_qubits, entanglement='full', reps=self.circuit_depth)

def _construct_rotation(self, n_state_qubits: int):
    reg_state = QuantumRegister(n_state_qubits, "state")
    reg_flag = QuantumRegister(1, "flag")
    circuit = QuantumCircuit(reg_state, reg_flag, name="UCRY")
    angles = [0]
    tot = 2**n_state_qubits
    for i in range(1, tot):
        phi = i / tot
        rotation_value = (
            self.norm_const * 0.5 / (phi - (i >= 2 ** (n_state_qubits - 1)))
        )
        if np.isclose(rotation_value, 1, 1e-5, 1e-5):
            angles.append(np.pi)
        elif np.isclose(rotation_value, -1):
            angles.append(-np.pi)
        elif -1 < rotation_value < 1:
            angles.append(2 * np.arcsin(rotation_value))
        else:
            angles.append(0)
    circuit.ucry(angles, reg_state[:], reg_flag[:])
    return circuit

