def prep_mean_bits(n):
  """Prepare the mean state for the bits encoding"""
  # Get the array of amplitudes of the W state on n qubits.
  wstate_amps = [0] * (2 ** n)
  for i in range(n):
    wstate_amps[1 << i] = 1 / sqrt(n)

  # Prepare W state on each row of n qubits
  wstateprep = StatePreparation(wstate_amps)
  circ = QuantumCircuit(n * n)
  for r in range(n):
    circ.append(wstateprep, range(r * n, (r + 1) * n))
  return circ.to_gate()

def oracle_bits(n):
  """The oracle for the N queens problem."""
  # The presence of a queen in row r and column c is described with x[r * n + c].
  x = QuantumRegister(n * n, 'x')
  y = QuantumRegister(1, 'y')
  valid_column = QuantumRegister(n - 1, 'valid_column')
  invalid_rowpair = QuantumRegister(n * (n - 1) // 2, 'invalid_rowpair')

  circ = QuantumCircuit(x, valid_column, invalid_rowpair, y)

  def one_queen_per_column():
    """Evaluate the constraint of one queen per column."""
    for c in range(n - 1):
      for r in range(n):
        circ.cx(x[r * n + c], valid_column[c])

  def one_queen_per_diagonal():
    """Evaluate the constraint of one queen per diagonal."""
    ind = 0
    for r1 in range(n):
      for r2 in range(r1 + 1, n):
        for c1 in range(n):
          for c2 in [c1 + (r2 - r1), c1 - (r2 - r1)]:
            if c2 >= 0 and c2 < n:
              circ.ccx(x[r1 * n + c1], x[r2 * n + c2], invalid_rowpair[ind])
        ind += 1
    circ.x(invalid_rowpair)

  one_queen_per_column()
  one_queen_per_diagonal()
  circ.append(XGate().control(len(valid_column) + len(invalid_rowpair)),
              valid_column[:] + invalid_rowpair[:] + y[:])
  one_queen_per_column()
  one_queen_per_diagonal()

  return circ

def _carry_body(constant: int, n: int, x_qreg: QuantumRegister, g_qreg: QuantumRegister) -> Gate:
    constant_bits = as_bits_reversed(constant, n)
    circuit = QuantumCircuit(x_qreg, g_qreg)

    for i in reversed(range(2, n)):
        if constant_bits[i] == '1':
            circuit.x(x_qreg[i])
        circuit.ccx(g_qreg[i - 2], x_qreg[i], g_qreg[i - 1])
        if constant_bits[i] == '1':
            circuit.x(x_qreg[i])

    if constant_bits[1] == '1':
        circuit.cx(x_qreg[1], g_qreg[0])
        circuit.x(x_qreg[1])

    if constant_bits[0] == '1':
        circuit.ccx(x_qreg[0], x_qreg[1], g_qreg[0])

    for i in range(2, n):
        if constant_bits[i] == '1':
            circuit.cx(x_qreg[i], g_qreg[i - 1])
            circuit.x(x_qreg[i])
        circuit.ccx(g_qreg[i - 2], x_qreg[i], g_qreg[i - 1])

    return circuit.to_gate()

def generateCircuit(n):
	'''
	Generate a parameterized Gibbs state preparation circuit of size 2n.
	PARAMS:
		n (int): The number of qubits in a register.
	'''

	def thetaIter():
		'''
		Iterator for theta parameter.
		'''
		n = 0
		while True:
			yield Parameter(fr'$\theta_{{{n}}}$')
			n += 1

	def phiIter():
		'''
		Iterator for phi parameter.
		'''
		n = 0
		while True:
			yield Parameter(fr'$\phi_{{{n}}}$')
			n += 1

	# Get the parameter iterators.
	theta = thetaIter()
	phi = phiIter()

	# Generate the quanutm circuit and return.
	circ = QuantumCircuit(2*n)
	for i in range(n):
		circ.ry(next(theta), i)
	for i in range(n-1):
		circ.cx(i, i+1)
	for i in range(n):
		circ.ry(next(theta), i)
	for i in range(n):
		circ.cx(i, i+n)
	for i in range(n-1):
		for j in range(n, 2*n):
			if j == 2*n - 1:
				addRpGate(circ, j, n, phi)
			else:
				addRpGate(circ, j, j+1, phi)
	return circ

def generate_QAOA_circuit(graph:nx.Graph, p:int):
    '''
        Doesn't actually generate any angles. This is more about compilation than execution.

        The edges in the graph dictate which ZZ interations we perform; we ignore Z interactions (single qubit gates affect compilation very little)
    '''
    assert p > 0, f'Number of rounds, p, must be postive; gave p={p}'

    c = qiskit.circuit.QuantumCircuit(len(graph))
    qs = list(range(len(graph)))

    node_qbit_map = {}
    for i, n in enumerate(graph.nodes):
        node_qbit_map[n] = qs[i]

    for i in range(p):
        for edge in graph.edges:
            c.cx(node_qbit_map[edge[0]], node_qbit_map[edge[1]])
            c.z(node_qbit_map[edge[1]])
            c.cx(node_qbit_map[edge[0]], node_qbit_map[edge[1]])

        for node in graph.nodes:
            c.x(node_qbit_map[node])

    return c

def _conv_layer(self, num_qubits, params):
    qc = QuantumCircuit(num_qubits, name="Convolutional")
    qubits = list(range(num_qubits))
    param_index = 0
    for q1, q2 in zip(qubits[0::2], qubits[1::2]):
        qc = qc.compose(
            self._conv_template(
                params[param_index : (param_index + self._conv_template_num_parameters)]
            ),
            [q1, q2]
        )
        if self._insert_barriers:
            qc.barrier()
        param_index += self._conv_template_num_parameters

    if num_qubits > 2:
        for q1, q2 in zip(qubits[1::2], qubits[2::2] + [0]):
            qc = qc.compose(
                self._conv_template(
                    params[param_index : (param_index + self._conv_template_num_parameters)]
                ),
                [q1, q2]
            )
            if self._insert_barriers:
                qc.barrier()
            param_index += self._conv_template_num_parameters

    return qc.to_instruction()

def _pool_layer(self, sources, sinks, params):
    num_qubits = len(sources) + len(sinks)
    qc = QuantumCircuit(num_qubits, name="Pooling")
    param_index = 0
    for source, sink in zip(sources, sinks):
        qc = qc.compose(
            self._pool_template(
                params[param_index : (param_index + self._pool_template_num_parameters)]
            ),
            [source, sink]
        )
        if self._insert_barriers:
            qc.barrier()
        param_index += self._pool_template_num_parameters

    return qc.to_instruction()

def _define(self):
    """
    gate ch a,b {
        s b;
        h b;
        t b;
        cx a, b;
        tdg b;
        h b;
        sdg b;
    }
    """
    # pylint: disable=cyclic-import
    from qiskit.circuit.quantumcircuit import QuantumCircuit
    from .x import CXGate  # pylint: disable=cyclic-import

    q = QuantumRegister(2, "q")
    qc = QuantumCircuit(q, name=self.name)
    rules = [
        (SGate(), [q[1]], []),
        (HGate(), [q[1]], []),
        (TGate(), [q[1]], []),
        (CXGate(), [q[0], q[1]], []),
        (TdgGate(), [q[1]], []),
        (HGate(), [q[1]], []),
        (SdgGate(), [q[1]], []),
    ]
    for instr, qargs, cargs in rules:
        qc._append(instr, qargs, cargs)

    self.definition = qc

def initialize_random_parameters(num_qubits: int, max_operands: int, conditional: bool, seed):
    if max_operands < 1 or max_operands > 3:
        raise qiskit.circuit.exceptions.CircuitError("max_operands must be between 1 and 3")

    qr = qiskit.circuit.QuantumRegister(num_qubits, 'q')
    qc = qiskit.circuit.QuantumCircuit(num_qubits)

    if conditional:
        cr = qiskit.circuit.ClassicalRegister(num_qubits, 'c')
        qc.add_register(cr)

    if seed is None:
        seed = np.random.randint(0, np.iinfo(np.int32).max)

    rng = np.random.default_rng(seed)
    thetas = qiskit.circuit.ParameterVector('theta')
    return qr, qc, rng, thetas

def _define(self):
    # This is a stripped-down version of the bytecode interpreter; there's very few opcodes that
    # we actually need to handle within gate bodies.
    # pylint: disable=protected-access
    qubits = [Qubit() for _ in [None] * self.num_qubits]
    qc = QuantumCircuit(qubits)
    for op in self._bytecode:
        if op.opcode == OpCode.Gate:
            gate_id, args, op_qubits = op.operands
            qc._append(
                CircuitInstruction(
                    self._gates[gate_id](*(_evaluate_argument(a, self.params) for a in args)),
                    [qubits[q] for q in op_qubits],
                )
            )
        elif op.opcode == OpCode.Barrier:
            op_qubits = op.operands[0]
            qc._append(
                CircuitInstruction(Barrier(len(op_qubits)), [qubits[q] for q in op_qubits])
            )
        else:
            raise ValueError(f"received invalid bytecode to build gate: {op}")
    self._definition = qc

def get_maxcut_cost_operator_circuit(G, gamma):
    N = G.number_of_nodes()
    qc = QuantumCircuit(N)
    for i, j in G.edges():
        if nx.is_weighted(G):
            append_zz_term(qc, i, j, gamma * G[i][j]["weight"])
        else:
            append_zz_term(qc, i, j, gamma)
    return qc

def get_mixer_operator_circuit(G, beta):
    N = G.number_of_nodes()
    qc = QuantumCircuit(N)
    for n in G.nodes():
        append_x_term(qc, n, beta)
    return qc

def get_circuit(nq, n_layers):
  theta = ParameterVector('θ', length=nq*n_layers)
  qc = QuantumCircuit(nq)
  qc.h(range(nq))

  for layer_i in range(n_layers):
    # if layer_i%2:
    for qubit_i in range(nq - 1):
      qc.cx(qubit_i, (qubit_i + 1)%nq)
    for qubit_i in range(nq):
      qc.ry(theta[(nq*layer_i)+qubit_i], qubit_i)
  return qc

