def build_circuit_stepwise(msg: str, upto_step: int) -> QuantumCircuit:
    """
    Build the superdense circuit up to the given step.
    """
    qc = QuantumCircuit(2)
    if upto_step >= 1:
        qc.h(1)
    if upto_step >= 2:
        qc.cx(1, 0)
    if upto_step >= 3:
        qc.barrier()
    if upto_step >= 4 and msg[1] == "1":
        qc.x(1)
    if upto_step >= 5 and msg[0] == "1":   # ✅ fixed indexing bug here
        qc.z(1)
    if upto_step >= 6:
        qc.barrier()
    if upto_step >= 7:
        qc.cx(1, 0)
    if upto_step >= 8:
        qc.h(1)
    if upto_step >= 9:
        qc.measure_all()
    return qc

def pauli_exp_circuit(qubit_operator, n, revert_endianness=False):
    """
    Implements the exponential of an operator, which must be anti-Hermitian.
    If the Paulis commute, the circuit is exact. If they don't, it's an approximation with 1 Trotter step.

    Arguments:
        qubit_operator (QubitOperator): the generator of the unitary (exponent)
        n (int): the number of qubits of the output circuit (must be >= number of qubits qubit_operator acts on)
        revert_endianness (bool): if True/False, big/little endian ordering will be assumed

    Returns:
        Circuit implementing e^qubit_operator (approximately if strings in generator do not commute)
    """

    pauli_dict = convert_hamiltonian(qubit_operator)
    qc = QuantumCircuit(n)

    for pauli_string in pauli_dict.keys():

        coeff = pauli_dict[pauli_string]

        if revert_endianness:
            pauli_string = pauli_string + "I" * (n - len(pauli_string))
            pauli_string = pauli_string[::-1]

        assert coeff.real < 10**-8
        coeff = coeff.imag

        active_qubits = []
        for i, pauli in enumerate(pauli_string):

            if pauli != "I":
                active_qubits.append(i)

            if pauli == "X":
                qc.h(i)

            if pauli == "Y":
                qc.rx(np.pi / 2, i)

        for i in range(len(active_qubits) - 1):
            qc.cx(active_qubits[i], active_qubits[i + 1])

        qc.rz(-2 * coeff, active_qubits[-1])

        for i in reversed(range(len(active_qubits) - 1)):
            qc.cx(active_qubits[i], active_qubits[i + 1])

        for i, pauli in enumerate(pauli_string):

            if pauli == "X":
                qc.h(i)

            if pauli == "Y":
                qc.rx(-np.pi / 2, i)

    return qc

def create_alice_circuit(bits, bases):
    n = len(bits)
    qc = QuantumCircuit(n, name='Alice_Circuit')
    for i in range(n):
        if bits[i] == 1: qc.x(i)
        if bases[i] == 1: qc.h(i)
    qc.barrier()
    return qc

def _set_sv(self, sv: np.ndarray):
    if self.circuit is None:
        return
    self.circuit = QuantumCircuit(self.num_qubits)
    self.circuit.initialize(sv, range(self.num_qubits))

def get_circuits(self) -> List[QuantumCircuit]:
    circs: List[QuantumCircuit] = []
    for nm, q in self.qm.qubits.items():
        if QuantumCircuit is None: continue
        n = int(np.ceil(np.log2(max(2, q.dimension if isinstance(q, Cubit) else q.dimension))))
        qc = QuantumCircuit(n, name=nm)
        sv = q.get_statevector()
        if np.isclose(np.linalg.norm(sv), 0):
            sv = np.zeros(2**n, dtype=complex); sv[0] = 1.0
        try:
            qc.initialize(sv, range(n))
        except Exception:
            continue
        circs.append(qc)
    self._circuits_cache = circs
    return circs

def quantum_entropy_64() -> float:
    qc = QuantumCircuit(64, 64)
    for i in range(64):
        qc.h(i)
        if i > 0:
            qc.cx(i-1, i)
        qc.rz(random.random() * quantum_entropy_32(), i)
        qc.rx(random.random() * quantum_entropy_32(), i)  # Additional rotation
    qc.measure_all()
    backend = AerSimulator()  # Use AerSimulator from qiskit_aer
    result = backend.run(qc, shots=1).result()
    counts = result.get_counts()
    return float(int(list(counts.keys())[0].replace(" ", ""), 2)) / (2**64)

def ghz_state(n=3) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    qc.h(0)
    for i in range(n-1):
        qc.cx(i, i+1)
    return qc

def qft_circuit(n=3) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    for j in range(n):
        qc.h(j)
        for k in range(j+1, n):
            qc.p(math.pi / (2 ** (k - j)), j)
    for i in range(n//2):
        qc.swap(i, n-1-i)
    return qc

def parse_and_run(qasm_lines: List[str]) -> QuantumCircuit:
    qc = None
    for raw in qasm_lines:
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        parts = line.lower().split()
        op = parts[0]
        if op == 'qubits':
            qc = QuantumCircuit(int(parts[1]))
        elif qc is None:
            raise ValueError("First instruction must be: qubits N")
        elif op in ('h','x','y','z','s','t','sdg','tdg'):
            getattr(qc, op)(int(parts[1]))
        elif op in ('rx','ry','rz','p'):
            getattr(qc, op)(float(parts[1]), int(parts[2]))
        elif op in ('cx','cnot'):
            qc.cx(int(parts[1]), int(parts[2]))
        elif op == 'cz':
            qc.cz(int(parts[1]), int(parts[2]))
        elif op == 'swap':
            qc.swap(int(parts[1]), int(parts[2]))
        elif op == 'measure':
            pass
        else:
            raise ValueError(f"Unknown gate: {op}")
    if qc is None:
        raise ValueError("No circuit defined. Use: qubits N")
    return qc

