def polygongraph(num_qubits: int = 3, num_layers: int = 1) -> qiskit.QuantumCircuit:
    """Create parameterized polygon-graph ansatz

    Args:
        - num_qubits (int)
        - num_layers (int, optional): Defaults to 1.

    Returns:
        - qiskit.QuantumCircuit: parameterized quantum circuit
    """
    qc = qiskit.QuantumCircuit(num_qubits, num_qubits)
    thetas = ParameterVector('theta', 2*num_qubits*num_layers)
    j = 0
    for _ in range(0, num_layers, 1):
        for i in range(0, num_qubits):
            qc.ry(thetas[j], i)
            j += 1
        for i in range(0, num_qubits - 1, 2):
            qc.cz(i, i + 1)
        if num_qubits % 2 == 1:
            for i in range(0, num_qubits - 1):
                qc.ry(thetas[j], i)
                j += 1
        else:
            for i in range(0, num_qubits):
                qc.ry(thetas[j], i)
                j += 1
        for i in range(1, num_qubits - 1, 2):
            qc.cz(i, i + 1)
        if num_qubits % 2 == 1:
            qc.ry(thetas[j], num_qubits - 1)
            j += 1
        qc.cz(0, num_qubits - 1)
        qc.barrier()
    return qc

def grover_like_circuit(n_qubits: int = 3) -> QuantumCircuit:
    """Simple Grover-style circuit with oracle + diffusion."""
    qc = QuantumCircuit(n_qubits)
    # Initial superposition
    for q in range(n_qubits):
        qc.h(q)
    # Fake oracle (CZ on last qubit controlled by previous)
    for q in range(n_qubits - 1):
        qc.cx(q, n_qubits - 1)
    qc.z(n_qubits - 1)
    for q in range(n_qubits - 1):
        qc.cx(q, n_qubits - 1)
    # Diffusion
    for q in range(n_qubits):
        qc.h(q)
        qc.x(q)
    # Multi-controlled Z using CX chain
    for q in range(n_qubits - 1):
        qc.cx(q, n_qubits - 1)
    qc.z(n_qubits - 1)
    for q in range(n_qubits - 1):
        qc.cx(q, n_qubits - 1)
    for q in range(n_qubits):
        qc.x(q)
        qc.h(q)
    return qc

def measure_ghz(n_qubits: int, n_gates: int, optimize_parts: bool, check_optimized: bool):
    n_gates //= 100
    qc = QuantumCircuit(n_qubits, 1)

    for _ in range(n_gates):
        qc.h(0)
        for j in range(1, n_qubits):
            qc.cx(0, j)
        qc.measure(0, 0)
        for j in range(1, n_qubits):
            qc.cx(0, j)

    return qc, qc

def to_qiskit(self) -> QuantumCircuit:
    """
    Convert stored gates to an actual Qiskit QuantumCircuit.
    If measurement not present, this function does NOT automatically add measurements
    (caller decides).
    """
    qc = QuantumCircuit(self.num_qubits, self.num_qubits)
    for g in self.gates:
        name = g["name"]
        targets = g["targets"]
        controls = g["controls"]
        params = g["params"]

        if name == "H":
            for t in targets: qc.h(t)
        elif name == "X":
            for t in targets: qc.x(t)
        elif name == "Y":
            for t in targets: qc.y(t)
        elif name == "Z":
            for t in targets: qc.z(t)
        elif name == "S":
            for t in targets: qc.s(t)
        elif name == "T":
            for t in targets: qc.t(t)
        elif name == "RX":
            theta = float(params.get("theta", 0.0))
            for t in targets: qc.rx(theta, t)
        elif name == "RY":
            theta = float(params.get("theta", 0.0))
            for t in targets: qc.ry(theta, t)
        elif name == "RZ":
            theta = float(params.get("theta", 0.0))
            for t in targets: qc.rz(theta, t)
        elif name in ("CX", "CNOT"):
            # allow many pairs (controls / targets lists zipped)
            if controls and targets and len(controls) == len(targets):
                for ctrl, tgt in zip(controls, targets): qc.cx(ctrl, tgt)
            elif len(targets) == 2 and not controls:
                # allow ["targets": [ctrl, tgt]] pattern
                qc.cx(targets[0], targets[1])
            else:
                raise ValueError("CNOT requires control(s) and target(s) or two-element targets")
        elif name == "CCX":
            if len(controls) >= 2 and len(targets) >= 1:
                qc.ccx(controls[0], controls[1], targets[0])
            else:
                raise ValueError("CCX requires two controls and one target")
        elif name == "MEASURE":
            # measure each target into corresponding classical bit index
            for i, t in enumerate(targets):
                qc.measure(t, t)
        else:
            raise ValueError(f"Unhandled gate: {name}")
    return qc

def create_quantum_clustering_circuit(X, n_clusters):
    n_features = X.shape[1]
    qc = QuantumCircuit(n_features, n_clusters)

    # Prepare input data
    for i in range(n_features):
        if X[i] > 0:
            qc.h(i)
            qc.rz(2 * X[i], i)
        else:
            qc.rz(2 * X[i], i)

    # Perform quantum clustering
    for i in range(n_clusters):
        qc.h(n_features + i)
        for j in range(n_features):
            qc.cx(j, n_features + i)
            qc.rz(2 * np.pi * X[j, 0] * X[j, 1], [j, n_features + i])
            qc.cx(j, n_features + i)
        qc.h(n_features + i)

    # Measure output
    for i in range(n_clusters):
        qc.measure(n_features + i, i)

    return qc

def create_quantum_random_circuit(self):
    """Create a quantum circuit for generating random numbers"""
    if not self.quantum_mode:
        return None

    qc = QuantumCircuit(self.n_qubits, self.n_qubits)

    # Apply Hadamard gates for superposition
    for i in range(self.n_qubits):
        qc.h(i)

    # Add some entanglement for better randomness
    for i in range(self.n_qubits - 1):
        qc.cx(i, i + 1)

    # Measure all qubits
    for i in range(self.n_qubits):
        qc.measure(i, i)

    return qc

def qft_gate(input_size):
    """Build QFT circuit."""
    qr = QuantumRegister(input_size)
    qc = QuantumCircuit(qr, name="qft_")

    for i_qubit in range(0, input_size):
        hidx = input_size - i_qubit - 1

        if hidx < input_size - 1:
            num_crzs = i_qubit
            for j in range(0, num_crzs):
                divisor = 2 ** (num_crzs - j)
                qc.crz(math.pi / divisor, qr[hidx], qr[input_size - j - 1])

        qc.h(qr[hidx])

    return qc

def inv_qft_gate(input_size):
    """Build inverse QFT circuit."""
    qr = QuantumRegister(input_size)
    qc = QuantumCircuit(qr, name="inv_qft")

    for i_qubit in reversed(range(0, input_size)):
        hidx = input_size - i_qubit - 1

        qc.h(qr[hidx])

        if hidx < input_size - 1:
            num_crzs = i_qubit
            for j in reversed(range(0, num_crzs)):
                divisor = 2 ** (num_crzs - j)
                qc.crz(-math.pi / divisor, qr[hidx], qr[input_size - j - 1])

    return qc

def get_qc_for_n_qubit_GHZ_state(n):
