        qc.h(0)
    if "cnot" in values and n_qubits >= 2:
        qc.cx(0, 1)
    if "pauli-x" in values and n_qubits >= 1:
        qc.x(0)
    if "pauli-z" in values and n_qubits >= 1:
        qc.z(0)
    if "toffoli" in values and n_qubits >= 3:
        qc.ccx(0, 1, 2)

    # Teleportation template (very rough)
    if "bell measurement" in values and "pauli correction" in values and n_qubits >= 2:
        # Prepare Bell pair
        qc.h(0)
        qc.cx(0, 1)
        # placeholders for measurement/correction (not fully implemented)

    qc.barrier()
    qc.measure(range(n_qubits), range(n_qubits))

    return qc, None

