def encoder(initial_state):
    """Takes a message and return the circuit that encodes it"""
    qc = QuantumCircuit(encode_reg)
    for i in range(0,k_cl):
        qc.initialize(initial_state[i], i) 
    for i in range(k_cl*(K + 1), ENC-k_cl*K):
        qc.initialize(initial_state[i], i)
    for i in range(ENC - k_cl*K,ENC):
        qc.h(i)
    qc.append(inv_fourier, encode_reg[:ENC])
    return qc

def build_circuit_from_input(input_text):
    lines = input_text.strip().split('\n')
    qubits = set()
    for line in lines:
        parts = line.split()
        if len(parts) < 2:
            continue
        for p in parts[1:]:
            try:
                qubits.add(int(p))
            except ValueError:
                pass
    if not qubits:
        raise ValueError("No valid qubits found in the circuit input.")

    num_qubits = max(qubits) + 1
    qc = QuantumCircuit(num_qubits)

    for line_no, line in enumerate(lines, start=1):
        parts = line.split()
        if not parts:
            continue
        gate = parts[0].upper()
        if gate not in GATE_ARGS:
            raise ValueError(f"Line {line_no}: Unsupported gate '{gate}'")
        expected_args = GATE_ARGS[gate]
        if len(parts) - 1 != expected_args:
            raise ValueError(f"Line {line_no}: Gate '{gate}' expects {expected_args} argument(s), got {len(parts)-1}")

        try:
            if gate == 'H':
                qc.h(int(parts[1]))
            elif gate == 'X':
                qc.x(int(parts[1]))
            elif gate == 'Y':
                qc.y(int(parts[1]))
            elif gate == 'Z':
                qc.z(int(parts[1]))
            elif gate in ['CX','CNOT']:
                qc.cx(int(parts[1]), int(parts[2]))
            elif gate in ['CCX','TOFFOLI']:
                qc.ccx(int(parts[1]), int(parts[2]), int(parts[3]))
            elif gate == 'CZ':
                qc.cz(int(parts[1]), int(parts[2]))
            elif gate == 'CH':
                apply_ch(qc, int(parts[1]), int(parts[2]))
            elif gate == 'SWAP':
                qc.swap(int(parts[1]), int(parts[2]))
            elif gate == 'CSWAP':
                apply_cswap(qc, int(parts[1]), int(parts[2]), int(parts[3]))
            elif gate == 'S':
                qc.s(int(parts[1]))
            elif gate == 'SDG':
                qc.sdg(int(parts[1]))
            elif gate == 'T':
                qc.t(int(parts[1]))
            elif gate == 'TDG':
                qc.tdg(int(parts[1]))
            elif gate == 'RX':
                qc.rx(float(parts[1]), int(parts[2]))
            elif gate == 'RY':
                qc.ry(float(parts[1]), int(parts[2]))
            elif gate == 'RZ':
                qc.rz(float(parts[1]), int(parts[2]))
            elif gate == 'U3':
                qc.u(float(parts[1]), float(parts[2]), float(parts[3]), int(parts[4]))
        except Exception as e:
            raise ValueError(f"Line {line_no}: Error applying gate '{gate}' - {str(e)}")

    return qc

def _run_vqe(self, qubits: int) -> Dict[str, Any]:
    """Run Variational Quantum Eigensolver"""
    # Create VQE-like circuit
    qc = QuantumCircuit(qubits)

    # Add parameterized ansatz
    for i in range(qubits):
        qc.ry(0.5, i)

    for i in range(qubits - 1):
        qc.cx(i, i + 1)

    return {
        'type': 'VQE',
        'circuit_depth': qc.depth(),
        'eigenvalue': -1.8567,  # Simulated eigenvalue
        'improvement': 12.7
    }

def create_qft_circuit(num_qubits: int, inverse: bool = False) -> QuantumCircuit:
    """Create a Quantum Fourier Transform circuit"""
    qc = QuantumCircuit(num_qubits)

    for i in range(num_qubits):
        qc.h(i)
        for j in range(i + 1, num_qubits):
            qc.cp(math.pi / 2**(j - i), i, j)

    # Swap qubits
    for i in range(num_qubits // 2):
        qc.swap(i, num_qubits - i - 1)

    if inverse:
        return qc.inverse()
    return qc

def create_phase_gradient_circuit(num_qubits: int, inverse: bool = False) -> QuantumCircuit:
    """Create a Phase Gradient circuit"""
    qc = QuantumCircuit(num_qubits)

    for i in range(num_qubits):
        angle = 2 * math.pi / (2**(i+1))
        if inverse:
            angle = -angle
        qc.p(angle, i)

    return qc

def create_reverse_bits_circuit(num_qubits: int) -> QuantumCircuit:
    """Create a circuit that reverses the order of bits"""
    qc = QuantumCircuit(num_qubits)

    for i in range(num_qubits // 2):
        qc.swap(i, num_qubits - i - 1)

    return qc

def create_cycle_bits_circuit(num_qubits: int, reverse: bool = False) -> QuantumCircuit:
    """Create a circuit that cycles the bits"""
    qc = QuantumCircuit(num_qubits)

    if reverse:
        # Cycle right
        for i in range(num_qubits - 1, 0, -1):
            qc.swap(i, i - 1)
    else:
        # Cycle left
        for i in range(num_qubits - 1):
            qc.swap(i, i + 1)

    return qc

def create_interleave_bits_circuit(num_qubits: int, deinterleave: bool = False) -> QuantumCircuit:
    """Create a circuit that interleaves/deinterleaves bits"""
    if num_qubits % 2 != 0:
        raise ValueError("Number of qubits must be even for interleaving")

    half = num_qubits // 2
    qc = QuantumCircuit(num_qubits)

    if deinterleave:
        # Deinterleave: move even bits to first half, odd bits to second half
        for i in range(half):
            qc.swap(i * 2, i)
            qc.swap(i * 2 + 1, half + i)
    else:
        # Interleave: first half to even positions, second half to odd positions
        for i in range(half):
            qc.swap(i, i * 2)
            qc.swap(half + i, i * 2 + 1)

    return qc

def extract_subcircuit(all_gates: List[Dict], 
                       partition_map: Dict[int, int], 
                       partition_id: int) -> QuantumCircuit:
    """
    Extract subcircuit for a specific partition.
    """
    partition_qubits = sorted([q for q, p in partition_map.items() if p == partition_id])

    if not partition_qubits:
        return QuantumCircuit(1)

    qc = QuantumCircuit(len(partition_qubits))
    qubit_map = {old_q: new_q for new_q, old_q in enumerate(partition_qubits)}

    # Add gates that operate entirely within this partition
    for gate_info in all_gates:
        gate_qubits = gate_info['qubits']

        # Check if all qubits are in this partition
        if all(q in partition_qubits for q in gate_qubits):
            # Map to local qubit indices
            local_qubits = [qubit_map[q] for q in gate_qubits]

            try:
                qc.append(gate_info['instruction'], local_qubits)
            except:
                continue

    return qc

def _measure_x_2_top(self, qX, step):
    assert type(qX) is not list,  "You must only give one Measure X qubit"
    assert type(self.lattice.nodes[qX]) is AncillaNode, "The given qubit must be an Ancilla qubit"

    dataNeighbours = []
    for k in self.lattice.graph[qX]:
        if k.active == True:
            dataNeighbours.append(k.node)

    qc = ConstrainedQuantumCircuit(self.lattice, self.num_nodes, 1)

    # Check if qX is at the top
    if type(self.lattice.nodes[qX - 1]) is not DataNode:
        return qc

    if step == 1:
        #Initialize in Z basis
        qc.reset(qX)
    if step == 4:
        qc.cx(qX, dataNeighbours[1])
    if step == 5:
        qc.cx(qX, dataNeighbours[0])
    if step == 6:
        qc.measure([qX], 0)

    # return qc.to_instruction(label="measure_x_2")
    return qc

