def dna_to_circuit(dna_string):
    n = len(dna_string) % 8 + 2
    qc = QuantumCircuit(n)
    for i, gate in enumerate(dna_string):
        idx = i % n
        if gate == "H": qc.h(idx)
        elif gate == "C": qc.cx(idx, (i + 1) % n)
        elif gate == "T": qc.t(idx)
        elif gate == "X": qc.x(idx)
        elif gate == "Y": qc.y(idx)
        elif gate == "Z": qc.z(idx)
    return qc

