def compute_circuit(self):
    qr = qiskit.QuantumRegister(self.max_wires, 'q')
    qc = qiskit.QuantumCircuit(qr)

    for column_num in range(self.max_columns):
        for wire_num in range(self.max_wires):
            node = self.nodes[wire_num][column_num]
            if node:
                if node.node_type == node_types.IDEN:
                    # Identity gate
                    qc.i(qr[wire_num])
                elif node.node_type == node_types.X:
                    if node.radians == 0:
                        if node.ctrl_a != -1:
                            if node.ctrl_b != -1:
                                # Toffoli gate
                                qc.ccx(qr[node.ctrl_a], qr[node.ctrl_b], qr[wire_num])
                            else:
                                # Controlled X gate
                                qc.cx(qr[node.ctrl_a], qr[wire_num])
                        else:
                            # Pauli-X gate
                            qc.x(qr[wire_num])
                    else:
                        # Rotation around X axis
                        qc.rx(node.radians, qr[wire_num])
                elif node.node_type == node_types.Y:
                    if node.radians == 0:
                        if node.ctrl_a != -1:
                            # Controlled Y gate
                            qc.cy(qr[node.ctrl_a], qr[wire_num])
                        else:
                            # Pauli-Y gate
                            qc.y(qr[wire_num])
                    else:
                        # Rotation around Y axis
                        qc.ry(node.radians, qr[wire_num])
                elif node.node_type == node_types.Z:
                    if node.radians == 0:
                        if node.ctrl_a != -1:
                            # Controlled Z gate
                            qc.cz(qr[node.ctrl_a], qr[wire_num])
                        else:
                            # Pauli-Z gate
                            qc.z(qr[wire_num])
                    else:
                        if node.ctrl_a != -1:
                            # Controlled rotation around the Z axis
                            qc.crz(node.radians, qr[node.ctrl_a], qr[wire_num])
                        else:
                            # Rotation around Z axis
                            qc.rz(node.radians, qr[wire_num])
                elif node.node_type == node_types.S:
                    # S gate
                    qc.s(qr[wire_num])
                elif node.node_type == node_types.SDG:
                    # S dagger gate
                    qc.sdg(qr[wire_num])
                elif node.node_type == node_types.T:
                    # T gate
                    qc.t(qr[wire_num])
                elif node.node_type == node_types.TDG:
                    # T dagger gate
                    qc.tdg(qr[wire_num])
                elif node.node_type == node_types.H:
                    if node.ctrl_a != -1:
                        # Controlled Hadamard
                        qc.ch(qr[node.ctrl_a], qr[wire_num])
                    else:
                        # Hadamard gate
                        qc.h(qr[wire_num])
                elif node.node_type == node_types.SWAP:
                    if node.ctrl_a != -1:
                        # Controlled Swap
                        qc.cswap(qr[node.ctrl_a], qr[wire_num], qr[node.swap])
                    else:
                        # Swap gate
                        qc.swap(qr[wire_num], qr[node.swap])

    return qc

def random_clifford_circuit(n=5, depth=10, seed=123):
    import numpy as np
    rng = np.random.default_rng(seed)
    qc = QuantumCircuit(n)
    # Simple pseudo-Clifford-ish sampler (H,S,CX)
    for _ in range(depth):
        for q in range(n):
            gate = rng.integers(0,3)
            if gate == 0: qc.h(q)
            elif gate == 1: qc.s(q)
        # random CX
        for _ in range(n//2):
            a, b = rng.integers(0,n,2)
            if a != b:
                qc.cx(int(a), int(b))
    return qc

