def _prepare_state(bit: int, basis: str) -> QuantumCircuit:
    qc = QuantumCircuit(1, 1)
    if basis == 'Z':
        if bit == 1:
            qc.x(0)
    elif basis == 'X':
        qc.h(0)
        if bit == 1:
            qc.z(0)
    else:
        raise ValueError("basis must be 'Z' or 'X'")
    return qc

