def dual_bv_oracle(n, s1, s2):
    qr = QuantumRegister(n + 2)
    oracle = QuantumCircuit(qr)

    s1 = s1[::-1]
    s2 = s2[::-1]

    for i, bit in enumerate(s1):
        if bit == '1':
            oracle.cx(i, n)  # s1 dot x goes to ancilla 1 (qubit n)

    for i, bit in enumerate(s2):
        if bit == '1':
            oracle.cx(i, n+1)  # s2 dot x goes to ancilla 2 (qubit n+1)

    return oracle

def generate_circuit(table1, table2):
    """
    Génère le circuit quantique pour la clé de leasing.
    Attention : le code suppose que q = 2 et que x est de dimension 1.
    """
    qc = QuantumCircuit(2 * (1 + 2 * int(np.log2(q)) * n), 2 * (1 + 2 * int(np.log2(q)) * n))

    # 1er échantillon
    qc.h(0)

    for i in range(1, int(np.log2(q)) + 1): # prendre la partie entiere si q n'est pas une puissance de 2
        qc.h(i)

    for input, output in table1.items():
        input = [int(x) for x in list(input)]
        output = [int(x) for x in list(output)]
        if output != [0] * len(output):
            for j in range(len(output)):
                if output[j] == 1:
                    to_invert = [k for k in range(len(input)) if input[k] == 0]
                    for i in to_invert:
                        qc.x(i)
                    # Portes ET
                    for k in range(1, len(input)):
                        qc = land(qc, 0, k, len(input) + j)
                    # On reset les entrées inversées
                    for i in to_invert:
                        qc.x(i)

    qc.measure(range(len(input), len(input) + len(output)), range(len(input), len(input) + len(output)))

    # 2ème échantillon
    m = len(input) + len(output)
    qc.h(m)

    for i in range(1, int(np.log2(q)) + 1): # prendre la partie entiere si q n'est pas une puissance de 2
        qc.h(m+i)

    for input, output in table2.items():
        input = [int(x) for x in list(input)]
        output = [int(x) for x in list(output)]
        if output != [0] * len(output):
            for j in range(len(output)):
                if output[j] == 1:
                    to_invert = [k for k in range(len(input)) if input[k] == 0]
                    for i in to_invert:
                        qc.x(m+i)
                    # Portes ET
                    for k in range(1, len(input)):
                        qc = land(qc, m, m+k, m + len(input) + j)
                    # On reset les entrées inversées
                    for i in to_invert:
                        qc.x(m + i)

    qc.measure(range(m + len(input), m + len(input) + len(output)), range(m + len(input), m + len(input) + len(output)))

    return qc

def to_qiskit(circuit: Circuit, *, add_measures: bool = True) -> Any:
    """Convert IR `Circuit` to a Qiskit `QuantumCircuit`.

    Supports ops: h, rx(theta), rz(theta), cx, measure_z.
    """
    if QuantumCircuit is None:
        raise RuntimeError("qiskit is not available; please install qiskit to use this provider")
    qc = QuantumCircuit(circuit.num_qubits)

    measure_indices: List[int] = []
    for op in circuit.ops:
        name = op[0]
        if name == "h":
            qc.h(int(op[1]))
        elif name == "rx":
            qc.rx(float(op[2]), int(op[1]))
        elif name == "rz":
            qc.rz(float(op[2]), int(op[1]))
        elif name == "cx":
            qc.cx(int(op[1]), int(op[2]))
        elif name == "measure_z":
            measure_indices.append(int(op[1]))
        else:
            raise NotImplementedError(f"Unsupported op for qiskit adapter: {name}")

    if add_measures:
        if measure_indices:
            if ClassicalRegister is None:
                raise RuntimeError("qiskit classical register not available")
            creg = ClassicalRegister(len(measure_indices), 'c')
            qc.add_register(creg)
            for i, q in enumerate(measure_indices):
                qc.measure(q, creg[i])
        else:
            # No explicit measure ops in IR: measure all for execution outputs
            qc.measure_all()
    return qc

