def create_bb84_qubit(bit, basis):
    """Creates a single qubit circuit for BB84 state preparation."""
    qc = QuantumCircuit(1, 1, name=f"Qubit(bit={bit}, basis={basis})")
    if basis == 'Z': # Computational basis (+ or |0>, x or |1>)
        if bit == 1:
            qc.x(0) # Prepare |1>
        # else: implicitly |0>
    elif basis == 'X': # Hadamard basis (H or |+>, V or |->)
        if bit == 0:
            qc.h(0) # Prepare |+>
        else:
            qc.x(0)
            qc.h(0) # Prepare |->
    else:
        raise ValueError("Basis must be 'Z' or 'X'")
    return qc

