def alice_prepare_qubits(self):
    """Alice generates random bits and random bases for each qubit"""
    alice_bits = [secrets.randbelow(2) for _ in range(self.key_length)]
    alice_bases = [secrets.choice(['Z', 'X']) for _ in range(self.key_length)]

    # Create quantum circuits for each qubit
    circuits = []
    for bit, basis in zip(alice_bits, alice_bases):
        qc = QuantumCircuit(1, 1)

        if basis == 'Z':
            # Computational basis
            if bit == 1:
                qc.x(0)  # |1⟩ state
            # else: |0⟩ state (default)
        else:  # X basis (Hadamard basis)
            if bit == 0:
                qc.h(0)  # |+⟩ state
            else:
                qc.x(0)
                qc.h(0)  # |-⟩ state

        circuits.append(qc)

    return alice_bits, alice_bases, circuits

def simulate_eavesdropping(self, circuits, eavesdrop_fraction=0.3):
    """Simulate Eve intercepting and measuring some qubits"""
    eve_bases = [secrets.choice(['Z', 'X']) for _ in range(len(circuits))]
    intercepted_circuits = []

    for i, qc in enumerate(circuits):
        if random.random() < eavesdrop_fraction:
            # Eve intercepts and measures
            eve_qc = qc.copy()

            if eve_bases[i] == 'X':
                eve_qc.h(0)

            eve_qc.measure(0, 0)
            job = self.backend.run(eve_qc, shots=1, memory=True)
            result = job.result()
            eve_measurement = int(result.get_memory()[0])

            # Eve prepares new qubit based on her measurement
            new_qc = QuantumCircuit(1, 1)
            if eve_bases[i] == 'Z':
                if eve_measurement == 1:
                    new_qc.x(0)
            else:  # X basis
                if eve_measurement == 0:
                    new_qc.h(0)  # |+⟩
                else:
                    new_qc.x(0)
                    new_qc.h(0)  # |-⟩

            intercepted_circuits.append(new_qc)
        else:
            intercepted_circuits.append(qc.copy())

    return intercepted_circuits

def generic_qft(n):
    circuit = QuantumCircuit(n)
    for i in range(n-1,-1,-1):
        circuit.h(i)
        for j in range(i-1,-1,-1):
            circuit.cp(np.pi/float(2**(i-j)), j, i)
        circuit.barrier()
    for i in range(n//2):
        circuit.swap(i, n-i-1)
    return circuit

def bounded_qubits_qft(n, m):
    circuit = QuantumCircuit(n)
    for i in range(n-1,-1,-1):
        circuit.h(i)
        if i >= m:
            for j in range(i-1, i-m-1, -1):
                circuit.cp(np.pi/float(2**(i-j)), j, i)
        else:
            for j in range(i-1,-1,-1):
                circuit.cp(np.pi/float(2**(i-j)), j, i)
        circuit.barrier()
    for i in range(n//2):
        circuit.swap(i, n-i-1)
    return circuit

def build_uniformly_controlled_rotation_circuit(control, target):
    """Build a quantum circuit implementing uniformly controlled rotations"""
    qc = QuantumCircuit(control + 1)
    angles = calculate_rotation_angles(control)

    gray_codes = gray_code(control)
    for idx, code in enumerate(gray_codes):
        for ctrl_qubit in range(control):
            if code[ctrl_qubit] == '1':
                qc.cx(ctrl_qubit, control)
        qc.ry(angles[idx], control)
        for ctrl_qubit in range(control):
            if code[ctrl_qubit] == '1':
                qc.cx(ctrl_qubit, control)

    return qc

