def expmiht_approx(n_terms:int, time_tau:float, gamma:float, lam:int, order:int=2, verbose:int=0):
    '''
    Hamiltonian simulation circuit in [1]. See Fig. 1, Eq. (39), (33)
    NOTE: the paper use little endian, as stated in the paragraph below (36)

    Hermitian matrix H = gamma * sum_{j=1}^{n} (e^{i*lam} s^-_j + e^{-i*lam} s^+_j)
    gamma in R is a scale parameter, lam in R is a phase parameter
    s^+_j = I^{⊗(n-j)} ⊗ sigma_01 ⊗ sigma_10^{⊗(j-1)}
    s^-_j = I^{⊗(n-j)} ⊗ sigma_10 ⊗ sigma_01^{⊗(j-1)}
    sigma_01 = |0><1|, sigma_10 = |1><0|

    [1]  Hamiltonian simulation for hyperbolic partial differential equations by scalable quantum circuits https://arxiv.org/pdf/2402.18398
    '''

    # num_qubits = int(numpy.log2(ham_mat.shape[0]))
    num_qubits = n_terms
    ##
    full_circuit = qiskit.QuantumCircuit(num_qubits)
    if order == 1:
        for i in range(num_qubits-1):
            ham_wj(full_circuit, gamma*time_tau, lam, 0, i )
    elif order == 2:
        ham_wj(full_circuit, -0.5*gamma*time_tau, lam, 0, 0 )
        for i in range(num_qubits-1):
            ham_wj(full_circuit, gamma*time_tau, lam, 0, i )
        ham_wj(full_circuit, 0.5*gamma*time_tau, lam, 0, 0 )

    ##
    if verbose > 0:
        if order == 1:
            error_upperbound = 0.5*(gamma**2)*(time_tau**2)*(num_qubits-1)
        elif order == 2:
            error_upperbound = (1.0/6.0)*(gamma**3)*(time_tau**3)*(2*num_qubits-3)
        print("  Ham. Sim. Error Upper Bound=", error_upperbound)
    return full_circuit

def parse ():
    """ Receives the JSONL payload, constructs the described circuit
        and returns the specified output.
    """
    data: list[dict] = [json.loads(line) for line in request.get_json().split('\n')]
    CUSTOMS.clear()
    POSTSELECTIONS.clear()

    for i, line in enumerate(data):
        if 0 < i < len(data) - 1:
            # all intermediary definitions are custom gates
            custom_gate = build(line)
            CUSTOMS[f'cg{len(CUSTOMS) + 1}'] = [custom_gate.to_gate, custom_gate.width()]
        if i == len(data) - 1:
            # the final definition is the circuit to execute
            circuit = QuantumCircuit(line.get('length'), line.get('length'))
            circuit = build(line, circuit)

    output = data[0].get('output')

    if output == 'counts':     return counts(circuit, data[-1])
    if output == 'amplitudes': return amplitudes(circuit, data[-1])
    if output == 'unitary':    return unitary_matrix(circuit, data[-1])
    if output == 'phases':     return phases(circuit, data[-1])
    if output == 'code':       return source_code(circuit, data[-1])

    return '"No such command."', 400

def build (template: dict, circuit: QuantumCircuit = None):
    """ Constructs the `QuantumCircuit` object as specified by the passed `template`.

        **Params:**\n
        `template`: The circuit instance to build.\n
        `circuit`: If passed, the construction will happen in-place, but the same
        object will be returned again.

        **Returns:** A `QuantumCircuit` object holding the specified circuit.
    """
    def unify (gates: list[str]):
        if len(gates) == 0: return None

        step  = QuantumCircuit(len(gates))
        swaps = []

        # place every gate in the order shown in the column
        for i, stamp in enumerate(gates):
            if stamp in DEFAULTS:
                step.append(DEFAULTS[stamp](), [i])
            if stamp.startswith('powered-'):
                kind, repr = stamp.split('powered-')[1].split(DELIMITER)
                power = float(sympify(repr).evalf())  # evaluate the exponent
                step.append(DEFAULTS[kind]().power(power), [i])
            if stamp == 'swap':
                swaps.append(i)
            if stamp in CUSTOMS:                 # jump as many qubits as this gate spans
                step.append(CUSTOMS[stamp][0](), [i + j for j in range(CUSTOMS[stamp][1])])

        if len(swaps) == 2:
            # place swaps only if they are a single pair
            # (redundant check as the interface shouldnt allow errors to pass through)
            step.swap(swaps[0], swaps[1])

        return step.to_gate()

    # collect the entire circuit as a matrix of gates, rows are qubit gate trains
    gate_matrix = np.array([
        element.get('gates')
        for element in template.values()
        if isinstance(element, dict)
    ])

    if circuit is None: circuit = QuantumCircuit(gate_matrix.shape[0]) 

    for col in gate_matrix.T:
        # unify every column into a single gate, so that any controls present affect the entire step
        control_state = ''.join(el.split(DELIMITER)[1] for el in col if el.startswith('control'))        
        step = unify([el for el in col if not el.startswith(('control', 'measurement', 'inertia'))])

        if control_state: step = step.control(len(control_state), ctrl_state=control_state[::-1])

        if step is not None: 
            circuit.append(step, 
                [i for i, stamp in enumerate(col) if stamp.startswith('control')] + 
                [i for i, stamp in enumerate(col) if not stamp.startswith(('control', 'measurement', 'inertia'))])

        for i, stamp in enumerate(col):
            if stamp.startswith('measurement'):
                # save any specified postselections for the execution phase
                mode = stamp.split(DELIMITER)[1]
                if mode != '2' : POSTSELECTIONS[i] = mode
                circuit.measure(i, i)

    return circuit

def construct(self):
    if not self.initialized:
        raise Exception('Initialization is required')

    if len(self.mapping) == 0:
        raise Exception('Variable to physical qubit mapping is required!')

    if len(self.gates) == 0:
        raise Exception(
            'Nothing to construct! Possibly, not input file was provided')

    for variable in self.variables:
        if variable not in self.mapping:
            raise Exception(
                'Variable {} is not mapped to any physical qubit!'.format(variable))

    if self.debugging:
        print('[INFO] Constructing quantum circuit...')

    self.circuit = QuantumCircuit()
    self._mapping = {}
    self.variable_to_logical = {}
    self.logical_to_variable = {}
    self.logical_to_physical = {}
    self.physical_to_logical = {}
    size = 0
    # Set all of the mappings: variable <-> logical layer <-> physical layer
    for v in self.mapping:
        self._mapping[v] = self.mapping[v]
        self.circuit.add_register(QuantumRegister(1, name=v))
        self.variable_to_logical[v] = size
        self.logical_to_physical[size] = self._mapping[v]
        self.physical_to_logical[self._mapping[v]] = size
        self.logical_to_variable[size] = v
        size += 1

    self.circuit.add_register(ClassicalRegister(len(self.outputs)))

    if self.debugging:
        print('[INFO] Setting constants values...')

    # The size of input is always same as the size of variables
    # Ex: variables: a b c d and input: a 0 c 1 means variables b and d are constants
    for i, v in enumerate(self.inputs):
        if v == '1':
            self.circuit.x(self.variable_to_logical[self.variables[i]])

    for gate in self.gates:
        # if self.debugging:
        #     print('[INFO] Inserting gate: {}'.format(gate))

        if gate.name == 'h' or gate.name == 'H':
            self.circuit.h(self.variable_to_logical[gate.variables[0]])
        elif gate.name == 'T':
            self.circuit.t(self.variable_to_logical[gate.variables[0]])
        elif gate.name == 'T+' or gate.name == 'T*':
            self.circuit.tdg(self.variable_to_logical[gate.variables[0]])
        elif gate.name == 'x' or gate.name == 't1':
            self.circuit.x(self.variable_to_logical[gate.variables[0]])
        elif gate.name.startswith('t') and len(gate.variables) > 2:
            self.n_ccnot(gate.variables[:-1], gate.variables[-1])
        else:
            if gate.name == 'v':
                self.cv(gate.variables[0], gate.variables[1])
            elif gate.name == 'v+':
                self.cvdg(gate.variables[0], gate.variables[1])
            elif gate.name == 'cx' or gate.name == 't2':
                position = self.variable_to_logical[gate.variables[0]]
                self.move_variable(gate.variables[0], gate.variables[1])
                control = self.variable_to_logical[gate.variables[0]]
                target = self.variable_to_logical[gate.variables[1]]
                self.circuit.cx(control, target)
                self.move_variable(
                    gate.variables[0], self.logical_to_variable[position], True)
            else:
                logical_a = self.variable_to_logical[gate.variables[0]]
                logical_b = self.variable_to_logical[gate.variables[1]]
                self.move_variable(
                    gate.variables[0], gate.variables[1], True)
                self.move_variable(
                    gate.variables[1], self.logical_to_variable[logical_a], True)
                self.variable_to_logical[gate.variables[0]] = logical_a
                self.variable_to_logical[gate.variables[1]] = logical_b
                self.logical_to_variable[logical_a] = gate.variables[0]
                self.logical_to_variable[logical_b] = gate.variables[1]

    if self.debugging:
        print('[INFO] Circuit is constructed!')

def construct_circuit(self, mode, register=None):
    """
    Construct the statevector of desired initial state.

    Args:
        mode (string): `vector` or `circuit`. The `vector` mode produces the vector.
                        While the `circuit` constructs the quantum circuit corresponding that
                        vector.
        register (QuantumRegister): register for circuit construction.

    Returns:
        QuantumCircuit or numpy.ndarray: statevector.

    Raises:
        ValueError: when mode is not 'vector' or 'circuit'.
    """
    if mode == 'vector':
        if self._state_vector is None:
            if self._circuit is not None:
                self._state_vector = np.asarray(q_execute(self._circuit, get_aer_backend(
                    'statevector_simulator')).result().get_statevector(self._circuit))
        return self._state_vector
    elif mode == 'circuit':
        if self._circuit is None:
            if register is None:
                register = QuantumRegister(self._num_qubits, name='q')
            circuit = QuantumCircuit(register)
            if self._state is None or self._state == 'random':
                circuit.initialize(self._state_vector, [
                                   register[i] for i in range(self._num_qubits)])
                circuit = Custom._convert_to_basis_gates(circuit)
            elif self._state == 'zero':
                pass
            elif self._state == 'uniform':
                for i in range(self._num_qubits):
                    circuit.u2(0.0, np.pi, register[i])
            else:
                pass
            self._circuit = circuit
        return self._circuit
    else:
        raise ValueError('Mode should be either "vector" or "circuit"')

