def create_oracle(values, target_idx, num_qubits):
    st = time.time()
    cache_key = f'oracle_{target_idx}_{num_qubits}'
    if cache_key in circuit_cache:
        return circuit_cache[cache_key]

    oracle = QuantumCircuit(num_qubits)
    for i in range(num_qubits):
        if (target_idx >> i) & 1:
            oracle.x(i)

    if num_qubits == 1:
        oracle.h(0)
        oracle.z(0)
        oracle.h(0)
    elif num_qubits > 3:
        mid = num_qubits // 2
        oracle.h(num_qubits - 1)
        oracle.mcx(list(range(mid)), mid)
        oracle.mcx(list(range(mid, num_qubits - 1)), num_qubits - 1)
        oracle.h(num_qubits - 1)
    else:
        oracle.h(num_qubits - 1)
        if num_qubits == 2:
            oracle.cx(0, 1)
        else:
            oracle.mcx(list(range(num_qubits - 1)), num_qubits - 1)

    for i in range(num_qubits):
        if (target_idx >> i) & 1:
            oracle.x(i)
    circuit_cache[cache_key] = oracle
    et = time.time()
    return oracle

def create_diffusion(num_qubits):
    st = time.time()
    cache_key = f'diffusion_{num_qubits}'
    if cache_key in circuit_cache:
        return circuit_cache[cache_key]

    diffusion = QuantumCircuit(num_qubits + 1)
    for qubit in range(num_qubits):
        diffusion.h(qubit)
    for qubit in range(num_qubits):
        diffusion.x(qubit)
    chunk_size = 3
    for i in range(0, num_qubits - 1, chunk_size):
        control_qubits = list(range(i, min(i + chunk_size, num_qubits - 1)))
        if len(control_qubits) > 0:
            diffusion.h(num_qubits)
            diffusion.mcx(control_qubits, num_qubits)
            diffusion.h(num_qubits)
    for qubit in range(num_qubits):
        diffusion.x(qubit)
    for qubit in range(num_qubits):
        diffusion.h(qubit)
    circuit_cache[cache_key] = diffusion
    et = time.time()
    return diffusion

def get_trotterized_ising_circuit(self):
    dt = self.t / self.steps
    qc = QuantumCircuit(self.k)
    for _ in range(self.steps):
        # Even pairs
        for i in range(0, self.k - 1, 2):
            qc.append(RZZGate(-2 * self.J * dt), [i, i + 1])
        # Odd pairs
        for i in range(1, self.k - 1, 2):
            qc.append(RZZGate(-2 * self.J * dt), [i, i + 1])
        qc.barrier()
        # Transverse field
        for i in range(self.k):
            qc.rx(-2 * self.h * dt, i)
        qc.barrier()
    return qc

def combine ( self, qasm_list ):
    """
    Combines the circuits into one circuit.

    Args:
        qasm_list(List[Tuple[str, Tuple[int]]]): The small circuits
            and their locations.

    Returns:
        (str): The final circuit's QASM
    """

    if not isinstance( qasm_list, list ):
        raise TypeError( "qasm_list must be a list." )

    if not all( isinstance( qasm[0], str ) for qasm in qasm_list ):
        raise TypeError( "qasm_list must contain QASM strings." )

    loc_fixed = [ qasm[1] for qasm in qasm_list ]
    qasm_list = [ qasm[0] for qasm in qasm_list ]

    # Calculate Output Circuit Size
    max_qubit = 0

    for loc in loc_fixed:
        for qub in loc:
            max_qubit = max( qub, max_qubit )

    # Convert to circuits
    circs = []
    for qasm in qasm_list:
        try:
            circs.append( QuantumCircuit.from_qasm_str( qasm ) )
        except:
            raise ValueError( "Invalid QASM string: %s" % qasm )

    if all( len( circ.qubits ) != len( loc )
            for circ, loc in zip( circs, loc_fixed ) ):
        raise ValueError( "Location and QASM qubit counts don't match." )

    # Join into One Circuit
    out_circ = QuantumCircuit( max_qubit + 1 )

    for circ, loc in zip( circs, loc_fixed ):
        for gate in circ.data:
            if gate[0].name == 'cx':
                out_circ.cx( loc[ gate[1][0].index ], loc[ gate[1][1].index ] )
            elif gate[0].name == 'u1':
                out_circ.u1( *gate[0].params, loc[ gate[1][0].index ] )
            elif gate[0].name == 'u2':
                out_circ.u2( *gate[0].params, loc[ gate[1][0].index ] )
            elif gate[0].name == 'u3':
                out_circ.u3( *gate[0].params, loc[ gate[1][0].index ] )
            elif gate[0].name == 'rx':
                out_circ.rx( *gate[0].params, loc[ gate[1][0].index ] )
            elif gate[0].name == 'ry':
                out_circ.ry( *gate[0].params, loc[ gate[1][0].index ] )
            elif gate[0].name == 'rz':
                out_circ.rz( *gate[0].params, loc[ gate[1][0].index ] )
            else:
                raise ValueError( "QASM must be in \'u1, u2, u3, cx\' basis." )

    out_circ = qiskit.compiler.transpile( out_circ, basis_gates = ['u3', 'cx'],
                                          optimization_level = 3 )
    return out_circ.qasm()

def segmented_excute_circuit(self, params) -> QuantumCircuit:
    mcx_mode = self.circuit_option.mcx_mode
    num_qubits = self.model_option.num_qubits
    # self.qc = self.circuit_option.provider.transpile(qc)

    def run_and_pick(dict:dict, hdi_qc: QuantumCircuit, param):
        # iprint("--------------")
        # iprint(f'input dict: {dict}')
        dicts = []
        total_count = sum(dict.values())
        for key, value in dict.items():
            if mcx_mode == "constant":
                qc_temp = QuantumCircuit(num_qubits + 2, num_qubits)
            elif mcx_mode == "linear":
                qc_temp = QuantumCircuit(2 * num_qubits, num_qubits)

            for idx, key_i in enumerate(key):
                if key_i == '1':
                    qc_temp.x(idx)
            qc_add = hdi_qc.assign_parameters([param])
            qc_temp.compose(qc_add, inplace=True)
            qc_temp.measure(range(num_qubits), range(num_qubits)[::-1])
            # iprint(f'hdi depth: {qc_temp.depth()}')
            qc_temp = self.circuit_option.provider.transpile(qc_temp)

            count = self.circuit_option.provider.get_counts_with_time(qc_temp, shots=self.circuit_option.shots * value // total_count)
            # origin = self.circuit_option.shots * value // total_count
            # count = self.circuit_option.provider.get_counts_with_time(qc_temp, shots=1024)
            # count = {k: round(v / 1024 * origin, 0) for k, v in count.items() if round(v / 1024 * origin, 0) > 0}

            dicts.append(count)
        # iprint(f'this hdi depth: {qc_temp.depth()}')

        # iprint(f'evolve: {dicts}')
        merged_dict = {}
        for d in dicts:
            for key, value in d.items():
                if all([np.dot([int(char) for char in key], constr[:-1]) == constr[-1] for constr in self.model_option.lin_constr_mtx]):
                    merged_dict[key] = merged_dict.get(key, 0) + value
        # iprint(f'feasible counts: {merged_dict}')
        return merged_dict


    register_counts = {''.join(map(str, self.model_option.feasible_state)): 1}
    for i, h_tau in enumerate(self.hlist):
        register_counts = run_and_pick(register_counts, h_tau, params[i])

    return register_counts

def encode_message(bits, bases):
    message = []
    for i in range(len(bits)):
        qc = QuantumCircuit(1,1)
        if bases[i] == 0: # Prepare qubit in Z-basis
            if bits[i] == 0:
                pass
            else:
                qc.x(0)
        else: # Prepare qubit in X-basis
            if bits[i] == 0:
                qc.h(0)
            else:
                qc.x(0)
                qc.h(0)
        qc.barrier()
        message.append(qc)
    return message

