def mps_circ(num_qubits):
    bond_dimensions = [2**ii for ii in range(1, int(np.ceil(num_qubits/2)+1))]
    if num_qubits%2 == 0:
        bond_dimensions += bond_dimensions[:-1][::-1]
    else:
        bond_dimensions += bond_dimensions[::-1]
    qc = QuantumCircuit(len(bond_dimensions)+1)
    skip = None
    ii = 0
    for idx, bd in enumerate(bond_dimensions):
        num_qubs = int(np.ceil(np.log2(bd)))

        for nq1 in range(1, num_qubs+1):
            if skip is not None:
                if skip[nq1-1]:
                    continue

            gate_idx = nq1-1
            for nq in range(nq1, 0, -1):
                qc.append(SU4Gate( param_prefix=f"θ{ii}"), (idx+nq, idx+nq-1) )
                if nq - 1 == np.ceil(nq1/2) and nq1%2 == 0:
                    gate_idx = gate_idx
                elif nq-1 > nq1/2:
                    gate_idx -= 2
                else:
                    gate_idx += 2
                ii += 1

        if idx < len(bond_dimensions)-1:
            if bd > bond_dimensions[idx+1] or bd >4:
                skip = [True if nq>1 else False for nq in range(num_qubs)][::-1]
                skip.append(False)
            else:
                skip = None
    metadata = dict({"entanglement_map": "linear"})
    qc.metadata = metadata

    return qc

def compile_circuit(self):
    if self.name_library == "qibo":
        if self.circuit_representation is None:
            self.circuit_representation = models.Circuit(self.size)
        circuit = self._qibo_circuit_(self.circuit_representation)
    elif self.name_library == "qiskit":
        c = QuantumCircuit(self.size)
        circuit = self._qiskit_circuit_(c)
    else:
        raise ("Library not implemented yet")
    self.circuit_representation = circuit

def rotate_x_measure(state, name_library, nqubits =None):
    nqubits_circuit = ceil(log2(len(state)))
    if nqubits is None:
        nqubits = nqubits_circuit

    if name_library == 'qibo':
        from qibo import gates, models
        circuit = models.Circuit(nqubits_circuit)
        circuit.add(gates.H(q) for q in range(nqubits))
        state = circuit.execute(state).state()
    elif name_library == 'qiskit':
        from qiskit import QuantumCircuit
        c = QuantumCircuit(nqubits_circuit)
        for i in range(nqubits):
            c.append(HGate(), [i])
        state = state.evolve(c)

    return state

def build_identity_block_ansatz(n_qubits, n_layers, seed=None):
    n_params = n_qubits * 2 * n_layers
    params = ParameterVector('θ', n_params)
    qc = QuantumCircuit(n_qubits)

    idx = 0
    for layer in range(n_layers):
        for qubit in range(n_qubits):
            qc.ry(params[idx], qubit)
            idx += 1

        for qubit in range(n_qubits - 1):
            qc.cx(qubit, qubit + 1)

        for qubit in range(n_qubits):
            qc.ry(-params[idx], qubit)
            idx += 1

        for qubit in range(n_qubits - 2, -1, -1):
            qc.cx(qubit, qubit + 1)

    return qc, params

def core_unitary_rotation_qiskit(core, body_type, wires):
    """Applies the unitary transformation corresponding to the core tensor using Qiskit."""
    num_qubits = 8
    qc = QuantumCircuit(num_qubits)

    if body_type == "one_body":
        diag_core = np.diag(core)
        for wire, cval in enumerate(diag_core):
            for sigma in [0, 1]:
                qubit = 2 * wire + sigma
                qc.rz(cval, qubit)  
        qc.global_phase += np.sum(core)

    elif body_type == "two_body":
        for odx1, odx2 in it.product(range(len(wires) // 2), repeat=2):
            cval = core[odx1, odx2]
            for sigma, tau in it.product(range(2), repeat=2):
                if odx1 != odx2 or sigma != tau:
                    q0 = 2 * odx1 + sigma
                    q1 = 2 * odx2 + tau
                    qc.rzz(cval / 4.0, q0, q1) 
        gphase = 0.5 * np.sum(core) + 0.25 * np.trace(core)
        qc.global_phase -= gphase


    return qc

def get_circuit(self, input_params):
    qc = QuantumCircuit(self.n_qubits)

    for l in range(self.layers):
        # 1. Input rotation
        for i in range(self.n_qubits):
            param_val = input_params[i % len(input_params)]
            qc.ry(param_val * self.scale, i)

        # 2. Interleaved fixed rotation (if not last layer)
        if l < self.layers - 1:
            for i in range(self.n_qubits):
                qc.rz(self.rotations[l, i], i)

    return qc

def create_qiskit_circuit():
    """Creates the symmetric quantum circuit."""
    num_qubits = 9
    qc = QuantumCircuit(num_qubits)

    # Input parameters for encoding the game board
    x = ParameterVector("x", length=num_qubits)
    # Trainable parameters (weights)
    p = ParameterVector("p", length=9)

    # 1. Encoding Layer
    for i in range(num_qubits):
        qc.rx(x[i], i)

    # 2. Variational Layer (with symmetry)
    qc.rx(p[0], 4); qc.ry(p[1], 4)
    for i in [0, 2, 6, 8]: qc.rx(p[2], i); qc.ry(p[3], i)
    for i in [1, 3, 5, 7]: qc.rx(p[4], i); qc.ry(p[5], i)
    qc.barrier()
    for c, t in [(0, 1), (2, 1), (2, 5), (8, 5), (8, 7), (6, 7), (6, 3), (0, 3)]: qc.cry(p[6], c, t)
    for i in [0, 2, 6, 8]: qc.cry(p[7], 4, i)
    for i in [1, 3, 5, 7]: qc.cry(p[8], i, 4)
    return qc

def ansatze_level(self, energy_level, params_level):
    qc_ansatze_E_level=QuantumCircuit(self.num_q_orbital, name='level_'+str(energy_level))
    for i in range(self.num_q_orbital-energy_level-1):
        inst=self.A(theta=params_level[2*i], phi=params_level[2*i+1]).to_instruction()
        qc_ansatze_E_level.append(inst, [i+energy_level, i+energy_level+1])
    return qc_ansatze_E_level

def QuantumFourierTransform(self):
    qc_QFT=QuantumCircuit(self.num_q_site, name='QFT')

    # Before SWAP
    for i in range(self.num_q_site):        
        qc_QFT.h(i)
        for j in range(self.num_q_site-1-i):
            theta=(2*np.pi)/(2**(j+2))
            qc_QFT.crz(theta=theta , control_qubit=j+1+i , target_qubit=i)
        qc_QFT.barrier()

    # after SWAP
    for i in range(self.num_q_site//2):
        qc_QFT.swap(i, self.num_q_site-1-i)

    return qc_QFT

def build_hea(N: int, n_layers: int, real: bool = False):
    params_per_layer = 2 * N if real else 6 * N
    params = ParameterVector("θ", params_per_layer * n_layers)
    qc = QuantumCircuit(N)

    for layer in range(n_layers):
        offset = params_per_layer * layer

        if real:
            for i in range(N):
                qc.ry(params[offset + i], i)
        else:
            for i in range(N):
                qc.rz(params[offset + i], i)
                qc.rx(params[offset + N + i], i)
                qc.rz(params[offset + 2 * N + i], i)

        qc.barrier()

        for i in range(N):
            qc.cx(i, (i + 1) % N)

        qc.barrier()

        if real:
            for i in range(N):
                qc.ry(params[offset + N + i], i)
        else:
            for i in range(N):
                qc.rz(params[offset + 3 * N + i], i)
                qc.rx(params[offset + 4 * N + i], i)
                qc.rz(params[offset + 5 * N + i], i)

        qc.barrier()

    return qc, params

def circ_convert(seq,m,p):
	'''
	Construct the quantum circuit based on the given sequence of gates and parameters.

	Args:
		seq: Sequence of gates (number of features x m).
		m: Number of layers.
		p: Parameter values of the Z-rotation gates (number of features x m).

	Returns:
		Quantum circuit.
	'''
	Qubits = n_qubit
	Descriptor=np.reshape(list(seq),(Qubits,m))
	Rotation=np.reshape(list(p),(Qubits,m))
	qreg_q = QuantumRegister(Qubits, 'q')
	circuit = QuantumCircuit(qreg_q)
	for i in range(len(Descriptor[0])):
		for j in range(len(Descriptor)):
			descript = Descriptor[j][i].split('_')
			if len(descript)==2:
				desc,ID = descript
				if ID == 'x':
					ID = 1
				ID = int(ID)
				if desc == 'U1':
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'U2':
					circuit.rx(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Rz':
					circuit.rz(Rotation[j][i],qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'H':
					circuit.h(qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'X':
					circuit.cx(qreg_q[j-1], qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Xn':
					circuit.cx(qreg_q[j-2], qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Xm':
					circuit.cx(qreg_q[j-3], qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Z':
					circuit.cz(qreg_q[j-1], qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Zn':
					circuit.cz(qreg_q[j-2], qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Zm':
					circuit.cz(qreg_q[j-3], qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'T':
					circuit.p(np.pi*0.25, qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Rx':
					circuit.rx(Rotation[j][i],qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Rxx':
					circuit.rxx(Rotation[j][i]*PARAM[ID],qreg_q[j-1],qreg_q[j])
				elif desc == 'Ry':
					circuit.ry(Rotation[j][i],qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Ryy':
					circuit.ryy(Rotation[j][i]*PARAM[ID],qreg_q[j-1],qreg_q[j])
				elif desc == 'Rzx':
					circuit.rzx(Rotation[j][i],qreg_q[j-1],qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Rzz':
					circuit.rzz(Rotation[j][i]*PARAM[ID],qreg_q[j-1],qreg_q[j])
				elif desc == 'S':
					circuit.s(qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Sdg':
					circuit.sdg(qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'swap':
					circuit.swap(qreg_q[j-1],qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Sx':
					circuit.sx(qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Sxdg':
					circuit.sxdg(qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'Y':
					circuit.y(qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'ZH':
					circuit.cz(qreg_q[j-1], qreg_q[j])
					circuit.h(qreg_q[j])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j])
				elif desc == 'ZHn':
					circuit.cz(qreg_q[j-1], qreg_q[j])
					circuit.h(qreg_q[j-1])
					circuit.rz(Rotation[j][i]*PARAM[ID],qreg_q[j-1])
	return(circuit)

def generate_from_data(self, data):
    '''Generates the NEQR circuit that encodes the data.

    Args:
        data:
            Integer numerical data with bit-depth nq_data to generate NEQR
            circuits for. The following input options are supported:
                * numpy array of size (2**nq_addr,)
                * list of numpy arrays of size (2**nq_addr,)
                * numpy array of size (2**nq_addr, k)
    '''
    if not isinstance(data, (np.ndarray, list)):
        raise RuntimeError('data should be either numpy array or list of '
                           f'numpy array, got {isinstance(data)}')
    if isinstance(data, list):
        data = np.stack(data, axis=2)
    if isinstance(data, np.ndarray) and data.ndim == 1:
        data = data[..., np.newaxis]
    if data.shape[0] != 2**self.nq_addr:
        raise RuntimeError(
            f'Input data of incorrect shape {data.shape}, expecting '
            f'({2**self.nq_addr}, ...) '
            '[(2**nq_addr, k)]'
        )
    if np.max(data) >= 2**self.nq_data:
        raise RuntimeError(
            f'Input data not properly normalized, expected data in range '
            f'[0, {2**self.nq_data-1}], found {np.max(data)}.'
        )
    circs = []
    for k in range(data.shape[1]):
        circ = QuantumCircuit(self._nq_addr + self._nq_data)
        # add diffusion
        for i in range(self.nq_addr):
            circ.h(i)
        if self.barrier : circ.barrier()
        # add multi-controlled CX gates
        for i, bi in enumerate(data[:, k]):
            # flip zero control bits
            for j in range(self.nq_addr):
                if not get_bit(i, j):
                    circ.x(j)
            ctrl = list(range(0, self.nq_addr))
            for j in range(self.nq_data):
                if get_bit(bi, j):
                    circ.mcx(ctrl, self.nq_addr + j)
            # flip zero control bits back
            for j in range(self.nq_addr):
                if not get_bit(i, j):
                    circ.x(j)
            if self.barrier : circ.barrier()
        if self.reverse_bits:
            circ = circ.reverse_bits()
        if self.measure:
            circ.measure_all()
        if self.statevec:
            circ.save_statevector()
        circs.append(circ)
    return circs

