def sub_cir(self,alpha,beta,subsystem_index,real_part):
    num_qubits = self.subsystem_qubits
    qc = QuantumCircuit(num_qubits + 1)  # Add one ancillary qubit

    # Encode |α⟩ on the subsystem qubits
    for i, bit in enumerate(alpha):
        if bit == 1:
            qc.x(i + 1)

    # Prepare initial state: (|0> + |1>) / sqrt(2) on ancilla
    qc.h(0)
    if not real_part:
        qc.s(0)

    # Apply controlled unitary CU
    for i, (a_bit, b_bit) in enumerate(zip(alpha, beta)):
        if a_bit != b_bit:
            qc.cx(0, i + 1)

    # Apply parameterized gates
    for l in range(self.layer):
        for i in range(num_qubits):
            qc.ry(self.params[subsystem_index][i + l * num_qubits], i + 1)
        for i in range(1, num_qubits):
            qc.cx(i, i + 1)
    for i in range(num_qubits):
            qc.ry(self.params[subsystem_index][i + self.layer * num_qubits], i + 1)

    # Apply Hadamard and phase gates for measurement preparation
    qc.h(0)
    if not real_part:
        qc.s(0)
    return qc

def fold_circuit_global(base: QuantumCircuit, scale_factor: int) -> QuantumCircuit:
    if scale_factor < 1 or scale_factor % 2 != 1:
        raise ValueError("scale_factor must be an odd integer >= 1")

    k = (scale_factor - 1) // 2
    folded = QuantumCircuit(base.num_qubits)
    folded.compose(base, inplace=True)
    for _ in range(k):
        folded.compose(base.inverse(), inplace=True)
        folded.compose(base, inplace=True)
    return folded

def add_register(self, *regs):
    """Add registers."""
    if not regs:
        return

    if any([isinstance(reg, int) for reg in regs]):
        # QuantumCircuit defined without registers
        if len(regs) == 1 and isinstance(regs[0], int):
            # QuantumCircuit with anonymous quantum wires e.g. QuantumCircuit(2)
            regs = (QuantumRegister(regs[0], 'q'),)
        elif len(regs) == 2 and all([isinstance(reg, int) for reg in regs]):
            # QuantumCircuit with anonymous wires e.g. QuantumCircuit(2, 3)
            regs = (QuantumRegister(regs[0], 'q'), ClassicalRegister(regs[1], 'c'))
        else:
            raise CircuitError("QuantumCircuit parameters can be Registers or Integers."
                               " If Integers, up to 2 arguments. QuantumCircuit was called"
                               " with %s." % (regs,))

    for register in regs:
        if register.name in [reg.name for reg in self.qregs + self.cregs]:
            raise CircuitError("register name \"%s\" already exists"
                               % register.name)
        if isinstance(register, QuantumRegister):
            self.qregs.append(register)
        elif isinstance(register, ClassicalRegister):
            self.cregs.append(register)
        else:
            raise CircuitError("expected a register")

def _create_custom_feature_map(self, n_qubits: int, n_features: int, reps: int,
                             gates: List[str] = None, **kwargs) -> QuantumCircuit:
    """Create custom feature map with specified gates."""
    circuit = QuantumCircuit(n_qubits)
    gates = gates or ['ry', 'rz']

    n_params = len(gates) * n_features * reps
    params = ParameterVector('custom_phi', n_params)

    param_idx = 0

    for rep in range(reps):
        for feature in range(min(n_qubits, n_features)):
            for gate in gates:
                if gate.lower() == 'rx':
                    circuit.rx(params[param_idx], feature)
                elif gate.lower() == 'ry':
                    circuit.ry(params[param_idx], feature)
                elif gate.lower() == 'rz':
                    circuit.rz(params[param_idx], feature)
                param_idx += 1

        # Entangling layer
        for qubit in range(n_qubits - 1):
            circuit.cx(qubit, qubit + 1)

    return circuit

