def _Ucp_Z(self, depth, n_dim=None):
    if n_dim is None:
        assert 1<=depth and depth<=self.n_depth
        n_dim = 4 * 2**(self.n_depth-depth)
    else:
        assert 1<=n_dim and n_dim<=self.n_qubits
        depth = None

    qc = QuantumCircuit(n_dim, name='Ucp')
    # convolutional-layer
    for i in range(1, n_dim, 2):
        if i+1<n_dim:
            qc.cx(i, i+1)
        else:
            qc.cx(i, 0) # periodic
    for i in range(0, n_dim, 2):
        if i+2<n_dim:
            qc.ccx(i, i+2, i+1)
        elif i+2==n_dim:
            qc.ccx(i, 0, i+1) # periodic
        elif i+1==n_dim:
            qc.ccx(i, 1, 0) # periodic
    qc.barrier()

    # pooling-layer
    for i in range(0, n_dim, 2):
        if i+1<n_dim:
            qc.cz(i, i+1)
        else:
            qc.cz(i, 0) # periodic

    return qc

def diffuser(nqubits):
    qc = QuantumCircuit(nqubits)
    for qubit in range(nqubits):
        qc.h(qubit)
    for qubit in range(nqubits):
        qc.x(qubit)
    qc.h(nqubits-1)
    qc.mct(list(range(nqubits-1)), nqubits-1)
    qc.h(nqubits-1)
    for qubit in range(nqubits):
        qc.x(qubit)
    for qubit in range(nqubits):
        qc.h(qubit)
    U_s = qc.to_gate()
    U_s.name = "U$_s$"
    return U_s

def const_mod_mult4_inv(C, X, A, B, CARRY, N, T, n, a):

    qc = QuantumCircuit(C, X, A, B, CARRY, N, T, name=f"inv_mod_mult4_{a}x_mod_{n}")

    qc.append(controlled_copy4(C, X, B), C[:] + X[:] + B[:])

    for i, qx in enumerate(X):
        qc.append(double_controlled_exp_prep(a, i), [C] + [qx] + A[:])
        qc.append(
            mod_subtr4(A, B, CARRY, N, T, n), A[:] + B[:] + CARRY[:] + N[:] + T[:]
        )
        qc.append(double_controlled_exp_prep_inv(a, i), [C] + [qx] + A[:])

    return qc

def control_prepare_4(x):
    qc = QuantumCircuit(5, name=f"control_prepare_{x}")
    if x & 1:
        qc.cx(4, 0)
    if x & 2:
        qc.cx(4, 1)
    if x & 4:
        qc.cx(4, 2)
    if x & 8:
        qc.cx(4, 3)
    return qc

def GammaHamiltonianCustom(gamma):
    """Gamma circuit"""
    qc = QuantumCircuit(nodes, nodes)
    for i, j in edges:
        qc.compose(ising_zz(gamma, i, j), inplace=True)
