def create_mux_circuit(i0, i1, s):
    qc = QuantumCircuit(4, 1)
    if i0 == 1: qc.x(0)
    if i1 == 1: qc.x(1)
    if s == 1: qc.x(2)
    qc.barrier()
    qc.x(2); qc.ccx(0, 2, 3); qc.x(2)
    qc.ccx(1, 2, 3)
    qc.barrier()
    qc.measure(3, 0)
    result_str = simulate_circuit(qc)
    return int(result_str, 2), qc

def create_d_flip_flop_circuit(d_in, clock, q_current):
    qc = QuantumCircuit(3, 1)
    if clock == 1: qc.x(0)
    if d_in == 1: qc.x(1)
    if q_current == 1: qc.x(2)
    qc.barrier()
    qc.cswap(0, 1, 2)
    qc.barrier()
    qc.measure(2, 0)
    result_str = simulate_circuit(qc)
    return int(result_str, 2), qc

def sum_inplace_circuit(nbits:int,
                        barrier: bool = False) -> QuantumCircuit:
    ar = QuantumRegister(nbits, 'a')
    br = QuantumRegister(nbits, 'b')
    ancr = QuantumRegister(1, 'anc')
    qc = QuantumCircuit(ancr, br, ar)

    maj = get_maj_gate()
    uma = get_uma_gate()
    a = ar[:]
    b = br[:]
    anc = ancr[:][0]

    for i in range(nbits):
        if i == 0:
            c = anc
        else:
            c = a[i-1]

        qc.append(maj, [c, b[i], a[i]])
        # add_maj(qc, c, b+i, a+i)
        if barrier:
            qc.barrier()
    for i in range(nbits-1, -1, -1):
        if i == 0:
            c = anc
        else:
            c = a[i-1]
        qc.append(uma, [c, b[i], a[i]])
        # add_uma(qc, c, b+i, a+i)
        if barrier:
            qc.barrier()
    return qc

def myqft(n, barrier=False, initv=None):
    qc = QuantumCircuit(n)

    if initv is not None:
        qc.initialize(initv)
        qc.barrier()

    for i in reversed(range(n)):
        qc.h(i)
        for j in reversed(range(i)):
            angle = np.pi / (2**(i-j))
            qc.cp(angle, i, j)
        if barrier:
            qc.barrier()

    for i in range(n//2):
        qc.swap(i, n-i-1)
    return qc

def fake_gate1(nvar_bits: int, ngate_bits: int,
               initial_state: str) -> QuantumCircuit:
    qc = QuantumCircuit(nvar_bits + ngate_bits + 1)
    for i in range(nvar_bits):
        if not int(initial_state[i], 2):
            qc.x(i)
    qc.append(MCXGate(nvar_bits), range(nvar_bits+1))
    for i in range(nvar_bits):
        if not int(initial_state[i], 2):
            qc.x(i)
    return qc

