def fake_gate5(nbits: int,
               solutions: List[str],
               ngate_bits: int = 0,
               barrier: bool = False) -> QuantumCircuit:
    values = QuantumRegister(nbits, 'values')
    res = QuantumRegister(1, 'res')
    if ngate_bits>0:
        gate_bits = QuantumRegister(ngate_bits, 'gate')
        qc = QuantumCircuit(values, res, gate_bits)
    else:
        qc = QuantumCircuit(values, res)

    for pos, sol in enumerate(solutions):
        sol = sol[::-1]
        for i in range(nbits):
            if int(sol[i], 2) == 0:
                qc.x(values[i])
        qc.append(MCXGate(nbits),
                  values[:] + res[:])
        for i in range(nbits):
            if int(sol[i], 2) == 0:
                qc.x(values[i])
        if barrier:
            qc.barrier()
    return qc

def QPE(circuit, nbits_est, vector=None, measure=True):
    qest = QuantumRegister(nbits_est, 'est')
    state = QuantumRegister(circuit.num_qubits, 'st')
    cest = ClassicalRegister(nbits_est, 'cest')
    qpe = QuantumCircuit(qest, state, cest)

    pos_state = nbits_est
    if vector is None:
        qpe.h(state)
    else:
        for i in range(circuit.num_qubits):
            if type(vector) is str:
                if vector[i] == "1":
                    qpe.x(pos_state+i)
                elif vector[i] == "h":
                    qpe.h(pos_state+i)
            elif type(vector) is list:
                qpe.initialize(vector, state[:])

    qpe.h(qest)
    repetitions = 1
    for counting_qubit in qest:
        for i in range(repetitions):
            qpe.append(circuit.control(1, label=' CU '), [counting_qubit]+state[:]);
        repetitions *= 2
    qpe.barrier()
    # Apply inverse QFT
    qpe.append(myqft(nbits_est).to_gate(label='QFT').inverse(), qest)
    #iqft = QFT(nbits_est, inverse=True, do_swaps=False).reverse_bits()
    #qpe.compose(iqft, qest[:], inplace=True)
    #
    # Measure
    qpe.barrier()
    if measure:
        qpe.measure(qest, cest)
    return qpe

def int_to_x(n, i):
    qc = QuantumCircuit(n)
    qc.name = "B"+str(i)
    for j in range(n):
        if (i>>j)&1 == 1:
            qc.x(j)
    return qc

def _qft(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    for j in range(n - 1, -1, -1):
        qc.h(j)
        for k in range(j - 1, -1, -1):
            qc.cp(math.pi / 2 ** (j - k), k, j)
    for i in range(n // 2):
        qc.swap(i, n - 1 - i)
    return qc

def _run(self):
    if self._qc_prefix is None or self._qc_amplitude_amplification_single_iteration is None:
        self._construct_circuit_components()
    if self._incremental:
        current_max_num_iterations, lam = 1, 6 / 5

        def _try_current_max_num_iterations():
            target_num_iterations = np.random.randint(current_max_num_iterations) + 1
            self._qc_amplitude_amplification = QuantumCircuit()
            for _ in range(target_num_iterations):
                self._qc_amplitude_amplification += self._qc_amplitude_amplification_single_iteration
            return self._run_with_num_iterations()

        while current_max_num_iterations < self._max_num_iterations:
            assignment, oracle_evaluation = _try_current_max_num_iterations()
            if oracle_evaluation:
                break
            current_max_num_iterations = min(lam * current_max_num_iterations, self._max_num_iterations)
        else:
            # after max is reached, try one more round
            assignment, oracle_evaluation = _try_current_max_num_iterations()
    else:
        self._qc_amplitude_amplification = QuantumCircuit()
        for i in range(self._num_iterations):
            self._qc_amplitude_amplification += self._qc_amplitude_amplification_single_iteration
        assignment, oracle_evaluation = self._run_with_num_iterations()

    self._ret['result'] = assignment
    self._ret['oracle_evaluation'] = oracle_evaluation
    return self._ret

def Random_unitary(random_theta, nqubit):
    qc_U = QuantumCircuit(nqubit)
    for i in range(nqubit):
        qc_U.u(random_theta[i], 0, 0, i)

    return qc_U

def param_circuit_unit(nqubits, entanglement, params):
    qc = QuantumCircuit(nqubits)

    for n in range(nqubits):
        qc.ry(params[n], n)
        qc.rz(params[n+nqubits], n)
    qc.barrier()

    if entanglement == 'linear':
        for n in range(nqubits-1):
            qc.cx(n, n+1)
    elif entanglement == 'circular':
        for n in range(nqubits-1):
            qc.cx(n, n+1)
        qc.cx(nqubits-1, 0)
    elif entanglement == 'full':
        for n in range(1, nqubits):
            for j in range(nqubits-n):
                qc.cx(j, j+n)
    qc.barrier()

    return qc

def RealAmplitudes_circuit_unit(nqubits, entanglement, params):
