def create_qaoa_circ(nqubits, edges, parameters):

    qc = QuantumCircuit(nqubits)

    # initial_state
    for i in range(0, nqubits):
        qc.h(i)

    for par in parameters:
        #print(f"... gamma, beta = {par.gamma} {par.beta}")

        # problem unitary
        for i,j in edges:
            qc.rzz(- par.gamma, i, j)

        qc.barrier()

        # mixer unitary
        for i in range(0, nqubits):
            qc.rx(2 * par.beta, i)

    return qc

def create_qaoa_circ_param(nqubits, edges, betas, gammas):

    qc = QuantumCircuit(nqubits)

    # initial_state
    for i in range(0, nqubits):
        qc.h(i)

    for beta, gamma in zip(betas, gammas):
        #print(f"... gamma, beta = {gammas}, {betas}")

        # problem unitary
        for i,j in edges:
            qc.rzz(- gamma, i, j)

        qc.barrier()

        # mixer unitary
        for i in range(0, nqubits):
            qc.rx(2 * beta, i)

    return qc

def qft(n):
  ar = QuantumRegister(n,'a')
  qc = QuantumCircuit(ar)
  for hbit in range(n-1,-1,-1):
    qc.h(hbit) 
    for cbit in range(hbit):
      qc.cp(pi/2**(hbit-cbit), cbit, hbit)  
  for bit in range(n//2):
    qc.swap(bit,n-bit-1)  
  return qc

