def entangling_layer(self, x, z, start=0):
    qc = QuantumCircuit(self.num_qubits)
    for n in range(start, self.num_qubits + start, 2):
        i = n % self.num_qubits
        j = (n + 1) % self.num_qubits
        qc.cz(i, j)

    for n in range(self.num_qubits):
        qc.rx(x[n], n)
        qc.rz(z[n], n)

    return qc

