def _build_qft(prompt: str) -> str:
    """根据提示推断量子比特数量并生成 QFT 示例实现。"""

    qubits = _normalize_qubit_count(prompt, default=3)

    return dedent(
        f"""
        import math
        from typing import Iterable

        from qiskit import QuantumCircuit


        def build_qft_circuit(num_qubits: int = {qubits}) -> QuantumCircuit:
            \"\"\"Construct a Quantum Fourier Transform circuit.\"\"\"

            if num_qubits <= 0:
                raise ValueError("QFT requires at least one qubit")

            circuit = QuantumCircuit(num_qubits, name="qft")
            for target in range(num_qubits):
                circuit.h(target)
                for control in range(target + 1, num_qubits):
                    angle = math.tau / (2 ** (control - target + 1))
                    circuit.cp(angle, control, target)
            circuit.reverse_bits()
            return circuit
        """
    ).strip()

def _build_variational(prompt: str) -> str:
    """构建基于硬件高效的变分量子线路骨架。"""

    layers = max(1, _normalize_qubit_count(prompt, default=2))

    return dedent(
        f"""
        import math
        from typing import Sequence

        from qiskit import QuantumCircuit


        def build_hardware_efficient_ansatz(num_qubits: int = 4, layers: int = {layers}) -> QuantumCircuit:
            \"\"\"Return a hardware-efficient ansatz useful for VQE-style workloads.\"\"\"

            if num_qubits <= 0:
                raise ValueError("Ansatz requires at least one qubit")
            if layers <= 0:
                raise ValueError("At least one layer of rotations is required")

            circuit = QuantumCircuit(num_qubits, name="hea")
            for layer in range(layers):
                for qubit in range(num_qubits):
                    circuit.ry(math.pi / 2, qubit)
                    circuit.rz(math.pi / 2, qubit)
                for qubit in range(num_qubits - 1):
                    circuit.cx(qubit, qubit + 1)
            return circuit
        """
    ).strip()

def _build_phase_estimation(prompt: str) -> str:
    """Generate a quantum phase estimation example circuit."""

    counting_qubits = _normalize_qubit_count(prompt, default=3)

    return dedent(
        f"""
        import math
        from typing import Callable, Optional

        from qiskit import QuantumCircuit


        def _inverse_qft(num_qubits: int) -> QuantumCircuit:
            iqft = QuantumCircuit(num_qubits, name="IQFT")
            for qubit in range(num_qubits // 2):
                iqft.swap(qubit, num_qubits - qubit - 1)
            for target in range(num_qubits - 1, -1, -1):
                iqft.h(target)
                for control in range(target - 1, -1, -1):
                    iqft.cp(-math.pi / (2 ** (target - control)), control, target)
            return iqft


        def build_phase_estimation_circuit(
            counting_qubits: int = {counting_qubits},
            unitary_factory: Optional[Callable[[int], QuantumCircuit]] = None,
        ) -> QuantumCircuit:
            \"\"\"Construct a simple phase estimation circuit.\"\"\"

            if counting_qubits <= 0:
                raise ValueError("Phase estimation requires at least one counting qubit")

            if unitary_factory is None:
                def unitary_factory(num_qubits: int) -> QuantumCircuit:
                    unitary = QuantumCircuit(num_qubits, name="U")
                    unitary.p(math.pi / 4, 0)
                    return unitary

            target_qubits = 1
            circuit = QuantumCircuit(counting_qubits + target_qubits, counting_qubits)
            circuit.h(range(counting_qubits))
            circuit.x(counting_qubits)

            unitary = unitary_factory(target_qubits).to_gate()
            for index in range(counting_qubits):
                controlled_gate = unitary.power(2 ** index).control(1)
                circuit.append(controlled_gate, [index, counting_qubits])

            circuit.append(_inverse_qft(counting_qubits).to_instruction(), range(counting_qubits))
            circuit.measure(range(counting_qubits), range(counting_qubits))
            return circuit
        """
    ).strip()

def _build_bernstein_vazirani(prompt: str) -> str:
    """Generate the Bernstein-Vazirani algorithm template."""

    secret = "1011"
    match = _BINARY_PATTERN.search(prompt)
    if match:
        secret = match.group(1)

    return dedent(
        f"""
        from qiskit import QuantumCircuit


        def build_bernstein_vazirani_circuit(secret_string: str = "{secret}") -> QuantumCircuit:
            \"\"\"Construct a Bernstein-Vazirani oracle circuit.\"\"\"

            if not secret_string or any(bit not in "01" for bit in secret_string):
                raise ValueError("Secret string must be binary")

            n = len(secret_string)
            circuit = QuantumCircuit(n + 1, n)
            circuit.h(range(n))
            circuit.x(n)
            circuit.h(n)

            for index, bit in enumerate(secret_string):
                if bit == "1":
                    circuit.cx(index, n)

            circuit.h(range(n))
            circuit.measure(range(n), range(n))
            return circuit
        """
    ).strip()

