def analytic_gradient(circuit, parameter=None):
    """Return the analytic gradient of the input circuit."""

    if parameter is not None:
        if parameter not in circuit.parameters:
            raise ValueError('Parameter not in this circuit.')

        if len(circuit._parameter_table[parameter]) > 1:
            raise NotImplementedError('No product rule support yet, params must be unique.')

    summands, op_context = [], []
    for i, op in enumerate(circuit.data):
        gate = op[0]
        op_context += [op[1:]]
        if (parameter is None and len(gate.params) > 0) or parameter in gate.params:
            summands += [gradient_lookup(gate)]
        else:
            summands += [[[1, gate]]]

    gradient = []
    for product_rule_term in itertools.product(*summands):
        summand_circuit = QuantumCircuit(*circuit.qregs)
        coeff = 1
        for i, a in enumerate(product_rule_term):
            coeff *= a[0]
            summand_circuit.data.append([a[1], *op_context[i]])
        gradient += [[coeff, summand_circuit.copy()]]

    return gradient

def _create_parameterized_rotation(self, num_qubits: int = 2, 
                                 rotation_angles: List[float] = None) -> QuantumCircuit:
    """Create a parameterized rotation circuit."""
    if rotation_angles is None:
        rotation_angles = [np.pi/4] * num_qubits

    if len(rotation_angles) != num_qubits:
        raise ValueError("Number of rotation angles must match number of qubits")

    circuit = QuantumCircuit(num_qubits, num_qubits)

    # Apply rotations
    for i, angle in enumerate(rotation_angles):
        circuit.ry(angle, i)
        circuit.rz(angle/2, i)

    # Add entangling gates
    for i in range(num_qubits - 1):
        circuit.cx(i, i + 1)

    # Measurements
    for i in range(num_qubits):
        circuit.measure(i, i)

    return circuit

def _create_multi_qubit_entangler(self, num_qubits: int = 4, 
                                entangling_pattern: str = "linear") -> QuantumCircuit:
    """Create a multi-qubit entangling circuit."""
    circuit = QuantumCircuit(num_qubits, num_qubits)

    # Initialize in superposition
    for i in range(num_qubits):
        circuit.h(i)

    # Apply entangling pattern
    if entangling_pattern == "linear":
        for i in range(num_qubits - 1):
            circuit.cx(i, i + 1)
    elif entangling_pattern == "circular":
        for i in range(num_qubits):
            circuit.cx(i, (i + 1) % num_qubits)
    elif entangling_pattern == "all_to_all":
        for i in range(num_qubits):
            for j in range(i + 1, num_qubits):
                circuit.cx(i, j)
    else:
        raise ValueError(f"Unknown entangling pattern: {entangling_pattern}")

    # Measurements
    for i in range(num_qubits):
        circuit.measure(i, i)

    return circuit

def qasm(self):
    """Print the qasm code of quantum circuit.

    Returns:
        qasm_string (str):
            A string of qasm code of quantum circuit.

    Example:
        >>> import renom_q
        >>> q = renom_q.QuantumRegister(1)
        >>> c = renom_q.ClassicalRegister(1)
        >>> qc = renom_q.QuantumCircuit(q, c, set_qasm=True)
        >>> qc.x(q[0])
        >>> qc.measure()
        >>> print(qc.qasm())
        OPENQASM 2.0;
        include "qelib1.inc";
        qreg q[1];
        creg c[1];
        x q[0];
        measure q[0] -> c[0];
    """
    qasm_string = 'OPENQASM 2.0;\ninclude "qelib1.inc";\n'
    for i in self.qasmlist:
        qasm_string += str(i)+'\n'
    return qasm_string

