def _calc_grad_A(self, params, dparams, *, is_shift=False):

    qc = QuantumCircuit(self.qreg, self.qreg_ancilla)
    qc = self.state_preparation(qc, zero_state='grad_ansatz', one_state='ansatz', params=params, dparams=dparams)

    if is_shift:
        qc = self.shift_add(qc)

    qc.h(self.qreg_ancilla)
    qc.h(self.qreg[0])
    if self.qinstance.is_statevector:
        sv = self.qinstance.execute(qc).get_statevector(qc)
        val = 0
        for l in range(len(sv)):
            bits = bin(l)[2:].zfill(qc.num_qubits)
            if bits[self.num_mct_ancilla] == '0' and bits[-1] == '0':
                val += np.real(sv[l]*sv[l].conjugate())
            elif bits[self.num_mct_ancilla] == '1' and bits[-1] == '0':
                val -= np.real(sv[l]*sv[l].conjugate())
            elif bits[self.num_mct_ancilla] == '0' and bits[-1] == '1':
                val -= np.real(sv[l]*sv[l].conjugate())
            elif bits[self.num_mct_ancilla] == '1' and bits[-1] == '1':
                val += np.real(sv[l]*sv[l].conjugate())
    else:
        creg = ClassicalRegister(2, 'c')
        qc.add_register(creg)
        qc.measure(self.qreg_ancilla, creg[1])
        qc.measure(self.qreg[0], creg[0])
        counts = self.qinstance.execute(qc).get_counts()

        for key in ['00', '01', '10', '11']:
            if not key in counts.keys():
                counts[key] = 0

        val = (counts['00'] - counts['01'] - counts['10'] + counts['11']) / float(self.qinstance.run_config.shots)

    self.circuit_counts += 1

    return val

def _calc_grad_for_bc(self, params, dparams, *, is_identity=False):

    qc = QuantumCircuit(self.qreg, self.qreg_ancilla)
    qc = self.state_preparation(qc, zero_state='grad_ansatz', one_state='ansatz', params=params, dparams=dparams)
    qc = self.shift_add(qc)

    qc.h(self.qreg_ancilla)
    if not is_identity:
        qc.h(self.qreg[0])

    if self.qinstance.is_statevector:
        sv = self.qinstance.execute(qc).get_statevector(qc)
        val = 0
        for l in range(len(sv)):
            bits = bin(l)[2:].zfill(qc.num_qubits)
            if is_identity:
                if bits[self.num_mct_ancilla] == '0' and not np.array([int(bits[i]) for i in range(self.num_mct_ancilla+1, len(bits)-1)]).any():
                    val += np.real(sv[l]*sv[l].conjugate())
                elif bits[self.num_mct_ancilla] == '1' and not np.array([int(bits[i]) for i in range(self.num_mct_ancilla+1, len(bits)-1)]).any():
                    val -= np.real(sv[l]*sv[l].conjugate())
            else:
                if not np.array([int(bits[i]) for i in range(self.num_mct_ancilla+1, len(bits)-1)]).any():
                    if bits[self.num_mct_ancilla] == '0' and bits[-1] == '0':
                        val += np.real(sv[l]*sv[l].conjugate())
                    elif bits[self.num_mct_ancilla] == '0' and bits[-1] == '1':
                        val -= np.real(sv[l]*sv[l].conjugate())
                    elif bits[self.num_mct_ancilla] == '1' and bits[-1] == '0':
                        val -= np.real(sv[l]*sv[l].conjugate())
                    elif bits[self.num_mct_ancilla] == '1' and bits[-1] == '1':
                        val += np.real(sv[l]*sv[l].conjugate())
    else:
        creg = ClassicalRegister(self.num_qubits+1, 'c')
        qc.add_register(creg)
        qc.measure(self.qreg_ancilla, creg[-1])
        qc.measure(self.qreg, creg[:-1])
        counts = self.qinstance.execute(qc).get_counts()

        for key in ['0'+'0'*(self.num_qubits-1)+'0', '0'+'0'*(self.num_qubits-1)+'1', '1'+'0'*(self.num_qubits-1)+'0', '1'+'0'*(self.num_qubits-1)+'1']:
            if key not in counts.keys():
                counts[key] = 0

        if is_identity:
            val = (counts['0'+'0'*(self.num_qubits-1)+'0'] + counts['0'+'0'*(self.num_qubits-1)+'1'] - counts['1'+'0'*(self.num_qubits-1)+'0'] - counts['1'+'0'*(self.num_qubits-1)+'1']) / float(self.qinstance.run_config.shots)
        else:
            val = (counts['0'+'0'*(self.num_qubits-1)+'0'] - counts['0'+'0'*(self.num_qubits-1)+'1'] - counts['1'+'0'*(self.num_qubits-1)+'0'] + counts['1'+'0'*(self.num_qubits-1)+'1']) / float(self.qinstance.run_config.shots)

    self.circuit_counts += 1

    return val

def get_statevec(self, x):

    qc = QuantumCircuit(self.qreg)
    qc = self.ansatz(qc, x)

    return execute(qc, Aer.get_backend('statevector_simulator')).result().get_statevector()

def _make_syndrome_graph(self):
    """
    This method injects all possible Pauli errors into the circuit for
    ``code``.

    This is done by examining the qubits used in each gate of the
    circuit for a stored logical 0. A graph is then created with a node
    for each non-trivial syndrome element, and an edge between all such
    elements that can be created by the same error.
    """

    S = nx.Graph()

    qc = self.code.circuit['0']

    blank_qc = QuantumCircuit()
    for qreg in qc.qregs:
        blank_qc.add_register(qreg)
    for creg in qc.cregs:
        blank_qc.add_register(creg)

    error_circuit = {}
    circuit_name = {}
    depth = len(qc)
    for j in range(depth):
        qubits = qc.data[j][1]
        for qubit in qubits:
            for error in ['x', 'y', 'z']:
                temp_qc = copy.deepcopy(blank_qc)
                temp_qc.name = str((j, qubit, error))
                temp_qc.data = qc.data[0:j]
                getattr(temp_qc, error)(qubit)
                temp_qc.data += qc.data[j:depth + 1]
                circuit_name[(j, qubit, error)] = temp_qc.name
                error_circuit[temp_qc.name] = temp_qc

    if HAS_AER:
        simulator = Aer.get_backend('qasm_simulator')
    else:
        simulator = BasicAer.get_backend('qasm_simulator')

    job = execute(list(error_circuit.values()), simulator)

    for j in range(depth):
        qubits = qc.data[j][1]
        for qubit in qubits:
            for error in ['x', 'y', 'z']:

                raw_results = {}
                raw_results['0'] = job.result().get_counts(
                    str((j, qubit, error)))
                results = self.code.process_results(raw_results)['0']

                for string in results:

                    nodes = self._string2nodes(string)

                    assert len(nodes) in [0, 2], "Error of type " + \
                        error + " on qubit " + str(qubit) + \
                        " at depth " + str(j) + " creates " + \
                        str(len(nodes)) + \
                        " nodes in syndrome graph, instead of 2."

                    for node in nodes:
                        S.add_node(node)
                    for source in nodes:
                        for target in nodes:
                            if source != target:
                                S.add_edge(source, target, distance=1)

    return S

def _resynth_2q_window_7(circ: QuantumCircuit, window: int = 7) -> Tuple[QuantumCircuit, RewriteResult]:
    ops = _flatten_ops(circ)
    n = len(ops)
    max_len = max(2, int(window))

    from qiskit.circuit.library import CXGate, CZGate, CYGate, SwapGate
    from qiskit.circuit.library import ECRGate, iSwapGate, RXXGate, RYYGate, RZZGate
    from qiskit.quantum_info import Operator

    base_gates = [
        ("cx", CXGate()),
        ("cz", CZGate()),
        ("cy", CYGate()),
        ("swap", SwapGate()),
        ("iswap", iSwapGate()),
        ("ecr", ECRGate()),
        ("rxx_pi_2", RXXGate(math.pi / 2.0)),
        ("ryy_pi_2", RYYGate(math.pi / 2.0)),
        ("rzz_pi_2", RZZGate(math.pi / 2.0)),
    ]

    candidate_ops: List[Tuple[str, List[Instruction]]] = [("identity", [])]
    for name, gate in base_gates:
        candidate_ops.append((name, [gate]))
    max_candidates = 2500

    def _should_prune(names: List[str]) -> bool:
        # Skip long runs of the same gate to limit search.
        run = 1
        for i in range(1, len(names)):
            if names[i] == names[i - 1]:
                run += 1
                if run >= 3:
                    return True
            else:
                run = 1
        return False

    for n1, g1 in base_gates:
        for n2, g2 in base_gates:
            if _should_prune([n1, n2]):
                continue
            candidate_ops.append((f"{n1}_{n2}", [g1, g2]))
            if len(candidate_ops) >= max_candidates:
                break
        if len(candidate_ops) >= max_candidates:
            break

    for n1, g1 in base_gates:
        if len(candidate_ops) >= max_candidates:
            break
        for n2, g2 in base_gates:
            if len(candidate_ops) >= max_candidates:
                break
            for n3, g3 in base_gates:
                if _should_prune([n1, n2, n3]):
                    continue
                candidate_ops.append((f"{n1}_{n2}_{n3}", [g1, g2, g3]))
                if len(candidate_ops) >= max_candidates:
                    break

    for n1, g1 in base_gates:
        if len(candidate_ops) >= max_candidates:
            break
        for n2, g2 in base_gates:
            if len(candidate_ops) >= max_candidates:
                break
            for n3, g3 in base_gates:
                if len(candidate_ops) >= max_candidates:
                    break
                for n4, g4 in base_gates:
                    if _should_prune([n1, n2, n3, n4]):
                        continue
                    candidate_ops.append((f"{n1}_{n2}_{n3}_{n4}", [g1, g2, g3, g4]))
                    if len(candidate_ops) >= max_candidates:
                        break

    for n1, g1 in base_gates:
        if len(candidate_ops) >= max_candidates:
            break
        for n2, g2 in base_gates:
            if len(candidate_ops) >= max_candidates:
                break
            for n3, g3 in base_gates:
                if len(candidate_ops) >= max_candidates:
                    break
                for n4, g4 in base_gates:
                    if len(candidate_ops) >= max_candidates:
                        break
                    for n5, g5 in base_gates:
                        if _should_prune([n1, n2, n3, n4, n5]):
                            continue
                        candidate_ops.append((f"{n1}_{n2}_{n3}_{n4}_{n5}", [g1, g2, g3, g4, g5]))
                        if len(candidate_ops) >= max_candidates:
                            break

    for i in range(n):
        for j in range(i + 1, min(n, i + max_len)):
            window_ops = ops[i : j + 1]
            qubits: List[Qubit] = []
            for op in window_ops:
                for q in op.qargs:
                    if q not in qubits:
                        qubits.append(q)
                if len(qubits) > 2:
                    break
            if len(qubits) == 0 or len(qubits) > 2:
                continue

            sub = QuantumCircuit(2)
            qmap = {qubits[0]: 0}
            if len(qubits) == 2:
                qmap[qubits[1]] = 1
            for op in window_ops:
                if op.name in ("measure", "barrier"):
                    break
                sub.append(op.inst, [qmap[q] for q in op.qargs], [])
            else:
                U = Operator(sub).data
                best = None
                for name, gates in candidate_ops:
                    cand = QuantumCircuit(2)
                    if name != "identity":
                        for gate in gates:
                            if gate.num_qubits == 2:
                                cand.append(gate, [0, 1])
                            else:
                                cand.append(gate, [0])
                    V = Operator(cand).data
                    if _equal_up_to_global_phase(U, V):
                        best = (name, gates)
                        break

                if best is None:
                    continue
                name, gates = best
                if len(gates) >= len(window_ops):
                    continue

                if name == "identity":
                    new_ops = ops[:i] + ops[j + 1 :]
                else:
                    replacement: List[Op] = []
                    valid_replacement = True
                    for inst in gates:
                        if inst.num_qubits < 1 or inst.num_qubits > len(qubits):
                            valid_replacement = False
                            break
                        replacement.append(
                            Op(
                                inst=inst,
                                qargs=tuple(qubits[: inst.num_qubits]),
                                cargs=(),
                            )
                        )
                    if not valid_replacement:
                        continue
                    new_ops = ops[:i] + replacement + ops[j + 1 :]

                new_circ = _rebuild_from_ops(circ, new_ops)
                res = RewriteResult(
                    changed=True,
                    action_id=ACTION_RESYNTH_2Q_WINDOW_7,
                    action_name="resynth_2q_window_7",
                    message=f"Resynthesized 2Q window {i}-{j} to {name}.",
                    old_len=n,
                    new_len=len(new_ops),
                    window=(i, j),
                )
                return new_circ, res

    res = RewriteResult(
        changed=False,
        action_id=ACTION_RESYNTH_2Q_WINDOW_7,
        action_name="resynth_2q_window_7",
        message="No resynthesizable 2Q window found.",
        old_len=n,
        new_len=n,
        window=None,
    )
    return circ.copy(), res

def _depth_aware_multi_swap(circ: QuantumCircuit, window: int = 15, max_swaps: int = 3) -> Tuple[QuantumCircuit, RewriteResult]:
    ops = _flatten_ops(circ)
    n = len(ops)
    max_len = max(2, int(window))

    def _local_depth(seq: Sequence[Op]) -> int:
        sub = QuantumCircuit(*circ.qregs, *circ.cregs)
        for op in seq:
            sub.append(op.inst, op.qargs, op.cargs)
        try:
            return int(sub.depth())
        except Exception:
            return 0

    best = None
    for start in range(0, n):
        end = min(n, start + max_len)
        window_ops = ops[start:end]
        if len(window_ops) < 2:
            continue
        base_depth = _local_depth(window_ops)
        swaps_made = []
        candidate = window_ops.copy()
        for _ in range(max_swaps):
            improved = False
            for i in range(len(candidate) - 1):
                if not _commute(candidate[i], candidate[i + 1]):
                    continue
                trial = candidate.copy()
                trial[i], trial[i + 1] = trial[i + 1], trial[i]
                if _local_depth(trial) < _local_depth(candidate):
                    candidate = trial
                    swaps_made.append((start + i, start + i + 1))
                    improved = True
                    break
            if not improved:
                break
        new_depth = _local_depth(candidate)
        if new_depth < base_depth and swaps_made:
            improvement = base_depth - new_depth
            if best is None or improvement > best[0]:
                best = (improvement, start, end, swaps_made, base_depth, new_depth)

    if best is not None:
        _, start, end, swaps_made, before, after = best
        new_ops = ops.copy()
        for i, j in swaps_made:
            new_ops[i], new_ops[j] = new_ops[j], new_ops[i]
        new_circ = _rebuild_from_ops(circ, new_ops)
        res = RewriteResult(
            changed=True,
            action_id=ACTION_DEPTH_AWARE_MULTI_SWAP,
            action_name="depth_aware_multi_swap",
            message=f"Applied {len(swaps_made)} commuting swaps to reduce depth {before}->{after}.",
            old_len=n,
            new_len=n,
            window=(start, end - 1),
        )
        return new_circ, res

    res = RewriteResult(
        changed=False,
        action_id=ACTION_DEPTH_AWARE_MULTI_SWAP,
        action_name="depth_aware_multi_swap",
        message="No multi-swap sequence reduced depth.",
        old_len=n,
        new_len=n,
        window=None,
    )
    return circ.copy(), res

def _fuse_multi_q_unitary(circ: QuantumCircuit, max_qubits: int = 3, max_ops: int = 5) -> Tuple[QuantumCircuit, RewriteResult]:
    ops = _flatten_ops(circ)
    n = len(ops)

    from qiskit.quantum_info import Operator
    from qiskit.circuit.library import UnitaryGate

    for i in range(n):
        for j in range(i + 1, min(n, i + max_ops)):
            window_ops = ops[i : j + 1]
            qubits: List[Qubit] = []
            for op in window_ops:
                for q in op.qargs:
                    if q not in qubits:
                        qubits.append(q)
                if len(qubits) > max_qubits:
                    break
            if len(qubits) < 2 or len(qubits) > max_qubits:
                continue
            if len(window_ops) <= 1:
                continue

            sub = QuantumCircuit(len(qubits))
            qmap = {q: idx for idx, q in enumerate(qubits)}
            for op in window_ops:
                if op.name in ("measure", "barrier"):
                    break
                sub.append(op.inst, [qmap[q] for q in op.qargs], [])
            else:
                U = Operator(sub).data
                gate = UnitaryGate(U)
                if 1 >= len(window_ops):
                    continue
                new_ops = ops[:i] + [Op(inst=gate, qargs=tuple(qubits), cargs=())] + ops[j + 1 :]
                new_circ = _rebuild_from_ops(circ, new_ops)
                res = RewriteResult(
                    changed=True,
                    action_id=ACTION_FUSE_MULTI_Q_UNITARY,
                    action_name="fuse_multi_q_unitary",
                    message=f"Fused {len(window_ops)}-op window {i}-{j} into {len(qubits)}Q unitary.",
                    old_len=n,
                    new_len=len(new_ops),
                    window=(i, j),
                )
                return new_circ, res

    res = RewriteResult(
        changed=False,
        action_id=ACTION_FUSE_MULTI_Q_UNITARY,
        action_name="fuse_multi_q_unitary",
        message="No multi-qubit window found to fuse.",
        old_len=n,
        new_len=n,
        window=None,
    )
    return circ.copy(), res

def _create_circuit(self) -> QuantumCircuit:
    """Crea un circuito cuántico para la carta en estado base."""
    qr = QuantumRegister(6, f'card_{self.card_id}')
    cr = ClassicalRegister(6, f'c_{self.card_id}')
    circuit = QuantumCircuit(qr, cr)

    palo_bits = self.PALO_CODE[self.palo]
    valor_bits = self.VALOR_CODE[self.valor]

    # q0-q1: palo
    for i, bit in enumerate(palo_bits):
        if bit == '1':
            circuit.x(qr[i])

    # q2-q5: valor
    for i, bit in enumerate(valor_bits):
        if bit == '1':
            circuit.x(qr[i + 2])

    return circuit

def get_output_state(qc, method, init_state):
    qc = qc.copy()

    if init_state is not None:
        init = QuantumCircuit(qc.num_qubits)
        if isinstance(init_state, Statevector):
            init.set_statevector(init_state)
        elif isinstance(init_state, DensityMatrix):
            init.set_density_matrix(init_state)
        else:
            raise TypeError("init_state must be Statevector or DensityMatrix.")
        qc = init.compose(qc, inplace=False)

    if method == "statevector":
        qc.save_statevector()
    elif method == "density_matrix":
        qc.save_density_matrix()
    else:
        raise ValueError("method must be 'statevector' or 'density_matrix'")

    sim = AerSimulator(method=method)
    res = sim.run(qc).result()

    if method == "statevector":
        return Statevector(res.data(0)["statevector"])
    return DensityMatrix(res.data(0)["density_matrix"])

def test_from_qasm_str_custom_gate2(self):
    """Test load custom gates (no so simple case, different bit order)
    See: https://github.com/Qiskit/qiskit-terra/pull/3393#issuecomment-551307250
    """
    qasm_string = """OPENQASM 2.0;
                     include "qelib1.inc";
                     gate swap2 a,b {
                       cx a,b;
                       cx b,a;  // different bit order
                       cx a,b;
                     }
                     qreg qr[3];
                     swap2 qr[0], qr[1];
                     swap2 qr[1], qr[2];"""
    circuit = from_qasm_str(qasm_string)

    ab_args = QuantumRegister(2, name="ab")
    swap_gate = QuantumCircuit(ab_args, name="swap2")
    swap_gate.cx(ab_args[0], ab_args[1])
    swap_gate.cx(ab_args[1], ab_args[0])
    swap_gate.cx(ab_args[0], ab_args[1])
    swap = swap_gate.to_instruction()

    qr = QuantumRegister(3, name="qr")
    expected = QuantumCircuit(qr, name="circuit")
    expected.append(swap, [qr[0], qr[1]])
    expected.append(swap, [qr[1], qr[2]])

    self.assertEqualUnroll(["cx"], expected, circuit)

