def consolidate(self):
    gates = []

    curr_gate = qiskit.QuantumCircuit(self.gate_size)
    curr_idcs = []
    curr_idcs_inv = {}

    # Consolidate the gate described by (U, idcs) into curr_gate
    def add_to_gate(U, idcs):
        for idx in idcs:
            if idx not in curr_idcs:
                curr_idcs_inv[idx] = len(curr_idcs)
                curr_idcs.append(idx)
        assert len(curr_idcs) <= self.gate_size
        curr_gate.append(UnitaryGate(U), [curr_idcs_inv[i] for i in idcs])

    # Add curr_gate to the output list of gates, and reset it back to identity
    def flush_gate():
        nonlocal curr_idcs, curr_idcs_inv, curr_gate

        # Add qubits until the curr_gate size reaches self.gate_size
        for i in range(self.n):
            if len(curr_idcs) == self.gate_size:
                break
            if i in curr_idcs:
                continue
            curr_idcs.append(i)
        assert len(curr_idcs) == self.gate_size

        # Convert curr_gate (a qiskit circuit) to a unitary matrix
        gates.append((Operator(curr_gate).data, curr_idcs))

        curr_gate = qiskit.QuantumCircuit(self.gate_size)
        curr_idcs = []
        curr_idcs_inv = {}

    for U, idcs in self.gates:
        can_consolidate = len(set(idcs) - set(curr_idcs)) <= self.gate_size - len(curr_idcs)
        if not can_consolidate:
            flush_gate()
        add_to_gate(U, idcs)

    flush_gate()

    self.gates = gates

def create_oracle(num_qubits: int, input_size: int, hidden_bits: List[int]):

    # Initialize first n qubits and single ancilla qubit
    qr = QuantumRegister(num_qubits)
    qc = QuantumCircuit(qr, name="Uf")

    # perform CX for each qubit that matches a bit in secret integer's bits
    for i_qubit in range(input_size):
        if hidden_bits[i_qubit] == 1:
            qc.cx(qr[i_qubit], qr[input_size])
    return qc

def brmWithModifications(nodes, edges, probsNodes, probsEdges, probsNodesModified, probsEdgesModified, model2gate=False):
    """input:
         Risk item list e.g.  nodes = ['0','1']
         Correlation risk e.g. edges=[('0','1')] # correlations
         probsNodes={'0':0.1,'1':0.1} # intrinsic probs
         probsEdges={('0','1'):0.2} # transition probs
         probsNodesModified={'0':0.1,'1':0.1} # intrinsic probs
         probsEdgesModified={('0','1'):0.3} # transition probs
         output: Either circuit (model2gate=False) or gate (model2gate=True) and the
                 matrix with the probabilities of the nodes and the edges. Also, return
                 dictionaries along with the number of tuning qubits that determine which
                 modification of nodes and edges should be turned on.
    """

    # Consider the variations and the necessary qubits to encode them.
    nodeMapping, edgeMapping, necessaryBits = variationsDictionary(nodes, edges, probsNodes, probsEdges, probsNodesModified, probsEdgesModified)

    qt=QuantumRegister(necessaryBits,'t') # tuning parameters
    qr=QuantumRegister(len(nodes),'q')
    qc=QuantumCircuit(qt,qr)

    # Turn probabilities for nodes and edges into matrix form. Unmodified version.
    mat=np.zeros((len(nodes),len(nodes)))
    for i in range(len(nodes)):
        mat[i][i]=probsNodes[nodes[i]]
    for i in range(len(nodes)):
        for j in range(len(nodes)):
            if (nodes[i],nodes[j]) in probsEdges:
                mat[i][j]=probsEdges[(nodes[i],nodes[j])]

    # Turn probabilities for nodes and edges into matrix form. Modified version.
    mat2=np.zeros((len(nodes),len(nodes)))
    for i in range(len(nodes)):
        mat2[i][i]=probsNodesModified[nodes[i]]
    for i in range(len(nodes)):
        for j in range(len(nodes)):
            if (nodes[i],nodes[j]) in probsEdgesModified:
                mat2[i][j]=probsEdgesModified[(nodes[i],nodes[j])]

    # Main processing loop.
    indicesProcessed=[]
    while len(indicesProcessed)<len(nodes):
        # Find the first unprocessed node that has no unprocessed parents.
        target=None
        for i in range(len(nodes)):
            allParentsAlreadyProcessed=True
            for j in range(len(nodes)):
                if not(i==j) and (mat[j][i]!=0) and not(j in indicesProcessed):
                    allParentsAlreadyProcessed=False
            if not(i in indicesProcessed) and allParentsAlreadyProcessed==True:
                target=i
                break
        indicesProcessed.append(target)

        # We might have a cycle.
        if target==None:
            print("Internal error. Please check the nodes and edges.")
            return qc, mat

        foundControllers=False
        collectedControllerIndices=[]
        for y in range(len(nodes)):
            if mat[y,target] !=0 and not(y==target):
                foundControllers=True
                collectedControllerIndices.append(y)

        if foundControllers==False:
            # This risk item is not triggered by transitions. Just put an uncontrolled gate in for it. It can only be controlled by the
            # modification register.
            qc.u(2*math.asin(math.sqrt(mat[target,target])),0,0,qr[target])
            if nodes[target] in nodeMapping:
                # The probability must be modified if the modification setting is active.
                newValue=2*math.asin(math.sqrt(mat2[target,target]))-2*math.asin(math.sqrt(mat[target,target]))
                qc.append(U3Gate(newValue,0,0).control(num_ctrl_qubits=necessaryBits,ctrl_state=nodeMapping[nodes[target]]),qt[:]+[qr[target]])
        else:
            # This risk item is triggered by more than one other risk item. The triggering risk item are in the list "collectedControllerIndices"
            modifiableEdges=[]
            for source in collectedControllerIndices:
                if (nodes[source],nodes[target]) in edgeMapping:
                    modifiableEdges.append((source,target))
            appendDependentNode(qt, qr, qc, mat, mat2, target, collectedControllerIndices, modifiableEdges, nodes, nodeMapping, edgeMapping, necessaryBits)

    if model2gate==True:
        gate=qc.to_gate()
        gate.label="BRM"
        return gate, mat, nodeMapping, edgeMapping, necessaryBits
    else:
        return qc, mat, nodeMapping, edgeMapping, necessaryBits

def dicke_init(n, k):
    #deterministic  Dicke state preparation (Bärtschi & Eidenbenz, 2019)
    #unoptimized version
    qc = QuantumCircuit(n)
    qc.x(range(n-k, n))
    for i in range(n, k, -1):
        qc.append(scs(i, k), range(0, i))

    for i in range(k, 1, -1):
        qc.append(scs(i, i-1), range(0, i))

    return qc.to_gate()

def OR_2q():
    qc = QuantumCircuit(3)
    qc.toffoli(0, 1, 2)
    qc.cnot(0, 1)
    qc.cnot(0, 2)
    return qc.to_gate()

def OR_nrz(n, gamma):
    ORGate = OR_2q()
    qc = QuantumCircuit(2*n)
    qc.append(ORGate, [0, 1, n])
    for i in range(2, n):
        qc.append(ORGate, [i, n+i-2, n+i-1])
    qc.crz(gamma, 2*n-2, 2*n-1)
    for i in range(n, 2, -1):
        qc.append(ORGate, [n-i-1, 2*n-2-i, 2*n-1-i])
    qc.append(ORGate, [0, 1, n])
    return qc.to_gate()

def sn(x): #swap network
    qc = QuantumCircuit(x)
    for i in range(1,x):
        qc.swap(0,i)
    return qc.to_gate(label=f'swap\nnet')

def ux(n): #
    qubits_num = n**2
    register = []
    for t in range(n):
        register.append([t*n+i for i in range(n)])

    qc = QuantumCircuit(qubits_num)

    #step1
    qc.append(w(n),register[0])
    for i in range(n):
        qc.x(register[-1][i])
    # qc.barrier()
    for i in range(n):
        qc.cnot(register[0][i],register[-1][i])
    # qc.barrier()

    #step2
    for x in range(n-1,2,-1):
        qc.append(w(x),register[-2][n-x:])
        for i in range(n):
            qc.cswap(register[-1][i],register[-2][-1],register[n-x][i])
            if i!=n-1:
                qc.append(sn(x).control(1),[register[-1][i]]+register[-2][n-x:])
        # qc.barrier()
        for i in range(n):
            qc.cnot(register[n-x][i],register[-1][i])
        # qc.barrier()

    #step3
    if n>2:
        for i,j in combinations(np.arange(n).tolist(),2):
            qc.append(w(2).control(2),[register[-1][i],register[-1][j],register[-2][i],register[-2][j]])
        # qc.barrier()
        for i in range(n):
            qc.cnot(register[-2][i],register[-1][i])
        # qc.barrier()

    return qc.to_gate(label=r'$U_x$')

def ux_dagger(n):
    qc = QuantumCircuit(n**2)
    qc.append(ux(n).inverse(),[i for i in range(n**2)])
    return qc.to_gate(label=r'$U_x^{\dagger}$')

def increment(num):
    wires = [i for i in range(num)][::-1]
    qc = QuantumCircuit(num)
    for i in range(num-1):
        qc.mcx(wires[:num-1-i],wires[num-1-i])
    qc.x(wires[0])
    return qc.to_gate(label=r'$+1$')

def decrement(num):
    qc = QuantumCircuit(num)
    qc.append(increment(num).inverse(),[i for i in range(num)])
    return qc.to_gate(label=r'$-1$')

def plus(num,q):
    wires = [i for i in range(num)]
    qc = QuantumCircuit(num)
    bits = format(q,f'0{num}b')[::-1]
    for i,b in enumerate(bits):
        if b=='1':
            qc.append(increment(num-i),wires[:num-i])
    label = f'+{q}'
    return qc.to_gate(label=label)

def minus(num,q):
    qc = QuantumCircuit(num)
    qc.append(plus(num,q).inverse(),[i for i in range(num)])
    label = f'-{q}'
    return qc.to_gate(label=label)

def larger(num,Q):
    qc = QuantumCircuit(num+1)
    c_wires = [i for i in range(num)]
    t_wire = num
    bit = format(Q,f'0{num}b')
    for i,b in enumerate(bit):
        if b=='0':
            ctrl_state = bit[:i]+'1'
            qc.append(MCXGate(i+1,ctrl_state=ctrl_state[::-1]),c_wires[:i+1]+[t_wire])
    label = rf'>{Q}'
    return qc.to_gate(label=label)

def CE(N,Q,q,num_qubits,register_x,register_y,register_a,register_d,register_c,register_r):
    qc = QuantumCircuit(num_qubits)
    num_d = len(register_d)

    #initial d and c
    for i in range(N-1):
        qc.append(plus(num_d,q[i]).control(1),[register_x[0][i]]+register_d)
    for i in range(N-1):
        qc.cnot(register_x[0][i],register_c[i])

    for t in range(1,N-1):
        # register demand
        for i in range(N-1):
            qc.append(plus(num_d,q[i]).control(1),[register_x[t][i]]+register_d)

        # control a_t
        qc.append(larger(num_d,Q).control(1,ctrl_state=0),[register_y[t]]+register_d+[register_a[t]])
        qc.cnot(register_y[t],register_a[t])

        # recover d
        if t < N-2:
            for i in range(N-1):
                qc.append(minus(num_d,q[i]).control(2),[register_a[t]]+[register_c[i]]+register_d)

        # recover c
        if t==1:
            for i in range(N-1):
                qc.mcx([register_x[0][i],register_a[1]],register_c[i])

        elif t>1 and t<N-2:
            for i in range(N-1):
                qc.mcx([register_a[t],register_c[i]],register_r[t][i])
                qc.cnot(register_r[t][i],register_c[i])

        # register c
        if t < N-2:
            for i in range(N-1):
                qc.cnot(register_x[t][i],register_c[i])

    return qc.to_gate(label=r'$U_E$')

def CE_dagger(N,Q,q,num_qubits,register_x,register_y,register_a,register_d,register_c,register_r):
    qc = QuantumCircuit(num_qubits)
    qc.append(CE(N,Q,q,num_qubits,register_x,register_y,register_a,register_d,register_c,register_r).inverse(),[i for i in range(num_qubits)])
    return qc.to_gate(label=r'$U_E^{\dagger}$')

def exp_minus_i_gamma_hc(num_qubits,terms,gamma):
    qc = QuantumCircuit(num_qubits)
    read_z_terms(qc,gamma,terms)
    return qc.to_gate(label=r'$exp(-i\gamma HC)$')

def cutGate(gate: Gate, control: int, target: int) -> dict:
    """Return a cutCZ circuit with the same parameters as the input gate."""
    if gate.num_qubits != 2:
        raise ValueError("Input gate must be a 2-qubit gate.")
    if control == target:
        raise ValueError("Control and target qubits must be different.")
    if control < 0 or target < 0:
        raise ValueError("Control and target qubits must be non-negative.")

    qc = QuantumCircuit(2, name=f"cut{gate.name.upper()}")
    if control > target:
        loccontrol = 1
        loctarget = 0
    else:
        loccontrol = 0
        loctarget = 1
    qc.append(gate, [loccontrol, loctarget])
    tr = transpile(qc, basis_gates=["cz", "r", "h", "s", "sdg", "x", "y", "z"])
    for ind, instr in enumerate(tr.data):
        if instr.operation.name == "cz":
            tr.data.pop(ind)
            test = CircuitInstruction(
                        operation=cutCZ_op,
                        qubits=tr.qubits,
                    )
            tr.data.insert(ind, test)
    return {"instruction": tr.to_instruction(label="CutGate"), 
            "qargs":[control, target]}

def _define(self):
    """
    gate can(theta, phi, lam) q0,q1 {
        rxx(theta) q0, q1;
        ryy(phi) q0, q1;
        rzz(lam) q0, q1;
    }

    gate can(theta, phi, lam) q0,q1 {
        u3(1.5*pi, 0.0, 1.5*pi) q1;
        u3(0.5*pi, 1.5*pi, 0.5*pi) q0;
        cx q1, q0;
        u3(1.5*pi, theta + pi, 0.5*pi) q1;
        u3(pi, 0.0, phi + pi) q0;
        cx q1, q0;
        u3(0.5*pi, 0.0, 0.5*pi) q1;
        u3(0.0, 1.5*pi, lam + 0.5*pi) q0;
        cx q1, q0;
    }
    """
    from qiskit.circuit.library import RXXGate, RYYGate, RZZGate
    from qiskit.circuit.library import UGate, CXGate

    q = QuantumRegister(2, "q")
    qc = QuantumCircuit(q, name=self.name)
    # rules = [
    #     (RXXGate(self.params[0] * pi), [q[0], q[1]], []),
    #     (RYYGate(self.params[1] * pi), [q[0], q[1]], []),
    #     (RZZGate(self.params[2] * pi), [q[0], q[1]], []),
    # ]
    rules = [
        (UGate(1.5 * pi, 0.0, 1.5 * pi), [q[1]], []),
        (UGate(0.5 * pi, 1.5 * pi, 0.5 * pi), [q[0]], []),
        (CXGate(), [q[1], q[0]], []),
        (UGate(1.5 * pi, self.params[0] * pi + pi, 0.5 * pi), [q[1]], []),
        (UGate(pi, 0.0, self.params[1] * pi + pi), [q[0]], []),
        (CXGate(), [q[1], q[0]], []),
        (UGate(0.5 * pi, 0.0, 0.5 * pi), [q[1]], []),
        (UGate(0.0, 1.5 * pi, self.params[2] * pi + 0.5 * pi), [q[0]], []),
        (CXGate(), [q[1], q[0]], []),
    ]
    for instr, qargs, cargs in rules:
        qc._append(instr, qargs, cargs)

    self.definition = qc

def adder_appro(a, b, n, appro):  # a+b in fourier space
    a_bin = bin(int(a))[2:].zfill(n)
    b_bin = bin(int(b))[2:].zfill(n)

    qr = QuantumRegister(2 * n)
    cr = ClassicalRegister(n)
    qc = QuantumCircuit(qr, cr)
    for i in range(n):
        if a_bin[i] == '1':
            qc.x(i)

    for i in range(n):
        if b_bin[i] == '1':
            qc.x(n + i)

    qc.append(myAQFT(n, appro), qargs=qr[n:n * 2])
    for i in range(1, n + 1):
        for j in range(n - i + 1):
            if a_bin[i + j - 1] == '1':
                qc.cu1(2 * math.pi / (2 ** i), i + j - 1, n + j)
    qc.append(myAQFT(n, appro, inverse=True), qargs=qr[n: 2 * n])

    for i in range(n):
        qc.measure(i + n, n - i - 1)

    return qc

def adder(a, b, n):  # a+b in fourier space
    a_bin = bin(int(a))[2:].zfill(n)
    b_bin = bin(int(b))[2:].zfill(n)

    qr = QuantumRegister(2 * n)
    cr = ClassicalRegister(n)
    qc = QuantumCircuit(qr, cr)
    for i in range(n):
        if a_bin[i] == '1':
            qc.x(i)
    for i in range(n):
        if b_bin[i] == '1':
            qc.x(n + i)

    qc.append(myQFT(n), qargs=qr[n:n * 2])
    for i in range(1, n + 1):
        for j in range(n - i + 1):
            if a_bin[i + j - 1] == '1':
                qc.cu1(2 * math.pi / (2 ** i), i + j - 1, n + j)

    qc.append(myQFT(n, inverse=True), qargs=qr[n: 2 * n])

    for i in range(n):
        qc.measure(i + n, n - i - 1)
    # circuit_drawer(qc,output='mpl',filename='./report/adder_prevent.png')

    return qc

def phiADD(bitlen, a):
    a_bin = bin(int(a))[2:].zfill(bitlen)
    qr = QuantumRegister(bitlen)
    qc = QuantumCircuit(qr)
    for i in range(1, bitlen + 1):
        for j in range(bitlen - i + 1):
            if a_bin[i + j - 1] == '1':
                qc.u1(2 * math.pi / (2 ** i), qr[j])
    qc.name = f'phiADD{a}'
    return qc

def cu_latex_gate(inv):
    qr = QuantumRegister(2)
    qc = QuantumCircuit(qr)
    ret = qc.to_gate()
    if not inv:
        ret.name = 'cMULT(a)MODN'
    else:
        ret.name = 'cMULT(ainv)MODN'
    return ret

def get_axis(axis, qr, cr):
    """ Returns a QuantumCircuit given a string such as X, XX, XYZ"""
    axis = axis.upper()
    size = len(axis)

    a = QuantumCircuit(qr, cr)
    for n in range(size):
        if axis[n] == 'X':
            a.h(qr[n])
        if axis[n] == 'Y':
            a.sdg(qr[n])
            a.h(qr[n])
    return a

def to_circuit(self, symmetric=False) -> qk.QuantumCircuit:
    if isinstance(self._data, qk.QuantumCircuit):
        return self._data
    else:
        x = qk.QuantumRegister(self._embedding_size, name="x")
        b = qk.QuantumRegister(1, name="b")
        a = qk.AncillaRegister(self.num_ancillas(), name="a")
        qc = qk.QuantumCircuit(x, b, a, name="CX_Pi")
        if self._data is None:
            qc.x(b)
        else:
            bits = []
            for (i, cs) in zip(self._data, self._ctrl_state):
                bits.append(x[i])
            for i in range(len(bits)):
                if self._ctrl_state[i] == 0:
                    qc.x(bits[i])
            if symmetric:
                qc.append(MCXGate(len(bits)), bits[:] + b[:])
                for i in range(len(bits)):
                    if self._ctrl_state[i] == 0:
                        qc.x(bits[i])
            else:
                qc.append(_mcx_nonsymmetric(len(bits), ancillas=not self._avoid_ancillas), bits[:] + b[:] + a[:])
        return qc.decompose(["ns_mcx"])

def logical_and(self, other: CPiNot) -> CPiNot:
    assert self._embedding_size == other._embedding_size

    if self._data is None:
        return other
    if other._data is None:
        return self
    if isinstance(self._data, qk.QuantumCircuit) or isinstance(other._data, qk.QuantumCircuit):
        x = qk.QuantumRegister(self._embedding_size, name="x")
        a1 = qk.AncillaRegister(self.num_ancillas())
        a2 = qk.AncillaRegister(other.num_ancillas())
        a3 = qk.AncillaRegister(2)
        b = qk.QuantumRegister(1, name="b")
        qc = qk.QuantumCircuit(x, b, a1, a2, a3, name="CX_Pi")
        qc.append(self.to_circuit(), x[:] + [a3[0]] + a1[:])
        qc.append(other.to_circuit(), x[:] + [a3[1]] + a2[:])
        qc.rccx(a3[0], a3[1], b)

        return CPiNot(self._embedding_size, qc)
    else:
        bits = self._data + other._data
        ctrl_state = self._ctrl_state + other._ctrl_state
        return CPiNot(self._embedding_size, bits, ctrl_state)

def extend_embedding(self, n: int, front: bool) -> CPiNot:
    if self._data is None:
        return CPiNot(self._embedding_size + n, None)
    elif isinstance(self._data, list):
        if front:
            return CPiNot(self._embedding_size + n, [i + n for i in self._data], self._ctrl_state)
        else:
            return CPiNot(self._embedding_size + n, self._data, self._ctrl_state)
    else:
        x = qk.QuantumRegister(self._embedding_size + n, name="x")
        a = qk.AncillaRegister(self.num_ancillas(), name="a")
        b = qk.QuantumRegister(1, name="b")
        qc = qk.QuantumCircuit(x, b, a)
        qc.append(
            self._data,
            (x[n:] if front else x[:-n]) +
            b[:] +
            a[:]
        )
        return CPiNot(self._embedding_size + n, qc)

def xor(self, other: CPiNot) -> CPiNot:
    assert self._embedding_size == other._embedding_size

    if self._data is None:
        return other
    if other._data is None:
        return self

    x = qk.QuantumRegister(self._embedding_size, name="x")
    a = qk.QuantumRegister(max(self.num_ancillas(), other.num_ancillas()), name="a")
    b = qk.QuantumRegister(1, name="b")
    qc = qk.QuantumCircuit(x, b, a)
    qc.append(
        self.to_circuit(True),
        x[:] + b[:] + a[:self.num_ancillas()]
    )
    qc.append(
        other.to_circuit(),
        x[:] + b[:] + a[:other.num_ancillas()]
    )
    return CPiNot(self._embedding_size, qc)

def identity(n: int) -> BlockEncoding:
    qc = qk.QuantumCircuit(n)
    return BlockEncoding(qc)

def extend(self, n: int, front: bool = False) -> BlockEncoding:
    x = qk.QuantumRegister(self._embedding_size + n, name="x")
    a = qk.AncillaRegister(self._U.num_ancillas, name="a")

    U = qk.QuantumCircuit(
        x, a,
        name=self._U.name)
    if front:
        U.append(self._U, x[n:] + a[:])
    else:
        U.append(self._U, x[:self._embedding_size] + a[:])
    U = U.decompose()

    if front:
        CX_dom = self._CX_dom.extend_embedding(n, True).logical_and(
            CPiNot(self._embedding_size + n, list(range(n)))
        )
        CX_img = self._CX_img.extend_embedding(n, True).logical_and(
            CPiNot(self._embedding_size + n, list(range(n)))
        )
    else:
        CX_dom = self._CX_dom.extend_embedding(n, False).logical_and(
            CPiNot(self._embedding_size + n, list(range(self._embedding_size, self._embedding_size + n)))
        )
        CX_img = self._CX_img.extend_embedding(n, False).logical_and(
            CPiNot(self._embedding_size + n, list(range(self._embedding_size, self._embedding_size + n)))
        )

    return BlockEncoding(U, CX_dom, CX_img, self._normalization)

def CRShift(LOG_N, DIM, uncompute_control=False):
    """
    Circuit implementing a bitwise right shift of the first register by the
    second register.

    The first register is interpreted as consisting of DIM registers with N
    qubits each, all of which are shifted.
    """

    N = 2**LOG_N
    x = qk.QuantumRegister(N * DIM, name="x")
    y = qk.QuantumRegister(LOG_N, name="y")

    qc = qk.QuantumCircuit(x, y, name="shift")
    if LOG_N == 1:
        for d in range(DIM):
            qc.cswap(y[0], x[2*d], x[2*d + 1])
    else:
        for d in range(DIM):
            for i in range(0, N, 2):
                qc.cswap(y[0], x[N*d + i], x[N*d + i+1])
        next = CRShift(LOG_N-1, DIM)
        qc.append(next, x[::2] + y[1:])
        qc.append(CInc(LOG_N-1), y[:])

        qc.append(next, x[1::2] + y[1:])
        if uncompute_control:
            qc.append(CInc(LOG_N-1).inverse(), y[:])

    return qc.decompose(["c_inc", "shift"])

def naive_image_storage(image):
    N = len(image)
    qc = QuantumCircuit(N)
    for i in range(N):
        if int(image[i])==1:
            qc.x(int(i))
    return qc

def fig2(n):
    controls = list(range(n))
    target = n + n - 2
    auxs = list(range(n, n + n - 2))

    qc = QuantumCircuit(n + n - 1)

    for c1, c2, t in zip(controls[::-1][:n - 2], auxs[::-1][:n - 2], [target] + auxs[::-1][:n - 2]):
        qc.append(CCXGate() if t == target else CCXGate(), [c1, c2, t])

    qc.append(CCXGate(), [controls[0], controls[1], auxs[0]])

    for c1, c2, t in zip(controls[2:], auxs, auxs[1:] + [target]):
        qc.append(CCXGate() if t == target else CCXGate(), [c1, c2, t])

    for c1, c2, t in zip(controls[::-1][1:n - 2], auxs[::-1][1:n - 2], auxs[::-1][:n - 2]):
        qc.append(CCXGate(), [c1, c2, t])

    qc.append(CCXGate(), [controls[0], controls[1], auxs[0]])

    for c1, c2, t in zip(controls[2:], auxs, auxs[1:]):
        qc.append(CCXGate(), [c1, c2, t])
    return qc

def fig3(n):
    controls = list(range(n))
    target = n + n - 2
    auxs = list(range(n, n + n - 2))

    qc = QuantumCircuit(n + n - 1)

    for c1, c2, t in zip(controls[::-1][:n - 2], auxs[::-1][:n - 2], [target] + auxs[::-1][:n - 2]):
        qc.append(CCXGate(), [c1, c2, t])

    qc.append(RTofDecomp(), [controls[0], controls[1], auxs[0]])

    for c1, c2, t in zip(controls[2:], auxs, auxs[1:] + [target]):
        qc.append(CCXGate() if t == target else RTofDecomp(), [c1, c2, t])

    for c1, c2, t in zip(controls[::-1][1:n - 2], auxs[::-1][1:n - 2], auxs[::-1][:n - 2]):
        qc.append(CCXGate() if t == target else RTofDecomp(), [c1, c2, t])

    qc.append(RTofDecomp(), [controls[0], controls[1], auxs[0]])

    for c1, c2, t in zip(controls[2:], auxs, auxs[1:]):
        qc.append(CCXGate(), [c1, c2, t])
    return qc

def operador_difusao(n_qubits, sigma, tempo):
    qc = QuantumCircuit(n_qubits)
    for q in range(n_qubits):
        ang = 2 * np.arctan(np.tanh(sigma * tempo / (q + 1)))
        qc.ry(ang, q)
    return qc

def ising_circuit(nqubits, t = 1, jmax = 1, h = .1, wmax = 10, rseed=0, mode=None, 
                  random=True, jpositive=False, wpositive=False):
    r"""Transverse field ising model.

    .. math:: 

        H = J X X + (h + D) Z \\

        U = e^{-iHt} ~ e^{-iJXXt} e^{-i(h+W)Zt} = Rxx(2Jt) Rz(2(h+W)t)

    https://arxiv.org/pdf/2103.05348.pdf

    Arguments:
        nqubits (int): number of qubits
        t (float): time in e^-iHt
        h (float): fixed magnetic field
        jmax (float): spin-spin coupling J in (-jmax, jmax)
        jpositive (bool): J in (0, jmax)
        wmax (float): onsite disorder strength W in (-wmax, wmax)
        wpositive (bool): D in (0, jmax)
        random (bool): if false, J=jmax and W=wmax
        mode (str): 
            | 'nn': Rxx on nearest neighbour, and Rz.
            | 'up_ladder': Rxx ladder from qubit 0 to qubit max, and Rz.
            | 'up_down_ladder': Rxx ladder from qubit 0 to qubit max, Rz, Rxx ladder from qubit max to qubit 0.
            | else: Rxx on all pairwise connections, and Rz.
        rseed (int): random seed for picking J, W

    Returns:
        QuantumCircuit
    """
    qc =  QuantumCircuit(nqubits)
    if random:
        if jpositive:
            jlow, jhigh = 0, jmax
        else:
            jlow, jhigh = -jmax, jmax
        if wpositive:
            wlow, whigh = 0, wmax
        else:
            wlow, whigh = -wmax, wmax
    else:
        jlow, jhigh = jmax, jmax
        wlow, whigh = wmax, wmax
    #
    rng = Generator(PCG64(seed=rseed))
    if mode == 'nn':
        for j in range(0, nqubits-1, 2):   
            qc.rxx(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
        for j in range(1, nqubits-1, 2):
            qc.rxx(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
        for j in range(0, nqubits):   
            qc.rz(phi = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
    elif mode in ['up_ladder', 'ladder']:
        for j in range(0, nqubits-1):
            qc.rxx(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
            qc.rz(phi = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
    elif mode == 'up_down_ladder':
        for j in range(0, nqubits-1):
            qc.rxx(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
            qc.rz(phi = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
        for j in range(nqubits-1, 0, -1):
            qc.rxx(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j-1)
    else:
        for j in range(nqubits):
            for i in range(j+1, nqubits):
                qc.rxx(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=i, qubit2=j)
            qc.rz(phi = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
    return qc

def ising_circuit_natural(nqubits, t = 1, jmax = 1, h = .1, wmax = 10, rseed=0, mode=None, 
                  random=True, jpositive=False, wpositive=False):
    r"""Transverse field ising model, adjusted to fit our natural 2-qubit gate.
    'Also has two possible ``adjustment methods``, to allow prevent the ZZ acting trivially.


    .. math:: 

        H = J Z Z + (h + D) X \\

        U = e^{-iHt} ~ e^{-iJZZt}e^{-i(h+W)Xt}  = RX(2(h+W)t)RZZ(2Jt) 

    https://arxiv.org/pdf/2103.05348.pdf

    Arguments:
        nqubits (int): number of qubits
        t (float): time in e^-iHt
        h (float): fixed magnetic field
        jmax (float): spin-spin coupling J in (-jmax, jmax)
        jpositive (bool): J in (0, jmax)
        wmax (float): onsite disorder strength W in (-wmax, wmax)
        wpositive (bool): D in (0, jmax)
        random (bool): if false, J=jmax and W=wmax
        mode (str): 
            | 'nn': Rxx on nearest neighbour, and Rz.
            | 'up_ladder': Rxx ladder from qubit 0 to qubit max, and Rz.
            | 'up_down_ladder': Rxx ladder from qubit 0 to qubit max, Rz, Rxx ladder from qubit max to qubit 0.
            | else: Rxx on all pairwise connections, and Rz.
        rseed (int): random seed for picking J, W
        adjustment (str):
            | 'Hadamard' : Performs a Hadamard on each gate at the start.
            | 'Swap Order': Performs 1 qubit then two qubit gates.
            | else -> Hadamard.

    Returns:
        QuantumCircuit
    """
    qc =  QuantumCircuit(nqubits)
    if random:
        if jpositive:
            jlow, jhigh = 0, jmax
        else:
            jlow, jhigh = -jmax, jmax
        if wpositive:
            wlow, whigh = 0, wmax
        else:
            wlow, whigh = -wmax, wmax
    else:
        jlow, jhigh = jmax, jmax
        wlow, whigh = wmax, wmax
    #
    rng = Generator(PCG64(seed=rseed))
    if mode == 'nn':
        for j in range(0, nqubits):   
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
        for j in range(0, nqubits-1, 2):   
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
        for j in range(1, nqubits-1, 2):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)

    elif mode in ['up_ladder', 'ladder']:
        for j in range(0, nqubits):
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
        for j in range(0, nqubits-1):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)

    elif mode == 'up_down_ladder':
        for j in range(0, nqubits):
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
        for j in range(0,nqubits-1):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
        for j in range(0, nqubits):
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
        for j in range(nqubits-1, 0, -1):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j-1)
    else:
        for j in range(nqubits):
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
        for j in range(nqubits):
            for i in range(j+1, nqubits):
                qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=i, qubit2=j)

    return qc

def ising_circuit_naturalH(nqubits, t = 1, jmax = 1, h = .1, wmax = 10, rseed=0, mode=None, 
                  random=True, jpositive=False, wpositive=False):
    r"""Transverse field ising model. Each unitary is sandwiched with a round of Hadamards, to avoid
    trivial actions.

    .. math::

        H = J Z Z + (h + D) X \\

        U = e^{-iHt} ~ e^{-iJZZt} e^{-i(h+W)Xt} = Rzz(2Jt) Rx(2(h+W)t)

    https://arxiv.org/pdf/2103.05348.pdf

    Arguments:
        nqubits (int): number of qubits
        t (float): time in e^-iHt
        h (float): fixed magnetic field
        jmax (float): spin-spin coupling J in (-jmax, jmax)
        jpositive (bool): J in (0, jmax)
        wmax (float): onsite disorder strength W in (-wmax, wmax)
        wpositive (bool): D in (0, jmax)
        random (bool): if false, J=jmax and W=wmax
        mode (str): 
            | 'nn': Rzz on nearest neighbour, and Rz.
            | 'up_ladder': Rzz ladder from qubit 0 to qubit max, and Rz.
            | 'up_down_ladder': Rzz ladder from qubit 0 to qubit max, Rx, Rzz ladder from qubit max to qubit 0.
            | else: Rzz on all pairwise connections, and Rz.
        rseed (int): random seed for picking J, W

    Returns:
        QuantumCircuit
    """
    qc =  QuantumCircuit(nqubits)
    if random:
        if jpositive:
            jlow, jhigh = 0, jmax
        else:
            jlow, jhigh = -jmax, jmax
        if wpositive:
            wlow, whigh = 0, wmax
        else:
            wlow, whigh = -wmax, wmax
    else:
        jlow, jhigh = jmax, jmax
        wlow, whigh = wmax, wmax
    #
    rng = Generator(PCG64(seed=rseed))
    for j in range(0, nqubits):
        qc.h(qubit=j)

    if mode == 'nn':
        for j in range(0, nqubits-1, 2):   
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
        for j in range(1, nqubits-1, 2):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
        for j in range(0, nqubits):   
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
    if mode == 'nnc': #closed loop.
        for j in range(0, nqubits-1, 2):   
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
        for j in range(1, nqubits-1, 2):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
        qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=0, qubit2=nqubits-1)
        for j in range(0, nqubits):   
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
    elif mode in ['up_ladder', 'ladder']:
        for j in range(0, nqubits-1):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
    elif mode == 'up_down_ladder':
        for j in range(0, nqubits-1):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j+1)
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
        for j in range(nqubits-1, 0, -1):
            qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=j, qubit2=j-1)
    else:
        for j in range(nqubits):
            for i in range(j+1, nqubits):
                qc.rzz(theta = rng.uniform(low=jlow, high=jhigh) * t, qubit1=i, qubit2=j)
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)

    for j in range(0, nqubits):
        qc.h(qubit=j)
    return qc

def native_circuit(nqubits, t = 1, jmax = 1, h = .1, wmax = 10, rseed=0, mode=None, 
                  random=True, jpositive=False, wpositive=False):
    qc =  QuantumCircuit(nqubits)
    if random:
        if jpositive:
            jlow, jhigh = 0, jmax
        else:
            jlow, jhigh = -jmax, jmax
        if wpositive:
            wlow, whigh = 0, wmax
        else:
            wlow, whigh = -wmax, wmax
    else:

        jlow, jhigh = jmax, jmax
        wlow, whigh = wmax, wmax
    #
    rng = Generator(PCG64(seed=rseed))
    for j in range(0, nqubits):
        qc.h(qubit=j)

    if mode == 'nn':
        for j in range(0, nqubits-1, 2):   
            qc.cz( control_qubit=j, target_qubit=j+1)
        for j in range(1, nqubits-1, 2):
            qc.cz( control_qubit=j, target_qubit=j+1)
        for j in range(0, nqubits):   
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
    if mode == 'nnc': #closed loop.
        #print(wlow,whigh)
        for j in range(0, nqubits-1, 2):   
            qc.cz( control_qubit=j, target_qubit=j+1)
        for j in range(1, nqubits-1, 2):
            qc.cz( control_qubit=j, target_qubit=j+1)
        qc.cz(control_qubit=nqubits-1, target_qubit=0)
        for j in range(0, nqubits):
            thetac=t * (h + rng.uniform(low=wlow, high=whigh))
            #print(thetac)   
            qc.rx(theta = thetac, qubit=j)

    elif mode in ['up_ladder', 'ladder']:
        for j in range(0, nqubits-1):
            qc.cz( control_qubit=j, target_qubit=j+1)
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
    elif mode == 'up_down_ladder':
        for j in range(0, nqubits-1):
            qc.cz( control_qubit=j, target_qubit=j+1)
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)
        for j in range(nqubits-1, 0, -1):
            qc.cz( control_qubit=j, target_qubit=j-1)
    else:
        for j in range(nqubits):
            for i in range(j+1, nqubits):
                qc.cz( control_qubit=i, target_qubit=j)
            qc.rx(theta = t * (h + rng.uniform(low=wlow, high=whigh)), qubit=j)

    for j in range(0, nqubits):
        qc.h(qubit=j)
    return qc

def spread_circuit(nqubits, sources, rseed=0):
    """Input connected to all others via a direct cnot"""
    rng = Generator(PCG64(seed=rseed))
    qc = QuantumCircuit(nqubits)
    for q in range(nqubits):
        qc.ry(theta = rng.random() * np.pi * 2, qubit=q)
        qc.rz(phi = rng.random() * np.pi, qubit=q)
    for s in sources:
        for q in range(nqubits):
            if q not in sources:
                qc.cx(control_qubit=s, target_qubit=q)
    return qc

def angle_encode_circuit(angles: List[float], q: int, L: int, entangler: str = "cz-ring", entangler_config: Optional[Dict[str, int]] = None) -> QuantumCircuit:
    """Build a simple angle-encoding circuit: L layers, each loads q angles into Ry then entangles.
    angles: length should be >= q*L; extra values ignored.
    """
    qc = QuantumCircuit(q)
    idx = 0
    for _ in range(L):
        # load angles
        for j in range(q):
            if idx < len(angles):
                qc.ry(angles[idx], j)
            idx += 1
        # entangle
        if entangler == "cz-ring":
            for j in range(q):
                qc.cz(j, (j + 1) % q)
        elif entangler == "cx-chain":
            for j in range(q - 1):
                qc.cx(j, j + 1)
        elif entangler == "cz-grid":
            # Expect entangler_config with H and W; map first q qubits row-major on HxW
            if not entangler_config or "H" not in entangler_config or "W" not in entangler_config:
                raise ValueError("cz-grid requires entangler_config with H and W")
            H = int(entangler_config["H"]) ; W = int(entangler_config["W"]) ;
            # Sanity: q should be <= H*W
            # Add CZ between right and down neighbors within the first q positions
            def idx(h, w):
                return h * W + w
            for h in range(H):
                for w in range(W):
                    a = idx(h, w)
                    if a >= q:
                        continue
                    if w + 1 < W:
                        b = idx(h, w + 1)
                        if b < q:
                            qc.cz(a, b)
                    if h + 1 < H:
                        b = idx(h + 1, w)
                        if b < q:
                            qc.cz(a, b)
        else:
            pass
    return qc

def phase_encode_circuit(phases: List[float], q: int, L: int, entangler: str = "cz-ring") -> QuantumCircuit:
    """Build a simple phase-encoding circuit: initialize |0>^q, optional H layer to create superposition,
    then apply Rz with provided phases in L re-upload layers and entangle.
    """
    qc = QuantumCircuit(q)
    # Optional layer to spread amplitudes (use H gates)
    for j in range(q):
        qc.h(j)
    idx = 0
    for _ in range(L):
        for j in range(q):
            if idx < len(phases):
                qc.rz(phases[idx], j)
            idx += 1
        if entangler == "cz-ring":
            for j in range(q):
                qc.cz(j, (j + 1) % q)
        elif entangler == "cx-chain":
            for j in range(q - 1):
                qc.cx(j, j + 1)
        else:
            pass
    return qc

def createFaultyGate(self, faultfreeGate):
    qc = QuantumCircuit(1)
    qc.sx(0)
    qc.rz(np.pi / 20, 0)  
    mat = Operator(qc).data
    return UnitaryGate(mat, label="SX+RZdrift")

def extract_subcircuit(qc, start, end):
    sub_qc = QuantumCircuit(*qc.qregs, name=qc.name)
    for instr in qc.data[start:end]:
        sub_qc.append(instr.operation, instr.qubits, instr.clbits)
    return sub_qc

def GHZstate(self):
    qr = QuantumRegister(self.NUM_QUBITS_VAR*self.NUM_VARS)
    qc = QuantumCircuit(qr,name='GHZstate')

    for i in range(self.NUM_QUBITS_VAR):
        qc.h(i)
    for j in range(1,self.NUM_VARS):
        qc.cx(i,i+j*self.NUM_QUBITS_VAR)

    return qc.to_instruction()

def parametrized_unitary(self,thetas,phis,rhos):

    """U_i transformation"""
    qr = QuantumRegister(self.NUM_QUBITS_VAR)
    qc = QuantumCircuit(qr,name = 'U_i')
    for i in range(self.NUM_QUBITS_VAR):
        qc.rz(thetas[i],i)
        qc.rx(phis[i],i)
    for i in range(self.NUM_QUBITS_VAR-1):
        qc.rzz(rhos[i],i,i+1)
    return qc.to_instruction()

def pennylane_to_qiskit(circuit, n_qubits, params = None, symbolic_params = True):
    qiskit_device = AerDevice(wires=n_qubits)
    qnode = qml.QNode(circuit.func, qiskit_device)
    if params is not None:
        qnode(*params)
    else:
        qnode()
    qiskit_circuit = qiskit_device._circuit

    if symbolic_params:
        # Create a new circuit with symbolic parameters
        new_qc = QuantumCircuit(n_qubits, n_qubits)
        param_mapping = {}  # Store parameters for reuse

        for instr, qubits, clbits in qiskit_circuit.data:
            new_params = []

            # Replace constant parameters with symbolic ones
            for param in instr.params:
                if isinstance(param, (float, int)):  # Detect constants
                    if param not in param_mapping:
                        param_mapping[param] = Parameter(f"x{len(param_mapping)}")
                    new_params.append(param_mapping[param])
                else:
                    new_params.append(param)

            new_qc.append(instr.__class__(*new_params), qubits, clbits)
    else:
        new_qc = qiskit_circuit

    return new_qc

def _target(self, task, target, seed):
  if task == 'SP':
    if target == 'random': return random_statevector(2**self.qubits, seed)
    if target == 'bell': return Statevector(np.array([1/np.sqrt(2), 0, 0, 1/np.sqrt(2)], dtype=np.complex128))
    if 'ghz' in target: 
      n = int(target[-1])
      assert 2 <= n <= self.qubits, f"GHZ entangled state must have at least 2 and at most {self.qubits} qubits." 
      target = np.zeros(shape=(2**n,), dtype=np.complex128)
      target[0] = target[-1] = 1/np.sqrt(2)
      return Statevector(target) 
  if task == 'UC':
    if target == 'random': return random_unitary(2**self.qubits, seed)
    _t = QuantumCircuit(self.qubits)
    if target == 'hadamard': _t.append(HGate(),[0])
    if target == 'toffoli': 
      assert self.qubits >= 3, "to build Toffoli gate you need at least three wires/qubits."
      _t.append(CCXGate(),[0,1,2])
    return Operator(_t)
  assert False, f'{task}-{target} not defined.'

def load_array(arr):
    """ "
    Loads an array into a cicruit

    Upon measuring with Qiskit, the result will look like: |value> ⊗ |index>

    Parameters
    ----------

    qc: QuantumCircuit
        Target quantum circuit, on which the array will be loaded

    arr: List[int]
        Array to load
    """
    arr_length = len(arr)
    if arr_length > 0:
        index_qubits = ceil(log2(arr_length))
        value_qubits = ceil(log2(max(arr) + 1))
        qc = QuantumCircuit(ceil(log2(arr_length)) + ceil(log2(max(arr) + 1)))
    else:
        return QuantumCircuit()
    control_indices = []
    assert qc.num_qubits == index_qubits + value_qubits
    for q, o in enumerate(arr):
        bin_q = format(q, f"0{index_qubits}b")[::-1]  # index
        bin_o = format(o, f"0{value_qubits}b")[::-1]  # output
        for index1, char1 in enumerate(bin_o):
            if char1 == "1":
                for index2, char2 in enumerate(bin_q):
                    if char2 == "0":
                        control_indices.append(index2)
                for ones in control_indices:
                    qc.x(ones)
                qc.mcx([xyz for xyz in range(index_qubits)], index1 + index_qubits)
                for ones in control_indices:
                    qc.x(ones)
                control_indices = []
    return qc

def oracle_arr(value: int, arr: list[int]) -> QuantumCircuit:
    arr_length = len(arr)
    if arr_length > 0:
        index_qubits = ceil(log2(arr_length))
        value_qubits = ceil(log2(max(arr) + 1))
        qc = QuantumCircuit(ceil(log2(arr_length)) + ceil(log2(max(arr) + 1)))
        val_bin = format(value, f"0{value_qubits}b")
    else:
        return QuantumCircuit()

    n_idx = []

    qc.append(load_array(arr), range(index_qubits + value_qubits))

    for index, char in enumerate(reversed(val_bin)):
        if char == "0":
            qc.x(index + index_qubits)
            n_idx.append(index)
    last_qubit_idx = index_qubits + value_qubits - 1
    qc.h(last_qubit_idx)
    qc.mcx(
        [k for k in range(index_qubits, last_qubit_idx)],
        last_qubit_idx,
    )
    qc.h(last_qubit_idx)
    for x_value in n_idx:
        qc.x(x_value + index_qubits)

    qc.append(load_array(arr).inverse(), range(index_qubits + value_qubits))

    return qc

def c_amod15(a, power):
	"""Controlled multiplication by a mod 15"""
	if a not in [2, 7, 8, 11, 13]:
		raise ValueError("'a' must be 2,7,8,11 or 13")
	U = QuantumCircuit(4)
	for iteration in range(power):
		if a in [2, 13]:
			U.swap(0, 1)
			U.swap(1, 2)
			U.swap(2, 3)
		if a in [7, 8]:
			U.swap(2, 3)
			U.swap(1, 2)
			U.swap(0, 1)
		if a == 11:
			U.swap(1, 3)
			U.swap(0, 2)
		if a in [7, 11, 13]:
			for q in range(4):
				U.x(q)
	U = U.to_gate()
	U.name = "%i^%i mod 15" % (a, power)
	c_U = U.control()
	return c_U

def qft_dagger(n):
	"""n-qubit QFTdagger the first n qubits in circ"""
	qc = QuantumCircuit(n)
	# Don't forget the Swaps!
	for qubit in range(n // 2):
		qc.swap(qubit, n - qubit - 1)
	for j in range(n):
		for m in range(j):
			qc.cp(-np.pi / float(2 ** (j - m)), m, j)
		qc.h(j)
	qc.name = "QFT†"
	return qc

def split_measurements(circuit: QuantumCircuit):
    """
    Split the measurements in the circuit into a list (to add back later)

    returns new circuit and list of measurements

    """
    new_circuit = QuantumCircuit(circuit.qubits, circuit.clbits)
    measurements = []

    for instr, qargs, cargs in circuit.data:
        if instr.name == "measure":
            measurements.append((instr, qargs, cargs))
        else:
            new_circuit.append(instr, qargs, cargs)

    return new_circuit, measurements

def split_circuit(qc: QuantumCircuit, n: int):
    registers = []
    remaining_qubits = qc.n_qubits
    qubits_per_circ = int(qc.n_qubits/n)
    for i in range(n):
        reg_len = min(qubits_per_circ, remaining_qubits)
        q_reg = QuantumRegister(reg_len)
        c_reg = ClassicalRegister(reg_len)
        sub_qc = QuantumCircuit(q_reg, c_reg)

        for inst, (q_reg, q_index), (c_index, c_reg) in qc:
            if i * qubits_per_circ <= q_index <= (i+1)*qubits_per_circ:
                sub_qc.append(inst, q_reg[q_index], c_reg[c_index])

        registers.append(q_reg)

def compile(self):
    temp_data_list = list(self.env_qs.data)

    self.env_qs.data = []
    super().compile()

    compiled_qc = self.env_qs.clearcopy()

    compiled_qc.data = list(self.env_qs.data)

    self.env_qs.clear_data()
    self.env_qs.data.extend(temp_data_list)

    if len(compiled_qc.data) == 0:
        self.instruction = None
        return None

    qc = QuantumCircuit(len(self.env_qs.qubits), len(self.env_qs.clbits))

    translation_dic = {
        self.env_qs.qubits[i]: qc.qubits[i] for i in range(len(qc.qubits))
    }
    translation_dic.update(
        {self.env_qs.clbits[i]: qc.clbits[i] for i in range(len(qc.clbits))}
    )

    qubit_set = set([])

    dealloc_list = []
    alloc_list = []

    for instr in compiled_qc.data:
        qubit_set = qubit_set.union(
            set([translation_dic[qb] for qb in instr.qubits])
        )
        if instr.op.name == "qb_dealloc":
            instr.qubits[0].allocated = True
            # dealloc_list.append(instr)
            dealloc_list.append(instr.qubits[0])
            continue
        if instr.op.name == "qb_alloc":
            alloc_list.append(instr.qubits[0])
            try:
                dealloc_list.remove(instr.qubits[0])
            except ValueError:
                pass
            continue

        qc.append(
            instr.op,
            [translation_dic[qb] for qb in instr.qubits],
            [translation_dic[cb] for cb in instr.clbits],
        )

    idle_qubit_list = list(set(qc.qubits) - qubit_set)

    for j in range(len(idle_qubit_list)):
        for i in range(len(qc.qubits)):
            if qc.qubits[i].identifier == idle_qubit_list[j].identifier:
                qc.qubits.pop(i)
                break

    translation_dic_inv = {
        translation_dic[key]: key for key in translation_dic.keys()
    }

    gate = qc.to_gate(self.name)

    alloc_list = list(set(alloc_list))
    for qb in alloc_list:
        self.env_qs.append(QubitAlloc(), [qb])

    self.env_qs.append(
        gate,
        [translation_dic_inv[qb] for qb in qc.qubits],
        [translation_dic_inv[cb] for cb in qc.clbits],
    )
    self.instruction = self.env_qs.data[-1]

    dealloc_list = list(set(dealloc_list))
    for qb in dealloc_list:
        self.env_qs.append(QubitDealloc(), [qb])
        qb.allocated = False

def get_permutation_circuit(self, permutation: dict[str, str]) -> QuantumCircuit:
    existing_states = np.array([list(map(int, key)) for key in permutation])
    target_states = np.array([list(map(int, val)) for val in permutation.values()])
    qc = QuantumCircuit(existing_states.shape[1] + 1)
    for i in range(existing_states.shape[0]):
        if np.all(existing_states[i, :] == target_states[i, :]):
            continue
        diff_inds = np.where(existing_states[i, :] != target_states[i, :])[0]
        control_inds, control_vals, interaction_ind = find_min_control_set_2(existing_states, i, diff_inds)
        cx_target_inds = diff_inds[diff_inds != interaction_ind]
        self.build_cx_mcx_pattern(qc, interaction_ind, cx_target_inds, control_inds, control_vals)
        existing_states[i, :] = target_states[i, :]
    return qc.reverse_bits()

def multi_x_gate(num_targets, num_ctrl):
    qc = QuantumCircuit(num_targets, name="X")
    for i in range(num_targets):
        qc.x(i)
    return qc.to_gate().control(num_ctrl)

def s2c(x,y,c):
    num_bits = len(x)

    qc = QuantumCircuit(y, c, name="S2C")

    sum_reg = list(y) + [c[0]]  # q = y0 ... yn,c


    for i in range(1, num_bits + 1):
        controls = sum_reg[:i]                 
        targets = sum_reg[i:]                  
        if targets:
            gate = multi_x_gate(num_targets=len(targets), num_ctrl=len(controls))
            qc.append(gate, controls + targets)

        if i != num_bits:
            qc.x(sum_reg[i-1])
        elif num_bits > 1:
            qc.x(sum_reg[0:num_bits - 1])

    qc = qc.to_gate()

    return qc

def smalls2c(y):
    num_bits = len(y)
    qc = QuantumCircuit(y, name="S2C")

