    qc = qc.to_gate().control()

    return qc

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    # Write your code here:

    if n == 1:
        if L == 1:
            qc.z(0)
        else:
            assert L == 2
        return qc

    qr = qc.qregs[0]
    for i in range(L):
        gate = ZGate()
        for j in range(n):
            if i & (1 << j) == 0:
                qc.x(qr[j])
        qc.append(ZGate().control(n - 1), qr)
        for j in range(n):
            if i & (1 << j) == 0:
                qc.x(qr[j])

    return qc

def to_circuit(self) -> QuantumCircuit:

    pauli = self.primitive.to_label()[-self.num_qubits :]
    phase = self.primitive.phase

    qc = QuantumCircuit(self.num_qubits)
    if pauli == "I" * self.num_qubits:
        qc.global_phase = -phase * pi / 2
        return qc

    if self.num_qubits == 1:
        if pauli != "I":
            gate = {"X": XGate, "Y": YGate, "Z": ZGate}[pauli]
            qc.append(gate(), [0])
    else:
        gate = PauliGate(pauli)
        qc.append(gate, range(self.num_qubits))

    if not phase:
        return qc

    qc.global_phase = -phase * pi / 2
    return qc

def __init__(self, num_classes, num_qubits=7, num_layers=3):
	super().__init__()
	self.num_qubits = num_qubits
	self.num_classes = num_classes

	# 1. Create the parameterized VQC circuit ONCE
	self.vqc_circuit = QuantumCircuit(num_qubits)
	self.thetas = ParameterVector("theta", length=3 * num_qubits * num_layers)

	# Apply the brickwork architecture to the VQC circuit
	for layer in range(num_layers):
		offset = layer * 3 * num_qubits
		for i in range(num_qubits):
			self.vqc_circuit.rx(self.thetas[offset + i], i)
		for i in range(num_qubits):
			self.vqc_circuit.ry(self.thetas[offset + num_qubits + i], i)
		for i in range(num_qubits):
			self.vqc_circuit.rz(self.thetas[offset + 2*num_qubits + i], i)

		# Alternating brickwork entanglement
		if layer % 2 == 0:
			for i in range(0, num_qubits - 1, 2):
				self.vqc_circuit.cx(i, i + 1)
		else:
			for i in range(1, num_qubits - 1, 2):
				self.vqc_circuit.cx(i, i + 1)
			self.vqc_circuit.cx(num_qubits - 1, 0)

	# 2. Register the quantum weights directly as a native PyTorch Parameter.
	# Initialized from -pi to pi so the gates are fully active!
	self.quantum_weight = nn.Parameter(
		torch.empty(len(self.thetas)).uniform_(-np.pi, np.pi)
	)

	# 3. Classical head
	self.classical_head = nn.Linear(2**num_qubits, num_classes)

def _precompute_batch(batch_idx, batch_X, batch_y):
	batch_matrices = []

	for img in batch_X:
		qc = geqie.encode(
			frqi.init_function,
			frqi.data_function,
			frqi.map_function,
			img,
		)

		flat_qc = qc.decompose()
		while len(flat_qc.data) != len(flat_qc.decompose().data):
			flat_qc = flat_qc.decompose()

		pure_qc = QuantumCircuit(flat_qc.num_qubits)
		for instruction in flat_qc.data:
			op_name = (
				instruction.operation.name
				if hasattr(instruction, "operation")
				else instruction[0].name
			)

			if op_name not in ["reset", "measure", "barrier"]:
				pure_qc.append(instruction)

		unitary_matrix = np.array(Operator(pure_qc).data, dtype=np.complex128)
		batch_matrices.append(unitary_matrix)

	return batch_idx, batch_matrices, np.array(batch_y)

def test_statevector_readout_correct_dimension(circuit_class, gates=almost_noise_free_gates):
    """Each saved statevector should have dimension 2^nqubits."""
    for nqubits in [2, 3]:
        # Arrange
        qc = QuantumCircuit(nqubits, nqubits)
        qc.barrier(label="save_sv_0")
        qc.measure(range(nqubits), range(nqubits))

        # Act
        result =_run_sim(_transpile(qc, nqubits), nqubits, gates, circuit_class, shots=3)

        # Assert
        for shot_readout in result["statevector_readout"]:
            for label, sv in shot_readout:
                assert len(sv) == 2 ** nqubits, (
                    f"Expected statevector of length {2**nqubits} for "
                    f"{nqubits} qubits but got {len(sv)}"
                )

def test_multiple_barriers_labels_are_correct(circuit_class, gates=almost_noise_free_gates):
    """Labels in the readout should match the barrier labels in the circuit."""
    # Arrange
    nqubits = 2
    n_barriers = 3
    qc = QuantumCircuit(nqubits, nqubits)
    for c in range(n_barriers):
        qc.barrier(label=f"save_sv_{c}")
    qc.measure(range(nqubits), range(nqubits))

    # Act
    result =_run_sim(_transpile(qc, nqubits), nqubits, gates, circuit_class, shots=3)
    expected_labels = {f"save_sv_{c}" for c in range(n_barriers)}

    # Assert
    for shot_readout in result["statevector_readout"]:
        found_labels = {lbl for lbl, _ in shot_readout}
        assert found_labels == expected_labels, (
            f"Expected labels {expected_labels} but found {found_labels}"
        )

def _qiskit_statevectors(qc_with_saves, save_labels):
    """Run the circuit on Qiskit's AerSimulator and return a dict of
    {label: statevector} for each save_statevector instruction.

    We insert Qiskit's save_statevector instructions at the same points as
    our barrier(label="save_sv_*") markers, then read back the snapshots.
    """
    sim = AerSimulator(method="statevector")
    # AerSimulator needs save_statevector instructions injected at barrier points
    # Rebuild the circuit replacing each save barrier with save_statevector

    # Find the indices of qubits actually used in the transpiled circuit
    used_indices = sorted({
        qc_with_saves.find_bit(q).index
        for op in qc_with_saves.data
        for q in op.qubits
        if op.operation.name not in ("barrier", "delay")
    })
    n_used = len(used_indices)
    idx_map = {old: new for new, old in enumerate(used_indices)}

    new_qc = QuantumCircuit(n_used, qc_with_saves.num_clbits)

    for op in qc_with_saves.data:
        name = op.operation.name
        if name == "barrier" and op.operation.label in save_labels:
            new_qc.save_statevector(label=op.operation.label, pershot=False)
        elif name == "delay":
            qubit_idx = qc_with_saves.find_bit(op.qubits[0]).index
            if qubit_idx in idx_map:
                qargs = [new_qc.qubits[idx_map[qubit_idx]]]
                new_qc.append(op.operation, qargs, [])
        else:
            qargs = [qc_with_saves.find_bit(q).index for q in op.qubits]
            cargs = [qc_with_saves.find_bit(c).index for c in op.clbits]
            new_qc.append(op.operation, qargs, cargs)

    job = sim.run(new_qc, shots=1)
    result = job.result()
    data = result.data(0)
    return {label: np.array(data[label]) for label in save_labels}

def gen_ext_field_layer(n, hz):
    qc = QuantumCircuit(n)
    for q in range(n):
        qc.rz(-hz[q], q)
    return qc

def gen_odd_coupling_layer(n, Jxx, Jz, J):
    qc = QuantumCircuit(n)
    for q in range(0, n, 2):
        trotter_step(qc, q, q + 1, J[q] * Jxx, J[q] * Jz)
    return qc

def gen_even_coupling_layer(n, Jxx, Jz, J):
    qc = QuantumCircuit(n)
    for q in range(1, n - 1, 2):
        q0 = q
        q1 = (q + 1) % n
        if q1 < q0:
            qc.barrier()
        trotter_step(qc, q0, q1, J[q0] * Jxx, J[q0] * Jz)
    return qc

def load_circuit_from_json(filepath):
    """从JSON文件加载量子电路"""
    with open(filepath, 'r', encoding='utf-8') as f:
        data = json.load(f)

    n_qubits = data.get('n_qubits', 4)
    qc = QuantumCircuit(n_qubits)

    for gate_info in data.get('gates', []):
        gate_name = gate_info['gate'].lower()
        qubits = gate_info.get('qubits', [0])
        params = gate_info.get('params', [])

        if gate_name == 'h':
            qc.h(qubits[0])
        elif gate_name == 't':
            qc.t(qubits[0])
        elif gate_name == 'tdg':
            qc.tdg(qubits[0])
        elif gate_name == 's':
            qc.s(qubits[0])
        elif gate_name == 'sdg':
            qc.sdg(qubits[0])
        elif gate_name == 'x':
            qc.x(qubits[0])
        elif gate_name == 'y':
            qc.y(qubits[0])
        elif gate_name == 'z':
            qc.z(qubits[0])
        elif gate_name == 'cx':
            qc.cx(qubits[0], qubits[1])
        elif gate_name == 'cz':
            qc.cz(qubits[0], qubits[1])
        elif gate_name == 'rx':
            qc.rx(params[0], qubits[0])
        elif gate_name == 'ry':
            qc.ry(params[0], qubits[0])
        elif gate_name == 'rz':
            qc.rz(params[0], qubits[0])

    return qc, data.get('description', '')

def prop_and(n, bits, flags, init_out):
    # check AND gate.
    test = "AND"
    bits, flags = normalize_bits_flags(n, bits, flags)
    assume(any(f != 0 for f in flags))

    trial = {"n": n, "bits": bits, "flags": flags, "init_out": init_out}

    try:
        qc = QuantumCircuit(n + 1)
        for i, b in enumerate(bits):
            if b:
                qc.x(i)
        if init_out:
            qc.x(n)
        qc.append(AND(n, flags=flags), range(n + 1))
    except Exception as e:
        LOGGER.log(test, "constructor_error", {**trial, "error": str(e)})
        assume(False)

    out = run_basis_output_bitstring_le(qc)
    assert out[:n] == "".join(str(b) for b in bits)
    assert int(out[n]) == (init_out ^ oracle_and(bits, flags))

    LOGGER.log_pass(test, trial)

