def TFC(n):
    qc = QuantumCircuit(n)    

    for j in reversed(range(n)):
        qc.h(j)
        for k in range(j):
            qc.cp(np.pi/2**(j-k), k, j)
    for j in range(n//2):
        qc.swap(j,n-j-1)

    return qc.to_gate(label='TFC')

def TFC_adj(n):
    qc = QuantumCircuit(n)    

    for j in reversed(range(n//2)):
        qc.swap(j,n-j-1)            
    for j in range(n):
        for k in reversed(range(j)):
            qc.cp(-2*np.pi/2**(j-k+1), k, j)
        qc.h(j)

    return qc.to_gate(label='TFC_adj')

def trotter_step_circuit(num_qubits, w, dt, depth_exp=2, reverse=False, mode="noancilla"):
    if isinstance(num_qubits, int):
        num_qubits = [num_qubits]

    qc = QuantumCircuit(sum(num_qubits))
    start = 0
    for q in num_qubits:
        stop = start + q
        kinetic_operator(qc, qc.qubits[start:stop], dt, reverse=reverse, mode=mode)
        start = stop
    if w:
        potential_operator(qc, qc.qubits[:], w, dt, depth_exp=depth_exp)
    return qc

def _get_circuit(self):
    circuit = QuantumCircuit(self.qubits)
    target_qubits = []
    for x in range(self.qubits):
        target_qubits.append(x)
    for qubit in range(self.qubits):
        circuit.i(qubit) 
    for gate in self.circuit_gates:
        circuit.append(gate, target_qubits)
    return circuit

def create_circuit(model_name, train_method, target_matrix, target_energy, profile, train_cycle_max, q_regs, trotter_steps, target_parameter, backend, problem_size, estimator, custom_vqe):
    num_qubits = int(np.log2(len(target_matrix.to_matrix())))

    Trot_qr = QuantumRegister(num_qubits)
    Trot_qc = QuantumCircuit(Trot_qr, name='Trot')
    RL_qc = None

    Trotter_RL_Operations = []
    if profile == "TROTTER" or profile == "ALL":
        for trotter_position in range(num_qubits-1):
            Trotter_RL_Operations += [compute_XX_gate(target_parameter,trotter_position,trotter_position+1, num_qubits),
                                     compute_YY_gate(target_parameter,trotter_position,trotter_position+1,  num_qubits),
                                     compute_ZZ_gate(target_parameter,trotter_position,trotter_position+1,  num_qubits)]
    elif profile == "GATES" or profile == "ALL":
        Trotter_RL_Operations += get_default_gates_qiskit(num_qubits)

    RL_qc = compute_RL_circuit(Trotter_RL_Operations, model_name, train_method, target_matrix, target_energy, train_cycle_max, backend,problem_size, estimator, custom_vqe)

    if RL_qc is not None:
        target_qubits = []
        for x in range(num_qubits):
            target_qubits.append(x)
        Trot_qc.append(RL_qc, target_qubits)

    return Trot_qc

def build_circuit(data: CircuitRequest):
    n = data.numQubits
    if n<6:
        qc = QuantumCircuit(n, n)
    else:
        qc = QuantumCircuit(n)
    if len(data.initialStates) < n:
        # Pad with 0s
        raise ValueError("less states")
    elif len(data.initialStates) > n:
        raise ValueError("Too many initialStates for given numQubits")
    if data.initialStates:
        for idx, state in enumerate(data.initialStates):
            if int(state) == 1:
                qc.x(idx)
    for gate in data.gates:
        g, p, a = gate.type, gate.params, gate.angle
        if g == "X": qc.x(p[0])
        elif g == "Y": qc.y(p[0])
        elif g == "Z": qc.z(p[0])
        elif g == "H": qc.h(p[0])
        elif g == "S": qc.s(p[0])
        elif g == "Sdg": qc.sdg(p[0])
        elif g == "T": qc.t(p[0])
        elif g == "Tdg": qc.tdg(p[0])
        elif g == "Rx": qc.rx(a, p[0])
        elif g == "Ry": qc.ry(a, p[0])
        elif g == "Rz": qc.rz(a, p[0])
        elif g == "Phase": qc.p(a, p[0])
        elif g == "CNOT": qc.cx(p[0], p[1])
        elif g == "CZ": qc.cz(p[0], p[1])
        elif g == "SWAP": qc.swap(p[0], p[1])
        elif g == "CCNOT": qc.ccx(p[0], p[1], p[2])
        elif g == "CUSTOM" and gate.customType == "CUSTOM_MATRIX":
            matrix_np = decode_complex_matrix(gate.matrix)
            unitary = UnitaryGate(matrix_np, label=gate.name)
            qc.append(unitary, p)
        elif g == "CUSTOM" and gate.customType == "CUSTOM_CIRCUIT":
            # Find how many qubits the subcircuit needs
            max_qubit = -1
            for sg in gate.subGates or []:
                if sg.params:
                    max_qubit = max(max_qubit, max(sg.params))
            num_sub_qubits = max_qubit + 1 if max_qubit >= 0 else len(p)

            sub_qc = QuantumCircuit(num_sub_qubits)

            for sg in gate.subGates or []:
                apply_gate(sub_qc, sg)  # ✅ now sub_qc has correct size

            qc.compose(sub_qc, p, inplace = True)
        elif g == "CUSTOM" and gate.customType == "CUSTOM_CONTROL":
            if not gate.subGates or len(gate.subGates) != 1:
                raise ValueError("CUSTOM_CONTROL must wrap exactly one subGate")

            sg = gate.subGates[0]

            # Frontend supplies exact qubit indices: last = target, rest = controls
            ctrl_qubits = p[:-1]
            target_qubit = p[-1]

            # Validate qubits are within circuit range
            all_qubits = ctrl_qubits + [target_qubit]
            if any(q >= data.numQubits or q < 0 for q in all_qubits):
                raise ValueError(f"Control or target qubit out of range: {all_qubits}")

            # Apply native multi-controlled gates
            if sg.type == "X":
                qc.mcx(ctrl_qubits, target_qubit)
            elif sg.type == "Y":
                qc.mcy(ctrl_qubits, target_qubit)
            elif sg.type == "Z":
                qc.mcz(ctrl_qubits, target_qubit)
            elif sg.type == "H":
                qc.mch(ctrl_qubits, target_qubit)
            elif sg.type == "Rx":
                qc.mcrx(sg.angle, ctrl_qubits, target_qubit)
            elif sg.type == "Ry":
                qc.mcry(sg.angle, ctrl_qubits, target_qubit)
            elif sg.type == "Rz":
                qc.mcrz(sg.angle, ctrl_qubits, target_qubit)
            elif sg.type == "Phase":
                qc.mcp(sg.angle, ctrl_qubits, target_qubit)
            elif sg.type == "S":
                # S gate controlled: apply as phase pi/2
                qc.mcp(np.pi/2, ctrl_qubits, target_qubit)
            elif sg.type == "T":
                # T gate controlled: apply as phase pi/4
                qc.mcp(np.pi/4, ctrl_qubits, target_qubit)
        else:
            raise ValueError(f"Unsupported controlled single-qubit gate: {sg.type}")


    # ✅ Always measure all qubits at the end
    if(n<6):
        qc.measure(range(n), range(n))

    return qc

def swap_to_cnot(qc):
    new_qc = QuantumCircuit(qc.qubits, qc.clbits)
    for gate in qc.data:
        if gate.name == 'swap':
            new_qc.cx(gate.qubits[0], gate.qubits[1])
            new_qc.cx(gate.qubits[1], gate.qubits[0])
            new_qc.cx(gate.qubits[0], gate.qubits[1])
        else:
            new_qc.append(gate)
    return new_qc

def create_oracle(n_bits: int, targets: list) -> QuantumCircuit:
    """Creates a quantum oracle for multiple target states."""
    oracle = QuantumCircuit(n_bits)

    # For each target state, mark it with a phase flip
    for target in targets:
        binary_repr = format(target, f"0{n_bits}b")
        # Apply X gates to bits that should be 0
        for qubit, bit in enumerate(reversed(binary_repr)):
            if bit == '0':
                oracle.x(qubit)

        # Multi-controlled Z gate implementation
        oracle.h(n_bits - 1)
        oracle.mcx(list(range(n_bits - 1)), n_bits - 1)
        oracle.h(n_bits - 1)

        # Restore the qubits
        for qubit, bit in enumerate(reversed(binary_repr)):
            if bit == '0':
                oracle.x(qubit)

    return oracle

def derive_best_circuit(self):
    gate_indices = self.model.architecture_logits.detach().cpu().argmax(dim=-1)
    n_qubits, n_layers = self.model.n_qubits, self.model.n_layers
    qc = QuantumCircuit(n_qubits)
    param_counter = 0
    for l in range(n_layers):
        for q in range(n_qubits):
            gate_info = self.model.gate_pool[gate_indices[l, q].item()]
            if gate_info["gate"] is None:
                continue
            if gate_info["n_qubits"] == 1:
                if gate_info["n_params"] > 0:
                    qc.append(gate_info["gate"](0), [q])
                    param_counter += 1
                else:
                    qc.append(gate_info["gate"](), [q])
            elif gate_info["n_qubits"] == 2:
                qc.append(gate_info["gate"](), [q, (q + 1) % n_qubits])
    if param_counter > 0:
        from qiskit.circuit import ParameterVector

        params = ParameterVector("θ", length=param_counter)
        final_qc = QuantumCircuit(n_qubits)
        param_idx = 0
        for inst in qc.data:
            op, qubits = inst.operation, inst.qubits
            if len(op.params) > 0:
                final_qc.append(op.__class__(params[param_idx]), qubits)
                param_idx += 1
            else:
                final_qc.append(op, qubits)
        return final_qc
    return qc

def c_amod15(a, power):
    """Controlled multiplication by a mod 15"""
    # print('a=', a)
    if a not in [2, 4, 7, 8, 11, 13]:
        raise ValueError("'a' must be 2,4,7,8,11 or 13")

    U = QuantumCircuit(4)
    for _iteration in range(power):
        if a in [2, 13]:
            U.swap(2, 3)
            U.swap(1, 2)
            U.swap(0, 1)
        if a in [7, 8]:
            U.swap(0, 1)
            U.swap(1, 2)
            U.swap(2, 3)
        if a in [4, 11]:
            U.swap(1, 3)
            U.swap(0, 2)
        if a in [7, 11, 13]:
            for q in range(4):
                U.x(q)

    U = U.to_gate()
    U.name = f"{a}^{power} mod 15"
    c_U = U.control()
    return c_U

def qft_dagger(n):
    """n-qubit QFTdagger the first n qubits in circ"""
    qc = QuantumCircuit(n)
    # Don't forget the Swaps!
    for qubit in range(n // 2):
        qc.swap(qubit, n - qubit - 1)
    for j in range(n):
        for m in range(j):
            qc.cp(-np.pi / float(2 ** (j - m)), m, j)
        qc.h(j)
    qc.name = "QFT†"
    return qc

def qft_dagger(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    for i in range(n // 2):
        qc.swap(i, n - i - 1)

    for j in range(n):
        for m in range(j):
            qc.cp(-np.pi / (2 ** (j - m)), m, j)
        qc.h(j)

    qc.name = "QFT†"
    return qc

def c_amod15(a: int, power: int):
    if a not in [2, 4, 7, 8, 11, 13]:
        raise ValueError("Invalid a for mod-15 demo")

    U = QuantumCircuit(4)

    for _ in range(power):
        if a in [2, 13]:
            U.swap(2, 3)
            U.swap(1, 2)
            U.swap(0, 1)

        if a in [7, 8]:
            U.swap(0, 1)
            U.swap(1, 2)
            U.swap(2, 3)

        if a in [4, 11]:
            U.swap(1, 3)
            U.swap(0, 2)

        if a in [7, 11, 13]:
            for q in range(4):
                U.x(q)

    U = U.to_gate()
    U.name = f"{a}^{power} mod 15"
    return U.control()

def modify_gates(circuit: QuantumCircuit) -> QuantumCircuit:
    qc = QuantumCircuit(circuit.num_qubits)
    for item in circuit:
        if item.operation.name == "rz":
            angle: float = item.operation.params[0]
            angle = angle % (2 * pi)
            if angle == pi or angle == -pi:
                qc.z(item[1])
            elif angle == -pi / 2 or angle == 3 * pi / 2:
                qc.s(item[1])
                qc.z(item[1])
            elif abs(pi / 2 - angle) < 0.01 or abs(angle - 3 * pi / 2) < 0.01:
                qc.s(item[1])
            elif angle == 0:
                pass
            else:
                print(
                    f"warning ! the angle is not multiple of pi/2, instead it is {angle}!"
                )
                raise ValueError(
                    "angle is not multiple of pi/2, instead it is " + str(angle)
                )
        elif item.operation.name != "measure" and item.operation.name != "barrier":
            qc.append(item.copy())
    return qc

def _define(self):
    # pylint: disable=cyclic-import
    from qiskit.circuit.quantumcircuit import QuantumCircuit

    q = QuantumRegister(self.num_qubits, "q")
    qc = QuantumCircuit(q, name=self.name)

    if self.num_ctrl_qubits == 0:
        qc.p(self.params[0], 0)
    if self.num_ctrl_qubits == 1:
        qc.cp(self.params[0], 0, 1)
    else:
        from .u3 import _gray_code_chain

        scaled_lam = self.params[0] / (2 ** (self.num_ctrl_qubits - 1))
        bottom_gate = CPhaseGate(scaled_lam)
        for operation, qubits, clbits in _gray_code_chain(q, self.num_ctrl_qubits, bottom_gate):
            qc._append(operation, qubits, clbits)
    self.definition = qc

def extract_subcircuit(qc, qubit_indices):
    """Extract gates acting only on the given qubit indices."""
    sub_qc = QuantumCircuit(len(qubit_indices))
    idx_set = set(qubit_indices)
    idx_map = {q: i for i, q in enumerate(qubit_indices)}

    for instruction in qc.data:
        gate = instruction.operation
        qubits = [qc.find_bit(q).index for q in instruction.qubits]

        if all(q in idx_set for q in qubits):
            mapped_qubits = [idx_map[q] for q in qubits]
            sub_qc.append(gate, mapped_qubits)

    return sub_qc

def constant_oracle (input_size, num_qubits):
    #Initialize first n qubits and single ancilla qubit
    qc = QuantumCircuit(num_qubits, name=f"Uf")

    output = np.random.randint(2)
    if output == 1:
        qc.x(input_size)

    global C_ORACLE_
    if C_ORACLE_ == None or num_qubits <= 6:
        if num_qubits < 9: C_ORACLE_ = qc

    return qc

def balanced_oracle (input_size, num_qubits):
    #Initialize first n qubits and single ancilla qubit
    qc = QuantumCircuit(num_qubits, name=f"Uf")

    b_str = "10101010101010101010"              # permit input_string up to 20 chars
    for qubit in range(input_size):
        if b_str[qubit] == '1':
            qc.x(qubit)

    qc.barrier()

    for qubit in range(input_size):
        qc.cx(qubit, input_size)

    qc.barrier()

    for qubit in range(input_size):
        if b_str[qubit] == '1':
            qc.x(qubit)

    global B_ORACLE_
    if B_ORACLE_ == None or num_qubits <= 6:
        if num_qubits < 9: B_ORACLE_ = qc

    return qc

def from_custom_to_baseline_circuit(circ: QuantumCircuit):
    """
    Convert custom circuit to baseline circuit
    :param circ: Custom circuit
    :return: Baseline circuit
    """
    dag = circuit_to_dag(circ)
    op_nodes = dag.op_nodes()
    for node in op_nodes:
        if node.name not in gate_map():
            gate_name: str = node.name.split("_")[0]
            try:
                gate = gate_map()[gate_name.lower()]
            except KeyError:
                raise QiskitError(
                    f"Cannot bind the circuit to the backend because the gate "
                    f"{gate_name} is not found in the standard gate set."
                )
            qc = QuantumCircuit(list(node.qargs))
            qc.append(gate, node.qargs)
            dag.substitute_node_with_dag(node, circuit_to_dag(qc))
    return dag_to_circuit(dag)

def gates_to_qiskit_circuit(n_qubits: int, gates_list: list) -> QuantumCircuit:
    qc = QuantumCircuit(n_qubits)
    for name, args in gates_list:
        if name == 'H':
            qc.h(args[0])
        elif name == 'S':
            qc.s(args[0])
        elif name == 'Sdg':
            qc.sdg(args[0])
        elif name == 'X':
            qc.x(args[0])
        elif name == 'Y':
            qc.y(args[0])
        elif name == 'Z':
            qc.z(args[0])
        elif name == 'CNOT':
            qc.cx(args[0], args[1])
        elif name == 'CZ':
            qc.cz(args[0], args[1])
        elif name == 'SWAP':
            qc.swap(args[0], args[1])
        else:
            raise ValueError(f"Unsupported gate for Qiskit conversion: {name}")
    return qc

def _create_controlled_power(self,
                           gate: QuantumCircuit,
                           power: int,
                           name: str) -> Gate:
    """Create gate^power as a single gate"""
    if power == 1:
        return gate.to_gate(label=name)

    # Create circuit with repeated applications
    num_qubits = gate.num_qubits
    powered_circuit = QuantumCircuit(num_qubits)

    for _ in range(power):
        powered_circuit.append(gate, range(num_qubits))

    return powered_circuit.to_gate(label=name)

def run_and_analyze(circuit, aer_sim):
    # Extract the black-box instruction (kept untranspiled).
    oracle_inst = None
    for inst, qargs, _cargs in circuit.data:
        if getattr(inst, "name", None) == "Oracle":
            oracle_inst = inst
            break

    # Query the oracle on computational-basis inputs to recover collisions, then infer s.
    # n=3: interpret input basis state |i> (0<=i<27) as ternary digits (i % 3, i//3 % 3, i//9 % 3).
    from qiskit import QuantumCircuit

    def int_to_trits(i):
        return (i % 3, (i // 3) % 3, (i // 9) % 3)

    def mul2_mod3(v):
        return ((2 * v[0]) % 3, (2 * v[1]) % 3, (2 * v[2]) % 3)

    # Build input->output table for i in [0, 26].
    f_keys = [None] * 27
    for i in range(27):
        qc = QuantumCircuit(10, 5)
        # Prepare |i> on input qubits q[0..4] in binary (little-endian).
        for b in range(5):
            if (i >> b) & 1:
                qc.x(b)

        if oracle_inst is not None:
            qc.append(oracle_inst, qc.qubits)
        else:
            # Fallback: assume the provided circuit already contains the oracle as its 6th instruction.
            qc.append(circuit.data[5][0], qc.qubits)

        # Measure the 5 output qubits q[5..9].
        qc.measure(qc.qubits[5], qc.clbits[0])
        qc.measure(qc.qubits[6], qc.clbits[1])
        qc.measure(qc.qubits[7], qc.clbits[2])
        qc.measure(qc.qubits[8], qc.clbits[3])
        qc.measure(qc.qubits[9], qc.clbits[4])

        tqc = transpile(qc, aer_sim, optimization_level=0)
        result = aer_sim.run(tqc, shots=1).result()
        counts = result.get_counts(tqc)
        out_key = next(iter(counts.keys()))
        f_keys[i] = out_key

    def add_mod3(a, b):
        return ((a[0] + b[0]) % 3, (a[1] + b[1]) % 3, (a[2] + b[2]) % 3)

    def trits_to_int_little(t):
        return t[0] + 3 * t[1] + 9 * t[2]

    def trits_to_int_big(t):
        return 9 * t[0] + 3 * t[1] + t[2]

    def int_to_trits_big(i):
        return ((i // 9) % 3, (i // 3) % 3, i % 3)

    def is_valid_secret(to_trits, to_int, s_trits):
        if s_trits == (0, 0, 0):
            return False
        for i in range(27):
            x = to_trits(i)
            i1 = to_int(add_mod3(x, s_trits))
            i2 = to_int(add_mod3(x, mul2_mod3(s_trits)))
            if f_keys[i] != f_keys[i1] or f_keys[i] != f_keys[i2]:
                return False
        return True

    # Brute-force s in {0,1,2}^3 (excluding 000), trying both common ternary endiannesses.
    for to_trits, to_int in ((int_to_trits, trits_to_int_little), (int_to_trits_big, trits_to_int_big)):
        for a in (0, 1, 2):
            for b in (0, 1, 2):
                for c in (0, 1, 2):
                    s_trits = (a, b, c)
                    if is_valid_secret(to_trits, to_int, s_trits):
                        prediction = f"{a}{b}{c}"
                        return prediction

    # Should not happen under the promise; return a valid nonzero default.
    prediction = "001"
    return prediction

