def rx_gradually_c(n) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    angle = pi
    for level in range(1, n + 1):
        current_angle = angle / (2 ** (level - 1))
        for i in range(level):
            qc.rx(current_angle, i)
    return qc

def track(self, qc, compose=True):

    if compose:
        # create a copy of the current circuit internally

        self.current_qc = QuantumCircuit(QuantumRegister(self.n_qubits), AncillaRegister(self.n_ancillae))

        # compose the circuit
        if type(qc) is list:

            for circuit in qc:
                self.current_qc.compose(circuit, inplace=True)

        elif type(qc) is QuantumCircuit:
            self.current_qc.compose(qc, inplace=True)
        else:
            print('Error: type of qc is', type(qc))
            return
    else:
        self.current_qc = qc

    # track the state        
    self._statevecs.append(self._statevecs[-1].evolve(self.current_qc))

    del self.current_qc

def your_evolution(p, num_qubits, num_ancillae):

    # implement yout evolution here
    qc = QuantumCircuit(num_qubits+num_ancillae)
    if p == 1:
        qc.h(range(num_qubits))
    if p == 2:
        qc.h(range(num_qubits))
        qc.x(range(num_qubits, num_qubits+num_ancillae))
    if p == 3:
        qc.x( 3)
    if p == 4:
        qc.x(2)

    return qc

def build_bitstring_phase_oracle_le(target_le: str) -> QuantumCircuit:
    """Phase oracle: flip sign of |target_le| (LE)."""
    n = len(target_le)
    qc = QuantumCircuit(n, name=f"U|{target_le}>")
    for i, b in enumerate(target_le):
        if b == '0':
            qc.x(i)
    if n == 1:
        qc.z(0)
    else:
        qc.h(n - 1)
        qc.mcx(list(range(n - 1)), n - 1)
        qc.h(n - 1)
    for i, b in enumerate(target_le):
        if b == '0':
            qc.x(i)
    return qc

def circuito_payoff(self):
    qc = self._QuantumCircuit(self.pq.n_qubits + 1)
    qc.compose(self.dist, range(self.pq.n_qubits), inplace=True)

    # Payoff pronto se disponível; senão LinearAmplitudeFunction
    if EuropeanCallExpectedValue is not None and _PAYOFF_MODE == "finance":
        try:
            payoff = EuropeanCallExpectedValue(
                num_state_qubits=self.pq.n_qubits,
                strike_price=self.pm.K,
                rescaling_factor=self.pq.fator_reescala,
                bounds=(self.pq.low, self.pq.high),
            )
        except TypeError:
            payoff = EuropeanCallExpectedValue(
                strike_price=self.pm.K,
                rescaling_factor=self.pq.fator_reescala,
                bounds=(self.pq.low, self.pq.high),
            )
        qc.compose(payoff, range(self.pq.n_qubits + 1), inplace=True)
    else:
        try:
            from qiskit.circuit.library import LinearAmplitudeFunction
        except Exception:
            # último fallback: step linear manual simples (digital)
            # marca S>=K com prob ~ min((S-K)/R,1)
            grid = np.linspace(self.pq.low, self.pq.high, 2**self.pq.n_qubits)
            k_idx = np.searchsorted(grid, self.pm.K, side="right")
            alvo = self.pq.n_qubits
            for idx, s_val in enumerate(grid):
                if idx < k_idx:
                    continue
                ganho = max(s_val - self.pm.K, 0.0) / max(self.pq.fator_reescala, 1e-9)
                ganho = max(0.0, min(ganho, 1.0))
                theta = 2*np.arcsin(np.sqrt(ganho))
                bits = format(idx, f"0{self.pq.n_qubits}b")
                for q, b in enumerate(bits):
                    if b == "0": qc.x(q)
                qc.mcry(float(theta), list(range(self.pq.n_qubits)), alvo)
                for q, b in enumerate(bits):
                    if b == "0": qc.x(q)
        else:
            slope = 1.0 / max(self.pq.fator_reescala, 1e-9)
            offset = -self.pm.K / max(self.pq.fator_reescala, 1e-9)
            f = LinearAmplitudeFunction(
                num_state_qubits=self.pq.n_qubits,
                slope=slope,
                offset=offset,
                domain=(self.pq.low, self.pq.high),
                image=(0, 1),
            )
            qc.compose(f, range(self.pq.n_qubits + 1), inplace=True)

    alvo = self.pq.n_qubits
    return qc, alvo

def add_rz_gates_det(num_qubits, qc, rng, rz_count):
    '''Generate random circ: Helper function. Add a set number of rz gates randomly to the circuit. Returns: QuantumCircuit'''
    qc_dag=circuit_to_dag(qc)
    new_qc=QuantumCircuit(QuantumRegister(num_qubits, name="q"))
    # NUM_RZ=rz_count

    # Each dag has layers and each layer has nodes.
    layers=list(qc_dag.multigraph_layers())
    # Get all the nodes. We will sample from this.
    all_nodes=[]
    for layer in layers:
        for node in layer:
            # We insert rz gates infront of the selected node. We distribute the required number of rzs
            # throught the circuit. We ignore the "in" nodes since they
            # would double the probability of getting an rz in the beginning. 
            # Also we need to add multiqubit nodes as many times as 
            # their number of arguments so that we have a uniform distribution.
            if node.type!="in":
                # print(node.type)
                # print(node.qargs)
                #Need to check that it's not an out node because out node returns an empty list for qargs.
                if node.type!="out" and len(node.qargs)>1:
                    # print(node.qargs)
                    for _ in range(len(node.qargs)):
                        all_nodes.append(node)
                else:
                    all_nodes.append(node)
    # Now we sample.
    if rz_count>len(all_nodes):
        rz_count=len(all_nodes)
        chosen_nodes=all_nodes
    else:
        chosen_nodes=rng.choice(all_nodes, replace=False, size=rz_count).tolist()

    for layer in layers:
        for node in layer:
            # The node is part of the chosen set so add an rz.
            if node in chosen_nodes:
                if node.type == "out":
                    insert_rz_gate(new_qc, rng, 1, node.wire.index)

                elif node.type == "op":
                    add_rz_to_node_det(new_qc, chosen_nodes, node, rng)
            # Only copy op nodes
            if node.type == "op":
                copy_node(new_qc, node)    
    assert dict(new_qc.count_ops())["rz"] == rz_count, "Number of rz's wasn't met."
    return new_qc

def ansatz(n_spins, par, depth):
    count = 0
    qc_ans = QuantumCircuit(n_spins)
    for l in range(depth):
        for i in range(n_spins):
            if l%2 == 0:
                qc_ans.rx(par[count],i)
                count += 1
            if l%2 == 1:
                qc_ans.ry(par[count],i)
                count += 1
        for j in range(n_spins-1):
            #qc_ans.rzz(par[count],j,j+1)
            qc_ans = qc_ans.compose(Rzz(par[count],j, j+1, n_spins))
            count += 1

    if (depth%2 == 1):
        for i in range(n_spins):
            qc_ans.ry(par[count],i)
            count = count +1
    if (depth%2 == 0):
        for i in range(n_spins):
            qc_ans.rx(par[count],i)
            count = count +1

    return qc_ans

def trotter_evolution(n_spins, dt, magnetic_fields):

    qc_trotter = QuantumCircuit(n_spins)

    for i in range(n_spins):
        qc_trotter.rx(2*magnetic_fields[1]*dt, i)
    for  i in range(n_spins-1):
        qc_trotter.rzz(2*dt*magnetic_fields[0], i,i+1)

    return qc_trotter

def get_quantum_only_circuit(self):
    """Return a copy of the circuit with all classical elements and measurements removed."""
    if self.circuit is None:
        raise ValueError("Circuit has not been built yet.")

    # Create a new QuantumCircuit with only quantum registers
    qc_clean = QuantumCircuit(self.time_qr, self.b_qr, self.ancilla_qr)

    # Copy only the quantum instructions
    for instr, qargs, cargs in self.circuit.data:
        if instr.name == 'measure':
            continue  # Skip measurement
        qc_clean.append(instr, qargs, cargs)

    return qc_clean

