def predict_proba_single(enc, x: np.ndarray, params: np.ndarray, *, stages: int, readout: int, shots: Optional[int]) -> float:
    qc = build_qcnn_circuit(enc, x, params, stages)

    if shots is None:
        psi, _ = statevector_from_circuit(qc)
        psi = np.asarray(psi, dtype=complex)
        expZ = _expZ_from_statevector(psi, readout)
        return 0.5 * (1.0 - expZ)

    if not _HAVE_AER:
        raise RuntimeError("qiskit-aer not available (needed for shots-based execution).")

    # NOTE: Some Aer versions can crash (segfault) on circuits that contain
    # StatePreparation-derived blocks unless we force a low-level basis and
    # decompose after transpile.
    basis = ["rz", "sx", "x", "cx"]
    be, bmeta = get_aer_simulator(basis_gates=basis, method="automatic")

    meas = QuantumCircuit(qc.num_qubits, 1)
    meas.compose(qc, inplace=True)
    meas.measure(int(readout), 0)

    # Compile to a safe low-level basis. Avoid passing `basis_gates` together with
    # a `backend` object (Qiskit warns this can invalidate backend timing metadata).
    meas_t = transpile(meas, basis_gates=list(basis), optimization_level=1)

    try:
        meas_t = meas_t.decompose()
    except Exception:
        pass

    try:
        res = be.run(meas_t, shots=int(shots)).result()
    except Exception as e:
        # If Aer GPU execution fails for shot-based sampling, fall back to CPU.
        if bmeta is not None and str(bmeta.get("selected_device", "")).upper() == "GPU":
            be_cpu, _cpu_meta = get_aer_simulator(basis_gates=basis, method="automatic", device="CPU")
            res = be_cpu.run(meas_t, shots=int(shots)).result()
        else:
            raise
    counts = res.get_counts()
    p1 = counts.get("1", 0) / float(shots)
    return float(p1)

def QFFT(n) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    for j in range(n):
        qc.h(j)
        for k in range(j+1,n):
            a = 2*np.pi*j/(2**k)
            #print(str(j) + " " + str(k) + " " + str(a))
            qc.cp(a,k,j)
    for i in range(n//2):
        qc.swap(i,n-i-1)
    return qc

def encode_message(bits, bases):
    message = []
    for i in range(n):
        qc = QuantumCircuit(1,1)
        if bases[i] == 0: # Prepare qubit in Z-basis
            if bits[i] == 0:
                pass
            else:
                qc.x(0)
        else: # Prepare qubit in X-basis
            if bits[i] == 0:
                qc.h(0)
            else:
                qc.x(0)
                qc.h(0)
        qc.barrier()
        message.append(qc)
    return message

