def simple_variational_layer(q: int, params: List[float]) -> QuantumCircuit:
    """A shallow variational layer: Ry on each qubit followed by CZ ring."""
    qc = QuantumCircuit(q)
    idx = 0
    for j in range(q):
        qc.ry(params[idx], j)
        idx += 1
    for j in range(q):
        qc.cz(j, (j + 1) % q)
    return qc

def simon_oracle(secret_string: str) -> QuantumCircuit:
    n = len(secret_string)
    qc = QuantumCircuit(2*n)
    for i in range(n):
        qc.cx(i, i+n)
    for i, bit in enumerate(secret_string):
        if bit == '1':
            qc.cx(0, i+n)
    return qc

def conv_layer(num_qubits: int, param_prefix: str) -> QuantumCircuit:
    qc = QuantumCircuit(num_qubits, name="Convolutional Layer")
    params = ParameterVector(param_prefix, length=num_qubits * 3)
    for i in range(0, num_qubits, 2):
        qc.append(conv_circuit(params[i:i+3]), [i, i+1])
    for i in range(1, num_qubits-1, 2):
        qc.append(conv_circuit(params[i:i+3]), [i, i+1])
    return qc

def build_classifier_circuit(num_qubits: int, depth: int) -> Tuple[QuantumCircuit, Iterable, Iterable, List[SparsePauliOp]]:
    encoding = ParameterVector("x", num_qubits)
    weights = ParameterVector("theta", num_qubits * depth)
    circuit = QuantumCircuit(num_qubits)
    for i, param in enumerate(encoding):
        circuit.rx(param, i)
    idx = 0
    for _ in range(depth):
        for i in range(num_qubits):
            circuit.ry(weights[idx], i)
            idx += 1
        for i in range(num_qubits - 1):
            circuit.cz(i, i + 1)
    observables = [SparsePauliOp("I" * i + "Z" + "I" * (num_qubits - i - 1)) for i in range(num_qubits)]
    return circuit, list(encoding), list(weights), observables

def _conv_layer(num_qubits: int, param_prefix: str) -> QuantumCircuit:
    qc = QuantumCircuit(num_qubits, name="Convolutional Layer")
    params = ParameterVector(param_prefix, length=num_qubits * 3)
    for i in range(0, num_qubits, 2):
        qc.compose(_conv_circuit(params[i : i + 3]), [i, i + 1], inplace=True)
        qc.barrier()
    for i in range(1, num_qubits - 1, 2):
        qc.compose(_conv_circuit(params[i : i + 3]), [i, i + 1], inplace=True)
        qc.barrier()
    return qc

def conv_layer(num_qubits: int, prefix: str) -> QuantumCircuit:
    qc = QuantumCircuit(num_qubits)
    params = ParameterVector(f"{prefix}_conv", length=num_qubits * 3)
    for i in range(0, num_qubits, 2):
        qc.append(conv_circuit(params[i*3:i*3+3]), [i, i+1])
    return qc

def pool_layer(num_qubits: int, prefix: str) -> QuantumCircuit:
    qc = QuantumCircuit(num_qubits)
    params = ParameterVector(f"{prefix}_pool", length=(num_qubits//2) * 3)
    for i in range(0, num_qubits, 2):
        qc.append(pool_circuit(params[(i//2)*3:(i//2)*3+3]), [i, i+1])
