def create_bitstring_oracle(bitstring: str) -> QuantumCircuit:
    """
    Oráculo simple y robusto — asumimos que Qiskit opera en little-endian.
    """
    n = len(bitstring)
    oracle = QuantumCircuit(n)

    for i, bit in enumerate(bitstring):
        if bit == '0':
            oracle.x(i)

    if n == 1:
        oracle.z(0)
    else:
        oracle.h(n - 1)
        oracle.mcx(list(range(n - 1)), n - 1, mode='noancilla')
        oracle.h(n - 1)

    for i, bit in enumerate(bitstring):
        if bit == '0':
            oracle.x(i)

    return oracle

