def construct_em_r_rounds(r):
    """Construct r-round EM: (X-Rz-U)^r followed by final X"""
    qc = QuantumCircuit(n)
    for _ in range(r):
        k = np.random.randint(0, 2, n)
        theta = 2 * np.pi * np.random.rand(n)
        for i in range(n):
            if k[i]:
                qc.x(i)
        for i in range(n):
            qc.rz(theta[i], i)
        qc.compose(random_clifford(n).to_circuit(), inplace=True)
    # Final X
    k_final = np.random.randint(0, 2, n)
    for i in range(n):
        if k_final[i]:
            qc.x(i)
    return Operator(qc)

