    qc.barrier()
    return qc.to_instruction(label='Correct U')

def _create_oracle(n_qubits, target_state):
    """Create oracle that marks target state."""
    oracle = QuantumCircuit(n_qubits)

    for i, bit in enumerate(reversed(target_state)):
        if bit == '0':
            oracle.x(i)

    oracle.h(n_qubits - 1)
    oracle.mcx(list(range(n_qubits - 1)), n_qubits - 1)
    oracle.h(n_qubits - 1)

    for i, bit in enumerate(reversed(target_state)):
        if bit == '0':
            oracle.x(i)

    return oracle

