def var_circ(num_qubits, reps):

    # reps is Number of times ry and cx gates are repeated
    qc = QuantumCircuit(num_qubits)
    parameter_vector = ParameterVector("t", length=num_qubits*reps*2)
    # print("parameter_vector",parameter_vector)
    counter = 0
    for rep in range(reps):
        for i in range(num_qubits):
            theta = parameter_vector[counter]
            qc.ry(theta, i)
            counter += 1

        for i in range(num_qubits):
            theta = parameter_vector[counter]
            qc.rx(theta, i)
            counter += 1

        for j in range(0, num_qubits - 1, 1):
            if rep<reps-1:
                qc.cx(j, j + 1)
    # print("counter",counter)
    return qc

def get_color_parity_ordering_swap_mixer_circuit(G, beta, T1, T2, encoding="onehot"):
    if encoding == "onehot":
        N = G.number_of_nodes()
        dt = beta/T2
        qc = QuantumCircuit(N**2)
        G = misra_gries_edge_coloring(G)
        colors = nx.get_edge_attributes(G, "misra_gries_color").values()
        for c in colors:
            for t in range(T2):
                for i in range(0,N-1,2):
                    for u, v in G.edges:
                        if G[u][v]["misra_gries_color"] == c:
                            qc = qc.compose(get_ordering_swap_partial_mixing_circuit(
                                G, i, i+1, u, v, dt, T1, encoding="onehot"))                       
                for i in range(1,N-1,2):
                    for u, v in G.edges:
                        if G[u][v]["misra_gries_color"] == c:
                            qc = qc.compose(get_ordering_swap_partial_mixing_circuit(
                                G, i, i+1, u, v, dt, T1, encoding="onehot"))
                if N%2 == 1:
                    for u, v in G.edges:
                        if G[u][v]["misra_gries_color"] == c:
                            qc = qc.compose(get_ordering_swap_partial_mixing_circuit(
                                G, N-1, 0, u, v, dt, T1, encoding="onehot"))
        return qc

def get_simultaneous_ordering_swap_mixer(G, beta, T1, T2, encoding="onehot"):
