def build_phase_oracle_from_good_states(n: int, good_states: list[int]) -> QuantumCircuit:
    """
    Возвращает oracle S_f: |x> -> (-1)^{f(x)} |x>,
    где f(x)=1 для x in good_states.
    """
    oracle = QuantumCircuit(n, name="S_f")

    for x in good_states:
        bits = [(x >> i) & 1 for i in range(n)]  # little-endian по кубитам

        # Превращаем |x> в |11..1> через X на нулевых битах
        for i, b in enumerate(bits):
            if b == 0:
                oracle.x(i)

        # Мультиконтролируемый Z на |11..1>
        if n == 1:
            oracle.z(0)
        else:
            oracle.h(n - 1)
            oracle.mcx(list(range(n - 1)), n - 1)  # controlled-X
            oracle.h(n - 1)

        # Возвращаем X обратно
        for i, b in enumerate(bits):
            if b == 0:
                oracle.x(i)

    return oracle

