def generate(self, seed):
    random.seed(seed)
    num_qubits = random.randint(self.low, self.high)
    circuit = QuantumCircuit(num_qubits)

    # make a random array of 0s and 1s
    xs = [random.randint(0, 1) for _ in range(num_qubits - 1)]

    # random array of 0s and 1s, but we must guarantee at least one 1
    if num_qubits > 1:
        rand_bits = [int(i) for i in bin(random.randint(1, 2**(num_qubits - 1) - 1))[2:]]
        cxs = [0]*((num_qubits - 1) - len(rand_bits)) + rand_bits
    else:
        cxs = []

    for idx, i in enumerate(xs):
        if i == 1:
            circuit.x(circuit.qubits[idx])

    for idx, i in enumerate(cxs):
        if i == 1:
            circuit.cx(circuit.qubits[idx], circuit.qubits[-1])

    for idx, i in enumerate(xs):
        if i == 1:
            circuit.x(circuit.qubits[idx])

    return circuit

def __circuit_init(qc: QuantumCircuit,
                   register_list: list[QuantumRegister],
                   system: ChromophoreSystem | ExcitonicSystem,
                   ) -> QuantumCircuit:
    qr_e = register_list[0]
    if system.state_type == 'state':
        qc.initialize(system.state, qr_e)
    elif system.state_type == 'delocalized excitation':
        relevant_qubits = np.where(np.array(system.state) != 0)[0].tolist()
        relevant_state = np.zeros(2**len(relevant_qubits), dtype = complex)
        for ni, i in enumerate(relevant_qubits):
            relevant_state[2**ni] = system.state[i]
        qc_relevant = QuantumCircuit(len(relevant_qubits))
        qc_relevant.initialize(relevant_state)
        qc.compose(qc_relevant,
                   qubits = [qr_e[i] for i in relevant_qubits],
                   inplace = True,
                   )
    elif system.state_type == 'localized excitation':
        qc.x(qr_e[system.state])
    return qc

def __sys_evolution(system: ChromophoreSystem | ExcitonicSystem,
                    dt: float,
                    Trotter_order: int,
                    ) -> QuantumCircuit:
    energies = system.e_el
    couplings = system.coupl_el
    N = system.system_size
    qc = QuantumCircuit(N)

    # Create the dictionary of Pauli operations
    op_dict = {}
    for i in range(N):
        if energies[i] != 0.:
            op_str = ''.join([*['I']*(N-i-1), 'Z', *['I']*i])
            op_dict[op_str] = - energies[i] / 2
    for i in range(N):
        for j in range(i+1, N):
            if couplings[i,j] != 0.:
                for pauli in ['X', 'Y']:
                    op_str = ''.join([*['I']*(N-j-1), pauli, *['I']*(j-i-1), pauli, *['I']*i])
                    op_dict[op_str] = couplings[i,j] / 2

    # Selecting the Trotter class
    Trotter = __Trotter_class(Trotter_order)

    # Creating the gates
    pauli_gates = SparsePauliOp(list(op_dict.keys()), coeffs=list(op_dict.values()))
    evolution_gate = PauliEvolutionGate(pauli_gates, time=dt, synthesis=Trotter)

    # Appending to qc and returning qc
    qc.append(evolution_gate, range(N))
    return qc.decompose(reps=2)

def grover_oracle(marked_states):
    """Build a Grover oracle for multiple marked states."""
    if not isinstance(marked_states, list):
        marked_states = [marked_states]
    num_qubits = len(marked_states[0])
    qc = QuantumCircuit(num_qubits)
    for target in marked_states:
        rev_target = target[::-1]
        zero_inds = [ind for ind in range(num_qubits) if rev_target.startswith("0", ind)]
        if zero_inds:
            qc.x(zero_inds)
            qc.compose(MCMT(ZGate(), num_qubits - 1, 1), inplace=True)
            qc.x(zero_inds)
        else:
            qc.compose(MCMT(ZGate(), num_qubits - 1, 1), inplace=True)
    return qc

def generate_grover(self, n: int) -> QuantumCircuit:
    if n < 2: return QuantumCircuit(n)
    # Simple Grover: Oracle |11...1>
    oracle = QuantumCircuit(n)
    oracle.cp(3.14159, 0, n-1) # Dummy phase oracle for benchmark

    grover_op = GroverOperator(oracle)
    qc = QuantumCircuit(n)
    for i in range(n): qc.h(i)
    qc = qc.compose(grover_op)
    return qc.decompose().decompose()

def classifier_circuit(num_qubits: int, depth: int) -> Tuple[QuantumCircuit, Iterable, Iterable, List[SparsePauliOp]]:
    """
    Build a variational classifier circuit.
    Encoding parameters are RX rotations, variational parameters are
    RY rotations, and CZ gates provide entanglement.
    """
    encoding = ParameterVector("x", num_qubits)
    weights = ParameterVector("theta", num_qubits * depth)

    qc = QuantumCircuit(num_qubits)
    for param, q in zip(encoding, range(num_qubits)):
        qc.rx(param, q)

    idx = 0
    for _ in range(depth):
        for q in range(num_qubits):
            qc.ry(weights[idx], q)
            idx += 1
        for q in range(num_qubits - 1):
            qc.cz(q, q + 1)

    observables = [
        SparsePauliOp("I" * i + "Z" + "I" * (num_qubits - i - 1))
        for i in range(num_qubits)
    ]

    return qc, list(encoding), list(weights), observables

def symmetry_preserving_initial_state(num_res, num_rot, theta=np.pi/4):
    if num_rot < 2:
        raise ValueError("num_rot must be at least 2.")

    qc = QuantumCircuit(num_rot)
    qc.x(num_rot // 2)
    agate = A_gate(theta=theta)

    for i in range(num_rot - 1):
        qc.compose(agate, [i, i + 1], inplace=True)

    init_state = create_product_state(qc, num_res)
    return init_state

