def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    qc.h(y)

    for j in range(m):
        for i in range(n):
            theta = (2 * math.pi * S[i] / 2**m) * 2**j
            qc.cp(theta, x[i], y[j])

    qc.compose(qft(m).inverse(), y, inplace=True)

    return qc

def get_quantum_circuit(self, n_data_qubits):
    self.qr = QuantumRegister(n_data_qubits, name="qr")
    self.qc = QuantumCircuit(self.qr, name="Shifted circ")

    for layer_no in range(self.layers):
        for _sweep in range(0, self.sweeps_per_layer):
            self.add_rotations(n_data_qubits)
            self.add_entangling_gates(n_data_qubits)
        if layer_no < self.layers - 1:
            self.apply_activation_function(n_data_qubits)
    return self.qc

def build_grover_oracle(num_qubits, target_index):
    qc = QuantumCircuit(num_qubits)
    target_bits = [(target_index >> i) & 1 for i in range(num_qubits)]

    for i, bit in enumerate(target_bits):
        if bit == 0:
            qc.x(i)

    if num_qubits == 1:
        qc.z(0)
    else:
        controls = list(range(num_qubits - 1))
        target = num_qubits - 1
        qc.h(target)
        qc.mcx(controls, target)
        qc.h(target)

    for i, bit in enumerate(target_bits):
        if bit == 0:
            qc.x(i)

    return qc

def deutsch_function(case: int): 
    f = QuantumCircuit(2)
    if case in [2, 3]:
        f.cx(0, 1)
    if case in [3, 4]:
        f.x(1)
    return f

def create_angle_encoding(self) -> QuantumCircuit:
    """Create angle encoding feature map using RY and RZ rotations"""
    qc = QuantumCircuit(self.num_qubits)

    # Create parameter vector for features
    params = ParameterVector('x', self.num_features)

    param_idx = 0
    for rep in range(self.reps):
        for qubit in range(self.num_qubits):
            # Each qubit can encode 2 features (RY and RZ)
            if param_idx < self.num_features:
                # RY rotation for first feature
                qc.ry(params[param_idx], qubit)
                param_idx += 1

            if param_idx < self.num_features:
                # RZ rotation for second feature
                qc.rz(params[param_idx], qubit)
                param_idx += 1

        # Add entanglement between reps
        if rep < self.reps - 1:
            for qubit in range(self.num_qubits - 1):
                qc.cx(qubit, qubit + 1)

    return qc, list(params)

def execute_quantum_circuit(self, gates: List[str]) -> List[int]:
    """Execute quantum circuit with given gates"""
    qc = QuantumCircuit(3, 3)

    for gate in gates:
        if gate == "H":
            qc.h(0)
        elif gate == "X":
            qc.x(0)
        elif gate == "Y":
            qc.y(0)
        elif gate == "Z":
            qc.z(0)
        elif gate == "CNOT":
            qc.cx(0, 1)
        elif gate == "RZ":
            qc.rz(np.pi/4, 0)
        elif gate == "RY":
            qc.ry(np.pi/4, 0)

    qc.measure_all()

    job = execute(qc, self.backend, shots=1)
    result = job.result()
    counts = result.get_counts(qc)

    if counts:
        measurement = list(counts.keys())[0]
        return [int(bit) for bit in reversed(measurement)]
    return [0, 0, 0]

def quantum_random_generator(self, num_bits: int) -> Dict[str, Any]:
    """Generate quantum random numbers using Qiskit"""
    qc = QuantumCircuit(num_bits, num_bits)

    for i in range(num_bits):
        qc.h(i)
        qc.measure(i, i)

    job = execute(qc, self.backend, shots=1)
    result = job.result()
    counts = result.get_counts(qc)

    if counts:
        binary = list(counts.keys())[0]
        decimal = int(binary, 2)
        hex_val = hex(decimal)[2:].upper()

        return {
            'binary': binary,
            'decimal': decimal,
            'hex': hex_val
        }

    return {'binary': '0', 'decimal': 0, 'hex': '0'}

def quantum_fourier_transform(self, n_qubits: int) -> str:
    """Implement Quantum Fourier Transform"""
    qc = QuantumCircuit(n_qubits)

    def qft_rotations(circuit, n):
        if n == 0:
            return circuit
        n -= 1
        circuit.h(n)
        for qubit in range(n):
            circuit.cp(np.pi/2**(n-qubit), qubit, n)
        qft_rotations(circuit, n)

    qft_rotations(qc, n_qubits)

    # Swap qubits
    for qubit in range(n_qubits//2):
        qc.swap(qubit, n_qubits-qubit-1)

    return str(qc)

def circuit(self) -> QuantumCircuit:
    """Make the quantum circuit."""

    n = self._num_qubits

    if n % 2 != 0:
        raise CircuitError("The number of qubits should be even!")


    ansatz = QuantumCircuit(n, name="RVB")

    # build initial state
    for i in range(0,n):
        ansatz.x(i)

    # build bell state
    for j in range(0,n):
        if j % 2 == 0:
            ansatz.h(j)
            ansatz.cx(j,j+1)

    for k in range(self._reps):
        for l in range(n-1,0,-2):

                if l < n-1:
                    ansatz.append(self.add_eSWAP(), [l,l+1])
                else:
                    ansatz.append(self.add_eSWAP(), [l,0])

        for l in range(0, n-1, 2):
            ansatz.append(self.add_eSWAP(), [l,l+1])

    return ansatz

def get_circuit(self, *args, **kwargs):
    qubits = QuantumRegister(self.n)
    qc,para = self.ansatz(QuantumCircuit(qubits), *args, **kwargs)

    return {
        'circuit': qc,
        'qubits': qubits,
        'para': para
    }

def criar_circuito_hardware_efficient(n_qubits: int, n_camadas: int) -> Tuple[QuantumCircuit, ParameterVector]:
    """Circuito eficiente para hardware (RY + CNOT linear)."""
    n_params = n_qubits * n_camadas
    params = ParameterVector('θ', n_params)

    qc = QuantumCircuit(n_qubits)

    param_idx = 0
    for camada in range(n_camadas):
        # Apenas RY (mais eficiente)
        for q in range(n_qubits):
            qc.ry(params[param_idx], q)
            param_idx += 1

        # CNOT linear
        if camada < n_camadas - 1:
            for q in range(n_qubits - 1):
                qc.cx(q, q + 1)

    return qc, params

def criar_circuito_alternating_layers(n_qubits: int, n_camadas: int) -> Tuple[QuantumCircuit, ParameterVector]:
    """Camadas alternadas de rotações e entanglement."""
    n_params = n_qubits * n_camadas * 2
    params = ParameterVector('θ', n_params)

    qc = QuantumCircuit(n_qubits)

    param_idx = 0
    for camada in range(n_camadas):
        # Camada par: RY + CNOT ímpar
        if camada % 2 == 0:
            for q in range(n_qubits):
                qc.ry(params[param_idx], q)
                param_idx += 1
                qc.rz(params[param_idx], q)
                param_idx += 1

            for q in range(0, n_qubits - 1, 2):
                qc.cx(q, q + 1)

        # Camada ímpar: RX + CNOT par
        else:
            for q in range(n_qubits):
                qc.rx(params[param_idx], q)
                param_idx += 1
                qc.ry(params[param_idx], q)
                param_idx += 1

            for q in range(1, n_qubits - 1, 2):
                qc.cx(q, q + 1)

    return qc, params

def criar_circuito_brickwork(n_qubits: int, n_camadas: int) -> Tuple[QuantumCircuit, ParameterVector]:
    """Padrão brickwork (tijolos) de entanglement."""
    n_params = n_qubits * n_camadas * 2
    params = ParameterVector('θ', n_params)

    qc = QuantumCircuit(n_qubits)

    param_idx = 0
    for camada in range(n_camadas):
        # Rotações
        for q in range(n_qubits):
            qc.ry(params[param_idx], q)
            param_idx += 1
            qc.rz(params[param_idx], q)
            param_idx += 1

        # Padrão brickwork alternado
        if camada % 2 == 0:
            for q in range(0, n_qubits - 1, 2):
                qc.cx(q, q + 1)
        else:
            for q in range(1, n_qubits - 1, 2):
                qc.cx(q, q + 1)

    return qc, params

def criar_circuito_tree(n_qubits: int, n_camadas: int) -> Tuple[QuantumCircuit, ParameterVector]:
    """Circuito com topologia de árvore."""
    n_params = n_qubits * n_camadas * 2
    params = ParameterVector('θ', n_params)

    qc = QuantumCircuit(n_qubits)

    param_idx = 0
    for camada in range(n_camadas):
        # Rotações
        for q in range(n_qubits):
            qc.ry(params[param_idx], q)
            param_idx += 1
            qc.rz(params[param_idx], q)
            param_idx += 1

        # Entanglement em árvore (binary tree)
        if camada < n_camadas - 1:
            for level in range(int(np.log2(n_qubits)) + 1):
                step = 2 ** (level + 1)
                for q in range(0, n_qubits, step):
                    if q + 2 ** level < n_qubits:
                        qc.cx(q, q + 2 ** level)

    return qc, params

def grover_search(n_qubits: int = 2, oracle_pattern: str = None) -> QuantumCircuit:
    """Create Grover's search algorithm circuit."""
    if oracle_pattern is None:
        oracle_pattern = '1' * n_qubits  # Search for all 1s

    qc = QuantumCircuit(n_qubits, n_qubits, name=f"Grover-{n_qubits}")

    # Initialize superposition
    qc.h(range(n_qubits))

    # Number of iterations for optimal probability
    iterations = int(np.pi / 4 * np.sqrt(2**n_qubits))

    for _ in range(iterations):
        # Oracle: flip phase of target state
        for i, bit in enumerate(oracle_pattern):
            if bit == '0':
                qc.x(i)

        if n_qubits > 1:
            qc.mcrz(np.pi, list(range(n_qubits-1)), n_qubits-1)
        else:
            qc.rz(np.pi, 0)

        for i, bit in enumerate(oracle_pattern):
            if bit == '0':
                qc.x(i)

        # Diffusion operator
        qc.h(range(n_qubits))
        qc.x(range(n_qubits))

        if n_qubits > 1:
            qc.mcrz(np.pi, list(range(n_qubits-1)), n_qubits-1)
        else:
            qc.rz(np.pi, 0)

        qc.x(range(n_qubits))
        qc.h(range(n_qubits))

    qc.measure_all()
    return qc

def _build_ansatz(self, theta: np.ndarray, n_qubits: int) -> 'QuantumCircuit':
    """Build parameterized ansatz circuit for VQE.

    v9.0: Uses L104CircuitFactory ParameterVector ansatz when available,
    binding parameters at execution time for 3x speedup.
    """
    if _L104_UTILS_AVAILABLE and _PARAM_VECTOR_AVAILABLE:
        # Build once, bind many times (cache the template)
        if not hasattr(self, '_vqe_ansatz_cache') or self._vqe_ansatz_cache.get('n', 0) != n_qubits:
            qc_template, params = L104CircuitFactory.vqe_ansatz(
                n_qubits, depth=VQE_ANSATZ_DEPTH, entanglement="linear"
            )
            self._vqe_ansatz_cache = {'n': n_qubits, 'qc': qc_template, 'params': params}

        template = self._vqe_ansatz_cache['qc']
        params = self._vqe_ansatz_cache['params']
        # Bind theta values to ParameterVector
        n_params = len(params)
        theta_padded = np.resize(theta, n_params)
        param_dict = {params[i]: float(theta_padded[i]) for i in range(n_params)}
        return template.assign_parameters(param_dict)
    else:
        # Legacy manual construction
        qc = QuantumCircuit(n_qubits)
        p_idx = 0
        for layer in range(VQE_ANSATZ_DEPTH):
            for q in range(n_qubits):
                qc.ry(float(theta[p_idx % len(theta)]), q)
                p_idx += 1
                qc.rz(float(theta[p_idx % len(theta)]), q)
                p_idx += 1
            for q in range(n_qubits - 1):
                qc.cx(q, q + 1)
            qc.rz(GOD_CODE / (1000.0 * (layer + 1)), 0)
        return qc

def quantum_kernel_classify(self, query_features: List[float],
                             domain_prototypes: Dict[str, List[float]]) -> Dict[str, Any]:
    """Classify a query into domains using quantum kernel similarity.

    Encodes features into a ZZ-entangling quantum feature map, computes
    kernel K[i,j] = |<phi(x_i)|phi(x_j)>|^2 via Statevector inner products,
    and classifies by maximum kernel similarity.
    """
    if not domain_prototypes:
        return {'quantum': False, 'error': 'no_domains', 'predicted_domain': 'unknown'}

    if not QISKIT_AVAILABLE:
        def cosine_sim(a, b):
            a_arr, b_arr = np.array(a, dtype=float), np.array(b, dtype=float)
            na, nb = np.linalg.norm(a_arr), np.linalg.norm(b_arr)
            return float(np.dot(a_arr, b_arr) / (na * nb)) if na > 1e-10 and nb > 1e-10 else 0.0

        sims = {name: cosine_sim(query_features, proto)
                for name, proto in domain_prototypes.items()}
        best = max(sims, key=sims.get)
        return {
            'quantum': False, 'fallback': 'qiskit_unavailable',
            'predicted_domain': best,
            'confidence': round(max(sims.values()), 6),
            'kernel_similarities': {k: round(v, 6) for k, v in sims.items()},
        }

    n_qubits = QKM_FEATURE_QUBITS

    def feature_map_circuit(features: List[float]) -> np.ndarray:
        padded = list(features[:n_qubits])
        while len(padded) < n_qubits:
            padded.append(0.0)

        # v9.0: Use L104CircuitFactory ZZ feature map when available
        if _L104_UTILS_AVAILABLE and _PARAM_VECTOR_AVAILABLE:
            qc_template, x_params = L104CircuitFactory.zz_feature_map(n_qubits, reps=2)
            param_dict = {x_params[i]: float(padded[i]) for i in range(n_qubits)}
            qc = qc_template.assign_parameters(param_dict)
            # Add GOD_CODE alignment
            qc.rz(GOD_CODE / 1000.0, 0)
        else:
            qc = QuantumCircuit(n_qubits)
            for i in range(n_qubits):
                qc.h(i)
                qc.rz(float(padded[i]) * 2.0, i)
            for i in range(n_qubits - 1):
                qc.cx(i, i + 1)
                qc.rz(float(padded[i] * padded[i + 1]) * PHI, i + 1)
                qc.cx(i, i + 1)
            for i in range(n_qubits):
                qc.ry(float(padded[i]) * np.pi, i)
            qc.rz(GOD_CODE / 1000.0, 0)
        probs, _ = self._execute_circuit(qc, n_qubits, algorithm_name="asi_qkm")
        return probs

    query_probs = feature_map_circuit(query_features)
    similarities = {}
    exec_meta_last = {}
    for name, proto in domain_prototypes.items():
        proto_probs = feature_map_circuit(proto)
        # Bhattacharyya kernel: K = (Σ √(p_i * q_i))²
        overlap = float(np.sum(np.sqrt(np.abs(query_probs) * np.abs(proto_probs)))) ** 2
        similarities[name] = round(float(overlap), 8)

    best_domain = max(similarities, key=similarities.get)

    self._metrics['qkm_runs'] += 1
    self._metrics['total_circuits'] += 1 + len(domain_prototypes)

    return {
        'quantum': True,
        'predicted_domain': best_domain,
        'confidence': round(similarities[best_domain], 6),
        'kernel_similarities': {k: round(v, 6) for k, v in similarities.items()},
        'feature_map': 'ZZ_entangling',
        'qubits': n_qubits,
    }

def _advanced_cirq_to_qiskit(self, circuit: cirq.Circuit) -> QuantumCircuit:
    all_qubits = sorted(list(circuit.all_qubits()))
    num_qubits = len(all_qubits)
    qreg = QuantumRegister(num_qubits, 'q')
    creg = ClassicalRegister(num_qubits, 'c')
    qc = QuantumCircuit(qreg, creg)
    qubit_map = {q: i for i, q in enumerate(all_qubits)}
    for moment in circuit:
        for op in moment.operations:
            gate = op.gate
            qubits = [qubit_map[q] for q in op.qubits]
            if isinstance(gate, cirq.H):
                qc.h(qubits[0])
            elif isinstance(gate, cirq.X):
                qc.x(qubits[0])
            elif isinstance(gate, cirq.Y):
                qc.y(qubits[0])
            elif isinstance(gate, cirq.Z):
                qc.z(qubits[0])
            elif isinstance(gate, cirq.CNOT):
                qc.cx(qubits[0], qubits[1])
            elif isinstance(gate, cirq.CZ):
                qc.cz(qubits[0], qubits[1])
            elif isinstance(gate, cirq.SWAP):
                qc.swap(qubits[0], qubits[1])
            elif isinstance(gate, cirq.XPowGate):
                qc.rx(gate.exponent * np.pi, qubits[0])
            elif isinstance(gate, cirq.YPowGate):
                qc.ry(gate.exponent * np.pi, qubits[0])
            elif isinstance(gate, cirq.ZPowGate):
                qc.rz(gate.exponent * np.pi, qubits[0])
            elif isinstance(gate, cirq.MeasurementGate):
                for idx, q_idx in enumerate(qubits):
                    qc.measure(q_idx, q_idx)
    if not any(isinstance(op.gate, cirq.MeasurementGate) for m in circuit for op in m.operations):
        qc.measure_all()
    return qc

def run_advanced_circuit(self, circuit_type, features=None, params=None, custom_circuit=None, show_diagram=False):
    """Run advanced quantum circuits with performance tracking, error handling, and optional diagram generation"""
    if not HAS_QISKIT:
        return self._simulate_classical(features), None, {}

    try:
        start_time = time.time()

        # Generate or use custom circuit
        try:
            # Prefer a provided custom circuit, otherwise generate based on the requested type
            if custom_circuit is not None:
                circuit = custom_circuit
            else:
                circuit = self._generate_circuit_by_type(circuit_type, features, params)
        except Exception as gen_err:
            logger.warning(f"Failed to generate circuit '{circuit_type}': {gen_err}")
            # Fallback to a minimal single-qubit circuit to keep flow working
            try:
                circuit = QuantumCircuit(1)
                circuit.h(0)
            except Exception:
                circuit = None

        if show_diagram:
            try:
                fig_obj = None
                # Only attempt to draw if circuit is not None and has draw attribute
                if circuit is None:
                    # Fallback to text representation if circuit is unavailable
                    st.code("Circuit not available.", language='text')
                elif hasattr(circuit, 'draw'):
                    try:
                        drawn = circuit.draw(output='mpl', style={'showindex': True})
                    except Exception as draw_err:
                        logger.warning(f"Circuit drawing failed: {draw_err}")
                        drawn = None

                    # If qiskit returned a Matplotlib Figure instance directly
                    if MatplotlibFigure is not None and isinstance(drawn, MatplotlibFigure):
                        fig_obj = drawn
                    # If qiskit returned an Axes or similar with a .figure attribute (safe access)
                    elif MatplotlibFigure is not None and hasattr(drawn, 'figure') and getattr(drawn, 'figure', None) is not None and isinstance(getattr(drawn, 'figure'), MatplotlibFigure):
                        fig_obj = getattr(drawn, 'figure')
                    # If it returned an object with a savefig method, try to use plt.gcf() as a safe fallback
                    elif hasattr(drawn, 'savefig') and callable(getattr(drawn, 'savefig', None)):
                        try:
                            fig_obj = plt.gcf() if HAS_MATPLOTLIB else None
                        except Exception:
                            fig_obj = None
                    # If draw returned a string or None or unexpected type, fallback to text representation
                    elif isinstance(drawn, str) or drawn is None:
                        fig_obj = None
                    # If we obtained a figure object attempt to render it, otherwise show text fallback
                    if fig_obj is not None:
                        try:
                            st.pyplot(fig_obj)
                        except Exception:
                            st.code(str(circuit), language='text')
                    else:
                        st.code(str(circuit), language='text')
                        st.markdown("**Circuit Text Representation**")
                else:
                    # If circuit has no draw method, fallback to text representation
                    try:
                        st.code(str(circuit), language='text')
                        st.markdown("**Circuit Text Representation**")
                    except Exception:
                        st.text("Circuit representation not available.")

                # Only access circuit attributes if circuit is available
                if circuit is not None:
                    st.markdown(f"**Circuit Diagram - {circuit_type.replace('_', ' ').title()}**")
                    st.markdown(f"- Qubits: {circuit.num_qubits}")
                    st.markdown(f"- Depth: {circuit.depth()}")
                    st.markdown(f"- Gates: {sum(circuit.count_ops().values())}")
                else:
                    st.markdown("**Circuit Diagram - Not Available**")
            except Exception as diagram_error:
                logger.warning(f"Could not generate circuit diagram: {diagram_error}")
                # Fallback to text representation if possible
                try:
                    st.code(str(circuit), language='text')
                except Exception:
                    st.text("Circuit representation not available.")

        # Advanced transpilation with optimization
        if self.backend is None:
            raise RuntimeError("Quantum backend is not available.")

        # Ensure circuit is valid for transpilation (transpile does not accept None)
        if circuit is None:
            logger.warning("Circuit is None, using minimal fallback circuit for transpilation.")
            try:
                circuit = QuantumCircuit(1)
                circuit.h(0)
            except Exception:
                raise RuntimeError("Failed to create fallback quantum circuit for transpilation.")

        transpiled = transpile(
            circuit,
            self.backend,
            optimization_level=self.optimization_level
        )

        # Execute with error mitigation if enabled
        try:
            job = self.backend.run(transpiled, shots=self.shots)
            result = job.result()
            counts = result.get_counts()
            if counts is None:
                raise RuntimeError("No counts returned from quantum execution")
        except Exception as exec_error:
            logger.warning(f"Quantum execution failed: {exec_error}. Using fallback simulation.")
            # Fallback to classical simulation
            return self._simulate_classical(features), None, {}

        # Calculate multiple expectation values with advanced observables
        expectation_values = self._calculate_advanced_expectation(counts, circuit_type)
        execution_time = time.time() - start_time

        # Store comprehensive performance metrics
        performance_data = {
            'execution_time': execution_time,
            'expectation': expectation_values['combined'],
            'z_expectation': expectation_values['z_expectation'],
            'parity_expectation': expectation_values['parity_expectation'],
            'variance': expectation_values['variance'],
            'shots': self.shots,
            'qubits': circuit.num_qubits,
            'depth': circuit.depth(),
            'gate_count': sum(circuit.count_ops().values()),
            'optimization_level': self.optimization_level,
            'error_mitigation': self.error_mitigation
        }

        self.circuit_performance[circuit_type] = performance_data

        # Store detailed results
        result_entry = {
            'circuit_type': circuit_type,
            'expectation': expectation_values['combined'],
            'expectation_breakdown': expectation_values,
            'counts': counts,
            'execution_time': execution_time,
            'circuit_metrics': {
                'qubits': circuit.num_qubits,
                'depth': circuit.depth(),
                'gate_count': sum(circuit.count_ops().values())
            },
            'timestamp': datetime.now(),
            'features_used': features[:6] if features else None,
            'params_used': params[:10] if params else None  # Store first 10 params
        }

        self.quantum_results.append(result_entry)

        return expectation_values['combined'], circuit, counts

    except Exception as e:
        logger.error(f"Advanced quantum circuit failed: {e}")
        st.error(f"Quantum computation failed: {e}")
        return self._simulate_classical(features), None, {}

def create_qnn_circuit(self, features, params=None, n_layers=2):
    """Create quantum neural network circuit with encoding and variational parts"""
    qc = QuantumCircuit(self.n_qubits)

    # Feature encoding layer
    features = self._normalize_features(features)
    for i in range(min(len(features), self.n_qubits)):
        qc.ry(features[i] * np.pi, i)

    # Variational layers
    if params is None:
        params = np.random.uniform(0, 2*np.pi, self.n_qubits * 2 * n_layers)

    param_idx = 0

    for layer in range(n_layers):
        # Rotation layer
        for i in range(self.n_qubits):
            if param_idx < len(params):
                qc.rz(params[param_idx], i)
                param_idx += 1
            if param_idx < len(params):
                qc.ry(params[param_idx], i)
                param_idx += 1

        # Entanglement layer
        for i in range(self.n_qubits - 1):
            qc.cx(i, i + 1)

        # Final rotation in each layer
        for i in range(self.n_qubits):
            if param_idx < len(params):
                qc.rz(params[param_idx], i)
                param_idx += 1

    return qc

def hweff_ansatz(n_spins,depth,p):

	circuit = QuantumCircuit(n_spins)
	count = 0

	for j in range(depth):

		if(j%2 == 0):
			# Rx - Rzz block
			for i in range(n_spins):
				circuit.rx(p[count],i)
				count = count +1

			circuit.barrier()

			for i in range(n_spins-1):
				circuit.rzz(p[count],i,i+1)
				count = count +1

			circuit.barrier()

		if(j%2 == 1):
			for i in range(n_spins):
				circuit.ry(p[count],i)
				count = count +1

			circuit.barrier()

			for i in range(n_spins-1):
				circuit.rzz(p[count],i,i+1)
				count = count +1

			circuit.barrier()

	# Final block to close the ansatz
	if (depth%2 == 1):
		for i in range(n_spins):
				circuit.ry(p[count],i)
				count = count +1
	if (depth%2 == 0):
		for i in range(n_spins):
				circuit.rx(p[count],i)
				count = count +1

	return circuit

	circuit = QuantumCircuit(n_spins)
	count = 0

	for j in range(depth):

		if(j%2 == 0):
			# Rx - Rzz block
			for i in range(n_spins):
				circuit.rx(p[count],i)
				count = count +1

			circuit.barrier()

			for i in range(n_spins-1):
				circuit.rzz(p[count],i,i+1)
				count = count +1

			circuit.barrier()

		if(j%2 == 1):
			for i in range(n_spins):
				circuit.ry(p[count],i)
				count = count +1

			circuit.barrier()

			for i in range(n_spins-1):
				circuit.rzz(p[count],i,i+1)
				count = count +1

			circuit.barrier()

	# Final block to close the ansatz
	if (depth%2 == 1):
		for i in range(n_spins):
				circuit.ry(p[count],i)
				count = count +1
	if (depth%2 == 0):
		for i in range(n_spins):
				circuit.rx(p[count],i)
				count = count +1

	return circuit

