def get_quantum_circuit(self, n_data_qubits):
    self.qr = QuantumRegister(n_data_qubits, name='qr')
    self.qc = QuantumCircuit(self.qr, name='Shifted circ')

    for layer_no in range(self.layers):
        if layer_no == 0:
            self.add_rotations(n_data_qubits)
        for sweep in range(0, self.sweeps_per_layer):
            self.add_entangling_gates(n_data_qubits)
            self.add_rotations(n_data_qubits)
        if layer_no < self.layers - 1:
            self.apply_activation_function(n_data_qubits)
    return self.qc

def getLossAndGrad(self, Hamiltonian, **options):
    jac = options.get('jac', 'param-shift')
    if jac not in set({'param-shift', 'spsa'}):
        raise ValueError(f"The parameter jac value {jac} is invalid, please input (param-shift, spsa).")

    def getLoss(params):
        if isinstance(Hamiltonian, (TaperedPauliSumOp, PauliSumOp)):
        # if isinstance(Hamiltonian, TaperedPauliSumOp) or isinstance(Hamiltonian, PauliSumOp):
            qubit_op = Hamiltonian._primitive
        else:
            qubit_op = Hamiltonian

        if isinstance(params, list):
            total_energy = [0.0] * len(params)
        else:
            total_energy = 0.0
        coef_identify = 0.0
        for coef, paulis in zip(qubit_op.coeffs, qubit_op.paulis):
            if paulis == Pauli('I'*self.qubits):
                coef_identify = coef
                continue
            qc_pauli = QuantumCircuit(self.qubits)
            Z_ops = ''
            for i, pauli in enumerate(str(paulis)[::-1]):
                if pauli in ['X', 'Y']:
                    qc_pauli.h(i)
                if pauli == 'Y':
                    qc_pauli.sdg(i)
                if pauli == 'I':
                    Z_ops += 'I'
                else:
                    Z_ops += 'Z'
            Z_ops = Pauli(Z_ops).to_matrix()
            ansatz = self.ansatz.compose(qc_pauli, range(self.qubits))
            ansatz.measure_all()

            if isinstance(params, list):
                ansatz = [ansatz.bind_parameters(param) for param in params]
            else:
                ansatz = ansatz.bind_parameters(params)

            results = self.backend.run(ansatz, seed_simulator=self.seed, shots=self.nshots).result()
            counts = results.get_counts()

            if isinstance(counts, list):
                total_energy = [total_energy[i] + coef * self.getEnergy(cts, Z_ops) for i, cts in enumerate(counts)]
            else:
                energy = self.getEnergy(counts, Z_ops)
                total_energy += coef * energy

        return np.real_if_close(np.asarray(total_energy) + coef_identify)

    def getGrad(params):
        """
        the parameter-shift rule
        """
        dim = params.size

        ei = np.identity(dim)
        plus_shifts = (params + np.pi / 2 * ei).tolist()  # boradcast
        minus_shifts = (params - np.pi / 2 * ei).tolist()

        doubleLoss = getLoss(plus_shifts + minus_shifts)  # (2*num_qubits, num_qubits)
        grad = (doubleLoss[:dim] - doubleLoss[dim:]) / 2
        return grad

    def getGradbySPSA(params):
        alpha = options['alpha'] if 'alpha' in options else 0.5
        c = options['c'] if 'c' in options else 0.02

        dim = self.ansatz.num_parameters

        delta = np.random.binomial(1, 0.5, size=dim)
        delta = np.where(delta==0, -1, delta)

        plus_shifts = params + c * delta
        minus_shifts = params - c * delta

        doubleLoss = getLoss([plus_shifts, minus_shifts])
        grad = (doubleLoss[0] - doubleLoss[1]) / (2 * c * delta)
        return grad

    return (getLoss, getGradbySPSA) if jac == 'spsa' else (getLoss, getGrad)

def kernel(self, h1, h2, norb, nelec, ecore=0, **kwargs):
    self.n_orbitals = norb
    self.n_qubit = self.fermion_qubit_mapping.n_qubits_required(2 * self.n_orbitals)
    self.n_electron = nelec[0] + nelec[1]

    # Get the active space Hamiltonian
    active_hamiltonian = _get_active_hamiltonian(h1, h2, norb, ecore)
    # Convert the Hamiltonian using `self.fermion_qubit_mapping`
    self.fermionic_hamiltonian = get_fermion_operator(active_hamiltonian)
    op_mapper = self.fermion_qubit_mapping.get_of_operator_mapper(
        n_spin_orbitals=2 * self.n_orbitals,
        n_fermions=self.n_electron,
    )
    qubit_hamiltonian = op_mapper(
        self.fermionic_hamiltonian,
    )
    # Set initial Quantum State

    if self.initial_states is None:
        self.initial_states = generate_initial_states(
            self.n_orbitals,
            self.n_electron,
            self.excitation_number,
            self.fermion_qubit_mapping,
        )
    if not isinstance(self.initial_states, list):
        raise TypeError("Initial_states must be of type list.")

    # Set given ansatz
    ansatz = _create_ansatz(
        self.ansatz,
        self.fermion_qubit_mapping,
        2 * self.n_orbitals,
        self.n_electron,
        self.layers,
        self.k,
        self.trotter_number,
        self.include_pi,
        self.use_singles,
        self.delta_sz,
        self.singlet_excitation,
    )
    # Create parametric state
    param_states = []
    for i in range(len(self.initial_states)):
        param_circuit = LinearMappedUnboundParametricQuantumCircuit(self.n_qubit)
        param_circuit.extend(self.initial_states[i].circuit)
        param_circuit.extend(ansatz)
        param_state = ParametricCircuitQuantumState(self.n_qubit, param_circuit)
        param_states.append(param_state)

    gradient_estimator = create_parameter_shift_gradient_estimator(
        self.parametric_estimator
    )

    def get_energies(params):
        return [
            self.parametric_estimator(qubit_hamiltonian, param_state, [params])[
                0
            ].value.real
            for param_state in param_states
        ]

    def cost_fn(params):
        if self.weight_policy == "exponential":
            weights = [2 ** (-i) for i in range(len(param_states))]
        elif self.weight_policy == "same":
            weights = [1] * len(param_states)
        elif self.weight_policy == "base_first":
            weights = [1] + [0.5] * (len(param_states) - 1)
        else:
            raise ValueError(
                "Invalid weight policy. weight_policy must be one of 'exponential', 'same', 'base_first'"
            )
        return sum(
            [
                self.parametric_estimator(
                    qubit_hamiltonian, param_states[i], [params]
                )[0].value.real
                * weights[i]
                for i in range(len(param_states))
            ]
        )

    def grad_fn(params):
        grads = []
        for i in range(len(param_states)):
            estimate = gradient_estimator(
                qubit_hamiltonian, param_states[i], params
            )
            grad = np.asarray([g.real for g in estimate.values])
            if self.weight_policy == "exponential":
                tmp = grad * 2 ** (-i)
            elif self.weight_policy == "same":
                tmp = grad
            elif self.weight_policy == "base_first":
                tmp = grad if i == 0 else grad * 0.5
            else:
                raise ValueError(
                    "Invalid weight policy. weight_policy must be one of 'exponential', 'same', 'base_first'"
                )
            grads.append(tmp)
        return np.sum(grads, axis=0)

    print("----VQE-----")

    if self.is_init_random:
        np.random.seed(self.seed)
        init_params = np.random.random(size=param_circuit.parameter_count)
    else:
        init_params = [0.0] * param_circuit.parameter_count

    result = vqe(init_params, cost_fn, grad_fn, self.optimizer)

    self.opt_param = result.params

    # Store optimal state
    self.opt_states = []
    for i in range(len(param_states)):
        self.opt_states.append(param_states[i].bind_parameters(result.params))

    # Get energy
    self.e = result.cost
    self.energies = get_energies(result.params)

    return self.energies[0], None

def measurement(op):
    qc = QuantumCircuit(2)
    #p represents the Pauli string in the circuit and i is its index
    for i, p in enumerate(op):
        if str(p) == 'X':
            qc.h(i)
        elif str(p) == 'Y':
            qc.sdg(i)
            qc.h(i)
    #We can have this since all observables act on both qubits non-trivially
    qc.cx(0,1)
    return qc

def get_circuit(self, barriers=True):
    qc = QuantumCircuit(self.num_qubits)
    params = []
    # initial Euler Rotation Layer
    for i in range(self.num_qubits):
        for _ in range(2):  # two new parameters
            params.append(Parameter(f'p{len(params):02}'))
        # rotation with the two new parameters. Don't need the first z rotation
        # qc.u(params[-2], params[-1], 0, i)
        qc.rz(-np.pi / 2, i)
        qc.rx(params[-2], i)
        qc.rz(params[-1] + np.pi / 2, i)
    if barriers:
        qc.barrier()
    for l in range(self.num_layers):
        # entangling layer
        for i in range(self.num_qubits - 1):
            qc.cnot(i, i + 1)
        if barriers:
            qc.barrier()
        for i in range(self.num_qubits):
            for _ in range(3):
                params.append(Parameter(f'p{len(params):02}'))
            # qc.u(params[-3], params[-2], params[-1], i)
            qc.rz(params[-3] - np.pi / 2, i)
            qc.rx(params[-2], i)
            qc.rz(params[-1] + np.pi / 2, i)
        if barriers:
            qc.barrier()
    return qc

