def create_feature_map_circuit(self, x: np.ndarray) -> 'QuantumCircuit':
    """
    Create quantum feature map circuit.
    Uses angle encoding with RY and entangling layers.
    """
    if not QISKIT_AVAILABLE:
        raise ImportError("Qiskit required for circuit creation")

    qc = QuantumCircuit(self.n_qubits)

    for rep in range(self.feature_map_reps):
        # Rotation layer
        for i in range(self.n_qubits):
            if i < len(x):
                qc.ry(x[i], i)
                qc.rz(x[i], i)

        # Entangling layer
        if rep < self.feature_map_reps - 1:
            for i in range(self.n_qubits - 1):
                qc.cx(i, i + 1)
            if self.n_qubits > 2:
                qc.cx(self.n_qubits - 1, 0)  # Circular entanglement

    return qc

def create_variational_ansatz(self, theta: np.ndarray) -> 'QuantumCircuit':
    """
    Create variational ansatz circuit.
    Uses parameterized two-local ansatz with RY and RZ rotations.
    """
    if not QISKIT_AVAILABLE:
        raise ImportError("Qiskit required for circuit creation")

    qc = QuantumCircuit(self.n_qubits)
    param_idx = 0

    for layer in range(self.ansatz_depth):
        # Rotation layer
        for i in range(self.n_qubits):
            if param_idx < len(theta):
                qc.ry(theta[param_idx], i)
                param_idx += 1
            if param_idx < len(theta):
                qc.rz(theta[param_idx], i)
                param_idx += 1

        # Entangling layer
        for i in range(0, self.n_qubits - 1, 2):
            qc.cx(i, i + 1)
        for i in range(1, self.n_qubits - 1, 2):
            qc.cx(i, i + 1)

    # Final rotation layer
    for i in range(self.n_qubits):
        if param_idx < len(theta):
            qc.ry(theta[param_idx], i)
            param_idx += 1

    return qc

def create_qiskit_ansatz(n_qubits, n_layers=2):
    """Create Qiskit hardware-efficient ansatz."""
    try:
        from qiskit import QuantumCircuit
        from qiskit.circuit import Parameter

        qc = QuantumCircuit(n_qubits)
        params = []

        for layer in range(n_layers):
            # Rotation layer
            for i in range(n_qubits):
                param = Parameter(f'theta_{layer}_{i}')
                params.append(param)
                qc.ry(param, i)

            # Entangling layer
            for i in range(n_qubits - 1):
                qc.cx(i, i + 1)

        return qc, params
    except ImportError:
        return None, []

def Q_Circuit(N_qubits, var_params, h_l):
    """
    Returns: qiskit n layer ALA circuit. n is specified by args.n_layers when parsing args.

    N_qubits: the number of qubits in the ALA.
    var_params: parameters used in the ALA.
    h_l: indexes for laying out hadamard gate(s) in the last layer.
    """
    circ = QuantumCircuit(N_qubits, N_qubits)
    param_idx = 0
    for i in range(N_qubits):
        circ.h(i)
    if N_qubits % 2 == 0:
        for layer in range(args.n_layers):
            if layer % 2 == 0:
                for i in range(0, N_qubits, 2):
                    circ.cx(i, i+1)
                for i in range(N_qubits):
                    circ.ry(var_params[param_idx], i)
                    param_idx += 1
            else:
                for i in range(1, N_qubits-1, 2):
                    circ.cx(i, i+1)
                for i in range(1, N_qubits-1):
                    circ.ry(var_params[param_idx], i)
                    param_idx += 1
    else:
        for layer in range(args.n_layers):
            if layer % 2 == 0:
                for i in range(0, N_qubits-1, 2):
                    circ.cx(i, i+1)
                for i in range(N_qubits-1):
                    circ.ry(var_params[param_idx], i)
                    param_idx += 1
            else:
                for i in range(1, N_qubits, 2):
                    circ.cx(i, i+1)
                for i in range(1, N_qubits):
                    circ.ry(var_params[param_idx], i)
                    param_idx += 1
    for h_idx in h_l:
        circ.h(h_idx)
    return circ

def _create_pennylane_vqc(self, circuit_id: str, num_qubits: int, num_layers: int) -> QuantumCircuit:
    """Create PennyLane variational quantum circuit."""
    gates = []
    params = []

    for layer in range(num_layers):
        for qubit in range(num_qubits):
            gates.append(f'RY_{layer}_{qubit}')
            params.append(0.0)
        for qubit in range(num_qubits - 1):
            gates.append('CNOT')

    return QuantumCircuit(
        circuit_id=circuit_id,
        num_qubits=num_qubits,
        num_layers=num_layers,
        parameters=params,
        gates=gates,
        depth=num_layers * 2,
        created_at=datetime.now(),
        backend=self.config.backend
    )

def _create_vqe_ansatz(self):
    """Create VQE ansatz circuit."""
    qr = QuantumRegister(self.config.num_qubits, 'q')
    qc = QuantumCircuit(qr)

    # Add parameterized gates
    for layer in range(self.config.num_layers):
        for qubit in range(self.config.num_qubits):
            param = Parameter(f'θ_{layer}_{qubit}')
            qc.ry(param, qr[qubit])

        for qubit in range(self.config.num_qubits - 1):
            qc.cx(qr[qubit], qr[qubit + 1])

    return qc

def run_estimator(circuit, driver, backend = None, shots = 2000, noise_model = None, coupling_map = None, mapper = JordanWignerMapper()):

   hamiltoniano = driver.second_q_ops()[0]

   num_qubits_hamiltonian = mapper.map(hamiltoniano).num_qubits
   num_qubits_circuit = circuit.num_qubits

   new_circuit = circuit.copy()

   if num_qubits_hamiltonian != num_qubits_circuit:

      new_circuit = QuantumCircuit(num_qubits_hamiltonian)

      for gate in circuit.data:

         if all(circuit.qubits.index(qubit) < num_qubits_hamiltonian for qubit in gate[1]):
            new_circuit.append(gate[0], [circuit.qubits.index(qubit) for qubit in gate[1]])

   circuit = new_circuit

   if noise_model is not None:

      estimator = Estimator(backend = backend, options = {"shots" : shots, "noise_model" : noise_model, "coupling_map" : coupling_map})

   else :

      estimator = Estimator(backend = backend, options = {"shots" : shots})

   job = estimator.run(circuit, mapper.map(hamiltoniano))

   return job.result().values[0]

