def make_circuit(self, thetas=None):
    """
    based on the angle of first rotation gate we decide if any rotation at
    a given qubit is present i.e.
    if thetas[0, i] == 0 then there is no rotation gate on the Control quibt
    if thetas[1, i] == 0 then there is no rotation gate on the NOT quibt
    CNOT gate have priority over rotations when both will be present in the given slot
    """
    state = self.state.clone()
    if thetas is None:
        thetas = state[:, self.num_qubits+3:]
    circuit = QuantumCircuit(self.num_qubits)

    for i in range(self.num_layers):

        cnot_pos = np.where(state[i][0:self.num_qubits] == 1)
        targ = cnot_pos[0]
        ctrl = cnot_pos[1]

        if len(ctrl) != 0:
            for r in range(len(ctrl)):
                circuit.add_gate(CNOT(ctrl[r], targ[r]))

        rot_pos = np.where(state[i][self.num_qubits: self.num_qubits+3] == 1)

        rot_direction_list, rot_qubit_list = rot_pos[0], rot_pos[1]

        if len(rot_qubit_list) != 0:
            for pos, r in enumerate(rot_direction_list):
                rot_qubit = rot_qubit_list[pos]
                if r == 0:
                    circuit.add_gate(RX(rot_qubit, thetas[i][0][rot_qubit])) 
                elif r == 1:
                    circuit.add_gate(RY(rot_qubit, thetas[i][1][rot_qubit])) 
                elif r == 2:
                    circuit.add_gate(RZ(rot_qubit, thetas[i][2][rot_qubit]))
                else:
                    print(f'rot-axis = {r} is in invalid')

                    assert r >2
    return circuit

def test_natural_gradient(self, method, regularization):
    """Test the natural gradient"""
    try:
        for params in (ParameterVector("a", 2), [Parameter("a"), Parameter("b")]):
            ham = 0.5 * X - 1 * Z

            q = QuantumRegister(1)
            qc = QuantumCircuit(q)
            qc.h(q)
            qc.rz(params[0], q[0])
            qc.rx(params[1], q[0])

            op = ~StateFn(ham) @ CircuitStateFn(primitive=qc, coeff=1.0)
            nat_grad = NaturalGradient(
                grad_method=method, regularization=regularization
            ).convert(operator=op)
            values_dict = [{params[0]: np.pi / 4, params[1]: np.pi / 2}]

            # reference values obtained by classically computing the natural gradients
            correct_values = [[-3.26, 1.63]] if regularization == "ridge" else [[-4.24, 0]]

            for i, value_dict in enumerate(values_dict):
                np.testing.assert_array_almost_equal(
                    nat_grad.assign_parameters(value_dict).eval(), correct_values[i], decimal=1
                )
    except MissingOptionalLibraryError as ex:
        self.skipTest(str(ex))

def adder(q):
    """Return a ripple carry adder circuit."""
    if q % 2 != 0:
        raise ValueError("q must be even")
    add_qc = QuantumCircuit(q).compose(
        CDKMRippleCarryAdder(num_state_qubits=int((q - 1) / 2)), inplace=False
    )
    return add_qc

def mul(q):
    """Return a rgqft multiplier circuit."""
    if q % 4 != 0:
        raise ValueError("q must be divisible by 4")
    mul_qc = QuantumCircuit(q).compose(
        RGQFTMultiplier(num_state_qubits=int(q / 4)), inplace=False
    )
    return mul_qc

def _twoq_only_depth(qc):
    """Depth counting only 2-qubit operations (ignoring barriers/measure)."""
    qc2 = QuantumCircuit(qc.num_qubits, qc.num_clbits)
    q_index = {q: i for i, q in enumerate(qc.qubits)}
    c_index = {c: i for i, c in enumerate(qc.clbits)}

    for inst in qc.data:
        op = inst.operation
        if op.name in {"barrier", "measure"}:
            continue
        if op.num_qubits == 2:
            qargs = [qc2.qubits[q_index[q]] for q in inst.qubits]
            cargs = [qc2.clbits[c_index[c]] for c in inst.clbits] if inst.clbits else []
            qc2.append(op, qargs, cargs)

    return qc2.depth()

def _build_ansatz(self) -> QuantumCircuit:
    """Build the variational ansatz circuit."""
    qc = QuantumCircuit(self.num_qubits, name=f"VQE-{self.ansatz_type}")

    param_idx = 0

    if self.ansatz_type == "hardware_efficient":
        for layer in range(self.num_layers):
            # Rotation layer
            for qubit in range(self.num_qubits):
                ry = Parameter(f"θ_{param_idx}")
                rz = Parameter(f"θ_{param_idx + 1}")
                qc.ry(ry, qubit)
                qc.rz(rz, qubit)
                param_idx += 2

            # Entanglement layer (linear)
            for i in range(self.num_qubits - 1):
                qc.cx(i, i + 1)

            qc.barrier()

    elif self.ansatz_type == "alternating":
        for layer in range(self.num_layers):
            # RY on all qubits
            for qubit in range(self.num_qubits):
                ry = Parameter(f"θ_{param_idx}")
                qc.ry(ry, qubit)
                param_idx += 1

            # CZ entanglement (alternating pattern)
            if layer % 2 == 0:
                for i in range(0, self.num_qubits - 1, 2):
                    qc.cz(i, i + 1)
            else:
                for i in range(1, self.num_qubits - 1, 2):
                    qc.cz(i, i + 1)

    return qc

def _build_ansatz_circuit(self, n_qubits: int, params: NDArray) -> Any:
    """Build variational ansatz circuit."""
    try:
        from qiskit import QuantumCircuit
    except ImportError as e:
        raise ImportError("Qiskit required") from e

    qc = QuantumCircuit(n_qubits)
    param_idx = 0

    for _layer in range(self.config.ansatz_layers):
        # Single-qubit rotations
        for q in range(n_qubits):
            if self.config.ansatz_type == AnsatzType.RY_LINEAR:
                qc.ry(params[param_idx], q)
                param_idx += 1
            elif self.config.ansatz_type == AnsatzType.HARDWARE_EFFICIENT:
                qc.ry(params[param_idx], q)
                param_idx += 1
                qc.rz(params[param_idx], q)
                param_idx += 1

        # Entangling layer
        if self.config.ansatz_type == AnsatzType.HARDWARE_EFFICIENT:
            for q in range(n_qubits - 1):
                qc.cx(q, q + 1)

    return qc

def vqe_ansatz(
    ham,
    parameters, #-> 2N + layers*N
    layers = 2,
    entangler = "full" # "full" or "linear"
    ):
    G = graph_from_hamiltonian(ham)
    qubits = list(range(len(G.nodes())))
    parameters = np.reshape(parameters, (layers+1,len(qubits)*2))
    circ = QuantumCircuit(len(qubits))
    for layer in range(layers):

        for iz in range (0, len(qubits)):
            circ.ry(parameters[layer][iz], qubits[iz])
            circ.rz(parameters[layer][iz+len(qubits)], qubits[iz])

        circ.barrier()
        if entangler == "full":
            for i, j in itertools.combinations(list(range(len(qubits))), 2):
                circ.cz(qubits[i], qubits[j])

        elif entangler == "linear":
            for i in range(len(qubits)-1):
                circ.cz(qubits[i], qubits[i+1])

        circ.barrier()

    for iz in range (0, len(qubits)):
        circ.ry(parameters[layers][iz], qubits[iz])
        circ.rz(parameters[layers][iz+len(qubits)], qubits[iz])

    circ.measure_all()
    return circ

