def create_circuit(self) -> QuantumCircuit:
    """Create quantum feature map circuit"""
    if not QUANTUM_AVAILABLE:
        raise ImportError("Quantum libraries not available")

    qr = QuantumRegister(self.num_qubits, 'q')
    cr = ClassicalRegister(self.num_qubits, 'c')
    circuit = QuantumCircuit(qr, cr)

    if self.map_type == "ZZFeatureMap":
        # ZZ Feature Map
        for rep in range(self.reps):
            for i in range(self.num_qubits):
                circuit.ry(np.pi/2, qr[i])
            for i in range(self.num_qubits):
                for j in range(i+1, self.num_qubits):
                    circuit.cx(qr[i], qr[j])
                    circuit.rz(np.pi, qr[j])
                    circuit.cx(qr[i], qr[j])
    elif self.map_type == "PauliFeatureMap":
        # Pauli Feature Map
        for rep in range(self.reps):
            for i in range(self.num_qubits):
                circuit.ry(np.pi/2, qr[i])
            for i in range(self.num_qubits):
                circuit.rz(np.pi, qr[i])
    elif self.map_type == "CustomFeatureMap":
        # Custom feature map
        for rep in range(self.reps):
            for i in range(self.num_qubits):
                circuit.h(qr[i])
                circuit.ry(np.pi/4, qr[i])
            for i in range(self.num_qubits-1):
                circuit.cx(qr[i], qr[i+1])

    self.circuit = circuit
    return circuit

def create_ansatz(self) -> QuantumCircuit:
    """Create variational ansatz circuit"""
    if not QUANTUM_AVAILABLE:
        raise ImportError("Quantum libraries not available")

    qr = QuantumRegister(self.config.num_qubits, 'q')
    cr = ClassicalRegister(self.config.num_qubits, 'c')
    circuit = QuantumCircuit(qr, cr)

    # Create parameterized circuit
    params = []
    for layer in range(self.config.num_layers):
        # Rotation gates
        for qubit in range(self.config.num_qubits):
            param = Parameter(f'θ_{layer}_{qubit}_ry')
            circuit.ry(param, qr[qubit])
            params.append(param)

            param = Parameter(f'θ_{layer}_{qubit}_rz')
            circuit.rz(param, qr[qubit])
            params.append(param)

        # Entangling gates
        if self.config.entanglement == "linear":
            for qubit in range(self.config.num_qubits - 1):
                circuit.cx(qr[qubit], qr[qubit + 1])
        elif self.config.entanglement == "circular":
            for qubit in range(self.config.num_qubits):
                circuit.cx(qr[qubit], qr[(qubit + 1) % self.config.num_qubits])
        elif self.config.entanglement == "full":
            for i in range(self.config.num_qubits):
                for j in range(i + 1, self.config.num_qubits):
                    circuit.cx(qr[i], qr[j])

    self.parameters = params
    self.circuit = circuit
    return circuit

def build_hardware_efficient_ansatz(num_qubits: int, reps: int) -> QuantumCircuit:
    qc = QuantumCircuit(num_qubits)
    theta = ParameterVector("theta", reps * num_qubits * 2)
    k = 0
    for _ in range(reps):
        for q in range(num_qubits):
            qc.ry(theta[k], q)
            k += 1
        for q in range(num_qubits):
            qc.rz(theta[k], q)
            k += 1
        for q in range(num_qubits - 1):
            qc.cx(q, q + 1)
        if ENTANGLEMENT_PATTERN == "circular" and num_qubits > 2:
            qc.cx(num_qubits - 1, 0)
    return qc

def create_qaoa_circuit(self, hamiltonian: PauliSumOp, p: int = 1) -> QuantumCircuit:
    """QAOA devresi oluşturur"""
    n = len(hamiltonian.paulis[0])
    qr = QuantumRegister(n, 'q')
    cr = ClassicalRegister(n, 'c')
    circuit = QuantumCircuit(qr, cr)

    # Başlangıç durumu
    for i in range(n):
        circuit.h(i)

    # QAOA katmanları
    beta = [Parameter(f'β_{i}') for i in range(p)]
    gamma = [Parameter(f'γ_{i}') for i in range(p)]

    for layer in range(p):
        # Problem Hamiltonian
        for pauli, coeff in zip(hamiltonian.paulis, hamiltonian.coeffs):
            for i, op in enumerate(pauli):
                if op == 'Z':
                    circuit.rz(2 * gamma[layer] * coeff, i)
                elif op == 'X':
                    circuit.rx(2 * gamma[layer] * coeff, i)
                elif op == 'Y':
                    circuit.ry(2 * gamma[layer] * coeff, i)

        # Karıştırıcı Hamiltonian
        for i in range(n):
            circuit.rx(2 * beta[layer], i)

    circuit.measure_all()
    return circuit

