def build_pair_seed_circuit(pos, pairs=None, base='neel', phi=np.pi/2):
    """
    Construct a spin-only seed circuit on 1 qubit/site using simple Heisenberg pair entanglers.
    """
    n_sites = len(pos)
    qc = QuantumCircuit(n_sites, name="pair_seed")

    if base == 'neel':
        if len(pos) == 8:  # L=1 case
            # explicit checkerboard pattern for Lieb L=1
            down_sites = [1, 3, 4, 6]   # indices you want as ↓
            for q in down_sites:
                qc.x(q)
        else:
            # fallback: old pattern for general lattices
            for q in sorted(pos.keys())[::2]:
                qc.x(q)


    # default pair grouping for L=1
    if pairs is None:
        pairs = [(0,1), (2,4), (3,5), (6,7)]

    # site index mapping
    sites_sorted = sorted(pos.keys())
    site_index = {s: k for k, s in enumerate(sites_sorted)}

    def apply_pair(i_site, j_site, angle):
        a = site_index[i_site]
        b = site_index[j_site]
        for ax in 'XYZ':
            lbl = _pauli_label_twoq(n_sites, a, b, ax)
            evolve_pauli_string(qc, lbl, angle/4.0)

    # apply to each pair
    for (i, j) in pairs:
        apply_pair(i, j, phi)

    return qc

