def make_circuit_2(i: int, j: int, H, delta_t):
    qc = QuantumCircuit(21)
    qc.h(20)
    for target in [4, 15]:
        qc.cx(20, target)
    m = i
    n = j - i
    time_evol = PauliEvolutionGate(H, delta_t, synthesis = LieTrotter(reps = 1))
    for t in range(n):
        qc.append(time_evol, range(20))
    for target in [4, 15]:
        qc.cx(20, target, ctrl_state='0')
    for t in range(m):
        qc.append(time_evol, range(20))
    return qc

def vqe_circuit() -> QuantumCircuit:
    """4-qubit, 2-layer VQE-like ansatz (parametric)."""
    qc = QuantumCircuit(4, 4)
    for layer in range(2):
        for q in range(4):
            qc.ry(Parameter(f"t_{layer}_{q}_a"), q)
        for q in range(3):
            qc.cx(q, q + 1)
        for q in range(4):
            qc.ry(Parameter(f"t_{layer}_{q}_b"), q)
    qc.measure(range(4), range(4))
    return qc

def _insert_reference_noise(base_circuit, density_noise):
    pytest.importorskip("qiskit")
    pytest.importorskip("qiskit_aer")

    from qiskit import QuantumCircuit
    from qiskit_aer.noise import (
        amplitude_damping_error,
        depolarizing_error,
        phase_damping_error,
    )

    noisy_circuit = QuantumCircuit(base_circuit.num_qubits)
    noise_by_gate = {}
    for noise_spec in density_noise:
        noise_by_gate.setdefault(noise_spec["after_gate_index"], []).append(
            noise_spec
        )

    for gate_index, instruction in enumerate(base_circuit.data):
        qargs = [
            noisy_circuit.qubits[base_circuit.find_bit(qubit).index]
            for qubit in instruction.qubits
        ]
        cargs = [
            noisy_circuit.clbits[base_circuit.find_bit(clbit).index]
            for clbit in instruction.clbits
        ]
        noisy_circuit.append(instruction.operation, qargs, cargs)

        for noise_spec in noise_by_gate.get(gate_index, []):
            target = noise_spec["target"]
            channel = noise_spec["channel"]
            if channel == "local_depolarizing":
                noisy_circuit.append(
                    depolarizing_error(noise_spec["error_rate"], 1),
                    [noisy_circuit.qubits[target]],
                )
            elif channel == "amplitude_damping":
                noisy_circuit.append(
                    amplitude_damping_error(noise_spec["gamma"]),
                    [noisy_circuit.qubits[target]],
                )
            elif channel == "phase_damping":
                noisy_circuit.append(
                    phase_damping_error(noise_spec["lambda"]),
                    [noisy_circuit.qubits[target]],
                )
            else:
                raise ValueError(f"Unsupported Story 2 channel: {channel}")

    noisy_circuit.save_density_matrix()
    return noisy_circuit

def prepare_parametric_state(initial_state, ansatz):
    circuit = LinearMappedUnboundParametricQuantumCircuit(initial_state.qubit_count)
    circuit += initial_state.circuit
    circuit += ansatz
    return ParametricCircuitQuantumState(initial_state.qubit_count, circuit)

def qaoa(edges: list[tuple[int, int]], depth: int) -> QuantumCircuit:

    graph = nx.Graph()
    graph.add_edges_from(edges)

    circuit = QuantumCircuit(graph.number_of_nodes())
    for d in range(depth):
        for i in graph.nodes:
            circuit.rx(0.4, i)
            circuit.rz(0.4, i)

        cur_edges = edges if d % 2 == 0 else reversed(edges)

        for i, j in cur_edges:
            circuit.rzz(np.random.rand() * 2 * np.pi, i, j)
    return circuit

def generate_ghz_state(n_qubits, backend='qiskit'):
    """
    Generate a GHZ (Greenberger-Horne-Zeilinger) state.
    |GHZ⟩ = (|00...0⟩ + |11...1⟩)/√2
    Maximally entangled state useful for quantum error correction.
    """
    if backend == 'qiskit':
        qc = QuantumCircuit(n_qubits, n_qubits)
        qc.h(0)
        for i in range(n_qubits - 1):
            qc.cx(i, i + 1)
        qc.measure(range(n_qubits), range(n_qubits))
        return qc
    else:
        qubits = [cirq.GridQubit(i, 0) for i in range(n_qubits)]
        ops = [cirq.H(qubits[0])]
        for i in range(n_qubits - 1):
            ops.append(cirq.CNOT(qubits[i], qubits[i + 1]))
        ops.append(cirq.measure(*qubits, key='result'))
        return cirq.Circuit(ops)

def generate_qft_circuit(n_qubits, backend='qiskit'):
    """
    Quantum Fourier Transform - the quantum analog of the discrete Fourier transform.
    Core subroutine of Shor's algorithm and quantum phase estimation.
    Complexity: O(n^2) gates for n qubits.
    """
    if backend == 'qiskit':
        qc = QuantumCircuit(n_qubits, n_qubits)
        for i in range(n_qubits):
            qc.h(i)
            for j in range(i + 1, n_qubits):
                angle = np.pi / (2 ** (j - i))
                qc.cp(angle, j, i)
        # Swap qubits for correct ordering
        for i in range(n_qubits // 2):
            qc.swap(i, n_qubits - i - 1)
        qc.measure(range(n_qubits), range(n_qubits))
        return qc
    else:
        qubits = [cirq.GridQubit(i, 0) for i in range(n_qubits)]
        ops = []
        for i in range(n_qubits):
            ops.append(cirq.H(qubits[i]))
            for j in range(i + 1, n_qubits):
                angle = np.pi / (2 ** (j - i))
                ops.append(cirq.CZPowGate(exponent=angle / np.pi)(qubits[j], qubits[i]))
        for i in range(n_qubits // 2):
            ops.append(cirq.SWAP(qubits[i], qubits[n_qubits - i - 1]))
        ops.append(cirq.measure(*qubits, key='result'))
        return cirq.Circuit(ops)

def generate_variational_circuit(n_qubits, params, depth=2, backend='qiskit'):
    """
    Parameterized variational circuit (ansatz) for VQE and QAOA.
    Uses alternating layers of rotations and entangling gates.
    BrionQuantum Variational Ansatz (BQVA) design.

    Args:
        n_qubits: Number of qubits
        params: Flat array of rotation angles, length = n_qubits * depth * 3
        depth: Number of variational layers
        backend: 'qiskit' or 'cirq'
    """
    param_idx = 0
    if backend == 'qiskit':
        qc = QuantumCircuit(n_qubits, n_qubits)
        for layer in range(depth):
            # Rotation layer: Rx, Ry, Rz on each qubit
            for q in range(n_qubits):
                if param_idx < len(params):
                    qc.rx(params[param_idx], q)
                    param_idx += 1
                if param_idx < len(params):
                    qc.ry(params[param_idx], q)
                    param_idx += 1
                if param_idx < len(params):
                    qc.rz(params[param_idx], q)
                    param_idx += 1
            # Entangling layer: CNOT chain
            for q in range(n_qubits - 1):
                qc.cx(q, q + 1)
            if n_qubits > 2:
                qc.cx(n_qubits - 1, 0)  # Circular entanglement
        qc.measure(range(n_qubits), range(n_qubits))
        return qc
    else:
        qubits = [cirq.GridQubit(i, 0) for i in range(n_qubits)]
        ops = []
        for layer in range(depth):
            for q in range(n_qubits):
                if param_idx < len(params):
                    ops.append(cirq.rx(params[param_idx])(qubits[q]))
                    param_idx += 1
                if param_idx < len(params):
                    ops.append(cirq.ry(params[param_idx])(qubits[q]))
                    param_idx += 1
                if param_idx < len(params):
                    ops.append(cirq.rz(params[param_idx])(qubits[q]))
                    param_idx += 1
            for q in range(n_qubits - 1):
                ops.append(cirq.CNOT(qubits[q], qubits[q + 1]))
            if n_qubits > 2:
                ops.append(cirq.CNOT(qubits[n_qubits - 1], qubits[0]))
        ops.append(cirq.measure(*qubits, key='result'))
        return cirq.Circuit(ops)

def generate_grover_oracle(n_qubits, target_state, backend='qiskit'):
    """
    Generate Grover's oracle for a specific target state.
    Marks the target state with a phase flip.

    Args:
        n_qubits: Number of qubits
        target_state: Integer representing target (e.g., 5 for |101⟩)
        backend: 'qiskit' or 'cirq'
    """
    if backend == 'qiskit':
        qc = QuantumCircuit(n_qubits)
        # Flip qubits where target has 0
        target_bits = format(target_state, f'0{n_qubits}b')
        for i, bit in enumerate(reversed(target_bits)):
            if bit == '0':
                qc.x(i)
        # Multi-controlled Z gate
        if n_qubits == 2:
            qc.cz(0, 1)
        else:
            qc.h(n_qubits - 1)
            qc.mcx(list(range(n_qubits - 1)), n_qubits - 1)
            qc.h(n_qubits - 1)
        # Unflip
        for i, bit in enumerate(reversed(target_bits)):
            if bit == '0':
                qc.x(i)
        return qc
    else:
        qubits = [cirq.GridQubit(i, 0) for i in range(n_qubits)]
        ops = []
        target_bits = format(target_state, f'0{n_qubits}b')
        for i, bit in enumerate(reversed(target_bits)):
            if bit == '0':
                ops.append(cirq.X(qubits[i]))
        if n_qubits >= 2:
            ops.append(cirq.Z(qubits[-1]).controlled_by(*qubits[:-1]))
        for i, bit in enumerate(reversed(target_bits)):
            if bit == '0':
                ops.append(cirq.X(qubits[i]))
        return cirq.Circuit(ops)

def build(self):
    num_qubits = self.hamiltonian.num_qubits
    qc = QuantumCircuit(num_qubits)

    num_param_gates = 0
    for gate in self.ansatz.gates:
        if gate in ["rx", "ry", "rz"]: 
            num_param_gates += 1
    self.param_vector = ParameterVector("θ", num_param_gates*self.hamiltonian.num_qubits)

    i_param = 0
    for gate in self.ansatz.gates:
        if gate in ["rx", "ry", "rz"]:                
            for qubit in range(num_qubits):
                param = self.param_vector[i_param]
                getattr(qc, gate)(param, qubit)
                i_param += 1
        else:
            gate().apply(qc)

    self.circuit = qc

def ansatz_vqe(nqubits, depth, params):
    circuit = QuantumCircuit(nqubits + 1)
    t = 0
    for i in range(nqubits):
        circuit.h(i)
    for idepth in range(depth):
        for i in range(nqubits):
            if i < (nqubits - 1):
                j = i + 1
            else:
                j = 0
            circuit.rzz(params[t], i, j)
            t += 1
        circuit.barrier()
        for i in range(nqubits):
            if i < (nqubits - 1):
                j = i + 1
            else:
                j = 0
            circuit.rx(params[t], i)
            t += 1
        circuit.ry(params[t], nqubits)
        t += 1
    return circuit

def ansatz_hamiltonian(nqubits, depth, params):
    circuit = QuantumCircuit(nqubits)
    t = 0
    for i in range(nqubits):
        circuit.h(i)
    for _ in range(depth):
        for i in range(nqubits):
            if i < (nqubits - 1):
                j = i + 1
            else:
                j = 0
            circuit.rzz(params[t], i, j)
            t += 1
        circuit.barrier()
        for i in range(nqubits):
            if i < (nqubits - 1):
                j = i + 1
            else:
                j = 0
            circuit.rx(params[t], i)
            t += 1
    return circuit

def ansatz_hea(nqubits, depth, params):
    circuit = QuantumCircuit(nqubits)
    t = 0
    for _ in range(depth):
        for i in range(nqubits):
            circuit.ry(params[t], i)
            t += 1
        circuit.barrier()
        for i in range(nqubits - 1):
            circuit.cx(i, i + 1)
    return circuit

def ansatz_1(nqubits, depth, params):
    circuit = QuantumCircuit(nqubits)
    t = 0
    for idepth in range(depth):
        for i in range(nqubits):
            circuit.ry(params[t], i)
            t += 1
        circuit.barrier()
        for i in range(nqubits-1):
            circuit.cry(params[t], i, i+1)
            t+=1
    return circuit

def construct_trotter_circuit(H, time, nqubits, order, time_step):
    if order == 0:
        formular = MatrixExponential()
    elif order == 1:
        formular = LieTrotter(reps=time_step)
    else:
        formular = SuzukiTrotter(order=order, reps=time_step)
    trotter_step_first_order = PauliEvolutionGate(H, time, synthesis=formular)
    circuit = QuantumCircuit(nqubits + 1)
    circuit.append(trotter_step_first_order, range(nqubits + 1))
    # circuit = circuit.decompose(reps=2)
    return circuit

