def QuantumFourierTransform(self):
    qc_QFT=QuantumCircuit(self.num_q_site, name='qft_to_site')

    # Before SWAP
    for idx_i, i in enumerate(reversed(range(self.num_q_site))):        
        qc_QFT.h(i)
        for idx_j, j in enumerate(reversed(range(self.num_q_site-1-idx_i))):
            theta=(2*np.pi)/(2**(idx_j+2))
            qc_QFT.crz(theta=theta , control_qubit=j , target_qubit=i)
        qc_QFT.barrier()

    # after SWAP
    for i in range(self.num_q_site//2):
        qc_QFT.swap(i, self.num_q_site-1-i)

    return qc_QFT

def ansatze_site_1D(self, p):
    bin_array=self.decimal_to_binary(p)
    qc_ansatze_site = QuantumCircuit(self.num_q_site, name=f'site_register[p={p}]')

    for i, bit in enumerate(reversed(bin_array)):
        if bit==1:
            qc_ansatze_site.x(i)
    qc_ansatze_site.barrier()

    # Before SWAP
    for idx_i, i in enumerate(reversed(range(self.num_q_site))):        
        qc_ansatze_site.h(i)
        for idx_j, j in enumerate(reversed(range(self.num_q_site-1-idx_i))):
            theta=(2*np.pi)/(2**(idx_j+2))
            qc_ansatze_site.crz(theta=theta , control_qubit=j , target_qubit=i)
        qc_ansatze_site.barrier()

    # after SWAP
    for i in range(self.num_q_site//2):
        qc_ansatze_site.swap(i, self.num_q_site-1-i)

    return qc_ansatze_site

def ansatze_site_2D(self, px, py):
    bin_array_x=self.decimal_to_binary(px)
    bin_array_y=self.decimal_to_binary(py)

    qc_ansatze_site = QuantumCircuit(2*(self.num_q_site))

    # p encoding
    for i, bit in enumerate(reversed(bin_array_x)):
        if bit==1:
            qc_ansatze_site.x(i)
    for i, bit in enumerate(reversed(bin_array_y)):
        if bit==1:
            qc_ansatze_site.x(i+self.num_q_site)
    qc_ansatze_site.barrier()


    # Before SWAP
    for idx_i, i in enumerate(reversed(range(self.num_q_site))):        
        qc_ansatze_site.h(i)
        for idx_j, j in enumerate(reversed(range(self.num_q_site-1-idx_i))):
            theta=(2*np.pi)/(2**(idx_j+2))
            qc_ansatze_site.crz(theta=theta , control_qubit=j , target_qubit=i)
        qc_ansatze_site.barrier()

    # after SWAP
    for i in range(self.num_q_site//2):
        qc_ansatze_site.swap(i, self.num_q_site-1-i)

    # Before SWAP
    for idx_i, i in enumerate(reversed(range(self.num_q_site))):        
        qc_ansatze_site.h(i+self.num_q_site)
        for idx_j, j in enumerate(reversed(range(self.num_q_site-1-idx_i))):
            theta=(2*np.pi)/(2**(idx_j+2))
            qc_ansatze_site.crz(theta=theta , control_qubit=j+self.num_q_site , target_qubit=i+self.num_q_site)
        qc_ansatze_site.barrier()

    # after SWAP
    for i in range(self.num_q_site//2):
        qc_ansatze_site.swap(i+self.num_q_site, self.num_q_site-1-i+self.num_q_site)

    return qc_ansatze_site

def _angle_encoding(self, data: np.ndarray) -> QuantumCircuit:
    """Angle encoding of data"""
    if not QISKIT_AVAILABLE:
        return self._simulate_angle_encoding(data)

    num_qubits = min(len(data), self.config.num_qubits)
    qc = QuantumCircuit(num_qubits)

    # Apply rotation gates
    for i, angle in enumerate(data[:num_qubits]):
        qc.ry(angle, i)

    return qc

def _basis_encoding(self, data: np.ndarray) -> QuantumCircuit:
    """Basis encoding of data"""
    if not QISKIT_AVAILABLE:
        return self._simulate_basis_encoding(data)

    # Convert to binary representation
    binary_data = []
    for value in data:
        binary_data.extend([int(x) for x in format(int(value), 'b')])

    num_qubits = len(binary_data)
    qc = QuantumCircuit(num_qubits)

    # Apply X gates based on binary data
    for i, bit in enumerate(binary_data):
        if bit == 1:
            qc.x(i)

    return qc

def create_variational_circuit(self, num_qubits: int, num_layers: int) -> QuantumCircuit:
    """Create variational quantum circuit"""
    if not QISKIT_AVAILABLE:
        return self._simulate_variational_circuit(num_qubits, num_layers)

    qc = QuantumCircuit(num_qubits)

    # Create parameters
    params = []
    for layer in range(num_layers):
        for qubit in range(num_qubits):
            params.append(Parameter(f'θ_{layer}_{qubit}'))

    # Build circuit
    for layer in range(num_layers):
        # Rotation gates
        for qubit in range(num_qubits):
            qc.ry(params[layer * num_qubits + qubit], qubit)

        # Entangling gates
        for qubit in range(num_qubits - 1):
            qc.cx(qubit, qubit + 1)

    return qc

def create_qwc_circuits(qubit_op, ansatz, GROUPS):
    print("\nPreparando circuitos...")
    mesurement_op = []
    n_qubits = qubit_op.num_qubits

    for groups in GROUPS:
        op = ['I'] * n_qubits
        for element in groups.to_labels():
            for n,pauli in enumerate(element):
                if pauli !='I':
                    op[n] = pauli
        op = ''.join(op)
        mesurement_op.append(op)
        print(f"Grupo QWC creado: {op}")

    qc = QuantumCircuit(n_qubits)
    qc.compose(ansatz, inplace=True, front=True)
    circuit=[]
    for paulis in mesurement_op:
        qp=QuantumCircuit(qubit_op.num_qubits)
        index=1
        for j in paulis:
            if j=='Y':
                qp.sdg(qubit_op.num_qubits-index)
                qp.h(qubit_op.num_qubits-index)
            if j=='X':
                qp.h(qubit_op.num_qubits-index)
            index+=1
        circuit.append(qp)
    for i in circuit:
        i.compose(qc,inplace=True, front=True)
        i.measure_all()

    print(f"Número de grupos QWC: {len(GROUPS)}")
    return circuit

def variational_circuit(num_qubits=2, reps=1):
