def dj_oracle(case: str, n: int) -> QuantumCircuit:
    # plus one output qubit
    oracle_qc = QuantumCircuit(n + 1)

    if case == "balanced":
        np.random.seed(10)
        b_str = ""
        for _ in range(n):
            b = np.random.randint(0, 2)
            b_str = b_str + str(b)

        for qubit in range(len(b_str)):
            if b_str[qubit] == "1":
                oracle_qc.x(qubit)

        for qubit in range(n):
            oracle_qc.cx(qubit, n)

        for qubit in range(len(b_str)):
            if b_str[qubit] == "1":
                oracle_qc.x(qubit)

    if case == "constant":
        output = np.random.randint(2)
        if output == 1:
            oracle_qc.x(n)

    oracle_gate = oracle_qc.to_gate()
    oracle_gate.name = "Oracle"  # To show when we display the circuit
    return oracle_gate

def dj_algorithm(oracle: QuantumCircuit, n: int) -> QuantumCircuit:
    dj_circuit = QuantumCircuit(n + 1, n)

    dj_circuit.x(n)
    dj_circuit.h(n)

    for qubit in range(n):
        dj_circuit.h(qubit)

    dj_circuit.append(oracle, range(n + 1))

    for qubit in range(n):
        dj_circuit.h(qubit)

    dj_circuit.barrier()
    for i in range(n):
        dj_circuit.measure(i, i)

    return dj_circuit

def to_qiskit_circuit(self) -> object:
    """
    Convert to a Qiskit ``QuantumCircuit``.

    Returns a lightweight placeholder when Qiskit is not installed.
    """
    try:
        from qiskit.circuit import QuantumCircuit, Parameter  # type: ignore

        if not self._gates:
            self.build()

        qc = QuantumCircuit(self._n_qubits)
        params = [Parameter(f"θ_{i}") for i in range(self._num_params)]

        for g in self._gates:
            qubits = g["qubits"]
            if g["name"] == "ry":
                qc.ry(params[g["param_index"]], qubits)
            elif g["name"] == "rz":
                qc.rz(params[g["param_index"]], qubits)
            elif g["name"] == "rx":
                qc.rx(params[g["param_index"]], qubits)
            elif g["name"] == "cx":
                qc.cx(qubits[0], qubits[1])
            elif g["name"] == "cz":
                qc.cz(qubits[0], qubits[1])

        return qc
    except ImportError:
        logger.warning("Qiskit not installed — returning gate list")
        return self._gates

def _ansatz(theta: np.ndarray, layers: int = 2) -> QuantumCircuit:
    num_qubits = 6
    qc = QuantumCircuit(num_qubits)
    # Hartree-Fock-style init: occupy first three qubits
    for q in range(3):
        qc.x(q)
    param_idx = 0
    for _layer in range(layers):
        for q in range(num_qubits):
            qc.ry(theta[param_idx], q)
            param_idx += 1
        for q in range(num_qubits - 1):
            qc.cz(q, q + 1)
    return qc

def construct_circuit(self, num_orbs: int, num_elec: tuple[int, int]) -> None:
    """Construct qiskit circuit.

    Args:
        num_orbs: Number of orbitals in spatial basis.
        num_elec: Number of electrons (alpha, beta).
    """
    self.num_orbs = num_orbs
    self.num_spin_orbs = 2 * num_orbs
    self.num_elec = num_elec
    self.grad_param_R: dict[
        str, int
    ] = {}  # Contains information about the parameterization needed for gradient evaluations.

    # State prep circuit
    if isinstance(self.ansatz, QuantumCircuit):
        self.state_circuit: QuantumCircuit = QuantumCircuit(
            self.ansatz.num_qubits
        )  # empty state as custom circuit is passed
    elif self.ansatz == "tUPS" and "do_pp" in self.ansatz_options.keys() and self.ansatz_options["do_pp"]:
        # HF in pp-tUPS ordering
        if not isinstance(self.mapper, JordanWignerMapper):
            raise ValueError(f"pp-tUPS only implemented for JW mapper, got: {type(self.mapper)}")
        if np.sum(num_elec) != num_orbs:
            raise ValueError(
                f"pp-tUPS only implemented for number of electrons and number of orbitals being the same, got: ({np.sum(num_elec)}, {num_orbs}), (elec, orbs)"
            )
        self.state_circuit = QuantumCircuit(2 * num_orbs)
        for p in range(0, 2 * num_orbs):
            if p % 2 == 0:
                self.state_circuit.x(p)
    else:
        self.state_circuit = HartreeFock(num_orbs, num_elec, self.mapper)
    self.num_qubits = self.state_circuit.num_qubits

    # Ansatz Circuit
    if isinstance(self.ansatz, QuantumCircuit):
        print(
            "QI was initialized with a custom QuantumCircuit object. This is assumed to be the Ansatz (without state preparation circuit)"
        )
        self.circuit = self.ansatz
    elif self.ansatz == "fpUCCD":
        self.ansatz_options["pD"] = True
        if "n_layers" not in self.ansatz_options.keys():
            # default option
            self.ansatz_options["n_layers"] = 1
        self.circuit, self.grad_param_R = fUCC(num_orbs, self.num_elec, self.mapper, self.ansatz_options)
    elif self.ansatz == "fUCCD":
        self.ansatz_options["D"] = True
        if "n_layers" not in self.ansatz_options.keys():
            # default option
            self.ansatz_options["n_layers"] = 1
        self.circuit, self.grad_param_R = fUCC(num_orbs, self.num_elec, self.mapper, self.ansatz_options)
    elif self.ansatz == "HF":
        if len(self.ansatz_options) != 0:
            raise ValueError(f"No options available for HF got {self.ansatz_options}")
        self.circuit = QuantumCircuit(self.num_qubits)  # empty ansatz circuit
    elif self.ansatz == "tUPS":
        self.circuit, self.grad_param_R = tUPS(num_orbs, self.num_elec, self.mapper, self.ansatz_options)
    elif self.ansatz == "QNP":
        self.ansatz_options["do_qnp"] = True
        self.circuit, self.grad_param_R = tUPS(num_orbs, self.num_elec, self.mapper, self.ansatz_options)
    elif self.ansatz == "fUCCSD":
        self.ansatz_options["S"] = True
        self.ansatz_options["D"] = True
        if "n_layers" not in self.ansatz_options.keys():
            # default option
            self.ansatz_options["n_layers"] = 1
        self.circuit, self.grad_param_R = fUCC(num_orbs, self.num_elec, self.mapper, self.ansatz_options)
    elif self.ansatz == "kSAfUpCCGSD":
        self.ansatz_options["SAGS"] = True
        self.ansatz_options["GpD"] = True
        self.circuit, self.grad_param_R = fUCC(num_orbs, self.num_elec, self.mapper, self.ansatz_options)
    elif self.ansatz == "SDSfUCCSD":
        self.ansatz_options["D"] = True
        if "n_layers" not in self.ansatz_options.keys():
            # default option
            self.ansatz_options["n_layers"] = 1
        self.circuit, self.grad_param_R = SDSfUCC(
            num_orbs, self.num_elec, self.mapper, self.ansatz_options
        )
    elif self.ansatz == "kSASDSfUpCCGSD":
        self.ansatz_options["GpD"] = True
        self.circuit, self.grad_param_R = SDSfUCC(
            num_orbs, self.num_elec, self.mapper, self.ansatz_options
        )
    elif self.ansatz == "fUCC":
        if "n_layers" not in self.ansatz_options.keys():
            # default option
            self.ansatz_options["n_layers"] = 1
        self.circuit, self.grad_param_R = fUCC(num_orbs, self.num_elec, self.mapper, self.ansatz_options)
    elif self.ansatz == "SDSfUCC":
        if "n_layers" not in self.ansatz_options.keys():
            # default option
            self.ansatz_options["n_layers"] = 1
        self.circuit, self.grad_param_R = SDSfUCC(
            num_orbs, self.num_elec, self.mapper, self.ansatz_options
        )
    else:
        raise ValueError(f"Unknown ansatz: {self.ansatz}")

    # Check that R parameter for gradient is consistent with the paramter names.
    if len(self.grad_param_R) == 0:
        for par in self.circuit.parameters:
            # Default value two
            self.grad_param_R[str(par)] = 2
    if len(self.grad_param_R) != len(self.circuit.parameters):
        raise ValueError(
            f"Number of elements in grad_param_R, {len(self.grad_param_R)}, does not match number of parameters, {len(self.circuit.parameters)}"
        )
    self.param_names = [str(x) for x in self.circuit.parameters]
    for name in self.param_names:
        if name not in self.grad_param_R.keys():
            raise ValueError(
                f"Got parameter name, {name}, that is not in grad_param_R, {self.grad_param_R}"
            )

    if not hasattr(self, "_parameters"):
        # Set parameter to HarteeFock
        self._parameters = [0.0] * self.circuit.num_parameters

def build_reference_state(num_qubits: int, occupations: Sequence[int]) -> QuantumCircuit:
    qc = QuantumCircuit(num_qubits)
    for idx in occupations:
        if idx < 0 or idx >= num_qubits:
            raise ValueError(f"Occupation index out of range: {idx}")
        qc.x(idx)
    return qc

def make_ansatz(self, reps=1) -> QuantumCircuit:
    """Construct the parameterized UCC operator corresponding 
        to the Hamiltonian

    Args:
        reps (int, optional): Number of Trotter steps. Defaults to 1.

    Returns:
        qiskit.circuit.QuantumCircuit: Trotterized UCC circuit
    """
    # Number of qubits
    Nq = self.n_qubits
    # Nq qubits and classical registers
    circuit = QuantumCircuit(Nq, Nq)
    for r in range(reps):
        for i, (string, coeff) in enumerate(self.pauli_hamiltonian):
            par = coeff * Parameter(f'theta_[{r},{i}]')
            oplist = []
            for j, op in enumerate(string[::-1]):
                if op == 'I':
                    continue
                oplist.append((j, op))
            nops = len(oplist)
            if nops == 0:
                continue
            for (j, op) in (oplist):
                if op == 'X':
                    circuit.h(qubit=j)
                if op == 'Y':
                    circuit.rz(phi=-np.pi / 2, qubit=j)
                    circuit.h(qubit=j)
            for ind, (j, op) in enumerate(oplist[1:][::-1]):
                circuit.cx(j, oplist[nops-ind-2][0])
            if oplist[0][1] == 'X':
                circuit.rx(par, oplist[0][0])
            elif oplist[0][1] == 'Y':
                circuit.ry(par, oplist[0][0])
            elif oplist[0][1] == 'Z':
                circuit.rz(par, oplist[0][0])

            for ind, (j, op) in enumerate(oplist[1:]):
                circuit.cx(j, oplist[ind][0])

            for ind, (j, op) in enumerate(oplist):
                if op == 'X':
                    circuit.h(qubit=j)
                if op == 'Y':
                    circuit.h(qubit=j)
                    circuit.rz(phi=np.pi / 2, qubit=j)
    return circuit

def build_ising_trotter(n_qubits: int, steps: int = 3, dt: float = 0.5) -> QuantumCircuit:
    """Trotterized transverse-field Ising model."""
    qc = QuantumCircuit(n_qubits, name=f'Ising_{n_qubits}q_t{steps}')
    J, h = 1.0, 0.5
    for q in range(n_qubits):
        qc.h(q)
    for _ in range(steps):
        for q in range(n_qubits - 1):
            qc.cx(q, q + 1)
            qc.rz(2 * J * dt, q + 1)
            qc.cx(q, q + 1)
        for q in range(n_qubits):
            qc.rx(2 * h * dt, q)
    return qc

def build_qaoa_maxcut_ring(n_qubits: int, p: int = 1, gamma: float = 0.5, beta: float = 0.5) -> QuantumCircuit:
    """QAOA for MAX-CUT on ring graph."""
    qc = QuantumCircuit(n_qubits, name=f'QAOA_ring_{n_qubits}q_p{p}')
    for q in range(n_qubits): qc.h(q)
    for _ in range(p):
        for q in range(n_qubits):
            q_next = (q + 1) % n_qubits
            qc.cx(q, q_next); qc.rz(2 * gamma, q_next); qc.cx(q, q_next)
        for q in range(n_qubits): qc.rx(2 * beta, q)
    return qc

def build_vqe_circuit(self, hamiltonian: PauliSumOp) -> QuantumCircuit:
    """Build VQE circuit."""
    num_qubits = len(hamiltonian.primitive.paulis[0])
    qc = QuantumCircuit(num_qubits)

    # Add parameterized ansatz
    for i in range(num_qubits):
        qc.ry(Parameter(f'θ_{i}'), i)

    for i in range(num_qubits - 1):
        qc.cx(i, i + 1)

    return qc

def _get_state_vector(self, state_preparation_gates, n_qubits):

    # Initialize circuit.
    circuit = qiskit.QuantumCircuit(n_qubits)
    for gate in state_preparation_gates:
        circuit.append(gate)

    self._get_circuit_stat_data(circuit)

    # set the same qubit order as other simulators
    circuit = circuit.reverse_bits()
    result = StatevectorSimulator().run(circuit).result()

    return np.array(result.get_statevector())

def get_circuit_info(self, ansatz):

    # get gates to prepare the state
    state_preparation_gates = ansatz.get_preparation_gates(self)

    # build the circuit
    circuit = qiskit.QuantumCircuit(ansatz.n_qubits)
    for gate in state_preparation_gates:
        circuit.append(gate)

    return {'depth': circuit.depth()}

def quantum_rope_qiskit(self, position: int) -> Any:
    """Build Qiskit circuit for quantum RoPE at given position."""
    if not QISKIT_AVAILABLE:
        return None

    qc = QuantumCircuit(self.n_qubits)
    n_pairs = min(len(self.freqs), self.n_qubits // 2)

    for pair_idx in range(n_pairs):
        freq = self.freqs[pair_idx]
        angle = position * freq * PHI

        q1 = pair_idx * 2
        q2 = pair_idx * 2 + 1

        if q1 < self.n_qubits:
            qc.rz(angle, q1)
        if q2 < self.n_qubits:
            qc.ry(angle * LOVE_COEFFICIENT, q2)
        if q1 < self.n_qubits and q2 < self.n_qubits:
            qc.cx(q1, q2)

    # GOD_CODE global phase
    g_phase = HARMONIC_BASE ** (1.0 / PHI) * (
        2.0 ** ((OCTAVE_REF - position) / L104)
    )
    qc.global_phase = g_phase * LOVE_COEFFICIENT

    return qc

def get_measuring_circuit(basis_list: list) -> QuantumCircuit:
    qc = QuantumCircuit(len(basis_list[0][1]))

    # Find a pauli word that has the most single qubit rotations
    basis = ''
    for qi in range(len(basis_list[0][1])):
        nonI = False
        for term in basis_list:
            if term[1][qi] != 'I':
                nonI = True
                basis += term[1][qi]
                break
        if not nonI:
            basis += 'I'

    # Construct the appropriate circuit
    for i,term in enumerate(basis):
        if term == 'X':
            qc.h(i)
        elif term == 'Y':
            qc.rx(np.pi/2,i)
        else:
            continue
    return qc

def core_unitary_rotation_qiskit(core, body_type, wires):
    """Applies the unitary transformation corresponding to the core tensor using Qiskit."""
    num_qubits = 8
    qc = QuantumCircuit(num_qubits)

    if body_type == "one_body":
        diag_core = np.diag(core)
        for wire, cval in enumerate(diag_core):
            for sigma in [0, 1]:
                qubit = 2 * wire + sigma
                qc.rz(cval, qubit)  
        #qc.global_phase += float(np.sum(core))

    elif body_type == "two_body":
        for odx1, odx2 in it.product(range(len(wires) // 2), repeat=2):
            cval = core[odx1, odx2]
            for sigma, tau in it.product(range(2), repeat=2):
                if odx1 != odx2 or sigma != tau:
                    q0 = 2 * odx1 + sigma
                    q1 = 2 * odx2 + tau
                    qc.rzz(cval / 4.0, q0, q1) 
        #gphase = 0.5 * float(np.sum(core)) + 0.25 * float(np.trace(core))  
        #qc.global_phase -= gphase

    return qc

def createParameterizedCircuit(self, depth):
    """Creates the parameterized quantum circuit for the QAOA algorithm at a specified depth.

    The function generates quantum circuits for the problem and mixer Hamiltonians and the initial state.
    The main circuit is constructed layer by layer starting from the initial state.
    For each layer, symbolic parameters are assigned to the problem unitary (gamma) and the mixer unitary (beta).
    Multi-angle components can use multiple parameters per layer.

    If `flip` is set to True, a bit-flip circuit is added between layers to modify the state according to a pre-defined bit-flip pattern.
    If `usebarrier` is set to True, visual barrier instructions are added between layers to improve circuit readability and potentially
    guide compiler optimizations.

    Finally, the full parameterized circuit is measured and transpiled for the target backend. The constructed depth is stored for reference.

    Args:
        depth (int): The depth p (number of alternating mixing and phase separating layers) of the QAOA circuit.
    """
    if self.parameterized_circuit_depth == depth:
        LOG.info(
            "Circuit is already of depth " + str(self.parameterized_circuit_depth)
        )
        return

    self.problem.create_circuit()
    self.mixer.create_circuit()
    self.initialstate.create_circuit()

    # Query number of parameters from each component
    self.n_gamma = self.problem.get_num_parameters()
    self.n_beta = self.mixer.get_num_parameters()
    self.n_init = self.initialstate.get_num_parameters()

    a = AncillaRegister(self.problem.N_ancilla_qubits)
    q = QuantumRegister(self.problem.N_qubits)
    c = ClassicalRegister(self.problem.N_qubits)
    self.parameterized_circuit = QuantumCircuit(q, c, a)

    self.gamma_params = [[None] * self.n_gamma for _ in range(depth)]
    self.beta_params = [[None] * self.n_beta for _ in range(depth)]
    self.init_params = [None] * self.n_init

    # Compose initial state circuit (with parameters if applicable)
    if self.n_init > 0:
        for i in range(self.n_init):
            self.init_params[i] = Parameter("init_{}".format(i))
        init_param_map = {
            self.initialstate.circuit.parameters[i]: self.init_params[i]
            for i in range(self.n_init)
        }
        tmp_init = self.initialstate.circuit.assign_parameters(
            init_param_map, inplace=False
        )
        self.parameterized_circuit.compose(tmp_init, inplace=True)
    else:
        self.parameterized_circuit.compose(self.initialstate.circuit, inplace=True)

    if self.usebarrier:
        self.parameterized_circuit.barrier()

    for d in range(depth):
        for i in range(self.n_gamma):
            self.gamma_params[d][i] = Parameter("gamma_{}_{}".format(d, i))
        gamma_param_map = {
            self.problem.circuit.parameters[i]: self.gamma_params[d][i]
            for i in range(self.n_gamma)
        }
        tmp_circuit = self.problem.circuit.assign_parameters(
            gamma_param_map, inplace=False
        )
        self.parameterized_circuit.compose(tmp_circuit, inplace=True)

        if self.usebarrier:
            self.parameterized_circuit.barrier()

        for i in range(self.n_beta):
            self.beta_params[d][i] = Parameter("beta_{}_{}".format(d, i))
        beta_param_map = {
            self.mixer.circuit.parameters[i]: self.beta_params[d][i]
            / self.number_trottersteps_mixer
            for i in range(self.n_beta)
        }
        tmp_circuit = self.mixer.circuit.assign_parameters(
            beta_param_map, inplace=False
        )
        for _ in range(0, self.number_trottersteps_mixer):
            self.parameterized_circuit.compose(tmp_circuit, inplace=True)

        if self.flip and (d != (depth - 1)):
            self.parameterized_circuit.barrier()
            self.flipper.create_circuit(self.bitflips[d])
            self.parameterized_circuit.compose(self.flipper.circuit, inplace=True)
            self.parameterized_circuit.barrier()

        if self.usebarrier:
            self.circuit.barrier()

    self.parameterized_circuit.barrier()
    self.parameterized_circuit.measure(q, c)
    self.parameterized_circuit = transpile(
        self.parameterized_circuit, self.backend
        #basis_gates=['cx', 'u', 'p', 'cp', 'id', 'x', 'h', 'ry', 'cry', 'cu']
    )
    self.parametrized_circuit_depth = depth

def _create_circuit(self, params, cost_terms, n_qubits=None):
    """Create quantum circuit with enhanced validation and error handling."""
    try:
        if not cost_terms:
            logger.warning("No cost terms provided for circuit creation")
            return None

        # Use provided n_qubits or default to self.n_qubits
        n_qubits = n_qubits if n_qubits is not None else self.n_qubits
        gamma, beta = self._validate_and_truncate_params(params)

        # Create and validate circuit
        circuit = QuantumCircuit(n_qubits)

        # Initial state preparation
        circuit.h(range(n_qubits))

        # Apply cost Hamiltonian
        for coeff, (i, j) in cost_terms:
            if not (0 <= i < n_qubits and 0 <= j < n_qubits):
                continue

            try:
                angle = 2 * gamma * coeff
                if i != j:
                    circuit.cx(i, j)
                    circuit.rz(angle, j)
                    circuit.cx(i, j)
                else:
                    circuit.rz(angle, i)
            except Exception as e:
                logger.error(f"Error applying cost gates at indices ({i}, {j}): {str(e)}")
                continue

        # Apply mixer Hamiltonian
        try:
            circuit.rx(2 * beta, range(n_qubits))
        except Exception as e:
            logger.error(f"Error applying mixer gates: {str(e)}")
            return None

        return circuit

    except Exception as e:
        logger.error(f"Error creating quantum circuit: {str(e)}")
        return None

def get_qaoa_ansatz(self, problem, layers, betas, gammas):

    quantum_circuit = QuantumCircuit(self.number_of_qubits)

    if problem['type'] == 'MaxCut':
        w = problem['properties']

        for layer in range(layers):
            for qubit1 in range(self.number_of_qubits):
                for qubit2 in range(self.number_of_qubits):
                    if qubit1 < qubit2 and w[qubit1, qubit2] != 0:
                        quantum_circuit.rzz(gammas[layer]*w[qubit1, qubit2], qubit1, qubit2)

            quantum_circuit.barrier()

            for qubit in range(self.number_of_qubits):
                quantum_circuit.rx(betas[layer], qubit)


    elif problem['type'] == 'NumberPartitioning':
        numbers_list = problem['properties']


        for layer in range(layers):
            for qubit1 in range(self.number_of_qubits):
                for qubit2 in range(self.number_of_qubits):
                    if qubit1 < qubit2:
                        quantum_circuit.rzz(gammas[layer]*numbers_list[qubit1]*numbers_list[qubit2], qubit1, qubit2)

            quantum_circuit.barrier()

            for qubit in range(self.number_of_qubits):
                quantum_circuit.rx(betas[layer], qubit)

    return quantum_circuit

def quantum_state(x):
    qc = QuantumCircuit(2)
    qc.ry(x[0], 0)
    qc.ry(x[1], 1)
    return Statevector.from_instruction(qc)

def create_qaoa_circuit(gamma, beta, Q):
    n = 4
    qc = QuantumCircuit(n, n)

    # Initial superposition
    for i in range(n):
        qc.h(i)

    # Cost Hamiltonian (RZZ interactions)
    for i in range(n):
        for j in range(i+1, n):   # <-- FIX HERE
            if Q[i][j] != 0:
                qc.rzz(2 * gamma * Q[i][j], i, j)


    # Mixer
    for i in range(n):
        qc.rx(2 * beta, i)

    qc.measure(range(n), range(n))
    return qc

def qft(n):
    """Creates an n-qubit QFT circuit"""
    circuit = QuantumCircuit(n)

    for i in range(n, 0, -1):  
        circuit.h(i - 1)
        for qubit in range(i - 1):
            circuit.cp(np.pi / 2 ** (i - 1 - qubit), qubit, i - 1)

    swap_registers(circuit, n)
    return circuit

def qft(num_qubits):
	circ = QuantumCircuit(num_qubits)

	for q in range(num_qubits):
		circ.h(q)
		for p in range(q+1, num_qubits):
			circ.cp(np.pi/2**(num_qubits-p), q, p) 

	for q in range(num_qubits//2):
	 	 circ.swap(q, num_qubits-q-1)

	return circ;

def input_bits_to_qubits(binary, circ, reg, wrap=False, inverse=False, phase=False, qphase=None, label='Input'):
    # Flips the qubits to match a classical bit string

    n = len(binary)

    if inverse:
        wrap = True

    if wrap:
        regs = []
        reg = QuantumRegister(n, 'reg')
        regs.append(reg)
        if qphase!=None:
            qphase = QuantumRegister(1, 'phase')
            regs.append(qphase)
        circ = QuantumCircuit(*regs)

    if phase and qphase==None:
        qphase = QuantumRegister(1, 'phase')
        circ.add(qphase)

    for bit in np.arange(n):
        if int(binary[::-1][bit])==1:
            circ.x(reg[bit])

    if phase<0.:
        #circ.p(np.angle(phase), phase_reg[0])
        circ.x(qphase[0])

    if wrap:
        circ = circ.to_gate()
        circ.label = label

    if inverse:
        circ = circ.inverse()
        circ.label = label+'†'

    return circ

def QFT(circ, qreg, do_swaps=True, approximation_degree=0., insert_barriers=False, wrap=False, inverse=False, label='QFT'):

    n = len(qreg)

    if inverse:
        wrap = True

    if wrap:
        qreg = QuantumRegister(n, 'q_reg')
        circ = QuantumCircuit(qreg)

    circ.append(QFT_pre(n, do_swaps=do_swaps, approximation_degree=approximation_degree, insert_barriers=insert_barriers).to_gate(), qreg)

    if wrap:
        circ = circ.to_gate()
        circ.label = label

    if inverse:
        circ = circ.inverse()
        circ.label = label+'†'

    return circ

def QFTAddition_prec(circ, qreg1, qreg2, wrap=False, inverse=False, label='Add', QFT_on=True, iQFT_on=True, nint1=None, nint2=None, phase=False):
    r"""
    |qreg1>|qreg2> -> |qreg1>|qreg2 + qreg1>
    """
    n1 = len(qreg1)
    n2 = len(qreg2)

    if nint1==None:
        nint1 = n1
    if nint2==None:
        nint2 = n2

    if inverse:
        wrap = True

    if wrap:
        qreg1 = QuantumRegister(n1, 'q_reg1')
        qreg2 = QuantumRegister(n2, 'q_reg2')
        circ = QuantumCircuit(qreg1, qreg2)

    if QFT_on:
        circ.append(QFT(circ, qreg2, do_swaps=False, wrap=True), qreg2[:])

    dp = (n2 - nint2) - (n1 - nint1)

    jstart = 0
    jend = n1
    switch = False
    if dp!=0 and phase:
        circ.append(TwosCompliment(circ, qreg1[:-1], wrap=True).control(1), [qreg1[-1], *qreg1[:-1]]);
        jstart += np.abs(dp)
        #jend += np.abs(dp)
        jend -= 1
        switch = True

    dpn = 0
    if dp<0:
        dpn = np.abs(dp)
        dp = 0

    for j in np.arange(0,jend):
        for l in np.arange(0,n2):
            lam = 2*np.pi*2.**(-dp+j-l+1)
            if lam%(2*np.pi)==0:
                continue
            #print(j,l)
            circ.cp(lam, qreg1[j], qreg2[l])
            if switch and lam%np.pi!=0:
                circ.append(PhaseGate(-2.*lam).control(2), [qreg1[-1], qreg1[j], qreg2[l]]);

    if switch:
        circ.append(TwosCompliment(circ, qreg1[:-1], wrap=True).control(1), [qreg1[-1], *qreg1[:-1]]);

    if iQFT_on:
        circ.append(QFT(circ, qreg2, do_swaps=False, wrap=True, inverse=True), qreg2[:])

    if wrap:
        circ = circ.to_gate()
        circ.label = label

    if inverse:
        circ = circ.inverse()
        circ.label = label+'†'

    return circ

def QFTAddition(circ, qreg1, qreg2, wrap=False, inverse=False, label='Add', QFT_on=True, iQFT_on=True, nint1=None, nint2=None, phase=False):
    r"""
    |qreg1>|qreg2> -> |qreg1>|qreg2 + qreg1>
    """
    n1 = len(qreg1)
    n2 = len(qreg2)

    if n1>n2:
        raise ValueError('First register cannot be greater than the second!',n1,n2)

    if inverse:
        wrap = True

    if wrap:
        qreg1 = QuantumRegister(n1, 'q_reg1')
        qreg2 = QuantumRegister(n2, 'q_reg2')
        circ = QuantumCircuit(qreg1, qreg2)

    if nint1==None:
        nint1 = n1
    if nint2==None:
        nint2 = n2

    dp = (n2 - nint2) - (n1 - nint1)
    dpn = 0
    if dp<0:
        dpn = np.abs(dp)
        dp = 0

    add_gate = QFTAddition_(circ, qreg1[dpn:], qreg2[dp:], wrap=True, phase=phase, QFT_on=QFT_on, iQFT_on=iQFT_on)
    circ.append(add_gate, [*qreg1[dpn:], *qreg2[dp:]]);

    if wrap:
        circ = circ.to_gate()
        circ.label = label

    if inverse:
        circ = circ.inverse()
        circ.label = label+'†'

    return circ

def QFTAddition_(circ, qreg1, qreg2, wrap=False, inverse=False, label='Add', QFT_on=True, iQFT_on=True, pm=1, phase=False):
    r"""
    |qreg1>|qreg2> -> |qreg1>|qreg2 + qreg1>
    """
    n1 = len(qreg1)
    n2 = len(qreg2)

    if inverse:
        wrap = True

    if wrap:
        qreg1 = QuantumRegister(n1, 'q_reg1')
        qreg2 = QuantumRegister(n2, 'q_reg2')
        circ = QuantumCircuit(qreg1, qreg2)

    if QFT_on:
        circ.append(QFT(circ, qreg2, do_swaps=False, wrap=True), qreg2[:])

    jend = n1
    if phase and n1!=n2:
        circ.append(TwosCompliment(circ, qreg1[:-1], wrap=True).control(1), [qreg1[-1], *qreg1[:-1]]);
        jend -= 1

    for j in np.arange(0,jend):
        for l in np.arange(0,n2):
            lam = pm*2*np.pi*2.**(j-l-1)
            if lam%(2*np.pi)==0:
                continue
            circ.cp(lam, qreg1[j], qreg2[l])
            if phase and n1!=n2 and lam%np.pi!=0:
                circ.append(PhaseGate(-2.*lam).control(2), [qreg1[-1], qreg1[j], qreg2[l]]);

    if phase and n1!=n2:
        circ.append(TwosCompliment(circ, qreg1[:-1], wrap=True).control(1), [qreg1[-1], *qreg1[:-1]]);

    if iQFT_on:
        circ.append(QFT(circ, qreg2, do_swaps=False, wrap=True, inverse=True), qreg2[:])

    if wrap:
        circ = circ.to_gate()
        circ.label = label

    if inverse:
        circ = circ.inverse()
        circ.label = label+'†'

    return circ

