    circ=qk.QuantumCircuit(reg,name='QFT')
    for i in range(nq):
        circ.append(clib.HGate(),[reg[nq-i-1]])
        k=1
        for j in range(i+1,nq):
            fac=1/math.pow(2.0,k)
            circ.append(clib.CZGate().power(fac),[reg[nq-j-1],reg[nq-i-1]])
            k=k+1
    for i in range(int(nq/2.0)):
