        qc.h(range(self.n_value_qubits))
        for _ in range(n_iterations):
            qc.compose(oracle, inplace=True)
            qc.compose(diffuser, inplace=True)
        qc.measure(range(self.n_value_qubits), range(self.n_value_qubits))
    return qc

